// Spell database.
// Cleric, Druid and Magic-user spells: Rules Cyclopedia (TSR 1071), Chapter 3 (pp. 34-61).
// Radiance spells: GAZ3 The Principalities of Glantri (pp. 77-78), cast by Brothers of the Radiance.
// Shadow Shaman spells: Tome of the Magic of Mystara Vol. 2 (Divine Magic), Table 4.13. Immortal spells (casterType 'immortal'): Tome of the Magic of Mystara Vol. 1-2, granted per Immortal by Vol. 2's appendix (see deities_db).
const SpellsDatabase = {
    "divine_cure_light": {"id": "divine_cure_light", "name": "Cure Light Wounds", "level": 1, "casterType": "divine", "range": "Touch", "duration": "Permanent", "effect": "Any one living creature", "description": "Heals 1d6+1 (2-7) points of damage or removes paralysis; if used to cure paralysis it heals no damage. The cleric may cast it on himself. It cannot raise a creature's hit points above their original total. Reversed (cause light wounds), it inflicts 1d6+1 (2-7) points of damage on any creature touched, with no saving throw; the cleric must make a normal attack roll to hit.\nReversible (Cause Light Wounds).", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_detect_evil": {"id": "divine_detect_evil", "name": "Detect Evil", "level": 1, "casterType": "divine", "range": "120'", "duration": "6 turns", "effect": "Everything within 120'", "description": "Evilly enchanted objects within 120' glow, as do creatures that intend to harm the cleric while they are within range. Their actual thoughts cannot be heard. A Chaotic alignment does not automatically mean Evil. Traps and poison are neither good nor evil, so the spell does not reveal them.", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_detect_magic": {"id": "divine_detect_magic", "name": "Detect Magic", "level": 1, "casterType": "divine", "range": "0", "duration": "2 turns", "effect": "Everything within 60'", "description": "Magical objects, creatures, and places within 60' of the cleric are surrounded by a glow. The glow does not last long, so the spell is best used to check whether objects already in sight are magical (e.g. a magically held door, an enchanted monster in disguise, or enchanted treasure).", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_light": {"id": "divine_light", "name": "Light", "level": 1, "casterType": "divine", "range": "120'", "duration": "12 turns", "effect": "Volume of 30' diameter", "description": "Creates a ball of light 30' across, as bright as a torch or lamp. Cast on an object (such as a weapon), the light moves with it. Cast at a creature's eyes, the victim must save vs. spells or be blinded for the duration or until the effect is canceled. Reversed (darkness), it creates a 30'-diameter circle of darkness that blocks all sight except infravision; it cancels a light spell and can be canceled by one. Cast at an opponent's eyes, darkness blinds for the duration unless the target saves vs. spells.\nReversible (Darkness).", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_protection_from_evil": {"id": "divine_protection_from_evil", "name": "Protection from Evil", "level": 1, "casterType": "divine", "range": "0", "duration": "12 turns", "effect": "The cleric only", "description": "Creates an invisible barrier around the cleric's body: attackers suffer -1 to attack rolls and the cleric gains +1 to all saving throws. Enchanted creatures (those hit only by magic weapons, or magically summoned or controlled, e.g. charmed; silver-only creatures do not count) cannot touch the cleric in melee, though their missile attacks can hit at -1. It does not affect magic missile. If the cleric attacks an enchanted creature, such creatures can then touch him, but the -1 attack penalty and save bonus remain for the duration.", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_purify_food_and_water": {"id": "divine_purify_food_and_water", "name": "Purify Food and Water", "level": 1, "casterType": "divine", "range": "10'", "duration": "Permanent", "effect": "See below", "description": "Makes spoiled or poisoned food and water safe. It purifies one ration of preserved food (iron or standard), or six waterskins of water, or enough normal food to feed a dozen people. Cast on mud, it settles the dirt and leaves a pool of pure water. It does not affect living creatures.", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_remove_fear": {"id": "divine_remove_fear", "name": "Remove Fear", "level": 1, "casterType": "divine", "range": "Touch", "duration": "2 turns", "effect": "Any one living creature", "description": "Calms the creature touched and removes any fear. Against magical fear (even fear that normally allows no save), the victim may make a saving throw vs. spells with a bonus equal to the cleric's level (maximum +6) to negate it; a roll of 1 always fails. Reversed (cause fear), it makes any one creature within 120' flee for two turns unless it saves vs. spells.\nReversible (Cause Fear).", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_resist_cold": {"id": "divine_resist_cold", "name": "Resist Cold", "level": 1, "casterType": "divine", "range": "0", "duration": "6 turns", "effect": "All creatures within 30'", "description": "All creatures within 30' of the cleric can withstand freezing temperatures without harm, gain +2 to all saving throws against cold attacks, and reduce cold damage by 1 point per die (minimum 1 point per die). The effect moves with the cleric.", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_bless": {"id": "divine_bless", "name": "Bless", "level": 2, "casterType": "divine", "range": "60'", "duration": "6 turns", "effect": "All within a 20' square area", "description": "Friendly creatures in a 20' x 20' area who are not yet in melee gain +1 to morale and +1 to all attack and damage rolls. Reversed (blight), it places a -1 penalty on enemies' morale, attack rolls, and damage rolls; each victim may save vs. spells to avoid the penalties.\nReversible (Blight).", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_find_traps": {"id": "divine_find_traps", "name": "Find Traps", "level": 2, "casterType": "divine", "range": "0 (Cleric only)", "duration": "2 turns", "effect": "Traps within 30' glow", "description": "All mechanical and magical traps glow dull blue when the cleric comes within 30' of them. The spell does not reveal the type of trap or how to remove it. Ambushes and natural hazards such as quicksand are not traps.", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_hold_person": {"id": "divine_hold_person", "name": "Hold Person", "level": 2, "casterType": "divine", "range": "180'", "duration": "9 turns", "effect": "Paralyzes up to 4 creatures", "description": "Affects humans, demihumans, and human-like creatures (e.g. bugbears, gnolls, hobgoblins, kobolds, orcs, ogres, pixies), but not undead or creatures larger than ogres. Each victim must save vs. spells or be paralyzed for nine turns. Cast at one person, the save is at -2; cast at a group, up to four persons of the cleric's choice are affected with no penalty. Only the reverse or dispel magic removes the paralysis. Reversed (free person), it frees up to four victims of hold person (including one cast by a magic-user or elf); it does not cure other paralysis such as a ghoul's.\nReversible (Free Person).", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_know_alignment": {"id": "divine_know_alignment", "name": "Know Alignment", "level": 2, "casterType": "divine", "range": "0 (Cleric only)", "duration": "1 round", "effect": "One creature within 10'", "description": "The caster learns the alignment (Lawful, Neutral, or Chaotic) of one creature within 10', or of an enchanted item or area (if any). Reversed (confuse alignment), it is cast by touch on one creature, lasts one turn per caster level, and allows no save; any know alignment cast on the recipient during that time gives a false answer, the same false answer each time.\nReversible (Confuse Alignment).", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_resist_fire": {"id": "divine_resist_fire", "name": "Resist Fire", "level": 2, "casterType": "divine", "range": "30'", "duration": "2 turns", "effect": "One living creature", "description": "Normal fire and heat cannot harm the recipient. The recipient gains +2 to all saving throws against magical fire (dragon breath, fireball, etc.), and such damage is reduced by 1 point per die (minimum 1 per die). Red dragon breath is reduced by 1 point per Hit Die of the dragon (minimum 1 per Hit Die).", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_silence_15_radius": {"id": "divine_silence_15_radius", "name": "Silence 15' Radius", "level": 2, "casterType": "divine", "range": "180'", "duration": "12 turns", "effect": "Sphere of silence 30' across", "description": "Makes the area totally silent: conversation and spellcasting inside it are impossible, though those inside can still hear noises from outside. If cast on a creature, it must save vs. spells or the silence moves with it; if it saves, the silence stays where cast and the victim may move out of it.", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_snake_charm": {"id": "divine_snake_charm", "name": "Snake Charm", "level": 2, "casterType": "divine", "range": "60'", "duration": "2-5 rounds or 2-5 turns", "effect": "Charms 1 HD of snakes per level of the caster", "description": "Charms 1 Hit Die of snakes per cleric level in any combination (a 5th level cleric could charm one 5 HD snake or five 1 HD snakes); no saving throw. The snakes rise and sway and will not attack unless attacked. Against attacking snakes it lasts 1d4+1 (2-5) rounds; otherwise 1d4+1 (2-5) turns. Afterwards the snakes return to normal, with normal (not automatically hostile) reactions.", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_speak_with_animal": {"id": "divine_speak_with_animal", "name": "Speak with Animal", "level": 2, "casterType": "divine", "range": "0 (Cleric only)", "duration": "6 turns", "effect": "Allows conversation within 30'", "description": "The cleric names one type of animal (e.g. wolves) and may speak with all normal or giant animals of that type within 30'; the effect moves with the caster. Only one type at a time, and not intelligent animals or fantastic creatures. The animals usually react favorably (+2 to reaction rolls) and may do a favor if the reaction is high enough, provided they can understand and perform it.", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_continual_light": {"id": "divine_continual_light", "name": "Continual Light", "level": 3, "casterType": "divine", "range": "120'", "duration": "Permanent", "effect": "Sphere of light 60' across", "description": "Creates daylight-bright light in a 30'-radius sphere, lasting until dispel magic or continual darkness is cast on it. Creatures penalized by daylight suffer the same penalties within it. It may be cast on an area, object, or creature; cast at a creature's eyes, the victim must save vs. spells or be blinded until the effect is removed. Reversed (continual darkness), it creates total darkness of the same size that torches, lanterns, light, and infravision cannot penetrate; continual light cancels it. Cast at the eyes, it blinds unless the victim saves vs. spells.\nReversible (Continual Darkness).", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_cure_blindness": {"id": "divine_cure_blindness", "name": "Cure Blindness", "level": 3, "casterType": "divine", "range": "Touch", "duration": "Permanent", "effect": "One living creature", "description": "Cures nearly any form of blindness, including that caused by light or darkness spells (normal or continual). It does not affect blindness caused by a curse.", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_cure_disease": {"id": "divine_cure_disease", "name": "Cure Disease", "level": 3, "casterType": "divine", "range": "30'", "duration": "Permanent", "effect": "One living creature within range", "description": "Cures one living creature of one disease, such as those caused by a mummy or green slime. Cast by a cleric of 11th level or higher, it also cures lycanthropy. Reversed (cause disease), the victim must save vs. spells or contract a wasting disease: -2 on all attack rolls, wounds cannot be magically cured, natural healing takes twice as long, and it is fatal in 2d12 (2-24) days unless removed by cure disease.\nReversible (Cause Disease).", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_growth_of_animal": {"id": "divine_growth_of_animal", "name": "Growth of Animal", "level": 3, "casterType": "divine", "range": "120'", "duration": "12 turns", "effect": "Doubles the size of one animal", "description": "Doubles the size of one normal or giant animal, giving it twice its normal strength, double damage, and double carrying capacity. It does not change the animal's behavior, armor class, or hit points, and does not affect intelligent animal races or fantastic creatures.", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_locate_object": {"id": "divine_locate_object", "name": "Locate Object", "level": 3, "casterType": "divine", "range": "0 (Cleric only)", "duration": "6 turns", "effect": "Detects one object within 120'", "description": "The cleric senses the direction (not distance) of one known object within 120'. A common object can be found from a partial description (e.g. \"stairs leading up\"), revealing only the nearest one; a specific object requires knowing exactly what it looks like. The spell will not locate a creature.", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_remove_curse": {"id": "divine_remove_curse", "name": "Remove Curse", "level": 3, "casterType": "divine", "range": "Touch", "duration": "Permanent", "effect": "Removes any one curse", "description": "Removes one curse from a character, item, or area. Some curses, especially on magic items, may be removed only temporarily at the DM's discretion, requiring dispel evil (or a high-level remove curse) for permanent removal. Reversed (curse), it afflicts the victim with a misfortune or penalty unless he saves vs. spells; suggested safe limits are -4 to attack rolls, -2 to saving throws, prime requisite halved, or -4 to others' reactions to him. An overly powerful curse may rebound on the caster (DM's discretion).\nReversible (Curse).", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_speak_with_the_dead": {"id": "divine_speak_with_the_dead", "name": "Speak with the Dead", "level": 3, "casterType": "divine", "range": "10'", "duration": "1 round per level of the cleric", "effect": "Cleric may ask three questions", "description": "The cleric may ask three questions of a deceased spirit whose body is within range. Time since death that can be reached: 6th-7th level, 4 days; 8th-14th, 4 months; 15th-20th, 4 years; 21st+, no limit. The spirit answers in a tongue the cleric knows but only knows things up to its death; if its alignment matches the cleric's it answers clearly and briefly, otherwise it may answer in riddles.", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_striking": {"id": "divine_striking", "name": "Striking", "level": 3, "casterType": "divine", "range": "30'", "duration": "1 turn", "effect": "1d6 bonus to damage on 1 weapon", "description": "One weapon inflicts an additional 1d6 points of damage with every successful blow for the duration (like a staff of striking). The bonus applies to damage only, not attack rolls. If cast on a normal weapon, it can damage creatures normally hit only by magic weapons, doing 1d6 per strike regardless of its normal damage.", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_animate_dead": {"id": "divine_animate_dead", "name": "Animate Dead", "level": 4, "casterType": "divine", "range": "60'", "duration": "Permanent", "effect": "Creates zombies or skeletons", "description": "Turns normal skeletons or bodies within range into skeletons or zombies that obey the cleric until destroyed by another cleric or dispel magic. The cleric may animate 1 Hit Die of undead per level. A skeleton has the original creature's Hit Dice; a zombie has one more. All humans and demihumans count as 1 HD regardless of level (a 9th level thief becomes a 2 HD zombie). The animated dead have no spells but are immune to sleep, charm, and poison. Animating the dead is usually a Chaotic act.", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_create_water": {"id": "divine_create_water", "name": "Create Water", "level": 4, "casterType": "divine", "range": "10'", "duration": "6 turns", "effect": "Creates one magical spring", "description": "Summons an enchanted spring from the ground or a wall that flows for an hour, creating enough water for 12 men and their mounts for a day (about 50 gallons). For each cleric level above 8th, water for 12 more men and mounts is created (a 10th level cleric supplies 36). The cleric may create less than the maximum by stating the number of gallons.", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_cure_serious_wounds": {"id": "divine_cure_serious_wounds", "name": "Cure Serious Wounds", "level": 4, "casterType": "divine", "range": "Touch", "duration": "Permanent", "effect": "Any one living creature", "description": "Similar to cure light wounds, but cures one creature of 2d6+2 (4-14) points of damage. Reversed (cause serious wounds), it inflicts 2d6+2 points of damage on any creature touched, with no saving throw; the caster must make a normal attack roll.\nReversible (Cause Serious Wounds).", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_dispel_magic": {"id": "divine_dispel_magic", "name": "Dispel Magic", "level": 4, "casterType": "divine", "range": "120'", "duration": "Permanent", "effect": "Destroys spells in a 20' cube", "description": "Destroys spell effects in a 20' x 20' x 20' volume. Effects created by a caster of equal or lower level are automatically destroyed; against a higher-level caster there is a 5% chance of failure per level of difference. It does not affect magic items themselves, but can dispel effects produced by them (e.g. free a victim of a ring of human control, or douse a flaming weapon).", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_neutralize_poison": {"id": "divine_neutralize_poison", "name": "Neutralize Poison", "level": 4, "casterType": "divine", "range": "Touch", "duration": "Permanent", "effect": "A creature, container, or object", "description": "Makes all poisons present in a creature, container, or one object harmless. It revives a victim slain by poison if cast within 10 rounds, but cures no damage. Reversed (create poison), cast by touch on a creature or container only: a creature must save vs. poison or die; a container's contents are poisoned with no save (drinkers get a save). Poisoning is usually a Chaotic act.\nReversible (Create Poison).", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_protection_from_evil_10_radius": {"id": "divine_protection_from_evil_10_radius", "name": "Protection from Evil 10' Radius", "level": 4, "casterType": "divine", "range": "0", "duration": "12 turns", "effect": "Barrier 20' diameter", "description": "Creates an invisible barrier extending 10' in all directions from the caster. Everyone within gains +1 to all saving throws, and attacks against them suffer -1 to hit. Enchanted creatures (magically summoned or controlled, or not harmed by normal weapons; silver-only creatures do not count) cannot attack those within in melee. If anyone inside attacks an enchanted creature, it may then melee them, though the bonus and penalty still apply. Missile and magical attacks can still be made at -1.", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_speak_with_plants": {"id": "divine_speak_with_plants", "name": "Speak with Plants", "level": 4, "casterType": "divine", "range": "0 (Cleric only)", "duration": "3 turns", "effect": "All plants within 30'", "description": "The cleric can talk to plants within 30' as if they were intelligent and request a simple favor, which they grant if they can understand and perform it (e.g. letting the party pass through impenetrable undergrowth). It also allows communication with plantlike monsters such as treants.", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_sticks_to_snakes": {"id": "divine_sticks_to_snakes", "name": "Sticks to Snakes", "level": 4, "casterType": "divine", "range": "120'", "duration": "6 turns", "effect": "Up to 16 sticks", "description": "Turns 2d8 sticks into snakes that obey the cleric and revert to sticks when slain or when the spell ends. Each has a 50% chance (1-3 on 1d6) of being poisonous. Snakes: AC 6, HD 1, one bite for 1d4, MV 90' (30'), Save F1, ML 12, AL Neutral.", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_commune": {"id": "divine_commune", "name": "Commune", "level": 5, "casterType": "divine", "range": "0 (Cleric only)", "duration": "3 turns", "effect": "3 questions", "description": "The cleric may ask three yes-or-no questions of the greater powers (forces of nature, greater spirits, or Immortals of the campaign). It may be cast only once a week (the DM may limit it to once a month). Once a year the cleric may ask twice the normal number of questions, perhaps on a day significant to the powers.", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_create_food": {"id": "divine_create_food", "name": "Create Food", "level": 5, "casterType": "divine", "range": "10'", "duration": "Permanent", "effect": "Creates food for 12 or more", "description": "Creates enough normal food to feed 12 men and their mounts for one day, plus food for 12 more for every cleric level above 8th. Less may be created if desired. The food spoils after 24 hours.", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_cure_critical_wounds": {"id": "divine_cure_critical_wounds", "name": "Cure Critical Wounds", "level": 5, "casterType": "divine", "range": "Touch", "duration": "Permanent", "effect": "Any one living creature", "description": "Similar to cure light wounds, but cures one living creature of 3d6+3 (6-21) points of damage. The entry's text also describes a reverse (cause critical wounds) that inflicts 3d6+3 points of damage on a living creature touched, with no saving throw; the caster must make a normal attack roll.\nReversible (Cause Critical Wounds).", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_dispel_evil": {"id": "divine_dispel_evil", "name": "Dispel Evil", "level": 5, "casterType": "divine", "range": "30'", "duration": "1 turn", "effect": "Enchanted or undead monsters or one curse or charm", "description": "Affects all undead and enchanted (summoned, controlled, or animated) monsters within range: each is destroyed unless it saves vs. spells (at -2 if the spell targets a single creature). Creatures from another plane are banished instead if they fail. Those that save must flee and stay away while the caster concentrates without moving. Alternatively, it removes the curse from one cursed item or the influence of one magical charm.", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_insect_plague": {"id": "divine_insect_plague", "name": "Insect Plague", "level": 5, "casterType": "divine", "range": "480'", "duration": "1 day", "effect": "Creates a swarm of 30' radius", "description": "Summons a 30'-radius swarm of insects that obscures vision and drives off creatures of less than 3 Hit Dice (no saving throw). The swarm moves up to 20' per round as directed while within range; the caster must concentrate without moving, and if disturbed the insects scatter and the spell ends. It works only outdoors and above ground.", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_quest": {"id": "divine_quest", "name": "Quest", "level": 5, "casterType": "divine", "range": "30'", "duration": "Special", "effect": "Compels one living creature", "description": "Forces one victim to perform a task (e.g. slay a monster, rescue a prisoner, fetch an item, go on a pilgrimage) unless he saves vs. spells. Impossible or suicidal tasks have no effect; the spell ends when the task is completed. A victim refusing the quest is cursed (DM's choice, possibly double strength) until he resumes it. Reversed (remove quest), it dispels a quest or quest-related curse with a 50% chance, modified by 5% per level of difference between the casters (maximum 99%).\nReversible (Remove Quest).", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_raise_dead": {"id": "divine_raise_dead", "name": "Raise Dead", "level": 5, "casterType": "divine", "range": "120'", "duration": "Permanent", "effect": "Body of one human or demihuman", "description": "Raises a dead human, dwarf, halfling, or elf whose body is present (missing parts leave disabilities). An 8th level cleric can raise one dead up to 4 days, +4 days per level above 8th. The recipient returns with 1 hp and cannot fight, cast spells, use abilities, carry heavy loads, or move over half speed until two weeks of bed rest (not magically hastened). Cast at an undead, it destroys it unless it saves vs. spells at -2 (a vampire flees to its coffin instead); undead with more HD than a vampire take 3d10, save for half. Reversed (finger of death), a death ray kills one living creature within 60' unless it saves vs. death ray; it heals 3d10 to undead of 10+ HD.\nReversible (Finger of Death).", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_truesight": {"id": "divine_truesight", "name": "Truesight", "level": 5, "casterType": "divine", "range": "0 (cleric only)", "duration": "1 turn + 1 round per level of caster", "effect": "Reveals all things", "description": "The cleric sees all things within 120' as they truly are: hidden, invisible, and ethereal objects and creatures (as the magic-user detect invisible spell), secret doors, and anything disguised or polymorphed, with no possibility of deception. Alignment, experience, and power are also \"seen.\"", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_aerial_servant": {"id": "divine_aerial_servant", "name": "Aerial Servant", "level": 6, "casterType": "divine", "range": "60'", "duration": "1 day per level of caster", "effect": "Servant fetches one item or creature", "description": "Summons an intelligent aerial servant from the elemental plane. The cleric must describe one creature or item and its location, or it departs; it then seeks the target and brings it back, taking as long as needed within the duration. It has 18 Strength, carries up to 500 lbs (5,000 cn), and can become ethereal at will, but cannot pass a protection from evil effect. If it fails to finish within the duration, it goes insane and returns to attack the caster. Full description in Chapter 14.", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_animate_objects": {"id": "divine_animate_objects", "name": "Animate Objects", "level": 6, "casterType": "divine", "range": "60'", "duration": "6 turns", "effect": "Causes objects to move", "description": "Makes nonliving, nonmagical objects move and attack: one object of up to 400 lbs (4,000 cn) or several smaller objects totaling no more than 400 lbs. The DM sets movement, attacks, damage, and AC; e.g. a man-sized statue moves 30' per round, attacks once for 2d8, AC 1; a chair moves 180' per round, AC 6, two attacks of 1d4. Objects hit with the same chances as the cleric.", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_barrier": {"id": "divine_barrier", "name": "Barrier", "level": 6, "casterType": "divine", "range": "60'", "duration": "12 turns", "effect": "Creates whirling hammers", "description": "Creates a wall of whirling hammers in an area up to 30' in diameter and 30' high, often used to block an entrance or passage. Any creature passing through it takes 7d10 (7-70) points of damage, no saving throw. Reversed (remove barrier), it destroys any one cleric's barrier, or a magic-user's wall of ice, wall of fire, clothform, woodform, or wall of stone; it does not affect wall of iron, stoneform, ironform, or steelform.\nReversible (Remove Barrier).", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_create_normal_animals": {"id": "divine_create_normal_animals", "name": "Create Normal Animals", "level": 6, "casterType": "divine", "range": "30'", "duration": "10 turns", "effect": "Creates 1-6 loyal animals", "description": "Creates normal animals from thin air at a point within 30'; they can be sent up to 240' away and obey the cleric, fighting or performing other tasks (instructions must be worded carefully). The cleric chooses one large (elephant, hippo), three medium (bear, great cat), or six small (wolf, rock baboon) animals; the DM decides the type. No giant animals. They vanish when slain or when the spell ends.", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_cureall": {"id": "divine_cureall", "name": "Cureall", "level": 6, "casterType": "divine", "range": "Touch", "duration": "Permanent", "effect": "Cures anything", "description": "Used on wounds, it restores the recipient to full hit points minus 1d6. Instead it can remove a curse, neutralize a poison, cure paralysis, disease, blindness, or a feeblemind effect, but only one affliction per casting (the cleric names which). Cast on someone just raised by raise dead, it removes the need for two weeks of bed rest; it is the only magical cure that works on a newly raised creature.", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_find_the_path": {"id": "divine_find_the_path", "name": "Find the Path", "level": 6, "casterType": "divine", "range": "0 (Cleric only)", "duration": "6 turns + 1 turn per level of the caster", "effect": "Shows the path to an area", "description": "The cleric names a specific place (not necessarily one visited) and for the duration knows its direction, plus any special knowledge needed to reach it, such as secret doors and passwords. When the spell ends only the general direction is remembered. The spell is negated instantly if the caster tries to write down, record, or disclose the special knowledge. Often used to find an escape route.", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_speak_with_monsters": {"id": "divine_speak_with_monsters", "name": "Speak with Monsters", "level": 6, "casterType": "divine", "range": "0 (Cleric only)", "duration": "1 round per level of the cleric", "effect": "Permits conversation with any monster", "description": "The caster may ask questions of any living or undead creatures within 30', even unintelligent ones, one question per round. Those spoken to will not attack while conversing but may defend themselves or flee if attacked. Reversed (babble), with range 60' and duration 1 turn per level, one target must save vs. spells at -2 or be unable to communicate in any way (speech, gestures, writing, telepathy); it can still cast spells but cannot use command-word magic items.\nReversible (Babble).", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_word_of_recall": {"id": "divine_word_of_recall", "name": "Word of Recall", "level": 6, "casterType": "divine", "range": "0 (Cleric only)", "duration": "Instantaneous", "effect": "Teleports the caster to sanctuary", "description": "Like the magic-user's teleport spell, carries the cleric and all equipment carried (but no other creatures) to the meditation room in his permanent home, regardless of distance. The cleric must have such a home and room. In the round the spell is cast, the cleric automatically gains initiative unless surprised.", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_earthquake": {"id": "divine_earthquake", "name": "Earthquake", "level": 7, "casterType": "divine", "range": "120 yards", "duration": "1 turn", "effect": "Causes earth tremors", "description": "Shakes the earth and opens large cracks. A 17th level caster affects an area up to 60' square, +5' to each dimension per level above 17th. Small dwellings are reduced to rubble, larger structures crack open, and hills and cliffs form rockslides. Cracks may engulf and crush 1 creature in 6 (chosen randomly); a character so endangered may save vs. death to avoid falling in.", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_holy_word": {"id": "divine_holy_word", "name": "Holy Word", "level": 7, "casterType": "divine", "range": "0", "duration": "Instantaneous", "effect": "All creatures within 40'", "description": "Affects all creatures, friend or foe, within a 40' radius of the caster; creatures of other alignments are affected with no saving throw: up to 5th level, killed; 6-8, stunned 2d10 turns; 9-12, deafened 1d6 turns; 13+, stunned 1d10 rounds. Victims of 13th level/HD or more, or of the caster's alignment, may save vs. spells to avoid all effects. It is blocked only by lead or an anti-magic shell.", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_raise_dead_fully": {"id": "divine_raise_dead_fully", "name": "Raise Dead Fully", "level": 7, "casterType": "divine", "range": "60'", "duration": "Permanent", "effect": "Raises any living creature", "description": "Like raise dead but works on any living creature. A human or demihuman awakens at once with full hp and no penalties except afflictions (curse, disease) held at death; other creatures follow raise dead's rules. A 17th level cleric can raise a human or demihuman dead up to 4 months, +4 months per level above 17th. Against undead: 7 HD or less destroyed (no save); 7-12 HD destroyed unless they save vs. spells at -4; over 12 HD take 6d10, save for half. Reversed (obliterate), it affects living creatures as the normal form affects undead, and on undead acts as a cureall.\nReversible (Obliterate).", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_restore": {"id": "divine_restore", "name": "Restore", "level": 7, "casterType": "divine", "range": "Touch", "duration": "Permanent", "effect": "Restores 1 level lost to energy drain", "description": "Restores one level lost to energy drain (e.g. a vampire's attack); it restores no more than one level and adds none if none was lost. The caster loses one level, as if struck by a wight, but regains it after 2d10 (2-20) days of rest. Reversed (life drain), it drains one level from the victim touched, like a wight or wraith; it costs the caster no level or rest, but is a Chaotic act avoided by Lawful clerics.\nReversible (Life Drain).", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_survival": {"id": "divine_survival", "name": "Survival", "level": 7, "casterType": "divine", "range": "Touch", "duration": "One hour per level of the caster", "effect": "Protects one creature against all non-magical damage from the environment", "description": "Protects the recipient from adverse natural conditions of all types, including heat, cold, and lack of air; while it lasts the recipient needs no air, food, water, or sleep. It also protects against natural conditions on other planes (e.g. vacuum, underwater, the plane of Fire). It does not protect against magical damage, attacks, poisons, breath weapons, or physical blows from creatures.", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_travel": {"id": "divine_travel", "name": "Travel", "level": 7, "casterType": "divine", "range": "0", "duration": "One turn per level of the caster", "effect": "Allows aerial or gaseous travel", "description": "The caster may fly (as the magic-user's fly spell) at 360' (120') and enter a nearby plane by concentrating one round (maximum one plane per turn). He may take one other creature per five levels, who must be touching; unwilling creatures may save vs. spells, and others cannot be sent alone. By concentrating one round the caster may become gaseous with all equipment, flying 720' (240'); while gaseous he cannot use items or cast spells, can be harmed only by magic, and cannot pass protection from evil or an anti-magic shell.", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_wish": {"id": "divine_wish", "name": "Wish", "level": 7, "casterType": "divine", "range": "Special", "duration": "Special", "effect": "Special", "description": "Castable only by 36th level clerics with 18+ Wisdom. The player states the exact wording, which is usually followed literally; the DM may distort or disallow greedy or unbalanced wishes. It can duplicate any magic-user spell of 8th level or less or clerical/druidic spell of 6th or less. A harmed victim saves vs. spells for half, the rest rebounding on the caster (save at -4). It can grant up to 50,000 gp (costing 1 XP per gp), change an ability score (3-18) for six turns, or raise one permanently (wishes equal to the new score, within a week). It cannot grant XP or levels.", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "divine_wizardry": {"id": "divine_wizardry", "name": "Wizardry", "level": 7, "casterType": "divine", "range": "0 (cleric only)", "duration": "One turn", "effect": "Allows the use of one magic-user device or scroll spell", "description": "The cleric may use one item normally restricted to magic-users: a device (such as a wand) or a scroll of a 1st or 2nd level magic-user spell (not 3rd level or higher). The ability lasts one turn or until the item is used. The cleric knows how to use it as a magic-user would, and is treated as the minimum level needed to cast that spell.", "source": "Rules Cyclopedia, Cleric spells", "isCustom": false},
    "druid_detect_danger": {"id": "druid_detect_danger", "name": "Detect Danger", "level": 1, "casterType": "druid", "range": "5' per level of the caster", "duration": "One hour", "effect": "Reveals hazards", "description": "Combines some effects of detect evil and find traps. The druid concentrates on places, objects or creatures within range: one full round examines one square foot of area, one creature, or one small object (chest, weapon or smaller); larger objects take longer. He learns whether the thing is immediately dangerous, potentially dangerous, or benign (from the druid's point of view; most creatures are potentially dangerous). It detects poisons. Lasts a full hour in natural outdoor settings on the Prime Plane; elsewhere, half duration (three turns).", "source": "Rules Cyclopedia, Druid spells", "isCustom": false},
    "druid_faerie_fire": {"id": "druid_faerie_fire", "name": "Faerie Fire", "level": 1, "casterType": "druid", "range": "60'", "duration": "1 round per level of caster", "effect": "Illuminates creatures or objects", "description": "Outlines one or more creatures or objects (which need only be detected somehow, e.g. by sight or detect invisible) with pale, flickering greenish fire that does no damage. All attacks against an outlined target gain +2 to attack rolls. The druid can outline one man-sized creature (about 12' of fire) per 5 levels; e.g. at 20th level, 48' of fire outlines one dragon-sized, two horse-sized or four man-sized creatures.", "source": "Rules Cyclopedia, Druid spells", "isCustom": false},
    "druid_locate": {"id": "druid_locate", "name": "Locate", "level": 1, "casterType": "druid", "range": "0 (druid only)", "duration": "6 turns", "effect": "Detects 1 animal or plant within 120'", "description": "The druid senses the direction of one known normal animal or plant within 120', similar to locate object. Works on any normal or giant-sized animal, but not fantastic creatures, plant monsters, or any intelligent creature or plant. He must name the exact type of animal or plant but need not have seen the specific one. The target gets no saving throw.", "source": "Rules Cyclopedia, Druid spells", "isCustom": false},
    "druid_predict_weather": {"id": "druid_predict_weather", "name": "Predict Weather", "level": 1, "casterType": "druid", "range": "0 (druid only)", "duration": "12 hours", "effect": "Gives knowledge of coming weather", "description": "The druid learns the accurate weather for the next 12 hours over an area 1 mile in diameter per level (e.g. a 20th level druid learns the weather within a 20-mile diameter, 10-mile radius). It gives no control over the weather.", "source": "Rules Cyclopedia, Druid spells", "isCustom": false},
    "druid_heat_metal": {"id": "druid_heat_metal", "name": "Heat Metal", "level": 2, "casterType": "druid", "range": "30'", "duration": "7 rounds", "effect": "Warms one metal object", "description": "Heats then cools one metal item weighing up to 1/2 lb (5 cn) per caster level (12th level: 6 lb/60 cn; 20th: 10 lb/100 cn). A holder takes 1, 2, 4, 8, 4, 2, 1 points over the seven rounds (22 total), with no saving throw; fire resistance negates it. In round 4, flammables touching the metal catch fire. Magic items are undamaged; normal items may be ruined. The holder may drop it (low-intelligence creatures 80% likely each round); an imbedded item can be removed at the cost of initiative. No concentration needed; only dispel magic stops it. A victim cannot cast spells in any round he takes heat damage.", "source": "Rules Cyclopedia, Druid spells", "isCustom": false},
    "druid_obscure": {"id": "druid_obscure", "name": "Obscure", "level": 2, "casterType": "druid", "range": "0 (druid only)", "duration": "1 turn per level of the caster", "effect": "Creates a huge misty cloud", "description": "Misty vapor rises around the druid, forming a cloud 1' high and 10' in diameter per level (a 20th level druid makes one 20' tall and 200' across). It has no ill effects except blocking vision. The caster and creatures able to see invisible things can see dimly through it; all other creatures inside are delayed, confused and effectively blind.", "source": "Rules Cyclopedia, Druid spells", "isCustom": false},
    "druid_produce_fire": {"id": "druid_produce_fire", "name": "Produce Fire", "level": 2, "casterType": "druid", "range": "0 (druid only)", "duration": "2 turns per level", "effect": "Creates fire in hand", "description": "A small flame appears in the druid's hand, harmless to him and shedding light like a torch. It can ignite combustibles touched to it (lantern, torch, oil, etc.). By concentrating, the caster can make it vanish and reappear once per round until the duration ends, using the hand normally while it is out. It may be dropped or thrown up to 30', but disappears 1 round after leaving his hand (fires it ignites keep burning).", "source": "Rules Cyclopedia, Druid spells", "isCustom": false},
    "druid_warp_wood": {"id": "druid_warp_wood", "name": "Warp Wood", "level": 2, "casterType": "druid", "range": "240'", "duration": "Permanent", "effect": "Causes wooden weapons to bend", "description": "Bends one or more wooden weapons, probably making them useless. Affects one arrow per caster level; a spear, javelin or magical wand counts as two arrows, and any club, bow or staff (magical or not) as four. Only wooden weapons are affected. The wielder of a held magical wooden item may save vs. spells to avoid the effect; items carried but not held get no save. Magical items with pluses have a 10% chance per plus to be unaffected.", "source": "Rules Cyclopedia, Druid spells", "isCustom": false},
    "druid_call_lightning": {"id": "druid_call_lightning", "name": "Call Lightning", "level": 3, "casterType": "druid", "range": "360'", "duration": "1 turn per level of the caster", "effect": "Calls lightning bolts from a storm", "description": "Works only if a storm of any type is taking place within 360' of the druid. He may then call 1 lightning bolt per turn (10 minutes) to strike any point within range, hitting an area 20' across. Each victim in the area takes 8d6 electrical damage (save vs. spells for half). He need not call a bolt every turn; the power remains until the spell's duration or the storm ends.", "source": "Rules Cyclopedia, Druid spells", "isCustom": false},
    "druid_hold_animal": {"id": "druid_hold_animal", "name": "Hold Animal", "level": 3, "casterType": "druid", "range": "180'", "duration": "1 turn per level of the caster", "effect": "Paralyzes several animals", "description": "Affects normal or giant-sized animals, but not fantastic creatures or any with more than animal intelligence (2). Each victim must save vs. spells or be paralyzed for the duration. The druid affects 1 Hit Die of animals per level, ignoring pluses (e.g. a 20th level druid can affect 10 giant toads of 2+2 HD). It can affect summoned, conjured or controlled animals.", "source": "Rules Cyclopedia, Druid spells", "isCustom": false},
    "druid_protection_from_poison": {"id": "druid_protection_from_poison", "name": "Protection from Poison", "level": 3, "casterType": "druid", "range": "Touch", "duration": "One turn per level of the caster", "effect": "Gives one creature immunity to all poison", "description": "The recipient is completely immune to poisons of all types, including gas traps and cloudkill spells, and the protection extends to items carried (e.g. against a spirit's poisonous presence). The recipient also gains +4 on saving throws vs. poisonous breath weapons (such as green dragon breath), but not petrification breath (such as a gorgon's).", "source": "Rules Cyclopedia, Druid spells", "isCustom": false},
    "druid_water_breathing": {"id": "druid_water_breathing", "name": "Water Breathing", "level": 3, "casterType": "druid", "range": "30'", "duration": "1 day", "effect": "One air-breathing creature", "description": "As the magic-user spell of the same name. The recipient can breathe under water at any depth. It does not affect movement in any way, nor interfere with breathing air.", "source": "Rules Cyclopedia, Druid spells", "isCustom": false},
    "druid_control_temperature_10_radius": {"id": "druid_control_temperature_10_radius", "name": "Control Temperature 10' Radius", "level": 4, "casterType": "druid", "range": "0 (druid only)", "duration": "1 turn per level of the caster", "effect": "Cools or warms air within 10'", "description": "The druid alters the temperature in an area 20' across, up to 50 degrees Fahrenheit warmer or cooler. The change is immediate and the area moves with the druid. He changes the temperature by concentrating for 1 round, and it stays changed while the spell lasts. Useful for surviving extremes of heat or cold.", "source": "Rules Cyclopedia, Druid spells", "isCustom": false},
    "druid_plant_door": {"id": "druid_plant_door", "name": "Plant Door", "level": 4, "casterType": "druid", "range": "0 (druid only)", "duration": "1 turn per level of the caster", "effect": "Opens a path through growth", "description": "No plants, however dense, can prevent the druid's passage; even trees bend or open to let him pass. He can carry equipment freely, but no other creature can use the passage. The druid can hide inside a large tree, but cannot see what is happening while inside.", "source": "Rules Cyclopedia, Druid spells", "isCustom": false},
    "druid_protection_from_lightning": {"id": "druid_protection_from_lightning", "name": "Protection from Lightning", "level": 4, "casterType": "druid", "range": "Touch", "duration": "1 turn per level of the caster", "effect": "Protects against lightning attack", "description": "The recipient is immune to 1d6 of electrical damage per caster level; subtract these dice from the dice of damage the recipient would take until they are used up. E.g. from a 20th level druid (20d6) it negates two full 8d6 call lightning attacks and half of a third (the third inflicts 4d6, with the normal save); later attacks do full damage.", "source": "Rules Cyclopedia, Druid spells", "isCustom": false},
    "druid_summon_animals": {"id": "druid_summon_animals", "name": "Summon Animals", "level": 4, "casterType": "druid", "range": "360'", "duration": "3 turns", "effect": "Calls and befriends normal animals", "description": "Summons any or all normal, nonmagical animals of animal intelligence within range (mammals, reptiles, amphibians, etc.; not insects, arthropods, humans or demihumans). The druid may pick known animals, specific types, or everything; total Hit Dice responding equals his level, with small creatures (frogs, mice, etc.) counting 1/10 HD each. They come at top speed, understand his speech, and befriend and help him. A harmed animal normally flees; if the druid is being attacked when it arrives, it attacks the foe, fleeing only on a failed morale check. Can also calm hostile animals.", "source": "Rules Cyclopedia, Druid spells", "isCustom": false},
    "druid_anti_plant_shell": {"id": "druid_anti_plant_shell", "name": "Anti-Plant Shell", "level": 5, "casterType": "druid", "range": "0 (druid only)", "duration": "1 round per level of the druid", "effect": "Personal barrier which blocks plants", "description": "An invisible barrier forms less than an inch from the druid's body, stopping all attacks by plants and plant-like monsters so they inflict no damage. Pushing through dense normal growth opens a path others can use. While protected, the druid cannot attack plants except with spells.", "source": "Rules Cyclopedia, Druid spells", "isCustom": false},
    "druid_control_winds": {"id": "druid_control_winds", "name": "Control Winds", "level": 5, "casterType": "druid", "range": "10' radius per level of the caster", "duration": "1 turn per level of the caster", "effect": "Calms or increases winds", "description": "All air within range behaves as the druid wishes, from dead calm to gale force. A complete change (e.g. calm to gale) takes one full turn of concentration (no moving or attacking). The effect moves with the caster, and a higher-level caster of this spell can easily counter it. Against an air creature (such as an elemental), the victim saves vs. spells; if it fails, the druid can slay or control it. A controlled creature obeys only while he concentrates and the spell lasts, then attacks him.", "source": "Rules Cyclopedia, Druid spells", "isCustom": false},
    "druid_dissolve": {"id": "druid_dissolve", "name": "Dissolve", "level": 5, "casterType": "druid", "range": "240'", "duration": "3-18 days", "effect": "Liquefies 3,000 square feet", "description": "Nearly identical to the magic-user spell of the same name. Turns soil or rock (not a construction) into mud, up to 10' deep with up to 3,000 square feet of surface area, in any dimensions the druid chooses (20' x 150', 30' x 100', etc.), all within 240'. Creatures moving through the mud are slowed to 10% of normal movement at best and may become stuck (at the DM's discretion, save vs. spells to avoid).", "source": "Rules Cyclopedia, Druid spells", "isCustom": false},
    "druid_pass_plant": {"id": "druid_pass_plant", "name": "Pass Plant", "level": 5, "casterType": "druid", "range": "0 (druid only)", "duration": "Instantaneous", "effect": "Short-range teleportation", "description": "The druid enters one tree and immediately steps out of another tree of the same type; both must be large enough to enclose him. Maximum distance depends on the tree: oak 600 yards; ash, elm, linden or yew 360 yards; evergreens 240 yards; other trees 300 yards.", "source": "Rules Cyclopedia, Druid spells", "isCustom": false},
    "druid_anti_animal_shell": {"id": "druid_anti_animal_shell", "name": "Anti-Animal Shell", "level": 6, "casterType": "druid", "range": "0 (druid only)", "duration": "1 turn per level of the caster", "effect": "Personal barrier that blocks animals", "description": "An invisible barrier forms less than an inch from the druid's body, stopping all attacks by normal and giant-sized animals, insects and all other nonfantastic creatures of animal intelligence or less (0-2). While protected, the druid cannot attack such animals except with spells.", "source": "Rules Cyclopedia, Druid spells", "isCustom": false},
    "druid_summon_weather": {"id": "druid_summon_weather", "name": "Summon Weather", "level": 6, "casterType": "druid", "range": "5 miles or more", "duration": "6 turns per level", "effect": "Brings weather to druid's area", "description": "Pulls some known nearby weather condition to the druid's location; he does not control it, only summons it. Range is 5 miles at levels 12-15, plus 1 mile per level above 15th (a 20th level druid can summon weather from 10 miles away). Only a druid of 25th level or higher can summon severe weather (hurricane, severe heat wave, etc.).", "source": "Rules Cyclopedia, Druid spells", "isCustom": false},
    "druid_transport_through_plants": {"id": "druid_transport_through_plants", "name": "Transport Through Plants", "level": 6, "casterType": "druid", "range": "Infinite", "duration": "Instantaneous", "effect": "Long-range teleportation", "description": "Usable at most once per day. The druid must be near a plant of any size and choose a general location or a specific known plant elsewhere; he enters the plant and steps out of one at the destination (a random plant chosen by the DM if he could not specify one). Range is unlimited, but both plants must be living and on the same plane, or the spell fails. He can bring two additional willing creatures.", "source": "Rules Cyclopedia, Druid spells", "isCustom": false},
    "druid_turn_wood": {"id": "druid_turn_wood", "name": "Turn Wood", "level": 6, "casterType": "druid", "range": "30'", "duration": "One turn per level of the druid", "effect": "Pushes all wooden items away", "description": "Creates an invisible wave of force 120' long and 60' tall, centred anywhere within 30', which moves in one horizontal direction at 10' per round to a maximum of 360', then stays for the duration (the druid may stop it early, but can't restart it). Wooden objects it touches stick to it and move with it unharmed; trapped wooden weapons and magic items (wands, staves) can't be used. It moves wooden objects with metal fittings, but not buildings, attached doors, or secured objects such as trees. No concentration needed; the caster can dismiss it by concentrating 1 round.", "source": "Rules Cyclopedia, Druid spells", "isCustom": false},
    "druid_creeping_doom": {"id": "druid_creeping_doom", "name": "Creeping Doom", "level": 7, "casterType": "druid", "range": "120'", "duration": "1 round per level of the caster", "effect": "Creates a 20' x 20' insect horde", "description": "Creates a swarm of 1,000 insects anywhere within 120', filling 20' x 20' up to 60' x 60'. It moves at up to 60' (20') while the caster stays within 120' of it, vanishing if he goes farther. It attacks everything in its path for 1 point per 10 insects (100 points per round to each creature caught, no save). Normal attacks harm it slightly; a fireball kills only 100 insects, reducing damage accordingly. Dispel magic can destroy it; it penetrates protection from evil and crosses most obstacles.", "source": "Rules Cyclopedia, Druid spells", "isCustom": false},
    "druid_metal_to_wood": {"id": "druid_metal_to_wood", "name": "Metal to Wood", "level": 7, "casterType": "druid", "range": "120'", "duration": "Permanent", "effect": "Changes metal into dead wood", "description": "Changes metal items into wood, up to 5 pounds (50 cn) per caster level. Magical metal items are 90% resistant. The change is permanent and cannot be reversed with dispel magic. Affected armor falls off the wearer, and affected weapons become nonmagical wooden clubs.", "source": "Rules Cyclopedia, Druid spells", "isCustom": false},
    "druid_summon_elemental": {"id": "druid_summon_elemental", "name": "Summon Elemental", "level": 7, "casterType": "druid", "range": "240'", "duration": "6 turns", "effect": "Summons one 16 HD elemental", "description": "Summons one 16 HD elemental of the druid's choice (see Chapter 14); he may summon only one of each type (air, earth, fire, water) per day. It understands his spoken commands and performs any tasks within its power. Unlike the magic-user version, no concentration is needed to control it. The caster can send it home with a simple command; others can send it back with dispel magic or dispel evil.", "source": "Rules Cyclopedia, Druid spells", "isCustom": false},
    "druid_weather_control": {"id": "druid_weather_control", "name": "Weather Control", "level": 7, "casterType": "druid", "range": "0 (druid only)", "duration": "Concentration", "effect": "All weather within 240 yards", "description": "Outdoors only, the druid creates one chosen weather condition within 240 yards, affecting all creatures (including himself) while he concentrates without moving (it moves with him if he is carried, e.g. on a ship). Rain: -2 to missile attacks; mud halves movement after 3 turns. Snow or Fog: 20' visibility, half movement (snow leaves mud; fog may get creatures lost). Clear: cancels bad weather but not mud. Intense Heat: half movement, dries up excess water. High Winds: no missile fire or flying, half movement (sandstorm in desert; ships with the wind +50%). Tornado: whirlwind under his control acting as a 12 HD air elemental.", "source": "Rules Cyclopedia, Druid spells", "isCustom": false},
    "arcane_analyze": {"id": "arcane_analyze", "name": "Analyze", "level": 1, "casterType": "arcane", "range": "0 (touch only)", "duration": "1 round", "effect": "Analyzes magic on one item", "description": "The caster handles one item and may learn its enchantment; the item must be used as intended (helm worn, sword held, bracelet on wrist), and any consequences (curses, traps) fall on the caster, who gets his usual saving throws. The chance is 15% plus 5% per caster level to determine one magical characteristic, or to determine that the item is non-magical. Information is imprecise: a weapon's pluses are described as \"many\" or \"few\", charges are estimated within 25% of the actual number.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_charm_person": {"id": "arcane_charm_person", "name": "Charm Person", "level": 1, "casterType": "arcane", "range": "120'", "duration": "See below", "effect": "One living person (see below)", "description": "Affects one human, demihuman or similar human-like creature (not animals, magical creatures, undead, or human-like creatures larger than ogres); it saves vs. spells to negate. A charmed victim regards the caster as its \"best friend\" and defends him; if they share a language, it usually obeys suggestions, but may refuse orders against its nature and always refuses to kill itself. The victim gets a new save every day (Int 13-18), week (Int 9-12) or month (Int 3-8). The charm breaks automatically if the caster attacks the victim.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_detect_magic": {"id": "arcane_detect_magic", "name": "Detect Magic", "level": 1, "casterType": "arcane", "range": "0", "duration": "2 turns", "effect": "Everything within 60'", "description": "All magical objects, creatures and places that are visible and within 60' of the caster glow for the duration. Items hidden from sight (e.g. inside a closed chest) are not seen. No saving throw is allowed.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_floating_disc": {"id": "arcane_floating_disc", "name": "Floating Disc", "level": 1, "casterType": "arcane", "range": "0", "duration": "6 turns", "effect": "Disc remains within 6'", "description": "Creates an invisible, horizontal magical platform the size of a small round shield that carries up to 5,000 cn (500 lbs). It appears at the caster's waist height, cannot be created in an occupied space, and follows the caster at his movement rate, staying within 6'. It cannot be used as a weapon. When the spell ends, the disc vanishes and drops anything on it. No saving throw is allowed.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_hold_portal": {"id": "arcane_hold_portal", "name": "Hold Portal", "level": 1, "casterType": "arcane", "range": "10'", "duration": "2-12 (2d6) turns", "effect": "One door, gate, or similar portal", "description": "Magically holds shut one door, gate or similar portal. A knock spell opens it. A creature with 3 or more Hit Dice more than the caster (or a character 3 or more levels higher) can break it open in one round, but the portal relocks if allowed to close before the duration ends.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_light": {"id": "arcane_light", "name": "Light", "level": 1, "casterType": "arcane", "range": "120'", "duration": "6 turns + 1 turn/level of the caster", "effect": "Volume of 30' diameter", "description": "Creates a ball of light 30' across, like bright torchlight; if cast on an object it moves with the object. If cast at a creature's eyes, the creature saves vs. spells or is blinded for the duration; on a successful save the light appears in the air behind it. Reversed (darkness) creates a 30'-diameter circle of darkness blocking all sight except infravision; it cancels a light spell (and vice versa) and can blind a creature the same way (save vs. spells), until canceled or the duration ends.\nReversible (Darkness).", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_magic_missile": {"id": "arcane_magic_missile", "name": "Magic Missile", "level": 1, "casterType": "arcane", "range": "150'", "duration": "1 round", "effect": "Creates 1 or more arrows", "description": "Creates a glowing magical arrow that hovers beside the caster until he shoots it (within the 1 round duration), then automatically hits any one visible target he chooses for 1d6+1 (2-7) damage; there is no attack roll and no saving throw. For every 5 caster levels, 2 more missiles are created (3 at level 6, 5 at level 11, etc.), which may be shot at one or several targets.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_protection_from_evil": {"id": "arcane_protection_from_evil", "name": "Protection from Evil", "level": 1, "casterType": "arcane", "range": "0", "duration": "6 turns", "effect": "The spellcaster only", "description": "Creates an invisible barrier around the caster: attacks against him suffer -1 to hit and he gains +1 to all saving throws. Enchanted creatures (those hit only by magical weapons, or magically summoned or controlled, such as charmed characters) cannot attack him in melee, though they may use missiles (at -1). It does not affect magic missiles. If the caster makes a melee attack during the spell, enchanted creatures may then touch him, but the attack and save adjustments still apply.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_read_languages": {"id": "arcane_read_languages", "name": "Read Languages", "level": 1, "casterType": "arcane", "range": "0", "duration": "2 turns", "effect": "The spellcaster only", "description": "For the duration, the caster can read (not speak) any unknown languages or codes, including treasure maps, secret symbols and so forth.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_read_magic": {"id": "arcane_read_magic", "name": "Read Magic", "level": 1, "casterType": "arcane", "range": "0", "duration": "1 turn", "effect": "The spellcaster only", "description": "The caster can read (not speak) magical words or runes, such as those on scrolls and other items; unfamiliar magical writings cannot be understood without it. Once the caster has read a given scroll or runes with this spell, he can read or speak that magic later without the spell. Only a spell book's owner may read it without this spell.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_shield": {"id": "arcane_shield", "name": "Shield", "level": 1, "casterType": "arcane", "range": "0", "duration": "2 turns", "effect": "The spellcaster only", "description": "Creates a magical barrier around the caster that moves with him, giving him AC 2 against missiles and AC 4 against all other attacks. Against each magic missile shot at him, the caster may save vs. spells; if successful, that missile has no effect.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_sleep": {"id": "arcane_sleep", "name": "Sleep", "level": 1, "casterType": "arcane", "range": "240'", "duration": "4d4 (4-16) turns", "effect": "2-16 Hit Dice of living creatures within a 40' square area", "description": "Puts to sleep 2d8 Hit Dice (or levels) of living creatures within a 40' x 40' area chosen by the caster; only creatures of 4+1 Hit Dice or less are affected, and not undead or very large creatures such as dragons. No saving throw is allowed. Sleepers are not woken by falling, but wake if slapped, kicked or shaken. A sleeping victim can be killed with a single blow of any edged weapon, regardless of its hit points.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_ventriloquism": {"id": "arcane_ventriloquism", "name": "Ventriloquism", "level": 1, "casterType": "arcane", "range": "60'", "duration": "2 turns", "effect": "One item or location", "description": "The caster can make his voice seem to come from somewhere else within 60', such as a statue, an animal or a dark corner.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_continual_light": {"id": "arcane_continual_light", "name": "Continual Light", "level": 2, "casterType": "arcane", "range": "120'", "duration": "Permanent", "effect": "Volume of 60' diameter", "description": "Creates a globe of light 60' across, brighter than a torch but less than daylight, which lasts until magically removed; it may be cast on an object. If cast at a creature's eyes, the creature saves vs. spells or is blinded permanently (until dispelled); on a success the globe appears where cast with no ill effect. Reversed (continual darkness) creates complete darkness in a 30' radius that torches, lanterns, light spells and infravision cannot penetrate; cast on a creature's eyes it blinds unless the victim saves vs. spells. A continual light cancels it.\nReversible (Continual Darkness).", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_detect_evil": {"id": "arcane_detect_evil", "name": "Detect Evil", "level": 2, "casterType": "arcane", "range": "60'", "duration": "2 turns", "effect": "Everything within 60'", "description": "Evilly-enchanted objects within 60' glow, as do creatures within range that want to harm the caster; their thoughts are not revealed. Chaotic alignment is not automatically evil, and traps and poison are neither good nor evil.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_detect_invisible": {"id": "arcane_detect_invisible", "name": "Detect Invisible", "level": 2, "casterType": "arcane", "range": "10' per level of the spellcaster", "duration": "6 turns", "effect": "The spellcaster only", "description": "The caster can see all invisible creatures and objects within 10' per caster level (e.g. 30' at 3rd level).", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_entangle": {"id": "arcane_entangle", "name": "Entangle", "level": 2, "casterType": "arcane", "range": "30'", "duration": "1 round per level", "effect": "Controls ropes", "description": "The caster commands a rope-like object of living or once-living material (roots, vines, leather or plant-fibre rope): about 50' of 1/2\" vine plus 5' per caster level. Commands include coil, coil and knot, loop, loop and knot, tie and knot, and their reverses; the rope must be within 1' of what it is to tie, so it is often thrown. Coil and knot effectively ties up a victim; a creature attacked this way may save vs. spells to avoid the effect.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_esp": {"id": "arcane_esp", "name": "ESP", "level": 2, "casterType": "arcane", "range": "60'", "duration": "12 turns", "effect": "All thoughts in one direction", "description": "The caster concentrates in one direction for 6 rounds to hear and understand the thoughts of a living creature within 60', regardless of language (not undead); several creatures produce a jumble that takes 6 more rounds to sort out. It penetrates wood, liquid and up to 2' of rock, but thin lead blocks it. Targets may save vs. spells to avoid it. Reversed (mindmask), cast by touch, makes one creature immune to ESP and all other mind-reading for the duration.\nReversible (Mindmask).", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_invisibility": {"id": "arcane_invisibility", "name": "Invisibility", "level": 2, "casterType": "arcane", "range": "240'", "duration": "Permanent until broken", "effect": "One creature or object", "description": "Makes one creature or object invisible. A creature's carried and worn items also become invisible, but become visible when they leave its possession; a light source can be made invisible but its light stays visible. An invisible object not carried becomes visible when touched by a living creature. An invisible creature stays invisible until it attacks or casts a spell.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_knock": {"id": "arcane_knock", "name": "Knock", "level": 2, "casterType": "arcane", "range": "60'", "duration": "See below", "effect": "One lock or bar", "description": "Opens any lock, including a normal or magically locked door (hold portal or wizard lock), a found secret door, a stuck or locked gate, or a treasure chest; it also forces a door's bar to fall. Locking magic remains and takes effect again when the door is closed. If a door is both locked and barred, only one is opened.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_levitate": {"id": "arcane_levitate", "name": "Levitate", "level": 2, "casterType": "arcane", "range": "0", "duration": "6 turns + 1 turn/level of the caster", "effect": "The spellcaster only", "description": "The caster can move up or down through the air without support at 20' per round, but cannot move sideways except by pushing and pulling on objects. It cannot be cast on others. The caster may carry up to 2,000 cn (200 lbs), possibly another man-sized creature not in metal armor. No saving throw is allowed.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_locate_object": {"id": "arcane_locate_object", "name": "Locate Object", "level": 2, "casterType": "arcane", "range": "60' + 10' per level of the spellcaster", "duration": "2 turns", "effect": "One object within range", "description": "The spell points toward the nearest designated object within range (e.g. 80' at 2nd level), giving direction but not distance. The caster must know exactly what the object looks like, or may name a common type of object such as \"any flight of stairs\".", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_mirror_image": {"id": "arcane_mirror_image", "name": "Mirror Image", "level": 2, "casterType": "arcane", "range": "0", "duration": "6 turns", "effect": "The spellcaster only", "description": "Creates 1d4 images of the caster that stay within 3' and mimic his actions; no concentration is required. Any successful attack on the caster strikes an image instead, which disappears regardless of damage, until all are gone. An area attack such as a fireball dispels all images and affects the caster.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_phantasmal_force": {"id": "arcane_phantasmal_force", "name": "Phantasmal Force", "level": 2, "casterType": "arcane", "range": "240'", "duration": "Concentration (see below)", "effect": "A volume 20' x 20' x 20'", "description": "Creates an illusion in a 20' cube; illusions of things the caster has not seen give viewers a saving throw bonus. A non-attacking illusion vanishes when touched; an illusory monster is AC 9 and vanishes when hit. Against an illusory attack the victim saves vs. spells to realize it is illusion and be unaffected. It lasts while the caster concentrates; moving, taking damage or failing a save ends it. It never does real damage: those \"killed\" fall unconscious, \"petrified\" are paralyzed, etc., for 1d4 turns; a successful save removes the damage at once.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_web": {"id": "arcane_web", "name": "Web", "level": 2, "casterType": "arcane", "range": "10'", "duration": "48 turns", "effect": "A volume 10' x 10' x 10'", "description": "Creates a mass of sticky strands filling a 10' cube, usually blocking the area. Giants and other very strong creatures break through in 2 rounds, someone with gauntlets of ogre power in 4 rounds, and a human of average Strength (9-12) in 2d4 turns. Flame destroys the web in 2 rounds, but everyone within it takes 1d6 fire damage.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_wizard_lock": {"id": "arcane_wizard_lock", "name": "Wizard Lock", "level": 2, "casterType": "arcane", "range": "10'", "duration": "Permanent", "effect": "One portal or lock", "description": "A more powerful hold portal that works on any lock and lasts until dispelled; a knock spell opens it. The caster, or any magic-using character or creature 3 or more levels (or Hit Dice) higher than the caster, can open it easily, but this does not remove the magic and the lock relocks when closed.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_clairvoyance": {"id": "arcane_clairvoyance", "name": "Clairvoyance", "level": 3, "casterType": "arcane", "range": "60'", "duration": "12 turns", "effect": "See through another's eyes", "description": "The caster sees through the eyes of any single creature within 60'. Seeing through one creature takes a full turn, after which he can switch to another, in any direction, without recasting. Two feet of rock or a thin coating of lead blocks it. No saving throw is allowed.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_create_air": {"id": "arcane_create_air", "name": "Create Air", "level": 3, "casterType": "arcane", "range": "Immediate area, 8,000 cu. ft.", "duration": "1 hour per level of caster", "effect": "Provides breathable air", "description": "Provides breathable air in a volume of 8,000 cubic feet (such as a 20' cube), which stays in place. It can instead be cast on an enclosed vehicle interior (moving with it), on a person (who can breathe anywhere, even underwater, but constantly bubbles air), or on equipment such as a helmet for its wearer. A flying creature so enchanted can fly through airless void. It does not protect against poison gases unless they are a normal part of the atmosphere.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_dispel_magic": {"id": "arcane_dispel_magic", "name": "Dispel Magic", "level": 3, "casterType": "arcane", "range": "120'", "duration": "Permanent", "effect": "Destroys spells in a 20' cube", "description": "Destroys spell effects in a 20' cube. Effects by a caster of equal or lower level are automatically dispelled; effects by a higher-level caster have a 5% chance per level of difference to resist (e.g. 10% for a 7th level caster vs. a 9th level caster's spell). It does not affect magic items themselves, but can end the effects of an item in use (e.g. free the victim of a ring of human control).", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_fireball": {"id": "arcane_fireball", "name": "Fireball", "level": 3, "casterType": "arcane", "range": "240'", "duration": "Instantaneous", "effect": "Explosion in a sphere 40' diameter", "description": "A missile of fire bursts into a 40' diameter (20' radius) ball where it strikes, inflicting 1d6 fire damage per caster level (e.g. 6d6 at 6th level) to every creature in the area. Each victim may save vs. spells for half damage.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_fly": {"id": "arcane_fly", "name": "Fly", "level": 3, "casterType": "arcane", "range": "Touch", "duration": "1d6 (1-6) turns + 1 turn per level of the caster", "effect": "One creature may fly", "description": "The recipient (possibly the caster) can fly in any direction at any speed up to 360' (120') by concentration, and may stop and hover as with levitate without concentrating.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_haste": {"id": "arcane_haste", "name": "Haste", "level": 3, "casterType": "arcane", "range": "240'", "duration": "3 turns", "effect": "Up to 24 creatures move double speed", "description": "Up to 24 creatures in a 60' diameter circle move at up to double speed and make double the normal number of missile or melee attacks. It does not speed magic: a hasted caster still casts one spell per round, and use of magic devices is not sped up. Reversed (slow), it removes a haste spell or makes victims move and attack at half speed (not affecting spellcasting or magic devices); victims may save vs. spells to avoid it.\nReversible (Slow).", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_hold_person": {"id": "arcane_hold_person", "name": "Hold Person", "level": 3, "casterType": "arcane", "range": "120'", "duration": "1 turn/level", "effect": "Paralyzes up to 4 creatures", "description": "Affects humans, demihumans and human-like creatures (e.g. bugbears, gnolls, orcs, ogres, sprites), not undead or creatures larger than ogres. Each victim saves vs. spells or is paralyzed for nine turns. Cast at one target, the save is at -2; cast at a group, up to four are affected with no penalty. The paralysis is removed only by the reverse or dispel magic. Reversed (free person), it frees up to four victims of hold person (including a cleric's), with no other effect (e.g. not ghoul paralysis).\nReversible (Free Person).", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_infravision": {"id": "arcane_infravision", "name": "Infravision", "level": 3, "casterType": "arcane", "range": "Touch", "duration": "1 day", "effect": "One living creature", "description": "The recipient can see heat in the dark to 60', like dwarves and elves: warm things appear red, cold things blue, and same-temperature objects faintly outlined. It does not work in normal or magical light, and heat sources can interfere. It is not good enough to read by, and individuals can be recognized only within 10' unless very distinctive.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_invisibility_10_radius": {"id": "arcane_invisibility_10_radius", "name": "Invisibility 10' Radius", "level": 3, "casterType": "arcane", "range": "120'", "duration": "Permanent until broken", "effect": "All creatures within 10'", "description": "Makes the recipient and all others within 10' of him at casting invisible, along with their carried items. Anyone who moves more than 10' from the recipient becomes visible and cannot regain invisibility by returning. Otherwise it works like invisibility: each creature stays invisible until it attacks or casts a spell.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_lightning_bolt": {"id": "arcane_lightning_bolt", "name": "Lightning Bolt", "level": 3, "casterType": "arcane", "range": "180'", "duration": "Instantaneous", "effect": "Bolt 60' long, 5' wide", "description": "Creates a lightning bolt starting up to 180' from the caster and extending 60' further in a straight line. All creatures in it take 1d6 damage per caster level (e.g. 6d6 at 6th level), or half with a successful save vs. spells. If it strikes a solid surface, it bounces back toward the caster until its total length is 60'.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_protection_from_evil_10_radius": {"id": "arcane_protection_from_evil_10_radius", "name": "Protection from Evil 10' Radius", "level": 3, "casterType": "arcane", "range": "0", "duration": "12 turns", "effect": "Barrier 20' diameter", "description": "Creates a barrier in a 10' radius around the caster, protecting against monsters of an alignment other than the caster's. Everyone within gains +1 to all saves, and attacks against them suffer -1 to hit. Enchanted creatures (summoned, controlled such as charmed, or hit only by magic weapons) cannot melee those within, but may use missile or magical attacks at -1. If anyone inside attacks an enchanted creature, it may then melee them, though the bonus and penalty still apply.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_protection_from_normal_missiles": {"id": "arcane_protection_from_normal_missiles", "name": "Protection from Normal Missiles", "level": 3, "casterType": "arcane", "range": "30'", "duration": "12 turns", "effect": "One creature", "description": "One creature within 30' gains complete protection from small nonmagical missiles (arrows, quarrels, thrown spears, etc.), which simply miss. Large or magical missiles, such as catapult stones or magic arrows, are not affected.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_water_breathing": {"id": "arcane_water_breathing", "name": "Water Breathing", "level": 3, "casterType": "arcane", "range": "30'", "duration": "1 day (24 hours)", "effect": "One air-breathing creature", "description": "The recipient can breathe underwater at any depth. It does not affect his movement, nor his ability to breathe air if he leaves the water.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_charm_monster": {"id": "arcane_charm_monster", "name": "Charm Monster", "level": 4, "casterType": "arcane", "range": "120'", "duration": "Special", "effect": "One or more living creatures", "description": "Works like charm person but affects any creature except undead. If cast on victims of 3 Hit Dice or less, it charms 3d6 of them; otherwise it charms only one victim. Each victim may save vs. spells to avoid it.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_clothform": {"id": "arcane_clothform", "name": "Clothform", "level": 4, "casterType": "arcane", "range": "Touch", "duration": "Permanent", "effect": "Creates up to 30' x 30' cloth", "description": "Creates one piece of nonmagical, undispellable cloth like undyed linen, up to 30' x 30'. With a suitable Craft skill the caster may shape it as created (tent, sail, garment, 60' of rope, etc.). An unfinished edge may later be extended seamlessly by another clothform. The cloth extrudes from the caster's hands along the ground, piling against obstacles without moving them; it cannot be dropped over enemies, attached to anything but other clothform cloth, or created in an occupied space.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_confusion": {"id": "arcane_confusion", "name": "Confusion", "level": 4, "casterType": "arcane", "range": "120'", "duration": "12 rounds", "effect": "3-18 creatures in an area 60' across", "description": "Confuses creatures within a 30' radius. Victims of less than 2+1 Hit Dice get no saving throw; those of 2+1 HD or more must save vs. spells each round they remain in the area or be confused. Each round the DM rolls 2d6 for each confused creature: 2-5 attacks the caster's party, 6-8 does nothing, 9-12 attacks its own party.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_dimension_door": {"id": "arcane_dimension_door", "name": "Dimension Door", "level": 4, "casterType": "arcane", "range": "10'", "duration": "1 round", "effect": "Safely transport one creature", "description": "Transports one creature (the caster or one within 10') to a place up to 360' away, chosen by the caster or given as directions and distances totaling no more than 360'. If the destination is occupied by a solid object, the spell has no effect. An unwilling recipient may save vs. spells to avoid it.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_growth_of_plants": {"id": "arcane_growth_of_plants", "name": "Growth of Plants", "level": 4, "casterType": "arcane", "range": "120'", "duration": "Special", "effect": "Enlarges 3000 square feet of plants", "description": "Normal brush or woods within range, in an area of up to 3,000 square feet shaped by the caster, become thickly overgrown and impassable to all but giant-sized creatures, until removed by the reverse or dispel magic. Reversed (shrink plants), it makes all normal plants in the area shrink and become passable, and can negate the normal spell; it does not affect plant-like monsters such as treants.\nReversible (Shrink Plants).", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_hallucinatory_terrain": {"id": "arcane_hallucinatory_terrain", "name": "Hallucinatory Terrain", "level": 4, "casterType": "arcane", "range": "240'", "duration": "Special", "effect": "Changes or hides terrain in 240' radius (or less)", "description": "Creates the illusion of a terrain feature, indoors (pit, stairs) or outdoors (hill, swamp, grove), possibly hiding a real one, such as solid ground over pits or forest over a camp. It may cover a small area or a large feature, but the whole feature must be within range (a hill over 480' across cannot be affected). It lasts until the illusion is touched by an intelligent creature or dispelled.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_ice_storm_wall_of_ice": {"id": "arcane_ice_storm_wall_of_ice", "name": "Ice Storm/Wall of Ice", "level": 4, "casterType": "arcane", "range": "120'", "duration": "Storm, 1 round; Wall, 12 turns", "effect": "Storm in 20' x 20' x 20' volume; or Wall of 1,200 square feet", "description": "Ice storm fills a 20' cube, dealing 1d6 cold damage per caster level to all within (save vs. spells for half); fire-type creatures save at -4, and cold-type creatures are unaffected. Wall of ice is a thin opaque vertical wall of up to 1,200 square feet in any shape, resting on the ground and not in an occupied space. Creatures under 4 Hit Dice cannot break through; those of 4 HD or more can, taking 1d6 damage (fire-type creatures 2d6).", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_massmorph": {"id": "arcane_massmorph", "name": "Massmorph", "level": 4, "casterType": "arcane", "range": "240'", "duration": "See below", "effect": "Causes illusion of trees within 240' range", "description": "Makes up to 100 willing human or man-sized creatures in a 240' diameter appear as trees or other large plants suited to the region (larger creatures count as two or three each), hiding them from creatures moving through the area. Unwilling creatures are unaffected. A creature leaving the area looks normal again, but movement within it does not break the illusion. It lasts until dispelled or dropped by the caster.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_polymorph_other": {"id": "arcane_polymorph_other", "name": "Polymorph Other", "level": 4, "casterType": "arcane", "range": "60'", "duration": "Permanent until dispelled", "effect": "Changes one living creature", "description": "Turns one living creature into another creature with no more than twice its original Hit Dice (or the spell fails); its hit points stay the same. The victim truly becomes the new creature, gaining its special abilities, tendencies and behavior. It cannot duplicate a specific individual, only a race or type (a \"9th level fighter\" becomes a human, not above 1st level). The victim may save vs. spells to avoid it; it lasts until dispelled or the creature dies.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_polymorph_self": {"id": "arcane_polymorph_self", "name": "Polymorph Self", "level": 4, "casterType": "arcane", "range": "0 (Caster only)", "duration": "6 turns + 1 turn per level of the caster", "effect": "Caster may change shapes", "description": "The caster takes the physical form of a living creature whose Hit Dice do not exceed his own. His AC, hit points, attack rolls and saves are unchanged, and he gains the form's natural physical abilities (strength, flight, hurling boulders) but not its special abilities, immunities, breath weapons or spells. He cannot cast spells while polymorphed or become a specific individual. It lasts for the duration, until dispelled, or until the caster is killed.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_remove_curse": {"id": "arcane_remove_curse", "name": "Remove Curse", "level": 4, "casterType": "arcane", "range": "Touch", "duration": "Permanent", "effect": "Removes any one curse", "description": "Removes one curse from a character, item or area; some curses, especially on magic items, may be only temporarily removed (DM's discretion), needing a dispel evil or a high-level caster's remove curse. Reversed (curse), it places a misfortune or penalty on the recipient, who may save vs. spells to avoid it; safe limits include -4 on attack rolls, -2 on all saves, or prime requisite halved. An overly powerful curse may rebound on the caster (DM's discretion).\nReversible (Curse).", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_wall_of_fire": {"id": "arcane_wall_of_fire", "name": "Wall of Fire", "level": 4, "casterType": "arcane", "range": "60'", "duration": "Concentration", "effect": "Creates 1200 square feet of fire", "description": "Creates a thin, opaque vertical wall of fire of any shape totaling 1,200 square feet (e.g. 10' x 120' or 30' x 40'), not in an occupied space; it lasts as long as the caster concentrates without moving. Creatures under 4 Hit Dice cannot break through; those of 4 HD or more can, taking 1d6 damage. Undead and cold-using creatures (white dragons, frost giants, etc.) take double damage breaking through.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_wizard_eye": {"id": "arcane_wizard_eye", "name": "Wizard Eye", "level": 4, "casterType": "arcane", "range": "240'", "duration": "6 turns", "effect": "Creates movable invisible eye", "description": "Creates an invisible, eye-sized floating eye with 60' infravision through which the caster sees while concentrating without moving. It moves up to 120' per turn, cannot pass through solid objects, and cannot go more than 240' from the caster.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_animate_dead": {"id": "arcane_animate_dead", "name": "Animate Dead", "level": 5, "casterType": "arcane", "range": "60'", "duration": "Permanent", "effect": "Creates zombies or skeletons", "description": "Turns normal skeletons or dead bodies within range into animated skeletons or zombies that obey the caster until destroyed by a cleric or a dispel magic spell. The caster may animate 1 Hit Die of undead per experience level. A skeleton has the original creature's Hit Dice; a zombie has 1 HD more. Humans and demihumans count as 1 HD creatures regardless of level (so a 9th level thief becomes a 2 HD zombie). The undead have no spells but are immune to sleep, charm and poison. Animating the dead is usually a Chaotic act.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_cloudkill": {"id": "arcane_cloudkill", "name": "Cloudkill", "level": 5, "casterType": "arcane", "range": "1'", "duration": "6 turns", "effect": "Creates a moving poisonous cloud", "description": "Creates a poisonous cloud 30' across and 20' tall next to the caster, which moves away at 60' (20' per round) with the wind, or in a direction chosen by the caster. It is heavier than air and sinks down holes and slopes, evaporates on hitting trees or thick vegetation, and may be smaller in cramped spaces. All living creatures in the cloud take 1 point of damage per round; any victim of less than 5 Hit Dice must save vs. poison or be killed.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_conjure_elemental": {"id": "arcane_conjure_elemental", "name": "Conjure Elemental", "level": 5, "casterType": "arcane", "range": "240'", "duration": "Concentration", "effect": "Summons one 16 HD elemental", "description": "Summons one elemental (AC -2, HD 16, Damage 3d8); only one of each type (earth, air, fire, water) per day. It performs any task within its power while the caster concentrates; the caster cannot fight, cast spells or move over half Normal Speed without losing control, and control cannot be regained. An uncontrolled elemental tries to slay its summoner, attacking anyone in its path. The caster may send a controlled elemental home by concentration; dispel magic or dispel evil can return an uncontrolled one.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_contact_outer_plane": {"id": "arcane_contact_outer_plane", "name": "Contact Outer Plane", "level": 5, "casterType": "arcane", "range": "0 (spellcaster only)", "duration": "See below", "effect": "3-12 questions may be answered", "description": "The caster contacts an Immortal on an outer plane to seek knowledge. He chooses the plane's \"distance\" (3 to 12), which equals the number of questions he may ask; more distant planes give better chances of a correct answer (knowing 25%-95%, lying 50%-5%) but greater chance of insanity (5% at distance 3 up to 50% at 12), checked once on first contact. Insanity chance drops 5% per caster level above 20th. The Immortal may not know or may lie. Usable at most once a month; an insane caster recovers after weeks of rest equal to the plane's number.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_dissolve": {"id": "arcane_dissolve", "name": "Dissolve", "level": 5, "casterType": "arcane", "range": "120'", "duration": "3-18 days", "effect": "Liquifies 3000 square feet", "description": "Turns soil or rock (not constructions) into mud, up to 10' deep and 3,000 square feet in area, shaped as the caster wishes (20' x 150', 30' x 100', etc.) and wholly within 240' of the caster. Creatures moving through the mud are slowed to 10% of normal movement at best and may become stuck (at the DM's discretion, a save vs. spells avoids this). The reverse, harden, permanently turns the same volume of mud into rock; a victim in the mud may save vs. spells to avoid being trapped.\nReversible (Harden).", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_feeblemind": {"id": "arcane_feeblemind", "name": "Feeblemind", "level": 5, "casterType": "arcane", "range": "240'", "duration": "Permanent until dispelled", "effect": "Lowers Intelligence score to 2", "description": "Affects only magic-users, elves, or monsters that cast magical (magic-user) spells; it does not affect those who cast only cleric or druid spells. The victim becomes helpless, unable to cast spells or think clearly, as if Intelligence were 2. The victim may save vs. spells at -4 to avoid it. Lasts until removed by dispel magic (normal chances) or a cleric's cureall spell.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_hold_monster": {"id": "arcane_hold_monster", "name": "Hold Monster", "level": 5, "casterType": "arcane", "range": "120'", "duration": "6 turns + 1 turn per level of the caster", "effect": "Paralyzes 1-4 creatures", "description": "As hold person, but affects any living creature (not undead). Each victim must save vs. spells or be paralyzed. Cast at a single creature, the victim saves at -2; cast at a group, it affects 1d4 creatures of the caster's choice within range with no save penalty. The reverse, free monster, removes the paralysis of up to four victims of hold person or hold monster spells and has no other effect.\nReversible (Free Monster).", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_magic_jar": {"id": "arcane_magic_jar", "name": "Magic Jar", "level": 5, "casterType": "arcane", "range": "30'", "duration": "See below", "effect": "Take over one body", "description": "The caster's body falls into a trance and his life force enters an inanimate object (the magic jar) within range. From it he may try to possess any creature within 120' of the jar; the victim saves vs. spells to resist (caster cannot retry for 1 turn), otherwise the victim's life force goes into the jar. The caster can use the body's normal actions but not special abilities; dispel evil forces him back into the jar. If the possessed body dies, the victim dies and the caster returns to the jar. If the jar is destroyed with the caster in it, he dies; if destroyed while he possesses a body, he is stranded there and the victim is destroyed. Possession is a Chaotic act.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_passwall": {"id": "arcane_passwall", "name": "Passwall", "level": 5, "casterType": "arcane", "range": "30'", "duration": "3 turns", "effect": "Creates a hole 10' deep", "description": "Opens a hole 5' in diameter and 10' deep, horizontal or vertical, in solid rock or stone only. The stone returns when the spell ends; anyone still in the tunnel must save vs. turn to stone: success means he is hurled out the nearest end, failure means he is trapped in the stone and dies.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_telekinesis": {"id": "arcane_telekinesis", "name": "Telekinesis", "level": 5, "casterType": "arcane", "range": "120'", "duration": "6 rounds", "effect": "200 cn of weight per level of caster", "description": "The caster moves a creature or object by concentration, up to 200 cn (20 lbs) per caster level, in any direction at up to 20' per round. An unwilling victim may save vs. spells to avoid being moved. Someone holding a target may save at -2 to keep it; an owner of a carried but unheld object may grab it with a save vs. spells at -5. Objects fall if the caster's concentration is disturbed.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_teleport": {"id": "arcane_teleport", "name": "Teleport", "level": 5, "casterType": "arcane", "range": "10'", "duration": "Instantaneous", "effect": "Transports one creature with equipment", "description": "Instantly transports the caster or one other recipient, with all carried equipment, to any unoccupied destination on the same plane; an unwilling victim may save vs. spells. The destination must be on a surface, not in the air or a known solid object. The DM rolls d% by the caster's knowledge of the destination: Casual (success 01-50, too high 51-75, too low 76-00), General (01-80, 81-90, 91-00) or Exact (01-95, 96-99, 00). Too high: arrives 1d10 x 10' up and falls for 1d6 per 10' (unless flying or levitating). Too low: arrives 1d10 x 10' below, killed instantly if in solid matter.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_wall_of_stone": {"id": "arcane_wall_of_stone", "name": "Wall of Stone", "level": 5, "casterType": "arcane", "range": "60'", "duration": "Special", "effect": "Creates 1000 cubic feet of stone", "description": "Creates a vertical stone wall exactly 2' thick with a total area up to 500 square feet (10' x 50', 20' x 25', etc.), shaped as the caster chooses and entirely within 60'. It must rest on the ground or similar support and cannot be created in a space occupied by another object. It lasts until dispelled or physically broken. If toppled, it inflicts 10d10 points of damage to what it hits and shatters.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_woodform": {"id": "arcane_woodform", "name": "Woodform", "level": 5, "casterType": "arcane", "range": "Touch", "duration": "Permanent", "effect": "Creates 1,000 cubic feet of wood", "description": "Creates 1,000 cubic feet of wood in any single-piece shape with no moving parts (10' x 10' x 10' block, 25' x 20' x 2' wall, etc.), resting on a support and not in an occupied space. Casting takes 1 round for simple shapes, 1 turn for a staircase, up to 12 turns for complex designs (DM decides). The caster may recast it on his creation to modify it for up to two hours, then \"lock\" it with a final casting; rough sides can be seamlessly joined by later woodforms. The wood is not dispellable; it has AC -4(6) and 60 hp per 1' of thickness.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_anti_magic_shell": {"id": "arcane_anti_magic_shell", "name": "Anti-Magic Shell", "level": 6, "casterType": "arcane", "range": "0 (Caster only)", "duration": "12 turns", "effect": "Personal barrier which blocks magic", "description": "Creates an invisible barrier just around the caster's body that stops all spells and spell effects, including the caster's own. The caster may end the shell at will; otherwise it lasts the full duration. No magic except a wish (not even dispel magic) can cancel it.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_death_spell": {"id": "arcane_death_spell", "name": "Death Spell", "level": 6, "casterType": "arcane", "range": "240'", "duration": "Instantaneous", "effect": "Slays 4d8 (4-32) Hit Dice of creatures within a 60' x 60' x 60' area", "description": "Affects 4d8 Hit Dice of living creatures in the area, lowest Hit Dice first; each victim must save vs. death ray or die. Normal plants and insects are automatically slain and those with no hit points are not counted in the total. Undead and creatures of 8 or more Hit Dice (or levels) are not affected.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_disintegrate": {"id": "arcane_disintegrate", "name": "Disintegrate", "level": 6, "casterType": "arcane", "range": "60'", "duration": "Instantaneous", "effect": "Destroys one creature or object", "description": "Causes one creature or nonmagical object (such as a dragon, a ship, or a 10' section of wall) to crumble to dust. A victim may save vs. death ray to avoid the effect. It does not affect magical items or spell effects.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_geas": {"id": "arcane_geas", "name": "Geas", "level": 6, "casterType": "arcane", "range": "30'", "duration": "Until completed or removed", "effect": "Compels one creature", "description": "Forces the victim to perform or avoid a stated action; the victim may save vs. spells when it is cast. The action must be possible and not directly fatal, or the geas affects the caster instead. If the victim ignores it, DM-chosen penalties (combat penalties, lowered abilities, lost spells, pain and weakness) apply until he obeys or dies. Dispel magic and remove curse do not affect it. The victim knows it is not his own idea and may seek revenge afterward. The reverse, remove geas, rids a character of a geas, with a 5% chance of failure per level the caster is below the original caster.\nReversible (Remove Geas).", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_invisible_stalker": {"id": "arcane_invisible_stalker", "name": "Invisible Stalker", "level": 6, "casterType": "arcane", "range": "0 (Caster only)", "duration": "Until mission is accomplished", "effect": "Summons one creature", "description": "Summons an invisible stalker which performs one task for the caster, regardless of time or distance, until the task is completed or the creature is slain. A dispel evil spell forces it back to its home plane.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_lower_water": {"id": "arcane_lower_water", "name": "Lower Water", "level": 6, "casterType": "arcane", "range": "240'", "duration": "10 turns", "effect": "Cuts depths to half normal", "description": "Lowers a body of water to half its normal depth over an area up to 10,000 square feet. On a constantly renewed source (river, ocean), the area stays lowered for the duration or until dispelled; surrounding water does not rush in until the spell ends. A ship in the area may become stuck. When the spell ends, the rushing water sweeps a ship's deck clear of most items (and people who fail a save vs. spells) and inflicts 1d12+20 (21-32) points of hull damage.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_move_earth": {"id": "arcane_move_earth", "name": "Move Earth", "level": 6, "casterType": "arcane", "range": "240'", "duration": "6 turns", "effect": "Moves soil", "description": "Moves soil (but not rock) horizontally, such as to make a hill, or vertically to open a hole up to 240' deep (unless solid rock is reached). The soil moves at up to 60' per turn and remains where it is put when the spell ends. Useful for constructing castles.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_projected_image": {"id": "arcane_projected_image", "name": "Projected Image", "level": 6, "casterType": "arcane", "range": "240'", "duration": "6 turns", "effect": "Creates one image", "description": "Creates an image of the caster up to 240' away that lasts without concentration and can be told from the original only by touch. Spells the caster casts seem to come from the image, though he must still see the target. Spells and missiles appear not to affect it; it disappears if touched or struck by a hand-to-hand weapon.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_reincarnation": {"id": "arcane_reincarnation", "name": "Reincarnation", "level": 6, "casterType": "arcane", "range": "10'", "duration": "Permanent", "effect": "Creates a new body", "description": "Using any part of a dead body, creates a new body which the departed life force returns to inhabit. The DM chooses or rolls 1d8: 1-3 human, 4 dwarf, 5 elf, 6 halfling, 7 original race, 8 monster (rolled by alignment, e.g. Lawful: blink dog, gnome, neanderthal, giant owl, pegasus, treant). A new race brings all its details (a cleric reincarnated as an elf becomes an elf). Experience level is kept unless limited by demihuman maximums. A monster body cannot gain levels; the character plays the creature, retires, or may be reincarnated again when slain.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_stone_to_flesh": {"id": "arcane_stone_to_flesh", "name": "Stone to Flesh", "level": 6, "casterType": "arcane", "range": "120'", "duration": "Permanent", "effect": "One creature or object", "description": "Turns one statue, or up to 10' x 10' x 10' of stone, into flesh; usually used to restore a character turned to stone. The reverse, flesh to stone, turns one living creature and all its carried equipment to stone; the victim may save vs. turn to stone to avoid it.\nReversible (Flesh to Stone).", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_stoneform": {"id": "arcane_stoneform", "name": "Stoneform", "level": 6, "casterType": "arcane", "range": "Touch", "duration": "Permanent", "effect": "Creates 1,000 cubic feet of stone", "description": "Creates 1,000 cubic feet of stone in any single-piece shape with no moving parts, resting on a support and not in an occupied space. Casting takes 1 round for simple shapes, 1 turn for a staircase, up to 12 turns for complex designs (DM decides). The caster may recast it to modify his creation for up to two hours, then \"lock\" it; rough sides can be seamlessly joined by later stoneforms. Stone type is the caster's choice within reason (e.g. clear lead crystal, not jade). Not dispellable; stone walls have AC -4(6) and 100 hp per 1' thickness.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_wall_of_iron": {"id": "arcane_wall_of_iron", "name": "Wall of Iron", "level": 6, "casterType": "arcane", "range": "120'", "duration": "Permanent", "effect": "Creates 500 square feet of iron", "description": "Creates a vertical iron wall exactly 2' thick with total area up to 500 square feet, entirely within 120', resting on the ground and not in an occupied space. It lasts until dispelled, disintegrated or physically broken, resists all but giant-sized physical attacks, and is unaffected by most spells (fireball, lightning bolt, etc.). It has hit points equal to the caster's level and can only be damaged by battering; a rust monster destroys it with one touch. If toppled, it inflicts 10d10 (10-100) damage to whatever it hits and shatters.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_weather_control": {"id": "arcane_weather_control", "name": "Weather Control", "level": 6, "casterType": "arcane", "range": "0 (magic-user only)", "duration": "Concentration", "effect": "All weather within 240 yards", "description": "Outdoors only, the caster creates one weather condition within a 240-yard radius, affecting everyone including himself, while he concentrates without moving (it moves with him if he is carried). Rain: -2 to missile attacks, mud after 3 turns (half movement). Snow: 20' visibility, half movement, waters may freeze. Fog: 20' visibility, half movement, may get lost. Clear: cancels bad weather. Intense heat: half movement, dries water. High winds: no missiles or flying, half movement, ships with the wind +50%, sandstorms. Tornado: acts as a 12 HD air elemental under the caster's control.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_charm_plant": {"id": "arcane_charm_plant", "name": "Charm Plant", "level": 7, "casterType": "arcane", "range": "120'", "duration": "6 months (see below)", "effect": "Charms one tree or more smaller plants", "description": "Like charm person, charms one tree, six medium bushes, 12 small shrubs, or 24 small plants (no saving throw; plant-like monsters may save vs. spells). Charmed plants understand and obey the caster's commands within their abilities, such as entangling passers-by, but cannot move. The charm lasts six months, until dispelled, or until winter (when the plants sleep).", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_create_normal_monsters": {"id": "arcane_create_normal_monsters", "name": "Create Normal Monsters", "level": 7, "casterType": "arcane", "range": "30'", "duration": "1 turn", "effect": "Creates 1 or more monsters", "description": "Creates monsters out of thin air that understand and faithfully obey the caster; they bring normal weapons and armor and vanish with all their equipment after 1 turn. Total Hit Dice equals the caster's level (drop fractions). Only monsters with no special abilities (no asterisk) may be chosen; no humans, demihumans or undead. Creatures of 1-1 HD count as 1 HD; those of 1/2 HD or less count as 1/2 HD. Example: a 15th level caster could create 30 kobolds, 15 orcs, 7 gnolls, 5 bugbears or 3 panthers.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_delayed_blast_fireball": {"id": "arcane_delayed_blast_fireball", "name": "Delayed Blast Fireball", "level": 7, "casterType": "arcane", "range": "240'", "duration": "0 to 60 rounds", "effect": "Delayed blast fireball of 20' radius", "description": "The caster states a delay of 0 to 60 rounds; a small gem-like rock flies to the chosen spot and remains there (it may be picked up and carried). When the delay ends it explodes as a normal fireball: 1d6 damage per caster level to all within a 20' radius sphere, save vs. spells for half. The timing cannot be changed except by a wish. The \"gem\" is pure magic: it cannot be moved by telekinesis, teleport, etc., but can be dispelled.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_ironform": {"id": "arcane_ironform", "name": "Ironform", "level": 7, "casterType": "arcane", "range": "Touch", "duration": "Permanent", "effect": "Creates 500 square feet of iron", "description": "Creates iron 2\" thick (or less) with an area of 500 square feet, in any single-piece shape with no moving parts; unlike wall of iron it need not be vertical, but must rest on a support and not in an occupied space. Casting takes 1 round for simple shapes, 1 turn for a staircase, up to 12 turns for complex designs. The caster may recast to modify it for up to two hours, then \"lock\" it; rough sides can be seamlessly joined by later ironforms. Not dispellable; destroyed by disintegrate or rust monsters. An iron wall has AC -10(2) and about 15 hp per 1\" thickness.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_lore": {"id": "arcane_lore", "name": "Lore", "level": 7, "casterType": "arcane", "range": "0 (magic-user only)", "duration": "Permanent", "effect": "Reveals details of 1 item, place, or person", "description": "Gives knowledge of one item, place, or person. For an item the caster holds, it takes 1d4 turns and reveals its name, one method of operation and command word, and approximate charges (within five); each casting reveals only one function without hinting at others. For a place, person, or item not held, it may take 1d100 days; legendary topics take longer and answers may come as riddles, and only general details are given for large places or powerful persons.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_magic_door": {"id": "arcane_magic_door", "name": "Magic Door", "level": 7, "casterType": "arcane", "range": "10'", "duration": "7 uses", "effect": "Creates one passage", "description": "Creates an invisible magical doorway on a wall, floor, ceiling or ground, with a passage through up to 10' of non-living solid material, usable only by the caster. It is detectable only by detect magic and destroyed only by dispel magic (normal chances); it lasts until dispelled or used seven times (each one-way passage counts). The reverse, magic lock, makes one portal (or empty 10' x 10' opening) totally impassable to all but the caster, unaffected by knock or magic items, until used seven times or dispelled.\nReversible (Magic Lock).", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_mass_invisibility": {"id": "arcane_mass_invisibility", "name": "Mass Invisibility", "level": 7, "casterType": "arcane", "range": "240'", "duration": "Permanent until broken", "effect": "Creatures or objects in 60' square area", "description": "Makes several creatures invisible, with all carried equipment, as the invisibility spell; all must be within a 60' square area within 240'. Affects up to 6 dragon-sized or up to 300 man-sized creatures. Each remains invisible until it attacks or casts a spell. The reverse, appear, makes all invisible creatures and objects in a 20' x 20' x 20' volume visible (magical and natural invisibility, but not creatures on the Astral or Ethereal planes), and they cannot become invisible again for one turn.\nReversible (Appear).", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_power_word_stun": {"id": "arcane_power_word_stun", "name": "Power Word Stun", "level": 7, "casterType": "arcane", "range": "120'", "duration": "2d6 or 1d6 turns", "effect": "Stuns 1 creature of 70 hp or less", "description": "Stuns one victim within 120' with no saving throw. A victim with 1-35 hit points is stunned for 2d6 turns; one with 36-70 hit points for 1d6 turns. Creatures with 71 or more hit points are unaffected.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_reverse_gravity": {"id": "arcane_reverse_gravity", "name": "Reverse Gravity", "level": 7, "casterType": "arcane", "range": "90'", "duration": "1/5 round (2 seconds)", "effect": "Causes victims in a 30' cubic volume to fall upward", "description": "All creatures and objects in a 30' x 30' x 30' volume \"fall\" opposite normal gravity, up to 65' in the two seconds, with no saving throw. Victims hitting a ceiling or obstruction take 1d6 damage per 10' fallen, then fall back down when gravity returns, taking more falling damage. The DM checks morale for each NPC victim. Example: giants in a 40' tall room take 4d6 going up and 4d6 coming down.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_statue": {"id": "arcane_statue", "name": "Statue", "level": 7, "casterType": "arcane", "range": "0 (Magic-user only)", "duration": "2 turns per level of the caster", "effect": "Allows caster to turn to stone", "description": "The caster may turn into a statue, with all nonliving equipment, or back again up to once per round for the duration. As a statue he is AC -4, cannot move or cast new spells (but may maintain concentration), is immune to normal and magical cold and fire, normal weapons, and gas or drowning, but magical weapons and other spells (e.g. lightning bolt) harm him normally. He can revert one round after being petrified. If a fire or cold spell is cast at him in normal form, he becomes a statue first by winning initiative (+2 bonus).", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_summon_object": {"id": "arcane_summon_object", "name": "Summon Object", "level": 7, "casterType": "arcane", "range": "Infinite", "duration": "Instantaneous", "effect": "Retrieves one object from caster's home", "description": "Brings one nonliving object from the caster's home to his hand, from any location, even another plane. The object must weigh no more than 500 cn, be no bigger than a staff or small chest, be well known to the caster in an exact location, and have been prepared with a special powder costing 1,000 gp per item. Only the prepared object comes (a chest arrives empty). If another being possesses the item, it does not appear, but the caster learns roughly who and where the possessor is.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_sword": {"id": "arcane_sword", "name": "Sword", "level": 7, "casterType": "arcane", "range": "30'", "duration": "1 round per level of the caster", "effect": "Creates a magical sword", "description": "Creates a glowing sword of magic next to the caster that attacks any creature within 30' while he concentrates (it stops if concentration breaks). It attacks twice per round at the caster's level, dealing 1d10 per hit, and can hit any target, even those hit only by powerful magical weapons. It cannot be destroyed before the duration ends except by dispel magic (normal chances) or a wish.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_teleport_any_object": {"id": "arcane_teleport_any_object", "name": "Teleport any Object", "level": 7, "casterType": "arcane", "range": "Touch", "duration": "Instantaneous", "effect": "Causes 1 object to teleport", "description": "Like teleport, but the caster touches one creature or object, living or not, and teleports it; normal chances of error apply (objects too high fall and may break, too low are destroyed), except the caster teleporting himself has no chance of error. Maximum weight 500 cn per caster level; part of a larger whole is limited to a 10' cube, and an overweight creature is not affected. A creature holding the item, or a touched creature, may save vs. spells at -2 to prevent the teleport.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_clone": {"id": "arcane_clone", "name": "Clone", "level": 8, "casterType": "arcane", "range": "10'", "duration": "Permanent", "effect": "Grows one duplicate creature from a piece of the original creature", "description": "Grows a duplicate of a living creature from a piece of it (not undead or constructs); one clone per character at a time. A human/demihuman clone needs 1 lb of flesh and 5,000 gp per HD, and takes 1 week per HD; it has the original's abilities and memories as of when the flesh was taken. If the original lives too, they share damage (save vs. spells for half), and the clone must kill the original within 1 day per level of its creator or go insane; the original then loses 1 Int and 1 Wis and has a 5%/day chance of insanity, killing both in a week. No link if on different planes. A simulacrum of other creatures (500 gp per hp) obeys its creator with 50% of the original's HD, hp and damage.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_create_magical_monsters": {"id": "arcane_create_magical_monsters", "name": "Create Magical Monsters", "level": 8, "casterType": "arcane", "range": "60'", "duration": "Two turns", "effect": "Creates one or more monsters", "description": "As create normal monsters, but can create monsters with up to two asterisks (special abilities), with double range and duration. Total Hit Dice equals the caster's level (drop fractions); no humans or demihumans, but undead may be created. Creatures of 1-1 HD count as 1 HD, those of 1/2 HD or less as 1/2 HD. With the proper materials (at least 5,000 gp per asterisk) it can create one permanent construct of two asterisks or less, which does not vanish but can be dispelled.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_dance": {"id": "arcane_dance", "name": "Dance", "level": 8, "casterType": "arcane", "range": "Touch", "duration": "3 or more rounds", "effect": "Causes 1 victim to dance", "description": "The caster must touch the victim (normal attack roll); the victim gets no saving throw and dances madly, unable to attack, cast spells or use spell-like abilities, or flee, and suffers -4 to saving throws and +4 to armor class. Duration is 3 rounds at caster level 18-20, 4 at 21-24, 5 at 25-28, 6 at 29-32, and 7 at 33-36.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_explosive_cloud": {"id": "arcane_explosive_cloud", "name": "Explosive Cloud", "level": 8, "casterType": "arcane", "range": "1'", "duration": "6 turns", "effect": "Creates a moving poisonous cloud", "description": "Creates a cloud looking identical to cloudkill (30' across, 20' tall, appearing next to the caster). Each round, every victim within must save vs. spells or be paralyzed that round, and all take explosion damage with no save: 1 point per two caster levels, rounded down (9 at 18th-19th, 10 at 20th-21st, etc.). The explosions affect any creature, including those immune to fire, gas, electricity and other special attacks.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_force_field": {"id": "arcane_force_field", "name": "Force Field", "level": 8, "casterType": "arcane", "range": "120'", "duration": "6 turns", "effect": "Creates an invisible barrier", "description": "Creates an invisible, immovable barrier of pure force: a sphere (up to 20' radius), hemisphere, flat surface, cylinder or box (flat surfaces up to 5,000 square feet total), smooth and regular. Nothing passes through it (spells, missiles, breath, blows), but teleport, dimension door and planar travel bypass it. Only disintegrate or a wish destroys it; dispel magic cannot. It will not form inside solids or creatures (leaving holes) and its edges do no damage. Enclosed creatures are preserved from starvation, suffocation and natural death. Can be made permanent with permanence.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_mass_charm": {"id": "arcane_mass_charm", "name": "Mass Charm", "level": 8, "casterType": "arcane", "range": "120'", "duration": "Special (as charm person spell)", "effect": "30 Levels of creatures", "description": "As charm person or charm monster, but affects 30 levels or Hit Dice of creatures at once; each victim may save vs. spells at -2. Creatures of 31 or more levels or HD are unaffected. Each charm's duration depends on the victim's Intelligence. Attacking one victim breaks only that creature's charm; other charmed creatures who see it may make another save. The reverse, remove charm, removes all charm effects in a 20' x 20' x 20' volume and prevents objects there from creating charm effects for one turn.\nReversible (Remove Charm).", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_mind_barrier": {"id": "arcane_mind_barrier", "name": "Mind Barrier", "level": 8, "casterType": "arcane", "range": "10'", "duration": "1 hour per level of the caster", "effect": "Protects against mind-affecting spells and items", "description": "One creature (an unwilling one may save vs. spells) becomes undetectable to ESP, clairvoyance, clairaudience, crystal balls and any other mental influence or information gathering (such as contact higher plane or summon object). It also gains +8 to saving throws against mind-influencing attacks (charm, illusions and phantasms, feeblemind, etc.), though a roll of 1 always fails. The reverse, open mind, cast by touch (normal attack roll), gives the victim -8 to saves against such effects for the duration.\nReversible (Open Mind).", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_permanence": {"id": "arcane_permanence", "name": "Permanence", "level": 8, "casterType": "arcane", "range": "10'", "duration": "Permanent until dispelled", "effect": "Causes one magical effect to become permanent", "description": "Makes one other magic-user spell effect of 7th level or less permanent; not spells with instantaneous or permanent durations, clerical spells, or 8th-9th level spells, and the DM may forbid specific spells. It lasts until dispelled by dispel magic from the caster or a higher-level caster, ending the other effect too. An item may hold one permanence, a creature two; exceeding this makes both fail. A weapon may hold five, but each after the first has a 25% chance to fail and destroy the weapon. It is not needed to make magic items.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_polymorph_any_object": {"id": "arcane_polymorph_any_object", "name": "Polymorph Any Object", "level": 8, "casterType": "arcane", "range": "240'", "duration": "See below", "effect": "Changes form of one object or creature", "description": "As polymorph others, but also affects objects (up to a 10' x 10' x 10' volume of a larger whole). A creature may save vs. spells at -4 to avoid it. Duration: one hour per caster level if changed to a neighboring kingdom (animal-vegetable, vegetable-mineral), one turn per level for animal to mineral or reverse, and permanent (until dispelled) if the kingdom is unchanged. Created creatures are not automatically friendly; age and hit points do not change. Creatures with more than twice the caster's level in Hit Dice are unaffected.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_power_word_blind": {"id": "arcane_power_word_blind", "name": "Power Word Blind", "level": 8, "casterType": "arcane", "range": "120'", "duration": "1-4 days or 2-8 hours (see below)", "effect": "Blinds 1 creature with 80 hit points or less", "description": "Blinds one victim within 120' with no saving throw: 1d4 days for a victim with 1-40 hit points, 2d4 hours for one with 41-80; creatures with 81 or more hit points are unaffected. A blinded victim suffers -4 on saving throws and +4 on armor class. A cleric's cure blindness or cureall removes it only if the cleric's level is equal to or higher than the caster's.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_steelform": {"id": "arcane_steelform", "name": "Steelform", "level": 8, "casterType": "arcane", "range": "Touch", "duration": "Permanent", "effect": "Creates up to 500 square feet of steel", "description": "Identical to ironform, but creates weapon-quality steel; a swordmaker could create a fine, high-quality sword in 12 turns (two hours) or less. A steel wall has AC -10(2) and about 20 hit points per 1\" thickness.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_symbol": {"id": "arcane_symbol", "name": "Symbol", "level": 8, "casterType": "arcane", "range": "Touch", "duration": "Permanent", "effect": "Creates one magical rune", "description": "Creates a magical rune, chosen when memorized, on an object or in mid-air; it cannot move. A living creature passing over or through it, touching it, or reading it triggers it with no saving throw, except that magic-users and other magic-user spellcasters who only read or touch it may save vs. spells. Death: slays a creature of 75 hp or less. Discord: victim confused and attacks allies, until dispel magic or cureall. Fear: flees at Running Speed for 30 rounds. Insanity: cannot attack, cast or use abilities, until dispel magic or cureall. Sleep: 1d10+10 hours or until dispelled. Stunning: stuns a creature of 150 hp or less for 2d6 turns.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_travel": {"id": "arcane_travel", "name": "Travel", "level": 8, "casterType": "arcane", "range": "0 (caster only)", "duration": "One turn per level of the caster", "effect": "Allows aerial or gaseous travel", "description": "The caster may fly at 360' (120') and enter a nearby plane by concentrating one round (at most one plane per turn), bringing one touching creature per five levels (unwilling ones save vs. spells); he cannot send others alone. By concentrating one full round he may become gaseous with all his equipment, flying at 720' (240'); while gaseous he cannot use items or cast spells, can be harmed only by magic, and cannot pass through protection from evil or an anti-magic shell.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_contingency": {"id": "arcane_contingency", "name": "Contingency", "level": 9, "casterType": "arcane", "range": "Touch", "duration": "Indefinite (see below)", "effect": "Prepares one other spell", "description": "Sets one magic-user spell of 4th level or less that does not normally cause damage to trigger automatically when a situation described by the caster occurs, as if cast then. The situation must pertain to something within 120' of the triggering event, and the target and effect of the secondary spell must be specified or it fails. No item or creature can have more than one contingency, not even with a wish. It has no maximum duration.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_create_any_monster": {"id": "arcane_create_any_monster", "name": "Create Any Monster", "level": 9, "casterType": "arcane", "range": "90'", "duration": "3 turns", "effect": "Creates one or more monsters", "description": "As create normal/magical monsters, but can create any creature except humans and demihumans, regardless of asterisks; for three or more asterisks the caster must have studied one for at least an hour. Total Hit Dice equals the caster's level. With proper materials (at least 5,000 gp per asterisk, doubled for four or more) it creates one permanent construct that does not vanish but can be dispelled. Created monsters are blocked by protection from evil or anti-magic shell.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_gate": {"id": "arcane_gate", "name": "Gate", "level": 9, "casterType": "arcane", "range": "30'", "duration": "1d10 x 10 (1-100) turns or 1 turn", "effect": "Opens a portal to another plane", "description": "Opens a connection to a named plane (Ethereal, Astral, an elemental plane or an outer plane), naming a resident. A gate to an outer plane stays open 1 turn; others stay open 1d10 x 10 turns with a 10% chance per turn of a creature wandering through. An elemental gate creates a vortex and wormhole. The named Immortal comes in 1d6 rounds (5% chance another being answers); without an excellent reason it will probably destroy the caster, and may help briefly only if the matter interests it. The reverse, close gate, closes a gate or permanent gate to a nearby plane but cannot affect an Immortal.\nReversible (Close Gate).", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_heal": {"id": "arcane_heal", "name": "Heal", "level": 9, "casterType": "arcane", "range": "Touch (one creature)", "duration": "Permanent", "effect": "Cures anything", "description": "Identical to the cleric's cureall: it cures all damage but 1d6 points, or instead removes a curse, neutralizes a poison, cures a disease, cures blindness, or removes a feeblemind effect.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_immunity": {"id": "arcane_immunity", "name": "Immunity", "level": 9, "casterType": "arcane", "range": "Touch (one creature)", "duration": "One turn per level of the caster", "effect": "Bestows immunity or resistance to some spells and weapons", "description": "The recipient is immune to all 1st-3rd level spells; 4th and 5th level spells have half effect, or one-quarter with a successful save (durations, bonuses, damage, etc., rounded in his favor). He is immune to all missiles and to normal and silver weapons, and takes half damage from magical hand-held weapons; natural attacks and breath are not blocked. He may drop the protection for one round by concentrating. A careful wish can extend it to 4th level spells and +1 weapons, and half effect from 5th-6th level spells.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_maze": {"id": "arcane_maze", "name": "Maze", "level": 9, "casterType": "arcane", "range": "60'", "duration": "See below (1d6 turns, 2d20 rounds, 2d4 rounds, or 1d4 rounds)", "effect": "Traps one creature", "description": "Places one victim (no saving throw) in an indestructible maze on the Astral Plane. Escape time depends on Intelligence: 1-8, 1d6 turns; 9-12, 2d20 rounds; 13-17, 2d4 rounds; 18+, 1d4 rounds. On escape, the victim returns to the exact place he disappeared from.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_meteor_swarm": {"id": "arcane_meteor_swarm", "name": "Meteor Swarm", "level": 9, "casterType": "arcane", "range": "240'", "duration": "Instantaneous", "effect": "Creates four or eight meteor-fireballs", "description": "Creates 4 or 8 meteors, each aimed at a different target within range (only one per creature); they never miss. Four meteors each strike for 8d6 and explode for 8d6 fire damage; eight meteors each strike for 4d6 and explode for 4d6. The struck target takes full strike damage (no save, even fire-resistant creatures); everyone in each 20' radius blast may save vs. spells for half, rolling separately for each overlapping blast.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_power_word_kill": {"id": "arcane_power_word_kill", "name": "Power Word Kill", "level": 9, "casterType": "arcane", "range": "120'", "duration": "Instantaneous", "effect": "Slays or stuns one or more creatures", "description": "Affects victims within 120' with no saving throw, except that magic-users and creatures that cast magic-user spells may save vs. spells at -4. A single victim with 1-60 hit points is slain; one with 61-100 is stunned for 1d4 turns; 101 or more is unaffected. Alternatively, it slays up to five victims of 20 hit points or less each.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_prismatic_wall": {"id": "arcane_prismatic_wall", "name": "Prismatic Wall", "level": 9, "casterType": "arcane", "range": "60'", "duration": "6 turns", "effect": "Creates a multi-colored barrier", "description": "Creates an immovable seven-colored wall, a 10' radius sphere around the caster or a flat surface up to 500 square feet; the caster passes freely. Others touching it suffer each color in turn (no save unless stated): red 12 damage, orange 24, yellow 48, green save vs. poison or die, blue save vs. turn to stone, indigo save vs. spells or be gated to a random outer plane (50% chance of being lost forever), violet save vs. wands or be unconscious and insane (curable only by cureall or wish). Colors are removed in order by magical cold, magical lightning, magic missile, passwall, disintegrate, dispel magic, continual light; a wish or rod of cancellation removes three. It extends into the nearest plane and blocks anti-magic shells.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_shapechange": {"id": "arcane_shapechange", "name": "Shapechange", "level": 9, "casterType": "arcane", "range": "0 (caster only)", "duration": "One turn per level of the caster", "effect": "Caster may change form", "description": "The caster becomes another creature or object he has seen, gaining its AC, attacks, special attacks, immunities and flaws, but keeping his own mind, hit points and saving throws; each change takes a round of concentration. He can cast memorized spells only in bipedal humanoid form, cannot take unique forms (specific characters, Elemental Rulers, Immortals), gains no class abilities, and huge inanimate forms are limited to 1' tall and 100 cn per level. It cannot be made permanent, is subject to dispel magic, and he cannot pass protection from evil or anti-magic shell.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_survival": {"id": "arcane_survival", "name": "Survival", "level": 9, "casterType": "arcane", "range": "Touch", "duration": "One hour per level of the caster", "effect": "Protects one creature against all non-magical environmental damage", "description": "Protects the recipient from all adverse natural conditions, such as heat, cold, lack of air, vacuum, underwater, or conditions on other planes (e.g. the elemental plane of Fire); the recipient needs no air, food, water, or sleep. It gives no protection against magical damage, attacks, poisons, breath weapons, or blows from creatures.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_timestop": {"id": "arcane_timestop", "name": "Timestop", "level": 9, "casterType": "arcane", "range": "0 (caster only)", "duration": "2-5 rounds", "effect": "Allows caster to act for 1d4+1 (2-5) rounds while everything else \"stops\"", "description": "The caster acts for 1d4+1 rounds, one action per round, while everything else seems frozen. Fire, cold, gas, etc. can still harm him, but other creatures are invulnerable to his attacks and spells; non-instantaneous spells may be cast to take effect when time resumes, and their durations begin afterward. He can move unheld items (including those worn or carried by others) but not held ones, is undetectable, and cannot pass protection from evil or an anti-magic shell.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "arcane_wish": {"id": "arcane_wish", "name": "Wish", "level": 9, "casterType": "arcane", "range": "Special", "duration": "Special", "effect": "Special", "description": "Only 36th level magic-users with Wisdom 18+ may cast it; never found on scrolls. The player states the exact wording, and the DM may distort greedy or unbalanced wishes. It can duplicate any magic-user spell of 8th level or less or cleric/druid spell of 6th or less. A harmed victim may save vs. spells to take half, with half rebounding on the caster (save at -4). It can give up to 50,000 gp (losing 1 XP per gp), raise an ability to 3-18 for six turns, permanently raise an ability by one point (wishes equal to the new score, within a week), add a demihuman Hit Die, change race, or alter the previous day's events. It cannot grant XP or levels.", "source": "Rules Cyclopedia, Magic-user spells", "isCustom": false},
    "shaman_ceremony": {"id": "shaman_ceremony", "name": "Ceremony", "level": 1, "casterType": "shadow_shaman", "range": "touch", "duration": "permanent", "effect": "consecrate a creature, object, or area", "description": "A versatile rite used to mark the key moments of shadow elf life; it leaves visible signs (some seen only by elves) that do not register to detect magic. Ceremonies include Adoption (moves an elf to another clan, also used in marriage), Anathema (banishes an 800-year-old elf as a Wanderer), Consecration (of a temple site, shrine, or crystal mine, costing 100 gp of treasure or 1,000 xp), Initiation (into adulthood) and Investiture (of a new shaman).\nSource: new Shadow Shaman spell.", "isCustom": false},
    "shaman_command_word": {"id": "shaman_command_word", "name": "Command Word", "level": 1, "casterType": "shadow_shaman", "range": "10 feet", "duration": "6 rounds", "effect": "a creature obeys an order", "description": "Each round, as a free action, the caster speaks a one-word command in a language the target understands and it obeys as best it can (e.g. Stop, Run, Surrender, Retreat); \"Die!\" makes it faint for one round. Undead are unaffected. Creatures with Wisdom 13+ or with 5+ HD/levels may save vs. Mental Spells to resist (only one save if both apply).", "isCustom": false},
    "shaman_protection_from_evil": {"id": "shaman_protection_from_evil", "name": "Protection from Evil", "level": 1, "casterType": "shadow_shaman", "range": "0", "duration": "12 turns", "effect": "offers a +1 bonus to the ST of the spellcaster and a -1 penalty to his enemies' Attack Rolls", "description": "An invisible barrier surrounds the caster: attackers suffer -1 to hit and the caster gains +1 to all Saving Throws. Magically summoned, created, animated or controlled creatures (and cursed ones) cannot touch the caster, blocking their melee attacks but not ranged ones. If the caster attacks such a creature, it can then attack him in melee (still at -1).", "isCustom": false},
    "shaman_purify_food_water": {"id": "shaman_purify_food_water", "name": "Purify Food & Water", "level": 1, "casterType": "shadow_shaman", "range": "10 feet", "duration": "permanent", "effect": "purify food and water from impurities and mould", "description": "Removes poison and rot from food and water in a 1 cubic foot volume, or up to 60 pounds/pints of food and water in total; a mud pool becomes drinkable water (within that limit). It has no effect on living beings, magic potions or vials of poison.", "isCustom": false},
    "shaman_sanctuary": {"id": "shaman_sanctuary", "name": "Sanctuary", "level": 1, "casterType": "shadow_shaman", "range": "touch", "duration": "6 rounds + 1 round per level", "effect": "the subject is protected from enemy attacks", "description": "Anyone trying to attack the protected creature must save vs. Spells each round; on a failure it cannot harm the subject that round and loses its attacks against it. The spell does not protect from spells or magical effects, only physical attacks. If the subject attacks, its foes may counterattack freely that round, but protection resumes once it stops attacking.", "isCustom": false},
    "shaman_remove_fear": {"id": "shaman_remove_fear", "name": "Remove Fear", "level": 1, "casterType": "shadow_shaman", "range": "60 feet", "duration": "2 turns", "effect": "1d4 creatures resist the effects of fear; reverse scares 1d4 adversaries", "description": "Protects 1d4 living creatures from magical or normal fear for 2 turns, granting a bonus to saves vs. fear equal to half the caster's level (max +5), and instantly ends any fear already affecting them. The reverse, terrify, makes 1d4 living creatures flee in panic from the caster for 2 turns unless they save vs. Mental Spells.\nReversible (Terrify).", "isCustom": false},
    "shaman_detect_danger": {"id": "shaman_detect_danger", "name": "Detect Danger", "level": 1, "casterType": "shadow_shaman", "range": "0", "duration": "6 turns or 6 rounds", "effect": "reveal dangers and hostile creatures", "description": "Works in one of two ways. Perceive danger: for 6 turns, concentrating 1 round per 3-foot square area, medium creature or object within 5' per level reveals whether it is dangerous, potentially hostile or benign (including hostile intent, traps and poisons, but not the type of danger). Detect enemy: every hostile creature within 60', even invisible ones, is outlined in a reddish, torch-bright glow for 6 rounds.\nSource: druid list.", "isCustom": false},
    "shaman_paralysing_touch": {"id": "shaman_paralysing_touch", "name": "Paralysing Touch", "level": 1, "casterType": "shadow_shaman", "range": "touch", "duration": "1 turn", "effect": "paralyse a part of a being's body", "description": "With a touch attack (armour ignored), the victim must save vs. Paralysis or be paralysed for 1 turn; on a successful save only the touched body part (1d8: head, torso, arm or leg) is numbed for 1 turn, with effects such as blindness and speechlessness, slowing, dropping held items or halved movement. It can be removed by dispel magic or an appropriate spell; undead and constructs are immune.", "isCustom": false},
    "shaman_bless": {"id": "shaman_bless", "name": "Bless", "level": 2, "casterType": "shadow_shaman", "range": "60 feet", "duration": "6 turns", "effect": "+1 bonus to the subjects' attacks and damage", "description": "All creatures in a 20-foot cube within 60 feet gain +1 to Attack Rolls, damage, Morale and saves vs. fear; it does not stack with itself. The reverse, anathema, gives creatures in the area -1 to attack, damage and Morale rolls with no Saving Throw. Bless and anathema cancel each other out.\nReversible (Anathema).", "isCustom": false},
    "shaman_hold_person": {"id": "shaman_hold_person", "name": "Hold Person", "level": 2, "casterType": "shadow_shaman", "range": "180 feet", "duration": "3 turns", "effect": "paralyse up to 4 humanoid creatures; reverse free up to 4 humanoid creatures", "description": "Paralyses up to 4 visible humanoids of Medium size or smaller within 180 feet for 3 turns (no effect on undead, constructs, animals or Large humanoids); victims can still see, hear and think. Each may save vs. Mental Spells to resist, at -2 if the spell targets a single creature. The reverse, free person, removes magical or poison-induced paralysis from up to 4 such humanoids.\nReversible (Free Person).", "isCustom": false},
    "shaman_cure_light_wounds": {"id": "shaman_cure_light_wounds", "name": "Cure Light Wounds", "level": 2, "casterType": "shadow_shaman", "range": "touch", "duration": "permanent", "effect": "heal 1d6+1 hp or 10% of total hp; reverse causes 1d6+1 hp or 10% of temporary hp", "description": "A touched living creature instantly regains the better of 1d6+1 hit points or 10% of its total hit points, up to its maximum. The reverse, inflict light wounds, deals the greater of 1d6+1 damage or 10% of the victim's current hit points, with no save for half.\nReversible (Inflict Light Wounds).", "isCustom": false},
    "shaman_detect_alignment": {"id": "shaman_detect_alignment", "name": "Detect Alignment", "level": 2, "casterType": "shadow_shaman", "range": "touch", "duration": "1 turn per level", "effect": "reveals a creature's alignment; reverse hides the alignment from identification", "description": "Listed in the book as Know Alignment. By touching a creature (which uses one of the caster's attacks) the caster learns its alignment with no Saving Throw, and may examine a different subject each round while the spell lasts. The reverse, obscure alignment, hides the touched subject's true alignment, warns it of attempts to detect it, and lets it project a false alignment.\nReversible (Obscure Alignment).", "isCustom": false},
    "shaman_obscure": {"id": "shaman_obscure", "name": "Obscure", "level": 2, "casterType": "shadow_shaman", "range": "0", "duration": "1 turn per level", "effect": "fogbank reduces visibility to 10 ft", "description": "Raises a fog 1 foot high and 10 feet in radius per level, centred on the caster (fixed or moving with him), which cuts vision to 10 feet for everyone except the caster and those with trueseeing; infravision is useless. A moderate wind (12 mph) disperses it in 1 round; underwater it clouds the water. The reverse, dispel fog, clears all normal or magical fog in the area and keeps mist out for the duration.\nReversible (Dispel Fog). Source: druid list.", "isCustom": false},
    "shaman_elemental_resistance": {"id": "shaman_elemental_resistance", "name": "Elemental Resistance", "level": 2, "casterType": "shadow_shaman", "range": "touch", "duration": "6 turns", "effect": "renders it immune to a normal element and protects from damage caused by a magical element", "description": "The touched creature becomes immune to one normal element chosen at casting: cold, fire, or electricity/lightning. Against magical attacks of that element (e.g. fireball, ice storm, dragon breath) it takes 1 point less damage per damage die and gains +2 to Saving Throws. It gives no protection from extreme temperatures above 400°F or below -150°F, such as lava.", "isCustom": false},
    "shaman_heat_metal": {"id": "shaman_heat_metal", "name": "Heat Metal", "level": 2, "casterType": "shadow_shaman", "range": "30 feet", "duration": "7 rounds", "effect": "heat metal objects causing damage", "description": "Heats up to 50 cn of metal per level; magic items may save vs. Fire. A creature holding or wearing a heated object takes 1, 2, 4, 8, 4, 2, 1 damage over the seven rounds (22 total, no save) unless it drops the item; from the fourth round flammable materials touching it ignite. Resistance to fire protects completely, and dispel magic ends the effect.\nSource: druid list.", "isCustom": false},
    "shaman_silence": {"id": "shaman_silence", "name": "Silence", "level": 2, "casterType": "shadow_shaman", "range": "180 feet", "duration": "12 turns", "effect": "silence in a 30 feet diameter sphere", "description": "No sound can be made or enter the 30-foot diameter sphere centred within 180 feet, so no one inside can speak or cast spells. If cast on a creature or a held/worn object, the victim may save vs. Spells to leave the silence fixed in place; otherwise it moves with the victim. Remove deafness does not counter it; dispel magic does.", "isCustom": false},
    "shaman_cone_of_cold": {"id": "shaman_cone_of_cold", "name": "Cone of Cold", "level": 3, "casterType": "shadow_shaman", "range": "0", "duration": "instantaneous", "effect": "cone of ice causes 1d6 hp per level", "description": "A 60-foot long, 20-foot wide cone of extreme cold deals 1d6 damage per caster level (max 20d6) to everything in it, with a save vs. Spells for half. Cold creatures automatically take half damage (a quarter with a successful save), and undead and constructs are immune.\nSource: Arcane Magic.", "isCustom": false},
    "shaman_control_temperature": {"id": "shaman_control_temperature", "name": "Control Temperature", "level": 3, "casterType": "shadow_shaman", "range": "0", "duration": "1d6+2 hours", "effect": "raise or lower the temperature in a 10' radius", "description": "Listed in the book as Control Temperature (10' radius sphere). Instantly raises or lowers the temperature in a 20-foot diameter sphere centred on and moving with the caster by up to 50°C, to resist extreme temperatures. The caster can change the setting again by concentrating for 1 round, but need not concentrate to maintain the spell.\nSource: druid list.", "isCustom": false},
    "shaman_dispel_magic": {"id": "shaman_dispel_magic", "name": "Dispel Magic", "level": 3, "casterType": "shadow_shaman", "range": "120 feet", "duration": "permanent", "effect": "destroy spells in a 20 feet sided cube", "description": "Ends all non-instantaneous, non-permanent magical effects in a 20-foot cube within 120 feet; it does not affect a magic item's permanent enchantments. Effects created by casters of equal or lower level are automatically dispelled; against higher-level casters there is a 5% chance of failure per level of difference, rolled per effect. It can instead be delivered by touch to affect only one creature or item.", "isCustom": false},
    "shaman_glyph_of_interdiction": {"id": "shaman_glyph_of_interdiction", "name": "Glyph of Interdiction", "level": 3, "casterType": "shadow_shaman", "range": "touch", "duration": "special", "effect": "protection inflicts 1d6 damage per level (max 10d6) or evokes the effects of a 1st-3rd level clerical spell on those who touched it or passed over it without deactivating it", "description": "Places a holy glyph on an object or passage, triggered by a condition set by the caster (e.g. creature type or alignment, or failure to speak a password). When triggered it explodes (fire, acid, electricity, cold or sonic) for 1d6 damage per level (max 10d6) to all within 5 feet, save vs. Spells for half, or releases a linked 1st-3rd level clerical spell on the trespasser. It can be spotted with an Intelligence check or detect magic/find traps, and dispelled normally.", "isCustom": false},
    "shaman_spell_of_striking": {"id": "shaman_spell_of_striking", "name": "Spell of Striking", "level": 3, "casterType": "shadow_shaman", "range": "touch", "duration": "1 turn", "effect": "weapon does an additional 1d6 points of damage; reverse use the weapon's bonus to improve its user's AC", "description": "A melee, thrown or natural weapon deals +1d6 damage on every blow for 1 turn and counts as magical (able to hit creatures needing +1 weapons; creatures with higher immunity take only the 1d6). The reverse, spell of parrying, lets the wielder forgo all attacks in a round to gain an AC bonus equal to the weapon's magic bonus (or 1 per 5 caster levels for a non-magical weapon) against melee and thrown attacks.\nReversible (Spell of Parrying).", "isCustom": false},
    "shaman_fireball": {"id": "shaman_fireball", "name": "Fireball", "level": 3, "casterType": "shadow_shaman", "range": "240 feet", "duration": "instantaneous", "effect": "explosion of fire causes 1d6 hp per level to all within a 40-foot diameter sphere", "description": "A fiery projectile flies to a point within 240 feet and explodes, dealing 1d6 damage per caster level (max 20d6) to every creature in the area, with a save vs. Spells for half; flammable items may ignite on a failed save. Fire creatures automatically take half damage (a quarter with a successful save).\nSource: Arcane Magic.", "isCustom": false},
    "shaman_protection_from_poison": {"id": "shaman_protection_from_poison", "name": "Protection from Poison", "level": 3, "casterType": "shadow_shaman", "range": "touch", "duration": "1 turn per level", "effect": "grant immunity to all poisons", "description": "The recipient and its carried items become immune to all poisons whose effects can be avoided or reduced by a save, including magical ones such as cloudkill or create poison, and it gets a save against poisons that normally allow none. Against green dragon breath (half acid) it automatically takes half damage, a quarter with a successful save vs. Dragon Breath.\nSource: druid list.", "isCustom": false},
    "shaman_remove_curse": {"id": "shaman_remove_curse", "name": "Remove Curse", "level": 3, "casterType": "shadow_shaman", "range": "10 feet", "duration": "permanent", "effect": "remove a curse from a creature, object, or place; reverse inflict a curse on a creature, object, or place", "description": "Removes the most serious curse from a creature, object or place, permanently if the caster's level is equal to or higher than the curser's, otherwise only for 1d20 rounds; one curse per casting. The reverse, curse, imposes a penalty of up to -4 (to an ability, attacks, damage, a save type or a skill) or another DM-approved affliction; a creature may save vs. Spells at -2.\nReversible (Curse).", "isCustom": false},
    "shaman_enchanted_weapon": {"id": "shaman_enchanted_weapon", "name": "Enchanted Weapon", "level": 4, "casterType": "shadow_shaman", "range": "touch", "duration": "6 turns", "effect": "make a weapon magical", "description": "A weapon gains +1 to attack and damage per 3 caster levels (max +5 at 15th); an already magical weapon has its bonus increased, up to +10. The bonus only works while the weapon is wielded by a follower of the caster's Immortal.", "isCustom": false},
    "shaman_walk_on_lava": {"id": "shaman_walk_on_lava", "name": "Walk on Lava", "level": 4, "casterType": "shadow_shaman", "range": "30 feet", "duration": "1 day", "effect": "creature breathes normally in lava", "description": "The creature can walk at normal speed and breathe normally on a lava surface without suffering from its heat. If fully immersed in lava it still breathes but is not protected from the damage, and the spell gives no protection against other fire, normal or magical, such as a fireball or wall of fire.\nSource: new Shadow Shaman spell.", "isCustom": false},
    "shaman_remove_blindness_deafness": {"id": "shaman_remove_blindness_deafness", "name": "Remove Blindness / Deafness", "level": 4, "casterType": "shadow_shaman", "range": "touch", "duration": "permanent", "effect": "heal a creature of blindness or deafness; reverse causes permanent blindness or deafness", "description": "Cures the touched creature of natural or magical blindness or deafness (caster's choice, not both), but cannot regrow missing eyes or ears. The reverse, blindness/deafness, permanently blinds or deafens a touched victim unless it saves vs. Spells at -4; it can only be removed by remove blindness/deafness or wish, not dispel magic.\nReversible (Blindness / Deafness).", "isCustom": false},
    "shaman_cure_serious_wounds": {"id": "shaman_cure_serious_wounds", "name": "Cure Serious Wounds", "level": 4, "casterType": "shadow_shaman", "range": "touch", "duration": "permanent", "effect": "heals 2d6+2 hp or 30% of total hp; reverse causes 2d6+2 hp or 30% of current hp", "description": "A touched living creature instantly regains the better of 2d6+2 hit points or 30% of its total hit points, up to its maximum. The reverse, inflict serious wounds, deals the greater of 2d6+2 damage or a percentage of the victim's current hit points, with no save for half; the touch attack ignores armour.\nReversible (Inflict Serious Wounds).", "isCustom": false},
    "shaman_remove_disease": {"id": "shaman_remove_disease", "name": "Remove Disease", "level": 4, "casterType": "shadow_shaman", "range": "30 feet", "duration": "permanent", "effect": "cure a disease; reverse inflict a disease", "description": "Instantly cures one creature of a normal or magical disease and its effects; the categories of disease that can be cured (and, at higher levels, lycanthropy) depend on the caster's level. The reverse, inflict disease, infects the victim with a disease unless it saves vs. Spells; the disease cannot be dispelled, only cured.\nReversible (Inflict Disease).", "isCustom": false},
    "shaman_wall_of_fire": {"id": "shaman_wall_of_fire", "name": "Wall of Fire", "level": 4, "casterType": "shadow_shaman", "range": "60 feet", "duration": "3 turns", "effect": "create a wall of fire of 1,200 ft2", "description": "Creates a 12-inch thick wall of flame covering 1,200 square feet in a shape of the caster's choice, blocking vision. Creatures of 4 HD/levels or less cannot pass (they burn to death if they try); those of 5+ HD take 4d6 fire damage passing through (no save), 5d6 for aquatic or cold creatures. It must rest on stable support and can be dispelled.\nSource: Arcane Magic.", "isCustom": false},
    "shaman_divine_ray": {"id": "shaman_divine_ray", "name": "Divine Ray", "level": 4, "casterType": "shadow_shaman", "range": "0", "duration": "instantaneous", "effect": "ray of energy causes 1d6 hp/lvl. (ST for half)", "description": "A ray of divine energy up to 3 feet long per level strikes every creature along its line for 1d6 damage per level (max 15d6), save vs. Death Ray for half. Followers of the caster's Immortal pass through unharmed, while the Immortal's sworn enemies (or, failing those, creatures of opposed alignment) save at -2.", "isCustom": false},
    "shaman_insect_swarm": {"id": "shaman_insect_swarm", "name": "Insect Swarm", "level": 4, "casterType": "shadow_shaman", "range": "480 feet", "duration": "1 minute per level", "effect": "create a 30' radius insect swarm", "description": "Summons a 30-foot radius swarm that moves at the caster's command (60 feet per round) without concentration. Inside, vision is limited to 10 feet, spellcasting is impossible, attacks are at -1, and living creatures take 1 point of damage regardless of AC. Creatures of 2 HD or less flee; those of 3-5 HD flee unless they save vs. Mental Spells. Strong wind (25 mph) or a large fire disperses it.\nSource: druid list.", "isCustom": false},
    "shaman_command": {"id": "shaman_command", "name": "Command", "level": 5, "casterType": "shadow_shaman", "range": "30 feet", "duration": "special", "effect": "force any being to follow an order; free victim from a command/geas", "description": "Forces any being, including undead and constructs, to obey a law or complete a task set by the caster (not suicidal); a follower cannot resist, others save vs. Mental Spells at -4. A victim who refuses is cursed until it resumes the task. The reverse, pardon, removes a command, geas or similar obligation (90% chance, -5% per level the other caster is higher); dispel magic and remove curse do not work on it.\nReversible (Pardon).", "isCustom": false},
    "shaman_commune": {"id": "shaman_commune", "name": "Commune", "level": 5, "casterType": "shadow_shaman", "range": "0", "duration": "3 turns", "effect": "3 questions", "description": "The caster communes with his Immortal and may ask up to 3 questions (one per turn), answered with a single word or a clear vision, if the Immortal knows the answer. It can be used only once per week; once per year the number of questions is doubled.", "isCustom": false},
    "shaman_create_food_water": {"id": "shaman_create_food_water", "name": "Create Food & Water", "level": 5, "casterType": "shadow_shaman", "range": "touch", "duration": "permanent", "effect": "create 20 pints of water × level or food for 5 humans × level", "description": "Either creates a spring of pure water (20 pints per level, flowing at 10 pints per round) or enough simple food to feed 5 humans per level for a day. Neither can be dispelled, but the food spoils after 24 hours unless purified.", "isCustom": false},
    "shaman_dispel_evil": {"id": "shaman_dispel_evil", "name": "Dispel Evil", "level": 5, "casterType": "shadow_shaman", "range": "0", "duration": "special", "effect": "destroy undead, magically summoned, controlled, or animated creatures, or a curse", "description": "Each undead or magically summoned, animated or controlled creature within 30 feet must save vs. Spells (-2 if alone): summoned creatures are sent back, animated ones with fewer HD than the caster's level are destroyed (others lose half their hp), and controlled ones are freed. The area then acts as a 30-foot circle of protection from evil for 1 turn. It can also cancel curse and desecrate.", "isCustom": false},
    "shaman_call_upon_souls": {"id": "shaman_call_upon_souls", "name": "Call upon Souls", "level": 5, "casterType": "shadow_shaman", "range": "30 feet from a soul crystal", "duration": "1 round per level", "effect": "augment spell effects", "description": "Radiance spell: the shaman draws on 1 to 7 souls in his soul crystal and, for 1 round per level, either casts as if 1 level higher per soul, or increases one parameter of his spells (range, area of effect or duration) by 10% per soul, max 70%. Each soul used is weakened and cannot power Radiance spells for a week; calling more souls than the crystal holds makes the spell fail and weakens them all.\nRadiance spell: uses souls from your soul crystal. Source: new Shadow Shaman spell.", "isCustom": false},
    "shaman_neutralise_poison": {"id": "shaman_neutralise_poison", "name": "Neutralise Poison", "level": 5, "casterType": "shadow_shaman", "range": "touch", "duration": "permanent", "effect": "neutralise any poison present in a being, container, or item; reverse creates poison in a being or container", "description": "Renders harmless all poison in a creature, container or item. Cast within 10 rounds of the poisoning, it also restores lost hit points or even revives a creature killed by the poison. The reverse, create poison, poisons a creature (save vs. Poison or die) or a container's contents.\nReversible (Create Poison).", "isCustom": false},
    "shaman_magic_resistance": {"id": "shaman_magic_resistance", "name": "Magic Resistance", "level": 5, "casterType": "shadow_shaman", "range": "0", "duration": "6 turns", "effect": "resistance to spells of 30% +1% per level.", "description": "Listed in the book as Resistance to Magic. The caster gains magic resistance of 30% + 1% per level (max 66%) against spells directed at him; he may lower it for a round to receive beneficial spells. It does not stack with other magic resistance and does not affect creatures' special powers such as breath or gaze attacks.", "isCustom": false},
    "shaman_trueseeing": {"id": "shaman_trueseeing", "name": "Trueseeing", "level": 5, "casterType": "shadow_shaman", "range": "0", "duration": "6 turns", "effect": "clearly see the true form, alignment, and level of creatures, objects, or hidden things", "description": "Within 120 feet the caster sees the true form of shapechanged or disguised beings, sees invisible and magically hidden creatures and objects, sees through fog and illusions of 1st-4th level, and spots secret doors and hidden thieves. By concentrating a round he learns a creature's alignment and level or HD, and he can look into an adjacent plane up to 20 feet.", "isCustom": false},
    "shaman_flesh_to_stone": {"id": "shaman_flesh_to_stone", "name": "Flesh to Stone", "level": 6, "casterType": "shadow_shaman", "range": "120 feet", "duration": "permanent", "effect": "petrify a creature of flesh; reverse make flesh a being or object of stone", "description": "Turns a creature of flesh and its equipment to stone unless it saves vs. Petrification; the statue has AC 5 and the victim's hit points, and if shattered the creature dies. The reverse, stone to flesh, turns up to 1,000 cubic feet of stone into flesh, typically restoring petrified creatures. Neither effect can be dispelled, only reversed by the opposite form.\nReversible (Stone to Flesh). Source: Arcane Magic.", "isCustom": false},
    "shaman_heal": {"id": "shaman_heal", "name": "Heal", "level": 7, "casterType": "shadow_shaman", "range": "touch", "duration": "permanent", "effect": "the cleric gives a creature 90% of its hp total; reverse takes the victim to 10% of his hp total", "description": "The touched creature is restored to 90% of its total hit points and cured of one malady (poison, disease, mental disturbance, blindness, deafness, paralysis or stun); it also restores temporarily lost ability points and removes the rest period after resurrection. The reverse, harm, reduces a living victim to 10% of its hit points (save vs. Death Ray to halve current hp instead); against undead the two forms are swapped.\nReversible (Harm).", "isCustom": false},
    "shaman_cure_critical_wounds": {"id": "shaman_cure_critical_wounds", "name": "Cure Critical Wounds", "level": 6, "casterType": "shadow_shaman", "range": "touch", "duration": "permanent", "effect": "heals 3d6+3 hp or 50% of total hp; reverse causes 3d6+3 hp or 50% of current hp", "description": "A touched living creature instantly regains the better of 3d6+3 hit points or 50% of its total hit points, up to its maximum. The reverse deals the greater of 3d6+3 damage or 50% of the victim's current hit points, with no save for half; the touch attack ignores armour.\nReversible (Inflict Critical Wounds).", "isCustom": false},
    "shaman_mental_cure": {"id": "shaman_mental_cure", "name": "Mental Cure", "level": 6, "casterType": "shadow_shaman", "range": "touch", "duration": "permanent", "effect": "cure the madness and mental diseases of a creature; reverse causes madness or a mental disease", "description": "Cures one form of normal or magical madness or mental disease (including feeblemind and confusion) per casting, restores 1 point of Intelligence or Wisdom lost to a mental malady, and can restore memories lost to amnesia. The reverse, madness, inflicts insanity, desperation, fury, obsession or paranoia on a touched victim unless it saves vs. Mental Spells.\nReversible (Madness).", "isCustom": false},
    "shaman_find_the_path": {"id": "shaman_find_the_path", "name": "Find the Path", "level": 6, "casterType": "shadow_shaman", "range": "0", "duration": "6 turns +1 turn per level", "effect": "show the way to the indicated place", "description": "The caster names a specific, unique place and for the duration instinctively knows the direction to it and any special knowledge needed to get there (secret doors, shortcuts, passwords), but not traps along the way. The knowledge fades when the spell ends, and places shielded from divination cannot be found.", "isCustom": false},
    "shaman_resurrection": {"id": "shaman_resurrection", "name": "Resurrection", "level": 6, "casterType": "shadow_shaman", "range": "60 feet", "duration": "permanent", "effect": "resuscitate a humanoid corpse; reverse kills a living being (ST at -2 causes only 3d6 hp)", "description": "Raises a humanoid within 60 feet that has been dead no longer than 2 days per caster level, if at least 80% of the body is intact, at a cost of 1,000 gp in valuables per level of the deceased. The subject returns with 1 hp and must rest two weeks (unless healed by heal). Against undead it destroys them unless they save vs. Spells at -2 (then 3d6 damage). The reverse, finger of death, kills a living creature unless it saves vs. Death Ray at -2 (then 3d6 damage).\nReversible (Finger of Death).", "isCustom": false},
    "shaman_holy_power": {"id": "shaman_holy_power", "name": "Holy Power", "level": 6, "casterType": "shadow_shaman", "range": "0", "duration": "24 hours", "effect": "the cleric obtains 1 extra spell of 1st, 2nd, and 3rd level, and can be easily turn undead", "description": "Cast at dusk before sleeping; after an extra hour of meditation the next morning, the caster memorises one extra spell each of 1st, 2nd and 3rd level, kept for 24 hours or until cast. For the day he also gains +1 to all rolls to turn or control undead. Two holy power spells are not cumulative.", "isCustom": false},
    "shaman_forbiddance": {"id": "shaman_forbiddance", "name": "Forbiddance", "level": 6, "casterType": "shadow_shaman", "range": "120 feet", "duration": "permanent", "effect": "prevents planar travel in the area of effect and damage creatures that attempt to enter it", "description": "Wards a cube of up to 30 feet per side per level against creatures of other alignments: they cannot enter by teleport or planar travel. Entering physically requires a save vs. Spells: differing on one alignment axis, failure means 4d6 damage and expulsion; differing on both, 8d6; success means half damage. A password can be set; dispel magic only suppresses it for 1d10 rounds.", "isCustom": false},
    "shaman_control_destiny": {"id": "shaman_control_destiny", "name": "Control Destiny", "level": 6, "casterType": "shadow_shaman", "range": "0", "duration": "permanent until used", "effect": "modify the shaman's destiny", "description": "Radiance spell: the shaman commits a number of souls (at least 5) from a soul crystal, all of which are weakened for a week. Before one of his dice rolls (attack, save, damage or skill check) he declares the spell in use; if the roll fails he may improve it by 1 point per soul, never beyond the dice's natural maximum. Several castings can be stored. If fewer than 5 charged souls are available, the spell fails and all souls in the crystal are weakened.\nRadiance spell: uses souls from your soul crystal. Source: new Shadow Shaman spell.", "isCustom": false},
    "shaman_creeping_doom": {"id": "shaman_creeping_doom", "name": "Creeping Doom", "level": 7, "casterType": "shadow_shaman", "range": "120 feet", "duration": "1 round per level", "effect": "create a 400 ft3 insect swarm", "description": "Summons a swarm of 1,000 insects filling 400 cubic feet within 120 feet, moving 60 feet per round. It deals 1 hp per 10 insects (100 hp per round) to every creature inside, with no save. Normal weapons cannot harm it; area spells kill 1 insect per hit point of damage. It vanishes if more than 120 feet from the caster and cannot enter protection from evil or anti-insect/anti-animal barriers.\nSource: druid list.", "isCustom": false},
    "shaman_delayed_action_fireball": {"id": "shaman_delayed_action_fireball", "name": "Delayed Action Fireball", "level": 7, "casterType": "shadow_shaman", "range": "240 feet", "duration": "special", "effect": "40 ft. diameter fireball that explodes after a delay, causing 1d6 hp per level", "description": "Listed in the book as Fireball, Delayed Action. Creates a pebble within 240 feet that explodes as a fireball after a delay of 0 to 60 rounds chosen by the caster, dealing 1d6 damage per level (max 20d6) to all in the area, save vs. Spells for half. The pebble looks normal, can be carried safely until it goes off, and can be destroyed by dispel magic or nullified in an anti-magic area.\nSource: Arcane Magic.", "isCustom": false},
    "shaman_holy_word": {"id": "shaman_holy_word", "name": "Holy Word", "level": 7, "casterType": "shadow_shaman", "range": "0", "duration": "special", "effect": "word damages creatures within the area of effect", "description": "All creatures within 60 feet not devoted to the caster's Immortal or church are affected according to their level or HD relative to the caster: 9+ lower, instant death; 5-8 lower, paralysed 2d10 turns; 1-4 lower, stunned 2d10 rounds; equal, blinded 1d10 rounds; higher, deafened 1d10 rounds. Only creatures of the caster's alignment may save vs. Spells to avoid it; extraplanar beings are sent home for 24 hours.", "isCustom": false},
    "shaman_true_resurrection": {"id": "shaman_true_resurrection", "name": "True Resurrection", "level": 7, "casterType": "shadow_shaman", "range": "60 feet", "duration": "permanent", "effect": "resuscitate any being; reverse kill any living being", "description": "Restores any creature to life, fully healed with lost parts regenerated, if at least 50% of the body remains and it has been dead no more than 2 months per caster level; it costs 3,000 gp per level/HD of the deceased (or the subject loses xp or 1 Constitution). Undead up to 7 HD are destroyed outright; 8+ HD must save vs. Spells at -4 or die (4d10 damage on a success). The reverse, obliterate, has the same effect on living beings.\nReversible (Obliterate).", "isCustom": false},
    "shaman_discharge_soul_power": {"id": "shaman_discharge_soul_power", "name": "Discharge Soul Power", "level": 7, "casterType": "shadow_shaman", "range": "60 feet per level", "duration": "instantaneous", "effect": "a discharge of poisonous energy", "description": "Radiance spell taking a full turn to cast: it draws 2d10 souls from a soul crystal, causing a fireball-like explosion of 1d6 per soul (rerolling 1s), doubled against stone or metal and halved against living beings. A poisonous smoke cloud then spreads 300 feet per soul; anyone staying in it for a day must save vs. Poison or contract a flesh-rotting disease. The souls are weakened for a week; if there are too few, the crystal may shatter, forcing the shaman to save vs. Death Ray at -2 or die.\nRadiance spell: uses souls from your soul crystal. Source: new Shadow Shaman spell.", "isCustom": false},
    "shaman_survival": {"id": "shaman_survival", "name": "Survival", "level": 7, "casterType": "shadow_shaman", "range": "touch", "duration": "1 hour per level", "effect": "protect a creature from all non-magical damage from the surrounding environment", "description": "The touched creature is protected from hostile environmental conditions: it needs no air, food, water or rest and is immune to extreme heat and cold, inhaled poisonous gases, and the natural hazards of other planes. It gives no protection from physical or magical attacks.", "isCustom": false},
    "shaman_earthquake": {"id": "shaman_earthquake", "name": "Earthquake", "level": 7, "casterType": "shadow_shaman", "range": "400 feet", "duration": "instantaneous", "effect": "create an earthquake in the area of effect that opens cracks in the ground and makes the structures present fall", "description": "Causes an earthquake over a square of 5 feet per level within 400 feet; non-flying creatures in it cannot attack or move. Collapsing caves, cliffs and structures deal 10d6 damage (save vs. Paralysis for half); on open ground creatures must save vs. Paralysis or fall and have a 25% chance of falling into cracks that close and crush them; water bodies turn to mud or quicksand.", "isCustom": false},
    "radiance_call": {"id": "radiance_call", "name": "Call Upon Radiance", "level": 5, "casterType": "radiance", "range": "30' radius from the receptacle", "duration": "1 round per level", "effect": "Increases spell effects", "description": "Cast your spells as if you were one level higher per nobility rank: Baron 1, Viscount 2, Count 3, Marquis 4, Duke 5, Archduke 6, Prince 7. If the caster's level makes no real difference to a spell, instead increase its range (not range 0), duration (not permanent or instantaneous) or area of effect (not single targets) by 10% per rank (+10% for a Baron to +70% for a Prince). Spells never deal more than 20d6. Requires the receptacle.\nRadiance spell: researched at double cost and half chance (GAZ3).", "source": "GAZ3 The Principalities of Glantri, pp. 77-78", "isCustom": false},
    "radiance_summon": {"id": "radiance_summon", "name": "Summon Radiance", "level": 6, "casterType": "radiance", "range": "24 miles per nobility rank", "duration": "1 round per level", "effect": "Using the Radiance away from the receptacle", "description": "Benefit from the Radiance without staying near the receptacle. A Baron can Call upon the Radiance within 24 miles of the capital or his receptacle, a Viscount 48, a Count 72, a Marquis 90, a Duke 120, an Archduke 144 and a Prince 168 miles. Works only on the Prime Material Plane.\nRadiance spell: researched at double cost and half chance (GAZ3).", "source": "GAZ3 The Principalities of Glantri, pp. 77-78", "isCustom": false},
    "radiance_retain": {"id": "radiance_retain", "name": "Retain Power", "level": 7, "casterType": "radiance", "range": "0 (caster only)", "duration": "Permanent", "effect": "Build up personal Radiance power", "description": "Store Radiance power for later: each casting adds 1d20 rads to your reserve, spent with control destiny or discharge. You can safely hold rads equal to your level. Beyond that, each excess rad gives a 1% chance of 2 hp damage per excess rad and of the rotting disease on one part of the body, checked when this spell is cast. With 12 or more rads you glow an eerie blue, like continual light; it cannot be dispelled and fades below 12 rads.\nRadiance spell: researched at double cost and half chance (GAZ3).", "source": "GAZ3 The Principalities of Glantri, pp. 77-78", "isCustom": false},
    "radiance_destiny": {"id": "radiance_destiny", "name": "Control Destiny", "level": 7, "casterType": "radiance", "range": "0 (caster only)", "duration": "Permanent until used", "effect": "Affects the fate of the caster", "description": "Alter dice rolls affecting you, using stored rads. Cast in advance; before an event you state that its result may be altered, and if the roll fails you spend 1 rad per point to change it. At least 5 rads are spent whether the roll succeeded or not. One spell affects one roll. Any number can be cast before an adventure, within 30' of the receptacle. Affects attack rolls, saving throws, weapon or spell damage and ability checks; you cannot get a result better than the dice could produce. If you run out of rads the spell is expended.\nRadiance spell: researched at double cost and half chance (GAZ3).", "source": "GAZ3 The Principalities of Glantri, pp. 77-78", "isCustom": false},
    "radiance_discharge": {"id": "radiance_discharge", "name": "Discharge", "level": 8, "casterType": "radiance", "range": "20 yards per level", "duration": "Instantaneous", "effect": "Poisonous energy blast", "description": "Release some or all of your stored rads as an energy blast followed by flames, like a 20d6 fire ball: double damage against stone or metal, normal against softer objects, half against living creatures. Only outdoors; takes a turn to cast. A flash, a thunderclap and a billowing cloud follow; the smoke spreads 200 yards per rad spent, and anything remaining in it for a full day must save vs. poison or catch the Radiance's rotting disease (+1 in a log cabin, +5 in a fortress, automatic underground). The cloud ignores wind and lasts one day.\nRadiance spell: researched at double cost and half chance (GAZ3).", "source": "GAZ3 The Principalities of Glantri, pp. 77-78", "isCustom": false},
    "radiance_transcend": {"id": "radiance_transcend", "name": "Transcend Life Force", "level": 9, "casterType": "radiance", "range": "0 (caster only)", "duration": "2d12 hours", "effect": "Attempt to reach Immortality", "description": "The culmination of a Glantrian wizard's career. Requires 50 rads, knowledge of all Radiance spells, the rank of Archduke or Prince, membership of the Brotherhood, and the ingredients: a lich's skull, a nightwing's tongue, 12 ounces of ashes of a greater phoenix, a pint of fresh gremlin blood, two mandragoras, a tooth of the Star Dragon, two malfera eyes and 12 feathers of an archon. Cannot be cast more than 36 miles from the capital. In a dream you walk a dark corridor toward a golden door, with a 5% chance per level above 20th of reaching it. Failure: 2d4 days of pain (30% spell failure), no Radiance for a day per percent missed, and a save vs. death ray or lose a point of Constitution. Success: duel the Empyreal of the Sphere of Energy; victory makes you a Novice Immortal, defeat imprisons your soul in the artifact.\nRadiance spell: researched at double cost and half chance (GAZ3).", "source": "GAZ3 The Principalities of Glantri, pp. 77-78", "isCustom": false},
    "imm_acid_rain": {"id": "imm_acid_rain", "name": "Acid Rain", "level": 7, "casterType": "immortal", "range": "360 feet", "duration": "1 round per level", "effect": "Acid rain that causes 1d6 hp/lvl per round", "area": "30 foot sided cube", "description": "This spell creates an acid storm in the indicated area of effect that lasts for 1 round per mage level. All those that are inside the area suffer 1d6 points of damage per mage level each round they remain in the rain. The damage can be halved with a successful ST vs. Dragon Breath, and also affects materials and constructions present melting and damaging their Structural Points based on the hp caused; the damage can be halved with a ST appropriate to the type of material (see Volume 3 for the Saving Throws of Objects), but stone isn’t affected by the acid. This effect cannot be made permanent.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 148", "school": "Conjuration", "isCustom": false},
    "imm_aestheticism": {"id": "imm_aestheticism", "name": "Aestheticism", "level": 1, "casterType": "immortal", "range": "", "duration": "", "effect": "", "description": "Granted by an Immortal in the Tome of the Magic of Mystara Vol. 2 (Divine Magic), Appendix \"Additional spells of each Immortal\". The provided books (Tome Vol. 1-2, Rules Cyclopedia) do not describe this spell; ask your DM or use your own source.", "source": "Tome of the Magic of Mystara Vol. 2, Appendix (no description)", "isCustom": false},
    "imm_alarm": {"id": "imm_alarm", "name": "Alarm", "level": 2, "casterType": "immortal", "range": "Touch", "duration": "1 hour per level", "effect": "Item warms of the presence of a species", "area": "An object", "description": "Uttering this spell, the mage touches an object that from that moment becomes sensitive to the presence of a particular type of being. If an individual of that species approaches to within 30 feet of the object, it will trigger an alarm that can be heard by all or just the mage (the mage chooses which when casting the spell). The alarm doesn’t sound of the creature, before entering the area of D LEVEL effect, speaks the command word established by the mage when casting the spell. Mental alarm: The alarm only alerts the spellcaster as long as he remains within 1½ miles of the object. He perceives a ringing in his mind strong enough to waken him if he is asleep, but doesn’t disturb his concentration; a silence spell has no effect on a mental alarm. Audible alarm: An alarm generates a blast of Strong intensity (see the rules for the Listen skill in the appropriate manual). The ringing lasts 1 round and automatically awakens any sleeping creature within 60 feet (except those under the effect of magic sleep), but is blocked by an area of silence. The alarm only vanishes at the end of the spell, so it can function more than once. Invisible creatures also trigger the alarm, but not ethereal creatures. Moreover, the alarm can be fooled by magic disguises and illusions.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 55", "school": "Abjuration", "isCustom": false},
    "imm_alter_memories": {"id": "imm_alter_memories", "name": "Alter Memories", "level": 6, "casterType": "immortal", "range": "", "duration": "", "effect": "", "description": "Granted by an Immortal in the Tome of the Magic of Mystara Vol. 2 (Divine Magic), Appendix \"Additional spells of each Immortal\". The provided books (Tome Vol. 1-2, Rules Cyclopedia) do not describe this spell; ask your DM or use your own source.", "source": "Tome of the Magic of Mystara Vol. 2, Appendix (no description)", "isCustom": false},
    "imm_alter_writing": {"id": "imm_alter_writing", "name": "Alter Writing", "level": 1, "casterType": "immortal", "range": "Touch", "duration": "Special (max 1 day per level)", "effect": "Alter a written text for a certain period of time", "area": "A non-magical written text", "description": "Casting this spell the places his hand over a non magical piece of writing of any type and can alter the contents of 1 page per level (max. 100 words per level) to his liking. The alteration is in the handwriting of the original writer or the cleric’s (his choice) and doesn’t leave any traces or dents in the surface. The writing gives off an aura of transmutation if analysed with spells, but unless it is restored the original writing cannot be read. The alteration lasts until magically dispelled or until a certain condition specified by the cleric is met (e.g. the reader says a certain word, or a certain person touches the writing, etc.). If the condition isn’t met, the effect disappears after a maximum of one day per caster level.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 52", "isCustom": false},
    "imm_analyse": {"id": "imm_analyse", "name": "Analyse", "level": 1, "casterType": "immortal", "range": "Touch", "duration": "Instantaneous", "effect": "Reveal a property of an item", "area": "An object", "description": "Thanks to this spell, the mage can analyse an item by just wearing (if it is clothing or a jewel) or holding it (for weapons or other unwearable items), also eventually know the type of magic that permeates it. However, any consequence derived from wearing or holding it (if for example the item is cursed), is applied normally to the spellcaster that seeks to discern the item’s nature (although he has the benefit of any normally allowed Saving Throw). The spellcaster has a base chance of 25%, plus 5% for each experience level, of learning one characteristic of the object, either a piece of data relating to its magical nature or simply to its mundane nature (in this latter case, it is up to the spellcaster to determine the type of information desired). This spell doesn’t permit the spellcaster to learn the exact number of charges in a magic item, but only an approximation within 25%, while it does give the exact bonus of weapons, armour, rings, and so on. If a magic item has more than one power (for example a sword +3, +6 vs. dragons, breathing), only one is given with each casting of this spell, along with its activation word. Analyse doesn’t however reveal the powers of artefacts. If the spell is used to enchant an item with the usual procedure (see Volume 3), each use gives one characteristic of another touched magic item; if analyse is made permanent, then all the magic characteristics of the touched item are immediately known, although the number of charges is always imprecise (see above).", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 37", "school": "Divination", "isCustom": false},
    "imm_animal_form": {"id": "imm_animal_form", "name": "Animal Form", "level": 3, "casterType": "immortal", "range": "0", "duration": "1 turn per level", "effect": "The spellcaster is transformed into an animal", "area": "Only the spellcaster", "description": "This spell can transform the spellcaster into a normal or giant animal (as long as it exists in nature) whose Hit Dice don’t exceed the spellcaster’s level. For the spell’s duration, the subject becomes for all intent the selected animal, while his equipment melds into the new form and therefore cannot be used. LEVEL The spellcaster keeps his own hp, ST, THAC0, and physical and mental abilities, but acquires the movement, AC, and the number and type of attacks of the animal in question, as well as its senses and language (can therefore communicate with animals of the same type), and cannot use magic items or cast spells. The spellcaster can return to his original form when he wants (the process takes a round), but at that moment the spell ends. While the spell is active, the spellcaster can assume the form of another type of animal simply by concentrating for a round.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 72", "school": "Transmutation", "isCustom": false},
    "imm_anti_animal_barrier": {"id": "imm_anti_animal_barrier", "name": "Anti-animal Barrier", "level": 4, "casterType": "immortal", "range": "", "duration": "", "effect": "", "description": "Granted by an Immortal in the Tome of the Magic of Mystara Vol. 2 (Divine Magic), Appendix \"Additional spells of each Immortal\". The provided books (Tome Vol. 1-2, Rules Cyclopedia) do not describe this spell; ask your DM or use your own source.", "source": "Tome of the Magic of Mystara Vol. 2, Appendix (no description)", "druidSpell": true, "isCustom": false},
    "imm_anti_magic_barrier": {"id": "imm_anti_magic_barrier", "name": "Anti-magic Barrier", "level": 6, "casterType": "immortal", "range": "0", "duration": "12 turns", "effect": "Personal barrier that defends against magic", "area": "Only the spellcaster", "description": "This spell creates around the spellcaster’s body (less than half an inch from him) an invisible barrier, which prevents any magical effect from entering or leaving the barrier. This means that no spell or magical effect (produced by items or creatures with magic powers) can hit the mage, and similarly that the mage cannot cast any other spells or use magical powers, as long as the barrier remains active. The anti-magic barrier doesn’t however annul the permanent spell placed on weapons or armour (so a +5 sword that hits a mage protected by this spell doesn’t lose its bonus), or dismiss the magic effects active on the subject before the barrier was created (for example, if the mage already had on himself a haste, protection from evil, and contingency, the spells continue to have effect despite the barrier), and doesn’t even prevent a summoned or controlled creature from attacking him. It only affects magical effects created afterwards (whether from magic items or the spellcaster’s memory) annulling them. In fact, as normally the formula invokes the raw magical energy from the environment and allows it to flow through the spellcaster’s body (or the item that evoked it), which shapes it and releases it in the form of a specific magical effect; it is therefore impossible to use new spells or produce magic effects from items after having created the barrier. The spellcaster can dismiss the barrier when he wants, thus ending the spell, otherwise it continues to exist until the end of the spell’s duration (12 turns). No magic power (including dispel magic) is able to dispel the antimagic barrier, with the exception of wish and disjunction, and if the barrier comes into contact with another antimagic area, the two areas simply ignore each other without either prevailing or dispelling the other.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 130", "school": "Abjuration", "isCustom": false},
    "imm_arcane_breath": {"id": "imm_arcane_breath", "name": "Arcane Breath", "level": 2, "casterType": "immortal", "range": "0", "duration": "Instantaneous", "effect": "Cone of fire or cold causes 1d4 hp per level", "area": "45 foot long, 15 foot wide cone", "description": "When casting this spell, the mage can select which form to use, from between fire breath and ice breath. In both cases, from the spellcaster’s mouth springs a cone of energy (fire or ice) 45 feet long and 15 feet wide, and all creatures within the area of effect suffer 1d4 points of damage per mage level (max 20d4), but can halve the damage with a successful ST vs. Dragon Breath. Beings of cold (like frost giants and ice salamanders) automatically suffer half damage from ice breath (and can reduce it to a quarter with a successful ST), while undead and constructs are immune to the effect. Beings of fire (like efreet and fire salamanders) automatically suffer half damage from fire breath, and can reduce it to a quarter with a successful ST.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 56", "school": "Evocation", "isCustom": false},
    "imm_arcane_sight": {"id": "imm_arcane_sight", "name": "Arcane Sight", "level": 6, "casterType": "immortal", "range": "0", "duration": "1 minute per level", "effect": "Spellcaster sees magic active within 120 feet", "area": "120 foot radius", "description": "As long as this spell is active the mage is able to identify without fail any magic effect within 120 feet (in red those derived from arcane magic, in blue those derived from divine magic, whose brightness increases based on the power level) and knows the school that each power placed on the item or place belongs to, simply by concentrating. Moreover, if the spellcaster concentrates on a creature, he is able to determine if it has spellcaster level and how many, which type of magical ability it has, the spells active on it as the moment, and even the level of the highest level spell it can cast at that moment. If instead he concentrates on a place or item, he is able to determine the gravity of curses and the item’s level of power (adding the levels of the evocable spells to the item in question’s magic bonus).", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 131", "school": "Divination", "isCustom": false},
    "imm_astral_body": {"id": "imm_astral_body", "name": "Astral Body", "level": 7, "casterType": "immortal", "range": "0", "duration": "1d4+1 hours", "effect": "Mage’s spirit is split from the body", "area": "Only the spellcaster", "description": "To evoke the spell the mage must not be in a stressful situation or fatigued, as the spell needs all his physical and mental force (it cannot therefore be used in the mind of a battle or in a storm, or if injured or in any way incapacitated). The mage must lie down and begin to meditate for 1 turn, repeating the formula that evokes the spell. After a turn he feels a sensation of incredible lightness and rises from the ground as if carried by the air. In reality, his physical body remains fixed in place and in its initial position, while that that separates is his astral projection. The astral body, impossible for anyone that cannot see invisible to notice, is extremely light and identical to the physical body that the mage has left behind. With it the mage can fly through space and solid objects at a speed of 2½ miles per minute (150 mph), using his visual and auditory senses as normal. The astral body doesn’t need to breathe (can even travel in the void), and can move between the Astral and the plane where his physical form is once a round by concentrating. His AC and all other characteristics remain unchanged. On any plane except the Astral, the projection cannot communicate with any physical being lacking telepathy, damage anyone, or cast spells. Only the incorporeal creatures and spirits that he encounters in these planes can interact with him; mutually able to speak or damage each other when they meet. On the other hand only at least +5 magic weapons, magical creatures with at least 20 HD, or spells of 6th level or higher that don’t act on the physical body but affect the soul or mind are able to damage the projection on these planes (it is important to note that astral body isn’t able to penetrate a prismatic wall without suffering the consequences, or pass through a forcefield). If instead the projection enters the Astral Plane, it assumes a more real, although two-dimensional, consistency. On this place it can interact normally with all (speak and be seen), is considered a native being of the Astral, and remains invulnerable to any non-magical weapon, although it can be hit by any spell and is able to cast spells memorised by the mage. If the astral body is injured, the damage is subtracted from the character’s real body, and if the mage is killed before returning to his real body, then his soul is destroyed and there is no way of it being returned to life. The spellcaster automatically returns to his body at the end of the spell’s duration (1d4+1 hours), regardless of where he is at that moment. He can reunite with his body earlier by returning to the exact place where he left it and merged back into it: although this ends the spell. Finally, if the astral body or the physical body are hit by a dispel magic, there is the normal chance that the spell is annulled and he reawakens in his body. A further note: while in his astral form, the mage isn’t aware of what happens to his physical body, unless it is damaged (i.e. loses hp). In this case, he has a painful fit that lets him know that something serious has happened. If the body is destroyed or mortally wounded before the astral body reunites with it, the spellcaster dies and there is a chance equal to double his level that he is transformed into a phantasm (type chosen by the DM with 9+ HD). If instead he doesn’t become undead, he can be resurrected normally (this cannot happen if the astral body has been destroyed).", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 148", "school": "Transmutation", "isCustom": false},
    "imm_atruaghin_s_favour": {"id": "imm_atruaghin_s_favour", "name": "Atruaghin’s Favour", "level": 5, "casterType": "immortal", "range": "Touch", "duration": "Special", "effect": "As the consecrate spell, plus the shaman and allies ignore their first failed ST", "area": "An area or group of creatures", "description": "This spell is the most potent magical ritual of the shamans of Atruaghin and is only used in the most solemn ceremonies, when it is used to create sanctuaries and places of faith. In game terms, Atruaghin’s favour can be used like the consecrate spell, but also imbues the cleric and his companions (up to one character per level) a special protection, making each of them automatically succeed the first Saving Throw they would otherwise have failed (basically it overturns the ST result). When this happens, the spell ends for that specific person, but continues for the other blessed creature for an indefinite period or until magically dispelled.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 74", "isCustom": false},
    "imm_aura_of_unpredictability": {"id": "imm_aura_of_unpredictability", "name": "Aura of Unpredictability", "level": 7, "casterType": "immortal", "range": "0", "duration": "1 round per level", "effect": "Random effects take place each round", "area": "20 feet radius sphere", "description": "When casting this spell, the cleric is wrapped by an invisible, 20 feet radius spherical aura, all inside frantically experience random events that change the surrounding reality in unexpected and unpredictable ways. The effect of the spell moves with the cleric, who cannot end it before its entire duration has run. At the start of each round, roll percentage dice to determine what will happen to all the creatures present within the area: neither the cleric nor anyone else is able to predict what will happen that round before directly experiencing it (there is no ST to avoid the effects). This spell cannot be made permanent on a magic item. TABLE 2.7 –EFFECTS OF AURA OF UNPREDICTABILITY d% Effect All the spells cast in that round by spellcasters that are in the area of effect have a 50% malfunction chance (the DM arbitrarily decides if the spell simply doesn’t function or as a 01-10 contrary effect to that desired). Spells cast previously, or cast from outside on creatures that are outside the area of effect aren’t affected. All the spells cast in this round by spellcasters within the area of effect have their duration doubled (if this effect isn’t applicable, 11-20 like for spells of instantaneous or permanent duration, nothing happens). All spells cast in this round by spellcasters within the area of effect have their duration halved if this effect isn’t applicable, 21-30 like for spells of instantaneous or permanent duration, nothing happens). All creatures within the area of effect become hasted (see the 31-40 haste spell) for the entire round. All creatures within the area of effect are slowed (see the slow 41-50 spell) for the entire round. All the creatures within the area of effect become lucky for the 51-60 full round: they gain a +1 bonus to all d20 rolls (like Attacks, ST, skill checks, etc.) and +5% to all d% rolls (e.g. thief skills). All the creatures within the area of effect become unlucky for 61-70 the full round: they suffer a –1 penalty to all d20 rolls and –5% to all d% rolls. All spells (except aura of unpredictability) and magic effects 71-80 within the area are dispelled; the failure chance is analogous to that of dispel magic spell cast by a spellcaster of the cleric’s level. All creatures within the area, except the caster, are teleported to a distance of 32d20 feet from the cleric in a randomly chosen 81-90 direction (the subject cannot materialise in a space already occupied by a solid or in an anti-magic zone) 91-00 The spell’s duration is increased by 1d4 rounds.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 79", "isCustom": false},
    "imm_authority": {"id": "imm_authority", "name": "Authority", "level": 3, "casterType": "immortal", "range": "0", "duration": "3 turns", "effect": "Cleric becomes authoritative leader", "area": "Only the cleric", "description": "Thanks to this spell the cleric is surrounded by an aura of authority and prestige: in game terms he gains a +4 bonus to all checks related to the general skills Authority and Persuasion. Moreover, he can give an order each round by speaking a single word (exactly like the command word spell): the order must be directed at a single living creature that can understand the language the order was expressed in. The creature has the right to a ST vs. Spells to avoid obeying: if successful, he is immune to the commands given by that cleric for 1 turn.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 60", "isCustom": false},
    "imm_balance": {"id": "imm_balance", "name": "Balance", "level": 1, "casterType": "immortal", "range": "", "duration": "", "effect": "", "description": "Granted by an Immortal in the Tome of the Magic of Mystara Vol. 2 (Divine Magic), Appendix \"Additional spells of each Immortal\". The provided books (Tome Vol. 1-2, Rules Cyclopedia) do not describe this spell; ask your DM or use your own source.\nReversible.", "source": "Tome of the Magic of Mystara Vol. 2, Appendix (no description)", "isCustom": false},
    "imm_bastion": {"id": "imm_bastion", "name": "Bastion", "level": 7, "casterType": "immortal", "range": "1,600 feet", "duration": "A day every 3 levels", "effect": "Protect a building from damage and intrusion", "area": "A structure of max surface 100 ft2 per level", "description": "This potent spell covers a building in hologlyphs of protection that fortify it and make it more resilient and impenetrable. The spell only affects a static structure whose surface isn’t greater than 100 ft2 per mage level (height isn’t important, as the spell protects all the building’s floors). If the construction is too large or if the mage wants it, the spell can be used to just protect a specific part of it (for example a castle wing, a fort’s tower, etc.). Six hours are needed to complete the ceremony that places the glyphs to guard the building, and in the process the mage consumes magical materials equal to 2 g.p. per square foot of affected surface. If the mage is interrupted in some way (injured, stunned, silenced) before the end of the ritual, the spell is wasted, as are all the materials used up to then. A construction can only receive one application of this spell. The building that benefits from the bastion automatically reduces to a quarter all the structural damage it suffers (both magical and natural). Moreover, any spell that alters its structure (like passwall or dissolve) is totally ineffective against it. As if this isn’t enough, bastion places an always active protection from evil on the construction, and it has a 50% chance of preventing access by any instantaneous transport spell (teleport, dimension door, etc.). Bastion lasts for one day per 3 mage levels (rounded down) or until the building is destroyed, but it cannot be magically dispelled. This effect cannot be bound to a permanency and can only be cast on a building, not a magic item.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 150", "school": "Abjuration", "isCustom": false},
    "imm_bind_air_elemental": {"id": "imm_bind_air_elemental", "name": "Bind Air Elemental", "level": 7, "casterType": "immortal", "range": "", "duration": "", "effect": "", "description": "Granted by an Immortal in the Tome of the Magic of Mystara Vol. 2 (Divine Magic), Appendix \"Additional spells of each Immortal\". The provided books (Tome Vol. 1-2, Rules Cyclopedia) do not describe this spell; ask your DM or use your own source.", "source": "Tome of the Magic of Mystara Vol. 2, Appendix (no description)", "isCustom": false},
    "imm_bind_earth_elemental": {"id": "imm_bind_earth_elemental", "name": "Bind Earth Elemental", "level": 7, "casterType": "immortal", "range": "", "duration": "", "effect": "", "description": "Granted by an Immortal in the Tome of the Magic of Mystara Vol. 2 (Divine Magic), Appendix \"Additional spells of each Immortal\". The provided books (Tome Vol. 1-2, Rules Cyclopedia) do not describe this spell; ask your DM or use your own source.", "source": "Tome of the Magic of Mystara Vol. 2, Appendix (no description)", "isCustom": false},
    "imm_bind_water_elemental": {"id": "imm_bind_water_elemental", "name": "Bind Water Elemental", "level": 7, "casterType": "immortal", "range": "", "duration": "", "effect": "", "description": "Granted by an Immortal in the Tome of the Magic of Mystara Vol. 2 (Divine Magic), Appendix \"Additional spells of each Immortal\". The provided books (Tome Vol. 1-2, Rules Cyclopedia) do not describe this spell; ask your DM or use your own source.", "source": "Tome of the Magic of Mystara Vol. 2, Appendix (no description)", "isCustom": false},
    "imm_bite_of_the_vampire": {"id": "imm_bite_of_the_vampire", "name": "Bite of the Vampire", "level": 3, "casterType": "immortal", "range": "Touch", "duration": "", "effect": "", "description": "Area of Effect: one living creature with blood Duration: special Effect: suck life energy to heal While invoking this spell the spellcaster must touch a living creature (a touch attack): if successful, he absorbs 2 HP per level from the victim (max +20 HP at 10th-level). With this spell, the mage can accumulate HP above his maximum up to one third of his total: any other applications damage the victim but don’t further increase the spellcaster’s HP. The HP acquired in this fashion are permanent, while those that exceed his HP maximum remain for 6 turns, or vanish earlier if dispelled magically or physically (from the mage taking damage). The victim can only recover the lost HP through magical cures. If he dies because of the bite of the vampire and the corpse isn’t destroyed or purified with remove curse or a spell that prevents it returning from the grave, after 24 hours it is reanimated as a ghoul (if it had 1 to 3 HD/levels) or as a spectre (with 4+ HD/levels), and acts freely, driven by evil aims and hunger. This effect cannot be made permanent.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 72", "school": "Necromancy", "isCustom": false},
    "imm_bleeding_wound": {"id": "imm_bleeding_wound", "name": "Bleeding Wound", "level": 1, "casterType": "immortal", "range": "60 feet", "duration": "1 hour per level", "effect": "Cause an extra 1d4 hp when a victim is wounded", "area": "One creature", "description": "This spell prevents the victim’s wounds from healing normally, causing a substantial spillage of blood. In game terms, if the designated victim doesn’t make a ST vs. Spells to avoid the effect, each wound received during the spell’s duration causes the subject to lose 1d4 Hit Points in addition to the damage suffered. The effects of bleeding wound can be negated only by a curative spell of any level. Undead, constructs, and creatures without bodily fluids (like oozes) are immune to the effects of this spell.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 52", "isCustom": false},
    "imm_blinding_light": {"id": "imm_blinding_light", "name": "Blinding Light", "level": 6, "casterType": "immortal", "range": "0", "duration": "Variable", "effect": "Blind all creatures within range", "area": "3 feet radius per level", "description": "Once he has uttered this spell, the mage emits a dazzling ray of light from his body. Anyone that is within the spell’s area of effect (3 feet per caster level) and has a clear sight of the mage remains blinded for a period of time that depends external conditions: if in the presence of light it remains blind for 1d4+1 rounds, if in the dark for 3d6 rounds (no ST allowed to negate the effect). Creatures that don’t use sight to perceive their surroundings are immune. Moreover, all the undead in the area of effect of the blinding light receive 3d6 points of damage because of the exposure to the sunlight, and those that survive flee away from the spellcaster as if under a successful turn undead attempt.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 131", "school": "Evocation", "isCustom": false},
    "imm_blood_thirst": {"id": "imm_blood_thirst", "name": "Blood Thirst", "level": 3, "casterType": "immortal", "range": "Touch", "duration": "1 round per level", "effect": "+2 damage bonus (+4 vs. demi-humans) and regenerate 1 hp per killing blow", "area": "A goblinoid", "description": "This spell exclusively affects goblinoid beings (kobold, goblin, hobgoblin, gnoll, bugbear, orc, ogre, and troll). The subject gains a +2 bonus to damage inflicted with melee weapons, and with each killing melee blow recovers 1 Hit Point by drinking his enemy’s blood (remembering that these hp cannot take him above his normal limit). If the goblinoid is fighting against a demihuman (dwarf, elf, or halfling) the damage bonus is +4 rather than +2.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 60", "isCustom": false},
    "imm_boiling_blood": {"id": "imm_boiling_blood", "name": "Boiling Blood", "level": 2, "casterType": "immortal", "range": "Touch", "duration": "Instantaneous", "effect": "Blood boils and causes hp = cleric level × 2", "area": "A living creature", "description": "When casting this spell the cleric must touch the target, and the victim’s blood begins to immediately boil provoking burns all over his body that cause damage equal to double the cleric’s level (max. 40 hp at 20th level). The victim can halve the damage with a successful ST vs. Death Ray. Undead, constructs, and creatures without blood are immune to this spell. Touching the victim requires ann attack with the holy symbol, but the victim’s AC doesn’t include his armour, only bonuses from his shield, Dexterity, magic, and weapon mastery.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 55", "isCustom": false},
    "imm_bone_armour": {"id": "imm_bone_armour", "name": "Bone Armour", "level": 2, "casterType": "immortal", "range": "0", "duration": "6 turns", "effect": "Armour gives AC 5 and absorbs 1 damage", "area": "Only the cleric", "description": "This spell creates, around the cleric’s body, bone armour of terrifying appearance, with ribs that protect his torso and limbs, and a hollow skull that covers his head. The armour gives AC 5, absorbs 1 damage and lasts per 6 turns, or until it is destroyed by his enemies’ blows (it can absorb upto double the priest’s Hit Points before falling to pieces) or is magically dispelled.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 55", "isCustom": false},
    "imm_boneshatter": {"id": "imm_boneshatter", "name": "Boneshatter", "level": 6, "casterType": "immortal", "range": "30 feet", "duration": "Instantaneous", "effect": "Fracture victim’s limbs", "area": "A being with limbs", "description": "This spell strikes the bones of the victim’s joints or in general the limbs chosen by the mage, instantly fracturing it and causing to the target 1d6 points of damage per mage level. Moreover, based on the body part chosen by the mage, it has the following secondary effects:  Wings: flight impossible, ground movement reduced to ⅔, −2 penalty to Dexterity.  Arm: impossible to make Attacks using the hands and held items, impossible to cast spells, −4 penalty to Dexterity.  Tail or similar appendage: movement reduced to ⅔, −2 penalty to Dexterity and AC.  Leg: movement reduced to 10 feet per round, Dex halved, −2 AC and ST vs. avoidable effects. If the victim makes a successful ST, the damage is halved, but imparts a −2 penalty to Dexterity until the damage is cured.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 131", "school": "Transmutation", "isCustom": false},
    "imm_bravery": {"id": "imm_bravery", "name": "Bravery", "level": 3, "casterType": "immortal", "range": "Touch", "duration": "1 turn per 2 levels", "effect": "The subject gains a +2 bonus to Strength, immunity to fear, and extra hp", "area": "One living creature", "description": "This spell makes the subject more courageous, agile, and well-set, and thus more predisposed to perform brave and daring actions. For the spell’s duration his Strength increases by 2 points and he is immune to fear and desperation effects. Moreover, if the beneficiary is a follower of the priest’s Immortal, he gains, as well as the effects listed above, extra Hit Points equal to the cleric’s level. These hit points are temporary and can allow him to exceed his maximum hit point total; if the character is wounded, he always removes these first, otherwise they vanish when the bravery ends or is magically dispelled.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 60", "isCustom": false},
    "imm_break_enchantment": {"id": "imm_break_enchantment", "name": "Break Enchantment", "level": 6, "casterType": "immortal", "range": "90 feet", "duration": "Instantaneous", "effect": "Free creature from charms, transmutations, and curses", "area": "A creature per level", "description": "This spell frees the creatures chosen by the mage from charms, transmutations, and curses. The spellcaster must identify a maximum number of creatures equal to his level, which must all be within 90 feet of his position. When it is cast, break enchantment automatically annuls any effect of enchantment, transmutation, or serious curse on them, only if the said effect was created by a being of equal or lower level than the spellcaster. Otherwise, the subject still anyhow benefits from another ST vs. Spells to break the spell. The spell can also be used to free a subject from a cursed item. In this case, the individual no longer feels the need to keep the item and is freed from its curse, although the item retains its curse.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 132", "school": "Abjuration", "isCustom": false},
    "imm_breathe_element": {"id": "imm_breathe_element", "name": "Breathe Element", "level": 3, "casterType": "immortal", "range": "30 feet", "duration": "24 hours", "effect": "Subject breathes through an element", "area": "A creature", "description": "This spell allows its beneficiary to breathe an element decided by the mage from air/gas, water/liquids, fire/lava, and earth/dust/sand as if it was the element that he needs to survive. It doesn’t protect against any noxious substance present in the inhaled element or ingested from the environment (pressure, heat, cold, etc.), but allows his lungs to transform it into the substance he normally breathes (for example on a human breathe water allows him to breathe normally underwater and on the surface). If used on the corresponding elemental plane, it allows to subject to breathe and see in its atmosphere.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 73", "school": "Transmutation", "isCustom": false},
    "imm_bull_s_strength": {"id": "imm_bull_s_strength", "name": "Bull’s Strength", "level": 5, "casterType": "immortal", "range": "120 feet", "duration": "6 turns", "effect": "Gain Strength 18; reverse gives Strength 3", "area": "A creature", "description": "When this spell is cast on a living creature, it’s Strength score becomes 18 for the spell’s duration; it clearly has no effect on creatures that already have a score of 18 or higher in this characteristic. All bonuses (Strength checks, Attack and damage rolls) are immediately applied. The reverse of this spell, weakness, reduces the victim’s Strength score to 3 (with all the penalties that entails), if he fails a Saving Throw vs. Spells; range and duration are the same as the normal spell. Neither effect can be combined with permanency.\nReversible.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 111", "school": "Transmutation", "isCustom": false},
    "imm_burning_hands": {"id": "imm_burning_hands", "name": "Burning Hands", "level": 1, "casterType": "immortal", "range": "10 feet per level", "duration": "Instantaneous", "effect": "Produce a tongue of flames that strikes a target and causes 1d6 hp + 2hp per level (max +20)", "area": "One target", "description": "The spellcaster evokes the power of fire to create a 3 foot long arc of fire that springs from his hand and always hits (no Attack Roll needed) a fixed target that must be with a 180° arc of the spellcaster’s front, and within 10 feet per level. The arc of flame causes 1d6 hp, +2 hp per mage level (max. 1d6+20 at 10th-level), but the victim can attempt a ST vs. Spells for half damage. If the ST fails, all the inflammable items he carries catch fire, and need a full round to extinguish to avoid suffering another 1d6 hp per round from the flames. Individuals protected by resistance to fire and beings of fire (like red dragons and creatures from the plane of fire) automatically take half damage.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 37", "school": "Evocation", "isCustom": false},
    "imm_call_animal": {"id": "imm_call_animal", "name": "Call Animal", "level": 4, "casterType": "immortal", "range": "360 feet", "duration": "Special", "effect": "Evoke and make friendly 1 HD of animals × level", "area": "1 HD of animals per level", "description": "With this spell, the druid can summon one or more normal animals present within 360 feet. It only calls normal creatures, not magical beasts, insects, or beings with higher than animal intelligence (2), but includes all mammals, reptiles, amphibians, fish, and birds (and giant versions). The druid can select one or more known animals, he can summon a specific species, or simply any animal that is plausibly present within range at the DM’s discretion (e.g. it is impossible to successfully call a bear in a desert or a tiger underground). The total Hit Dice of the called animals is equal to the druid’s level: animals of ½ HD count as ½ HD beings. The summoned animals arrive at the caster’s feet within 1d6 rounds (unless they are already around the druid), and for the spell’s duration understands the druid language, are friendly and aid the summoner to the limit of their abilities. The animals remain faithful at the druid’s side for a maximum of 24 hours or until they have lost more than half their total Hit Points; if reduced to below half hp, each round it must make a Moral check or flee (which ends the spell for that animal). If the druid is attacked, each animal that isn’t already performing a task immediately attacks the assailant to protect the summoner, only fleeing if it fails a Morale check after being seriously wounded (see above). Moreover, if the druid attacks of the called animals, this ends the effect for the entire group. Defeating magically created or summoned creatures don’t grant xp unless their summoner has also been defeated.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 121", "druidSpell": true, "isCustom": false},
    "imm_calm_emotions": {"id": "imm_calm_emotions", "name": "Calm Emotions", "level": 3, "casterType": "immortal", "range": "120 feet", "duration": "1 turn", "effect": "Calm the strong emotions of one creature per level and annul blessings, fear, and confusion", "area": "One creature per level", "description": "This spell calms agitated and infuriated creatures, and prevents them from taking any violent actions for its duration. The cleric can choose to influence up to a maximum of being per experience level within 120 feet, and each victim can make a ST vs. Mental Spells mentali to totally avoid the effects. Those that fail the ST are instantly calmed, even if in the middle of a battle, and cannot undertake any destruction acrions, but only protect themselves for 1 turn. Any aggressive action that damages a creature calmed by this spell breaks the effect on the threatened creatures (and only them). This spell moreover suppresses the effects of a bless, and any form of confusion, rage, hate, and fear on the affected subjects, for its duration; if at the end of the turn the duration of the suppressed effects hasn’t ended, they return and affect the creature normally.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 60", "isCustom": false},
    "imm_camouflage": {"id": "imm_camouflage", "name": "Camouflage", "level": 2, "casterType": "immortal", "range": "Touch", "duration": "6 turns", "effect": "Target can change colour and camouflage himself", "area": "A creature", "description": "This spell can change the touched subject’s outer colouring based on the surrounding environment. For the duration of the effect, the subject’s body (including all of his equipment) assumes the colour of his surroundings, camouflaging him like a chameleon: in this form, he only has a 10% chance of being detected if he is stationary. If, instead, he moves, attacks, or casts spells, an Observe check is needed with a base penalty of –2 to detect him beyond automatic range. Moreover, anyone attempting to hit him suffers a –1 penalty to their Attacks as long as the camouflage lasts. Remember that those that cannot see an enemy cannot attack him with missile or thrown weapons, and if the subject surprises an individual he benefits from a +4 bonus to his Attack Roll. The spells detect magic and trueseeing allow the subject to be seen normally.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 57", "school": "Illusion", "isCustom": false},
    "imm_capture_the_soul": {"id": "imm_capture_the_soul", "name": "Capture the Soul", "level": 4, "casterType": "immortal", "range": "Touch", "duration": "Permanent", "effect": "Trap the soul of a deceased in a durable object and can ask it questions once per day", "area": "A corpse", "description": "This spell is only effective if cast on a creature at the moment of its death or up to 1 round after the death. If the victim fails his ST, the spell permanently traps his soul within an object of durable material (which can be mundane or magical, in which case it retains all its powers in addition to the effect of this spell) that is in contact with the corpse. Only if the object is physically destroyed, is the creature’s soul finally freed; not even the use of dispel magic can break the spell, although a disjunction or a wish can achieve the effect. Obviously, while the soul remains imprisoned within the object any attempt to resurrect the deceased automatically fails. In theory, there isn’t a limit on the number of souls that can be imprisoned in the same object with this spell. Anyone touching the object is able to mentally contact the spirit inside it once per day to ask a question. To spirit can only respond with what knowledge it had in life (its experience of the world stops at the moment of its death). If there are questions regarding secrets that the deceased was told to keep, or it receives questions from a creature with a morality that differs from its own, the being can avoid answering clearly, using cryptic phrases or unclear but truthful metaphor. If a spell is used to read thoughts (ESP or Telepathy) while holding the object, it is possible to converse longer with the soul imprisoned there, but in this case the answers are unclear and the victim can always refuse the give the information. Note: Enchanted weapons with this power are automatically activated when killing the victim, who can attempt the ST to prevent its soul from being drawn into the weapon.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 67", "isCustom": false},
    "imm_cat_s_grace": {"id": "imm_cat_s_grace", "name": "Cat’s Grace", "level": 5, "casterType": "immortal", "range": "120 feet", "duration": "6 turns", "effect": "Gain Dexterity 18; inverse gain Dexterity 3", "area": "A creature", "description": "When this spell is cast on a living creature, its Dexterity immediately becomes 18 for the spell’s duration; it clearly doesn’t have any effect on a creature that already has a Dexterity of 18 or higher. It is immediately affects all the derived bonuses (Dexterity check, AC, initiative, etc.). The reverse of this spell, clumsiness, reduces the victim’s Dexterity to 3 (with all the corresponding penalties), if he fails a Saving Throw vs. Spells; range and duration are the same as the normal version. Neither effect can be combined with permanency.\nReversible.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 111", "school": "Transmutation", "isCustom": false},
    "imm_ceremony": {"id": "imm_ceremony", "name": "Ceremony", "level": 1, "casterType": "immortal", "range": "Touch", "duration": "Permanent", "effect": "Consecrate a creature", "area": "One creature", "description": "This is a versatile spell that the demihuman clerics use as a part of the rites that are carried out at the salient moments of their life. These spells leave external signs: some are visible to anyone; others can only be seen by the demihuman clerics. Anyone possessing one of theses marks cannot be identified with detect magic, unless he LEVEL possesses other items that react to that spell. These ceremonies include: Adoption: a ritual that serves to transfer a demihuman (and, in very special occasions, a human or demihuman of a different race) from one clan to another. The cleric that officiates over the ceremony must be of at least the same level as the adopted individual, and the Clanmaster must also participate in the ceremony. It can also serve to create a new sacred relic, taking part of the original relic. Anathema: this ceremony is performed exclusively when a demihuman has deliberately acted against the laws of his community and must be permanently banished from any clan. The rite can only be celebrated by the head of the clan that the traitor belonged to aided by the community’s Keeper. The cursed demihuman acquires a mark, a characteristic sign visible only to the eyes of members of the same race, impossible to hide and that can only be removed if the individual repents his crimes and is accepted back into the clan with a ceremony of adoption. Initiation: a ceremony in which a young demihuman becomes an adult within the community, with the obligations and advantages that follow. This rite must be celebrated by a cleric of higher level than the initiate. Investiture: the ceremony is only performed when a cleric becomes a Relic Keeper, and it must be celebrated by another Keeper (either the Elder or Acolyte Keeper).", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 52", "isCustom": false},
    "imm_charm_animals": {"id": "imm_charm_animals", "name": "Charm Animals", "level": 2, "casterType": "immortal", "range": "120 feet", "duration": "Special", "effect": "Induces friendship in various animals", "area": "Normal animals", "description": "This spell has an identical effect to the 1st-level charm person spell, but influences normal and giants animals of any species, while excluding intelligent monsters (with an Intelligence higher than 2) and fantastic animals, which require the charm monsters spell. If the animals have 3 Hit Dice or less, it can influence 3d6, otherwise it can only charm a number of Hit Dice of animals equal to the spellcaster’s level (1 minimum). Each victim can avoid the charm by making a successful ST vs. Mental Spells, and can repeat it every 24 hours (otherwise, the effect is permanent). The charmed animals are instinctively friendly towards the spellcaster and cannot do anything bad to him, unless he attacks them (which breaks the spell). They can follow simple orders, but if they receive, none continues to follow the spellcaster until they are freed from the spell or removed from it (or the spell is dispelled). If he is attacked in their presence, the animals make a Morale roll, and if it succeeds they throw themselves against the attackers to defend him; if reduced to less than half hp, the spell is dispelled and they flee. If another being attempts to magically control the charmed animals, the spellcaster if he notices it and can resist the effects of the control in place of his animals, making a ST vs. Mental Spells: if the roll succeeds, he maintains control, otherwise the animals follow the orders of their new master and the charm on them is terminated.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 57", "school": "Enchantment", "isCustom": false},
    "imm_choke": {"id": "imm_choke", "name": "Choke", "level": 1, "casterType": "immortal", "range": "10 feet", "duration": "Concentration", "effect": "1d6 +1/lvl debilitating damage per round and paralysis", "area": "A living creature", "description": "Casting this spell on a living creature, the mage blocks its respiratory system and causes 1d6 debilitating damage +1 per level (max 1d6+5) per round and completely paralyses it whilst he concentrates and the victim remains in range. The victim can make a ST vs. Paralysis each round to act; otherwise, he remains paralysed by the asphyxiation and cannot speak or move. When the mage stops concentrating or the subject leaves, the effect ceases.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 38", "school": "Necromancy", "isCustom": false},
    "imm_clairaudience_clairvoyance": {"id": "imm_clairaudience_clairvoyance", "name": "Clairaudience/Clairvoyance", "level": 3, "casterType": "immortal", "range": "Same plane of existence or 120 feet", "duration": "1 turn per level", "effect": "See or hear a remote location", "area": "A known or near place", "description": "This spell allows the spellcaster to concentrate on a specific location and hear (Clairaudience) or see (Clairvoyance) what is happening in that place as if he was present (each application of this spell only allows vision or hearing at distance, mage’s choice). The distance of the place is irrelevant, but must be a known place (which he visited at least once), or an unknown place but present within a radius of 180 feet from his current position (for example a room of the castle he is in but hasn’t yet explored). As long as he concentrates, the spellcaster can rotate the watched area by up to 360° each round (but remaining fixed to a spot). The spellcaster can interrupt his concentration and then resume scrying without limitation, as long as the effect lasts or isn’t dispelled. The spell doesn’t allow any magical senses to function through it, and the mage can cast spells into the area he is scrying only if it is in the spell’s range in respect to his real position. Moreover, any environmental condition in the area also affects the spellcaster’s vision or hearing (for example, darkness or silence prevents him from seeing or hearing correctly). Note that the spellcaster is also effectible by any visual or auditory spell or magic effect that is present in the scryed area (like a symbol, or the gaze of a basilisk, or music that fascinates the listener, etc.). 10 feet of stone, a thin layer of gold or lead, or magical protection (like magic sanctum) cast on the place, is enough to block the spell’s effects. Moreover, anyone protected by a mental barrier or by a spell that prevents vision at a distance isn’t revealed by this spell (it is as if he wasn’t there), although the spellcaster can deduce his presence based on environmental reactions. This effect cannot be combined with permanency.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 73", "school": "Divination", "isCustom": false},
    "imm_claws_of_the_demon": {"id": "imm_claws_of_the_demon", "name": "Claws of the Demon", "level": 1, "casterType": "immortal", "range": "Touch", "duration": "1 turn", "effect": "Grow claws that cause 1d8 hp + Str bonus", "area": "One creature", "description": "Casting this spell the priest touches a consenting creature that is imbued by the malign energy of Entropy. Its features become bestial and frightening, and it grows long, sharp claws on its hands with which it gains a barehanded melee attack that causes 1d8 points of damage plus any Str bonus. The effect doesn’t give the subject additional attacks and the claws strike as normal weapons, but with each wound it suffers, the victim must make a ST vs. Poison to not lose the Initiative in the next round. It is however possible to use other weapons while the claws persist.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 52", "isCustom": false},
    "imm_climate": {"id": "imm_climate", "name": "Climate", "level": 3, "casterType": "immortal", "range": "0", "duration": "1 hour per level", "effect": "Maintains the area with a fixed temperature, humidity etc.", "area": "Volume of 8,000 cubic feet", "description": "This spell is used to make an area more comfortable for those within it. When it is cast, it affects a maximum volume of 8,000 cubic feet (for example a cube of 20×20×20 feet, or eight connected rooms of 10×10×10 feet) and changes the climatic conditions based on the mage’s wishes. The spell cannot change a normal environmental condition into a dangerous one (it cannot produce a freezing cold or a roasting heat), or vice versa change a dangerous climate into a normal one, but can keep a tower cool during the warm summer days, or keep it warm during winter nights. In general, it can alter the temperature up to 40°C higher or lower than that of the surrounding environment, and vary humidity by 30%.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 73", "school": "Transmutation", "isCustom": false},
    "imm_collar_of_enslavement": {"id": "imm_collar_of_enslavement", "name": "Collar of Enslavement", "level": 7, "casterType": "immortal", "range": "Touch", "duration": "24 hours", "effect": "The collar’s wear is enslaved to a master", "area": "A metal or leather collar", "description": "This spell can only be cast on a metal or leather collar (like those used to mark Thyatian slaves) and the mage must decide on which race of living, sentient beings the collar will affect from the following: animals, humanoids, dragons, magical monsters. If the collar is put on (which is usually only possible if the creature is consenting or immobilised) a creature of the appropriate race (as long as the collar is of an appropriate size) as long as the spell has effect (it lasts for 24 hours from the enchanting of the collar), the latter is totally subservient to the will of the person who put the collar on it (no ST allowed): it obeys to the best of its ability all his orders (even when the commands are suicidal or plainly against the victim’s moral principles), as long as it understands them or they are within the abilities it has been trained in, and it addresses its master with the maximum deference and respect. Even if the master isn’t present or hasn’t given precise instructions, the victim always tries to serve him in the best way it knows (based on its conscience and common sense); it moreover never tries to free itself of the collar and finds it perfectly normal to obey all its master’s orders. The spell can be ended by physically removing (Strength check with a –4 penalty) or destroying the collar (for example with disintegrate), or even if a dispel magic is cast on it (in the latter case the still wears the collar, but, as it has lost every magical property, he no longer needs to serve the master). Note that a victim cannot wear more than a single collar of enslavement at a time (the second simply has no effect). Moreover, a person that just wears a collar of enslavement is reduced to a pitiful state of mental regression, as if under the effects of a feeblemind until the spell ends. It is possible to prolong the effects of the sorcery beyond the 24 hours simply by casting the spell again on the collar before its duration ends. In this case however, the victim has a chance to free himself of the yoke with a successful ST vs. Mental Spells with a –2 penalty. If the ST doesn’t succeed he must continue to serve the master until he succeeds or the effect ends.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 151", "school": "Enchantment", "isCustom": false},
    "imm_colour": {"id": "imm_colour", "name": "Colour", "level": 1, "casterType": "immortal", "range": "Touch", "duration": "Permanent; the casting time can require up to", "effect": "A maximum surface of 400 ft2", "description": "12 turns (2 hours) Effect: colours an area or creates a design; inverse completely cancels the colours in the area hit This spell allows the spellcaster to spread a coat of magic colour or to create a design on a surface. The surface can be as small as a miniature in Ochalese porcelain, or up to 400 ft2 large; for an unconsenting creature, a ST vs. Spells negates the colourisation. The casting time can vary from one round for a uniform colour up to two hours to give different shades to various parts of an item or a setting, or create a fresco. During this time, the spellcaster can vary the colour of the entire area, or can colour different parts in different ways. The spellcaster can paint for a maximum period of two hours, creating colours that are permanent and immune to the ravages of time and inclemencies. Dispel magic doesn’t remove the effects of colour: only bleach or a wish can do that. Spellcasters use this spell for different aims. Artists use for paintings that won’t fade, or to decorate himself and others with body painting. Builders instead use it to colour stone and wood to make it more beautiful, and so on. To use the spell in a truly artistic manner, it is necessary to possess the appropriate general skill (Paint). Anyone without such a skill can only colour without artistic ability. If colour is cast on an area previously affected by another colour spell, the second application only has effect if the mage is of equal or higher level to the first: in this case the second application is overlaps the first, masking it. However, the first spell isn’t dispelled: to eliminate it, he would have to cast bleach. Mages can cast hidden messages in this way: after agreeing on the place, the first mage uses colour to write the message, and another to cover it. The other mage uses bleach to reveal the communication, and can then hide it or remove it with bleach. Colour can also be used to create magical tattoos of various sizes that can move and is permanent (it can only be removed with bleach) on the skin of a consenting creature. During the work the mage can add a 1st or 2nd level Abjuration, Divination, or Illusion spell that he knows to a tattoo, and can use the effect once per day as long as the tattoo remains (a subject can have only one enchanted tattoo). The ritual to add the spell to the tattoo is expensive (1,000 gp per spell level) and the procedure takes 1 hour per spell and covers an entire limb for a 1st-level spell, and half the body for a 2nd-level spell. The reverse spell, bleach causes a certain amount of material to return to its original colour – a hamper of laundry, a painting, an application of the colour spell, a tattoo, etc. Mundane marks are automatically removed. When it is cast on a colour spell, it only works if the spellcaster is of a higher or equal level to whoever cast colour. When it is cast on a magic tattoo or work of art, there is a chance that it will resist the destruction. The larger and more valuable the work of art, the greater the chance that is undamaged: the exact chance is decided by the DM within a range between 10% per level for an enchanted tattoo or 30% for a work of art. The spell doesn’t discolour the surface that is behind the design or pigment. If it is cast on a tattoo for example, it eliminates it, but the skin under it remains its normal colour.\nReversible.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 38", "school": "Transmutation", "isCustom": false},
    "imm_commune_with_nature": {"id": "imm_commune_with_nature", "name": "Commune with Nature", "level": 5, "casterType": "immortal", "range": "1 mile per level", "duration": "Instantaneous", "effect": "Immediate knowledge of the surrounding area", "area": "Only the druid", "description": "Thanks to this spell the druid becomes one with nature, gaining a profound knowledge of the surrounding territory within 1 mile per level. He gains the immediate knowledge related to a maximum of one topic per 4 levels from the following: the geological composition of the land, the plant species present, the minerals present, the location of water courses present, the species of animals present, the species of intelligent inhabitants present (including monstrous), the location of famous buildings or refuges, the location of a certain group of creatures (selected from a humanoid, animal, fantastic beast, undead, construct, ooze, extraplanar creature, or intelligent monstrous plant species). The spell doesn’t give information on cities (population of at least 5,000 inhabitants) in which nature has been replaced by artificial installations and constructions.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 125", "druidSpell": true, "isCustom": false},
    "imm_concentration": {"id": "imm_concentration", "name": "Concentration", "level": 3, "casterType": "immortal", "range": "0", "duration": "1 turn", "effect": "Mage can control more magic at the same time 67", "area": "Only the spellcaster", "description": "Thanks to this spell, the spellcaster can maintain his concentration even in circumstances that wouldn’t normally allow him to, like when the mage moves or runs, is injured, fails a Saving Throw, falls, or affected by a paralysing gas or similar. The spell allows the spellcaster to maintain his concentration if he makes a successful ST vs. Spells. If the circumstances occur more than once, multiple ST are required. Example: during a combat round, a mage that has cast concentration on himself already uses the spell phantasmal force, which requires concentration. In this same round the mage is hit three times and fails a ST vs. Paralysis: if he wishes to maintain the phantasmal force, he must therefore make four ST vs. Spells, and if just one of these fails, the concentration is broken; if all succeed, our mage, although paralysed, is still able to concentrate on the phantasmal force! The spell doesn’t permit concentration to be maintained in extreme conditions (for example if the mage is killed, petrified, or stunned, or if he loses consciousness, or finally if he suffers 50 points or more damage from a single attack), but it still works if the spellcaster is paralysed. A spellcaster with concentration can cast spells or use magic items and at the same time move at normal speed: he must make the ST vs. Spells as mentioned above, and if he fails, the spell is lost. In no case however, can he cast spells and simultaneously attack physically or use magic items, although he can concentrate to simultaneously maintain a number of spells equal to his Intelligence bonus (for example, a mage with Intelligence 18 [+3] could control a phantasmal force and in the meantime cast ventriloquism, then the round after a wizard’s eye, and maintain concentration on all three spells).", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 73", "school": "Abjuration", "isCustom": false},
    "imm_control_currents": {"id": "imm_control_currents", "name": "Control Currents", "level": 6, "casterType": "immortal", "range": "0", "duration": "1 turn per level", "effect": "Calm or agitate the currents with 30 feet per level", "area": "30 foot radius per level", "description": "This spell creates an “eye of the hurricane” type effect, reducing the intensity of any type of marine current until it is completely calm, while allowing the mage to vary the intensity of the currents within a 30 feet radius per level (the affected area moves with him). By concentrating, the mage can vary the direction, speed, and intensity of the currents by 25 mph per round, up to a maximum of 2.5 mph per level. As long as he concentrates, the spellcaster can only move at half speed, or transport himself in the water as if swimming at the same speed as the currents. The effect can be countered by anyone of higher level than the mage and using the same spell. The spellcaster doesn’t have to continue to concentrate to maintain the spell, but must only concentrate when he wants to modify the intensity of the currents in the area of effect, or to obtain one of the two effects given below. If control currents is used against a creature composed of water (for example a water elemental), the victim can make a Saving Throw vs. Spells: if failed, the mage can kill the being by smashing it into a thousand pieces, or make it move like a puppet as he likes (as if under the telekinesis effect). If the concentration is broken, the being is freed and attacks the mage to avenge itself, trying to kill him by any means available. The spellcaster can moreover once per turn trigger a marine whirlpool, which attacks and moves as if it was a Water Elemental with 16 HD as long as the mage continues to concentrate. The vortex vanishes if the concentration is broken or if it is magically dispelled or physically destroyed. The spellcaster can try to summon another vortex after a turn has passed (until the end of its duration).", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 133", "school": "Transmutation", "isCustom": false},
    "imm_control_dragons": {"id": "imm_control_dragons", "name": "Control Dragons", "level": 6, "casterType": "immortal", "range": "60 feet", "duration": "Concentration", "effect": "Mage controls up to 3 adult dragons", "area": "Up to 3 adult dragons", "description": "Not to be confused with charm, this spell allows the mage to control, with simple concentration, up to three Adult dragons (Small according to the categories of the classic D&D rules) or younger visible within 60 feet belonging to the specific species chosen when casting the spell. Each dragon can make a ST vs. Mental Spells to escape the control, but even if the ST succeeds, the mage can try again to take control of the dragon in the next round, continuing until the victim fails its Saving Throw or the concentration is interrupted. The controlled dragons are always friendly towards the mage and obey his orders, with the exception of suicidal orders, as long as the spell lasts. To give telepathic orders to the victim, the spellcaster must just concentrate for the entire round in which he imparts the command, without being able to attack or cast spells, but can move at normal speed and speak. Each round, the spellcaster can chose to release dragons from his control to try to affect others. When the concentration is broken, the victims are always hostile towards the mage: attacking him if they believe that they have a good chance of defeating him, or try to escape. This effect cannot be combined with permanency.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 133", "school": "Enchantment", "isCustom": false},
    "imm_control_emotions": {"id": "imm_control_emotions", "name": "Control Emotions", "level": 4, "casterType": "immortal", "range": "30 feet", "duration": "6 turns", "effect": "Alter the emotions of the subjects", "area": "1 creature every 4 levels", "description": "This spell can be used in two ways by the mage: on himself or on others. If he uses it on himself to make himself calm and tranquil, the spellcaster is able to react better to any type of effect that causes a shock or a violent emotion (fear, terror, horror, hate, anger, despair, etc.), obtaining a +4 bonus to all his Saving Throws to negate these effects until the spell ends. If instead he is already under the effect of such an emotion, he can use control emotions to calm himself and return to normal, although this state only lasts 1 turn. Moreover, for the entire duration of the sorcery the spellcaster is able to project a false emotion that reads true by any divinatory spell trying to plumb his mind (he can change the emotion once per round). If instead he uses control emotions on other creatures, it only affects the living (animals and not) and affects a maximum of 1 creature for every 4 mage levels that must be within 30 feet. The targets can resist the control with a successful ST vs. Mental Spells, otherwise the spellcaster projects a well-defined emotion on them that invades their mind and lasts for 1 turn, conditioning their actions. The spellcaster can choose one of the following emotions when he invokes the spell: Friendship: the subject reacts positively to every encounter and is always available and friendly. He never attacks first but only reacts to defend himself or his endangered allies, and tries to help those who ask for aid. Friendship counters and annuls the effects of Hate. Courage: the subject receives a +2 bonus to all his ST to counter fear (magical or mundane) and if he is frightened he can immediately make a new ST with the listed bonus to beat the terror. He, moreover, becomes so courageous that if attacked in melee he receives a +2 bonus to his Attack Rolls and damage, and if he is a NPC he need not make Morale checks. Courage counters and annuls the effects of Fear. Despair: the Morale of the subject (if he is a NPC) drops by 3 points and he has a −1 penalty to his ST and all skill and characteristic checks. Despair counters and annuls the effects of Hope. Happiness: the subject is in a state of grace and is well disposed to all. As such he never attacks first (reacting only to defend himself) and obtains a +2 bonus to all his Saving Throws. Happiness counters and annuls the effects of Sadness. Hate: the subject is harbours a deep aversion to anyone, always refusing any proposal of collaboration, and if he is treated in an abrupt or rude way he attacks those that insulted him, he also attacks on sight anyone that did him a wrong in the past. When he is in melee with someone he gains a +2 to his Attack Rolls and damage. Hate counters and annuls the effects of Friendship. Fear: the subject is invaded by a maddening fear towards the spellcaster and flees at maximum speed away from him for 10 entire rounds, and he refuses to return to a place where he might encounter him. If he sees the spellcaster again before the effect ends, he flees again. Fear counters and annuls the effects of Courage. Hope: the Morale of the subject (if he is a NPC) rises by 3 points and he has a +1 bonus to his ST and all skill and characteristic checks. Hope counters and annuls the effects of Despair. Sadness: the subject is constantly dejected, pessimistic, and subject to moments of apathy. All his attacks have a −1 penalty as does his Saving Throws and Initiative checks, and he is always surprised. Sadness counters and annuls the effects of Happiness.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 90", "school": "Enchantment", "isCustom": false},
    "imm_control_gravity": {"id": "imm_control_gravity", "name": "Control Gravity", "level": 7, "casterType": "immortal", "range": "90 feet", "duration": "Variable", "effect": "Control the force of gravity in the affected area", "area": "30×30×30 foot cube", "description": "This spell hits all the items and beings that are in a cube of 30×30×30 feet, within 90 feet of the mage, who has the faculty of deciding how gravity will work in the area. There are three types of possible effect (naturally each excludes the others) for this spell: zero gravity, hypergravity, and reverse gravity. Zero gravity: the effect reduces the gravity in the area to zero for a period of 1 round per mage level (but can be magically dispelled earlier). Anyone entering the area is subject to the annulled force of gravity and begins to float in midair and cannot move except rotate on the same spot. Anyone attempting to move can only do so with a Dexterity check by throwing items in the opposite direction to that desired, and receives a –4 penalty to Initiative and a –2 penalty to Attacks and ST to avoid effects as long as they remain in the area. Subjects with the general skill Aerial combat can interact better with the effects of zero gravity, while flying creatures are able to act normally (ignoring the penalty) by making a Dexterity check each round. Reverse gravity: the effect reverses the gravity within the area and make “fall” those that aren’t anchored to the ground in the opposite direction to the normal force of gravity for 3 seconds (instantaneous effect), making them “fall” for a maximum of 140 feet, then the gravity returns to normal; it isn’t possible to oppose this effect with a ST. Victims that encounter a ceiling or another obstacle suffer 1d6 points of damage for every 10 feet of “fall”, and as at the end of 3 seconds the gravity returns to normal, the victims fall again, this time in the opposite direction, and suffer the same amount of falling damage, while fragile items (ceramics, pottery, glass)break on impact. Even flying creatures in the area suffer the effects of this inversion, but unlike others they can avoid it with a Dexterity check at –4. If cast on a place without gravity, it is totally useless. Example: a mage casts the spell against a group of 13 feet tall giants, in a place 30 feet high. The giants “fall” up to the ceiling and then rebound to the earth, suffering a total of 6d6 points of damage, as they have fallen a total of 60 feet. If the ceiling had been 20 feet high, they would have only suffered 4d6 points of damage, travelling for 40 feet. Table 2.12 gives the falling speed of any body, and the distance it covers each round, remembering that after 20 rounds it has reached terminal velocity, or the maximum possible falling speed: from that moment, each round (10 seconds) the falling speed of the body remains constant (120 mph, or 3,000 feet per round). For every 10 feet fallen, a body suffers 1d6 points of damage, up to a maximum of 20d6. If a body falls over 300 feet, it automatically suffers maximum damage (120 hp) and a critical hit on impact (if using this rule) and must make a ST vs. Death Ray to avoid instantaneous death, with a cumulative –1 penalty for every 150 feet travelled after the first 300 feet; If the ST succeeds, it is however stunned for 1 turn if it still has more than 10 Hit Points, otherwise it passes out for 1d10 minutes. TABLE 2.12: FALLING BODIES Duration Velocity reached Total distance fallen of fall ft./s [mph] 1 sec 32 [22⅓] 15 ft. 2 sec 63 [42¼] 62 ft. 3 sec 90 [60¼] 138 ft. 4 sec 108 [74] 236 ft. 5 sec 130 [87] 354 ft. 6 sec 141 [96⅓] 489 ft. 7 sec 151 [103] 637 ft. 8 sec 158 [108] 791 ft. 9 sec 164 [112] 951 ft. 10 sec 167 [114] 1,115 ft. 11 sec 171 [116] 1,286 ft. 12 sec 171 [116] 1,457 ft. 13 sec 174 [118] 1,627 ft. 14 sec 174 [118] 1,801 ft. 15 sec 174 [118] 1,975 ft. 16 sec 174 [118] 2,156 ft. 17 sec 174 [118] 2,323 ft. 18 sec 174[118] 2,497 ft. 19 sec 177 [120] 2,674 ft. 20 sec 177 [120] 2,851 ft. … … 177 ft./sec Hypergravity: the effect hugely increases the force of gravity within the area for a period of 1 round per mage level (but can be magically dispelled earlier). Anyone within the area is subject to the increased gravity and has the following limitations based on their Strength bonus:  +0 or negative: subject completely immobilised (cannot even speak).  +1: partial mobility. Running impossible, movement reduced to ⅓, –4 penalty to Attacks, damage, and ST that involve avoidable effects; Strength and Dexterity reduced by 4 points; Strength check needed to speak or cast spells.  +2: subject slowed. Movement halved running impossible, –3 penalty to Attacks, damage, and ST that involve avoidable effects; Strength and Dexterity reduced by 3 points; Strength check needed to speak or cast spells.  +3: subject hampered. Movement halved –2 penalty to Attacks, damage, and ST that involve avoidable effects; Strength and Dexterity reduced by 2 points.  +4: subject annoyed. Movement reduced by ⅓, –1 penalty to Attacks, damage, and ST that involve avoidable effects; Strength and Dexterity reduced by 1 point. Those with a Strength bonus of +5 or higher aren’t affected by the area of hypergravity, as are all incorporeal creatures (they are immune to this spell as they aren’t subject to the force of gravity).", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 153", "school": "Transmutation", "isCustom": false},
    "imm_control_liquid": {"id": "imm_control_liquid", "name": "Control Liquid", "level": 6, "casterType": "immortal", "range": "240 feet", "duration": "10 turns", "effect": "Lower or higher the level of a surface of 4,000 square feet of liquid", "area": "4,000 ft2", "description": "This spell can be used to lower or raise the level of a liquid mass. In the former case it halves the height of a mass of liquid (water, lava, oil, or similar) of 4,000 square feet of surface area that must be within 240 feet, or lowers it by 10 feet per spellcaster level (his choice), for all the spell’s duration. Any mass the remains around the altered area doesn’t flow into the space left empty, but remains immobile at its normal level, and anyone can enter or leave it. The lowering of the liquid isn’t sudden, but happens gradually over 1 minute (6 rounds), so that people or ships within the area don’t suffer damage. However, at the end of the spell, the barrier that holds back the surrounding liquid mass vanishes, and the space created by the lowering of the liquid level is rapidly refilled. This effect causes 1d12+20 points of damage to the hull of any ship within the area, and the creatures present must make a ST vs. Death Ray to avoid being submerged and drowned (or worse, if the liquid is incandescent like molten lava); if the ST is successful, they still however suffer 3d20 points of damage. If instead the spellcaster chooses to raise the level of a liquid mass, the elevation affects an area of 4,000 square feet of liquid up to 100 feet of height. Any creature inside the raised area is thrown into the air and loses 3d20 Hit Points because of the sudden jet of pressure it is placed under, plus another 10d6 Hit Points from the fall once the column of liquid returns to its old level after 10 turns (unless the victim is able to levitate in the air). If there is a ship within the area of effect, it suffers 1d20+20 points of damage to its hull during the elevation, and as much once the column of liquid returns to its normal level (which happens after 10 turns, or earlier if the spell is dispelled). If control liquid is used a being composed entirely of liquid (for example a water elemental), the victim can make a Saving Throw vs. Spells: if failed, the mage can kill the being or take control of it by using the force of the liquid. The being continues to obey as long as the mage maintains his concentration: if the concentration is broken, the being is freed and attacks the mage to avenge itself by any means available. Finally, control liquid can also be used to start an abnormal wave and direct it at a point within 240 feet. The raised surface must stay within the spell’s limits, i.e. 4,000 ft2 (like a 40 ft. tall and 100 feet wide wave, or 10 ft. high and with a 400 feet wide wave front). Anything that is hit by the abnormal wave suffers 1d6 Hit Points per mage level (or 1 Damage Point per level to the structure) halved with a successful ST vs. Spells. Any living creature that fails its ST must moreover make a ST vs. Paralysis to not faint and die from drowning and being crushed by the increased weight of water. Clearly the abnormal wave can only be used against targets that are on a sufficiently large surface (like a river, lake, or sea), or within 240 feet of a surface of water. Any volume of water with a surface of less than 4,000 ft2 (for example a swimming pool) can however be used to produce the effects described above, but the damage derived from these effects is always halved. Water volumes of less than 1,000 ft³ cannot produce significant damage, although it is possible to control the liquids in the ways given above.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 134", "school": "Transmutation", "isCustom": false},
    "imm_control_temperature": {"id": "imm_control_temperature", "name": "Control Temperature", "level": 5, "casterType": "immortal", "range": "0", "duration": "1d6+2 hours", "effect": "Raise or lower the temperature in a 10’ radius", "area": "10’ radius sphere", "description": "This spell allows the druid to alter the environmental temperature in a 20 feet diameter sphere around himself to resist extreme temperatures: the maximum variation of the temperature is plus or minus 50°C. The change happens instantly and the affected area moves with the druid, centred on him. As long as the spell lasts, the druid can continue to change the temperature, by concentrating for 1 round, but doesn’t need to concentrate continuously to keep the spell active.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 122", "druidSpell": true, "isCustom": false},
    "imm_control_totem": {"id": "imm_control_totem", "name": "Control Totem", "level": 6, "casterType": "immortal", "range": "240 feet", "duration": "1 turn per level", "effect": "Establish a totally one-to-one bond between an animal totem and an individual", "area": "An animal and an individual", "description": "To cast this spell, the cleric must capture the animal totem of the victim he intends to hit; this naturally can be also be done with consent or knowledge of the latter. Once the animal has been caught, the spell is cast on it. From that moment and for the spell’s duration, anything that happens to the animal also happens to the victim (and vice-versa). So, if the animal falls asleep, the character bound to it also goes to sleep. This bond lasts until death: the killing of the animal in fact provokes the victim’s death. When the spell is cast, the victim (not the animal) can make a Saving Throw vs. Spells to avoid the effects; if failed, he is totally at the mercy of the shaman who has the animal totem. If an individual is already a victim of this spell, it isn’t possible to doubly affect him with a second animal totem.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 79", "isCustom": false},
    "imm_control_undead": {"id": "imm_control_undead", "name": "Control Undead", "level": 6, "casterType": "immortal", "range": "60 feet", "duration": "Concentration", "effect": "Spellcaster controls up to 18 HD of undead", "area": "Up to 18 HD of undead", "description": "Not to be confused with charm, this spell allows the mage to control up to 18 Hit Dice of undead (with no limit on the type of controlled creature, or the maximum HD of each, as long as it is within 18 HD), by simple concentration. The spellcaster can try to take control of any undead within 60 feet (provided he can see them), and it can make a ST vs. Mental Spells to escape the control. Even if the ST succeeds, the mage can try to take control of the undead in the next round, continuing to try once per round until the victim fails its ST or his concentration is broken. The controlled undead are friendly to the mage and obey any of his orders (except suicidal ones), as long as the spell lasts. To give orders to the victims, the mage must just concentrate for the entire in which he imparts the order, without being able to attack or cast spells but only walk and speak. The spellcaster cannot control more than 18 HD of undead at a time, and can chose which creatures to release control of to try to control others. When the concentration is broken, the victims are always hostile towards the mage: attacking him if they believe that they have a good chance of defeating him, or try to escape. This effect cannot be combined with permanency.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 134", "school": "Necromancy", "isCustom": false},
    "imm_control_weather": {"id": "imm_control_weather", "name": "Control Weather", "level": 7, "casterType": "immortal", "range": "2 miles", "duration": "Concentration", "effect": "Alter the weather conditions within ½ mile", "area": "½-mile radius", "description": "This spell allows the spellcaster the weather conditions in a ½ mile radius within 2 miles of him, selecting the specific type and maintain or varying it as he pleases, as long as he continues to concentrate (which means he can only move at walking speed and speak slowly), and the area of effect moves with him. The weather conditions affect all living creatures within the indicated area, including the mage. The types of weather conditions that can be evoked are the following: Good weather: annul the bad weather (rain, snow, fog), but not the secondary effects (e.g. mud). Sultry heat: movement halved. Dries excess humidity (rain, snow, mud). Fog: visibility reduced to 20 feet (or to 10 feet at night, even with infravision) and movement halved. Those surrounded by fog cannot orientate themselves and can become lost. Snow: visibility reduced to 40 feet (or less at night) and movement halved. The surface of rivers and stream can be covered in a layer of ice. When the snow melts, the ground remains covered by mud and the movement continues to apply until the earth dries out. Rain: all Attacks Rolls by ranged weapons suffer –2 penalty. After 3 turns, the ground surface is covered in mud, halving normal speed. Storm: this looses a storm with lightning bolts, winds in excess of 40 mph, and driving rain that prevents anyone from continuing. There is moreover a 5% chance (1 on 1d20) that each round a lightning bolt strikes a creature that is outside causing 6d6 damage, halved with a successful ST vs. Dragon Breath (the mage cannot however control this effect in any way and can indeed be a victim). Tornado: creates a whirlwind under the mage’s control, which attacks and moves as a 14 HD Air Elemental. At sea, the tornado creates a waterspout. Intense wind: winds with a force of greater than 50 mph, impossible to use ranged weapons and flight, movement is halved. At sea, increase the speed of sailing ships by 50%. In deserts, it creates sandstorms that reduce movement to a third and visibility to 10 feet.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 154", "school": "Transmutation", "isCustom": false},
    "imm_copy_spell": {"id": "imm_copy_spell", "name": "Copy Spell", "level": 7, "casterType": "immortal", "range": "", "duration": "", "effect": "", "description": "Granted by an Immortal in the Tome of the Magic of Mystara Vol. 2 (Divine Magic), Appendix \"Additional spells of each Immortal\". The provided books (Tome Vol. 1-2, Rules Cyclopedia) do not describe this spell; ask your DM or use your own source.", "source": "Tome of the Magic of Mystara Vol. 2, Appendix (no description)", "isCustom": false},
    "imm_cornucopia": {"id": "imm_cornucopia", "name": "Cornucopia", "level": 3, "casterType": "immortal", "range": "0", "duration": "12 turns, or when the cornucopia is used", "effect": "From the cornucopia extract a common object", "area": "N/A", "description": "When this curious spell is cast, a cornucopia appears between the cleric’s hands: it appears as a hollow horn about 20 inches long with a 12 inch diameter mouth that weighs no more than 10 cn (1 lb); when shaken it always makes a muffled sound from within (as if full of items), but if searched visually or by hand appears empty. At anytime within the spell’s duration a cleric or follower of the same Immortal can evoke the Immortal’s aid, turning the cornucopia upside down while speaking the name of a common, non-magical item or good, for example a meal, a full wineskin, a flask of flammable oil, a pair of boots, etc. Immediately from the cornucopia falls the desired object, which is non-magical and permanent, then the cornucopia vanishes. The spell’s limitations (that, if not respected, make the cornucopia vanish without giving anythinga) are the following: the summoned object must pass through the mouth (so he can obtain a dagger or a bag with 20 slingstones, but certainly not a battleaxe), must have a maximum weight of 5 cn (½ lb) per cleric level and not have a monetary value greater than 2 g.p. per cleric level. Moreover, it isn’t possible to obtain precious stones or noble metals (silver, gold, platinum). Whenever the cleric uses this spell with excessive frequency and with greedy intent the Immortal can punish him by limiting its use.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 61", "isCustom": false},
    "imm_corpse_possession": {"id": "imm_corpse_possession", "name": "Corpse Possession", "level": 4, "casterType": "immortal", "range": "30 feet", "duration": "1 hour per level", "effect": "Mage’s spirit possesses and animate a corpse", "area": "A humanoid corpse", "description": "Casting this spell, the mage’s soul leaves his body to assume control of a corpse of any humanoid creature that is within 30 feet and dead for no longer than 1 day per spellcaster level. For the spell’s duration, the spellcaster is able to move the body normally as if it was his own, and can speak, although obviously the appearance would be the same that the deceased had at the moment of death (including wounds and hideous or not disablements). While he possesses the corpse, the spellcaster cannot use the magical abilities, competence in weapons, or special qualities possessed by the deceased or even himself (he thus cannot cast spells). The spellcaster uses his own Intelligence, Wisdom, and Charisma scores, as well as his own THAC0 and ST while he possesses the corpse, while the corpse’s physical characteristics (Strength, Dexterity, and Constitution) are equal to 10. The Hit Points of the corpse are equal to the creature’s base Hit Dice +1d8 hp, which indicates how much damage the corpse can suffer before falling apart. At the end of the effect, the soul returns to the mage’s body, who can however end the spell earlier with simple concentration. The soul also automatically returns to the spellcaster’s body if the corpse is reduced to zero or fewer hit points or suffers a successful attempt to annul the magic. The spellcaster’s body remains inanimate for the effect’s duration. If it is destroyed while the soul is in the corpse, the spellcaster dies at the spell’s end. Moreover, it is necessary that both the corpse and the original body be on the same plane when the soul returns to its original body, otherwise the spellcaster dies.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 91", "school": "Necromancy", "isCustom": false},
    "imm_cough": {"id": "imm_cough", "name": "Cough", "level": 1, "casterType": "immortal", "range": "60 feet", "duration": "1 round per level", "effect": "Victim coughs and has –2 to Attack Rolls and AC", "area": "1 creature", "description": "This spell gives rise in the victim to an unexpected and powerful coughing attack that impedes speech and acting normally for its duration (1 round per level of the mage). The victim can negate the effect with a successful ST vs. Paralysis; otherwise, he suffers a –2 penalty to his Attack Rolls and Armour Class. Moreover, he must make a Concentration check with a –2 penalty each time he attempts to cast a spell: if the check fails, the spell is wasted because of the coughing. The spell is effective against any living being, as well as in the non-living (constructs and undead) provoking spasms similar to coughs that shake the body and make it difficult to speak and coordinate movement.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 39", "school": "Necromancy", "isCustom": false},
    "imm_create_fiery_beast": {"id": "imm_create_fiery_beast", "name": "Create Fiery Beast", "level": 5, "casterType": "immortal", "range": "40 feet", "duration": "6 turns", "effect": "Evoke a fiery beast on a structure", "area": "A structure or statue", "description": "This spell allows the cleric to creat a fire version of any real animal he knows (e.g a horse, wolf, or eagle), which obeys his orders. The beast uses the same attacks as the normal animal, causing damage based on its size and the animal’s standard damage, but anything it touches must make a ST vs. Fire to avoid catching light. Because of this, weapons of wood or similar materials that hit the beast must make a ST vs. Fire or ignite. Moreover, each successful hit causes additional fire damage based on the beast’s size: Tiny or smaller: 2d6; Small: 3d6, Medium: 4d6, Large: 5d6, Huge or larger. The beast has the same movement abilities as the normal animal and an AC of 0, it is immune to any firebased attack and can jump upto 75 feet over uneven ground, while if it flies it can leap to a height of 500 feet. The only limitation of this spell is that the beast can only be created on a pre-existing structure of animal form, which therefore determines its real dimensions and that isn’t consumed by the beast’s heat (as if it forms the skeleton on which the fiery skin is grafted). Lacking a suitable structure, the cleric can evoke the beast on any statue of a normal animal, which becomes the being’s body. Any creature within the structure doesn’t suffer from the heat given off by the flames as they form part of the skeleton, as long as they remain within the flames. The Fiery Chariots (Hover-Chariots) of the Nithians are LEVEL created by this spell, usually of enormous dimensions and with a fire resistant platform above the structure to transport soldiers. This spell cannot be made permanent.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 74", "isCustom": false},
    "imm_create_fire": {"id": "imm_create_fire", "name": "Create Fire", "level": 2, "casterType": "immortal", "range": "0", "duration": "2 turns per level", "effect": "Create a flame on the hand; reverse extinguishes any fire in a 40 feet diameter sphere", "area": "A flame or 40’ diameter sphere", "description": "The spell cause a small magic flame to appear on the druid’s hand. The fire doesn’t burn the caster in any way and illuminates a 60 feet radius sphere. The flame can be used to light inflammable materials (lanterns, torches, oil, etc.) without being consumed, and until the end of its duration (2 turns per level), the druid can make it appear and disappear, by concentrating, once per round. Moreover, he can use the same hand to hold or use other objects. The fire can be put down or thrown up to a distance of 30 feet, but in this case disappears the next round, although it can cause fire damage (1d6 hp) and ignite inflammable materials with the normal chance. As long as it remains in the druid’s hands moreover, the fire cannot be extinguished by the wind, although it can be magically dispelled with the normal chance and is extinguished if immersed in water. The reverse spell, devour flame, creates a magical field around the spellcaster that automatically extinguishes any normal flame within a 40 feet diameter sphere, while it has a 50% chance of extinguishing any magical flame each round. The volume of the flames isn’t important: all those within the area of effect immediately cease. The corrosive or other harmful effects of the heat cannot be repaired, however, or altered. The area of effect of devour flame is centred on the spellcaster and moves with him, unless he chooses to cast it on a fixed point, to prevent any type of fire from starting in that area for the spell’s duration. For example, if a fireball is cast in an area where a devour flame is active, there is a 50% chance that the explosion doesn’t happen and the fireball is wasted; while if the spell is put into being a round after the explosion, it automatically extinguishes all the flames in the area (without however regenerating the damage produced). When devour flame is fixed on a specific area (as explained above), the druid can no longer more it, although he can cast it again to still benefit from its protection. Once the flames in an area are extinguished, they don’t return if the spell’s area of effect moves from the area, unless they are relit later. If a fire elemental or a similar being completely made of fire enters the devour flame’s radius of effect, it must make a ST vs. Spells or be returned to its plane of origin.\nReversible.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 119", "druidSpell": true, "isCustom": false},
    "imm_create_greater_undead": {"id": "imm_create_greater_undead", "name": "Create Greater Undead", "level": 7, "casterType": "immortal", "range": "Touch", "duration": "Permanent", "effect": "Animate corpse as undead", "area": "A corpse", "description": "This spell is a more powerful version of the 6th level spell create undead. The mage must have at his disposal a corpse (partial or intact) and must only evoke this power at night. The spellcaster places within the corpse (usually in the mouth or thorax) a gem to the value of 300 gold pieces per Hit Dice to animate, which catalyses the necromantic energy and is consumed by it, animating the corpse as undead when the spell is cast. The mage is able to permanently create an undead that can have a maximum of 1 HD per 2 mage levels (max. 18 HD at 36th level) and that faithfully obeys its creator. The total Hit Dice of the undead are decided by the mage when he cast the spell and don’t depend on those of the original creature. There are two types of undead that can be created with this spell, which depends on the quantity of mortal remains available and the mage’s knowledge (the mage cannot create a type of undead he doesn’t know): Corporeal (requires at least 40% of the body): skeleton, zombie, ghoul, ghast, wight, mummy, vampire, and any corporeal undead with less than 18 HD. Incorporeal (must have a body part, like an arm or skull): wraith, spectre, phantom, poltergeist, shade, druji, odic and any other incorporeal undead with less than 18 HD. The created beings retain 50% of their knowledge (only skills linked to Intelligence and Wisdom for incorporeal beings, skills linked to Strength and Wisdom for corporeal beings) and of the memories they had in life, and there is a 25% chance that those that were spellcasters in life are still able to use some of their spells in the normal way (based on the original class), only if the appropriate characteristic (Intelligence, Wisdom, or Charisma) was originally 16 or higher. As undead they are immune to the effects of sleep and charm, to poison and paralysis. The being gains the number of attacks and type of damage typical of the type of undead into which it has been transformed, and its THAC0 depends on its number of HD. There is moreover a 50% chance that each being keeps its own skill with weapons (mastery included, make the roll for each weapon known). The mage can try to control a maximum number of Hit Dice of undead created with this spell or with the 6th level version equal to his own level. If he creates undead beyond this limit, the excess undead have free will and aren’t subject to the mage’s control. Defeating magically created or summoned creatures doesn’t grant the xp related to them until whoever summoned them has also been defeated.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 169", "school": "Necromancy", "isCustom": false},
    "imm_create_ice_zombies": {"id": "imm_create_ice_zombies", "name": "Create Ice Zombies", "level": 5, "casterType": "immortal", "range": "40 feet", "duration": "Permanent", "effect": "Create frozen and preserved zombies", "area": "One corpse per 2 levels", "description": "This spell allows the caster to animate any corpses within 40 feet, as long as if it died over a month ago and has been buried, creating several ice zombies. He can animate up to one ice zombie per 2 levels (rounded down), and each creature obeys his ordrs until destroyed. Indeed, zombies created this way are immune to dispel magic and persist until destroyed physically or with a dispel evil. Each ice zombie, at the moment of animation, undergoes a transformation that renders it perfectly preserved and gives it the same appearance it had in life (with the disappearance of any cuts or mutilations that caused its death), although it remains particularly palid and cold to the touch (anyone interacting with it can notice that it isn’t normal with an Intelligence check). Ice Zombie: AC 6; HD original+1; # Atk. 1 touch or 1 weapon; Damage 1d6 + paralysing touch (like the spell) or varies; MV 90/30; ST F equal to HD.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 74", "isCustom": false},
    "imm_create_projectiles": {"id": "imm_create_projectiles", "name": "Create Projectiles", "level": 4, "casterType": "immortal", "range": "120 feet", "duration": "1 turn every 2 levels", "effect": "Create normal projectiles", "area": "A missile weapon or quiver", "description": "This spell can be cast on any missile weapon, or on a quiver, obtaining two different effects. If used on a missile weapon, it becomes capable of firing arrows or bolts that appear when it is used, without requiring the use of existing projectiles. The bolts created in this way are totally normal, and disappear after either hitting or missing the target, when they impact a surface. The weapon keeps the power to create normal projectiles for the spell’s duration, and it can fire up to a maximum of 5 bolts per round. The bolt cannot be created and then stored for later instead of being fired, as it disappears after either causing damage or touching a surface. If the spell is cast on a non-magical bolt instead, once the bolt is placed in a container it immediately produces a total of 5 identical projectiles per level (or a lesser amount if the container’s capacity is smaller), then the effect ends. Unlike the previous use, in this case the projectiles become a permanent creation that cannot be magically dispelled. Neither of the two above effects can be combined with a permanency spell.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 92", "school": "Conjuration", "isCustom": false},
    "imm_create_ravenous_dead": {"id": "imm_create_ravenous_dead", "name": "Create Ravenous Dead", "level": 5, "casterType": "immortal", "range": "60 feet", "duration": "Permanent", "effect": "Create undead that kill create other undead", "area": "1 HD of zombies per level", "description": "This spell is similar to animate dead with one important exception: all the corpses must be at least 90% intact and rise as ravenous zombies, who aren’t destroyed with dispel magic. They, as well as their original attacks, also have a bite attack that causes 1d4 points of damage (or the creature’s bite damage is improved by 1 point, if it already has one). Anyone bitten by a ravenous zombie must make a ST vs. Death Ray and if they fail their body is inexorably corrupted by Entropic energy and in 1d4 hours the creature dies and transformed at once into a ravenous zombie, unless he is cured first with dispel evil. Also, anyone killed by a ravenous zombie returns to life after 1d4 minutes as such, but these cases are very rare, as once the victim dies, the zombie normally eats its body to feed itself (from which the creature gets its name) and what remains can certainly not be reanimated.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 74", "isCustom": false},
    "imm_create_undead": {"id": "imm_create_undead", "name": "Create Undead", "level": 5, "casterType": "immortal", "range": "60 feet", "duration": "Permanent", "effect": "Animate corpse as undead", "area": "A corpse", "description": "This spell is a more powerful version of the simple 5th level animate dead spell. The mage must have a corpse available (at least 50% of the original body) and must only evoke this spell at night. The spellcaster places within the corpse (usually in the mouth or thorax) a gem of a value of 100 gold pieces per Hit Dice to animate, which is used as a catalyst for the necromantic energy and is consumed by it, animating the body as undead the moment when the spell is cast. The mage is able to permanently create a type of lesser undead of his choice (skeleton, zombie, ghoul, ghast, spectre, or mummy) that can have a maximum of 1 HD for every 2 mage levels (max. 10 HD at 20th level) and that faithfully obey its creator. The total Hit Dice of the undead are decided by the mage when casting this spell and they don’t depend on those of the original creature. The created beings don’t have any spells, and retain 20% of their general skills linked to Strength and Wisdom that it had whilst alive, as well as partial memories of its past life. As undead they are immune to the effects of sleep and charm, poison, and paralysis, and cannot be destroyed with dispel magic. The being gains the number of attacks and type of damage typical of the type of undead into which it was transformed, and its THAC0 depends on its number of HD. The spellcaster can keep under control a maximum number equal to his own level of Hit Dice of undead created with this spell or with the empowered 8th level version. If he creates undead beyond this limit, the excess undead have free will and aren’t subject to the mage’s will. Defeating magically created or summoned creatures doesn’t grant the xp related to them until those that summoned them have also been defeated.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 135", "school": "Necromancy", "isCustom": false},
    "imm_crushing_despair": {"id": "imm_crushing_despair", "name": "Crushing Despair", "level": 4, "casterType": "immortal", "range": "", "duration": "", "effect": "", "description": "Granted by an Immortal in the Tome of the Magic of Mystara Vol. 2 (Divine Magic), Appendix \"Additional spells of each Immortal\". The provided books (Tome Vol. 1-2, Rules Cyclopedia) do not describe this spell; ask your DM or use your own source.", "source": "Tome of the Magic of Mystara Vol. 2, Appendix (no description)", "isCustom": false},
    "imm_curative_power": {"id": "imm_curative_power", "name": "Curative Power", "level": 2, "casterType": "immortal", "range": "Touch", "duration": "Permanent", "effect": "Cure 1d6 +1 hp/lvl and cleric recovers 1 hp/lvl", "area": "A living being and the cleric", "description": "When this spell is cast, the subject touched immediately recovers 1d6 hp +1 point per cleric level (max 1d6 +10 hp at 10th level). Moreover, the same cleric benefits from the energy evoked and recovers 1 Hit Point per level (max 10 hp), until he is returned to full health.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 55", "isCustom": false},
    "imm_curse_of_silver": {"id": "imm_curse_of_silver", "name": "Curse of Silver", "level": 2, "casterType": "immortal", "range": "120 feet", "duration": "Permanent", "effect": "Corrupt silver", "area": "A 20×20×20 feet cube", "description": "All silver items in the area of effect (except those permanently enchanted) that fail their ST vs. Destruction suffer a process of rapid and irreversible corruption: over a few seconds they become rusty and fragile, and completely unusable. The silver is transformed into a vile metal that thus loses its monetary value and ability to damage lycanthopes. The effect is permanent and cannot be dispelled.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 55", "isCustom": false},
    "imm_d_j_vu": {"id": "imm_d_j_vu", "name": "Déjà-vu", "level": 5, "casterType": "immortal", "range": "", "duration": "", "effect": "", "description": "Granted by an Immortal in the Tome of the Magic of Mystara Vol. 2 (Divine Magic), Appendix \"Additional spells of each Immortal\". The provided books (Tome Vol. 1-2, Rules Cyclopedia) do not describe this spell; ask your DM or use your own source.", "source": "Tome of the Magic of Mystara Vol. 2, Appendix (no description)", "isCustom": false},
    "imm_deadly_bolt": {"id": "imm_deadly_bolt", "name": "Deadly Bolt", "level": 5, "casterType": "immortal", "range": "Touch", "duration": "3 turns or when the attack is made", "effect": "A bolt causes the victim’s death", "area": "A projectile", "description": "This spell can only be cast on a bolt or any one type of projectile; if it is cast on a bludgeoning or melee weapon the spell is ineffective. The spell’s effect remains on the projectile for a maximum of three turns, within which it must be used: after the first blow struck (whether it hits or not), the spell ends. If the bolt strikes the target, it can have one of the three following effects, chosen by the mage when he casts the spell: annihilation, bleeding, or poisoning. Annihilation: the spellcaster must choose a specific class of enemies for the bolt from the following: undead, elementals, lycanthropes, dragons, constructs, outsiders, fey, giants, insects, animals (normal and giant), magical beasts (creatures with strange anatomies in respect to normal or intelligent animals or with special powers), enchanted monsters (catchall category that includes all creatures immune to normal weapons). If the projectile strikes a victim that belongs to the indicated class, and as well as the normal injury it makes a ST vs. Death Ray to avoid instant death. The effect strikes the creature’s physical body, which stops working, but isn’t able to destroy the soul (so for example a vampire or lich is reduced to dust but not annihilated). Bleeding: the projectile doesn’t inflict extra damage when it strikes the target, but penetrates deeply and leaves an open wound that begins to pour bleed. At the start of successive rounds, the victim suffers 1 Hit Point of damage per round, and this bleeding continues without stopping until the victim dies or is magically cured; the curative spell or potion used to end the bleeding only does this and doesn’t cure any Hit Points. A victim subjected to bleeding has difficulty concentrating: if he intends to cast a spell or use a magic item must first make a Wisdom check, and if successful the victim can concentrate, otherwise the spell (or the item’s charge) is wasted. Undead, constructs, and oozes are totally immune to this effect. Poisoning: the projectile is transformed into a snake when it strikes the target, and as well as the normal injury, the victim suffers the effects of instantaneous poisoning and must make a ST vs. Poison at –4 to avoid dying in 1d4 rounds in appalling agony. Undead, constructs, and oozes are totally immune to this effect. This effect cannot be combined with permanency. DÉJÀ-VU School: Divination Range: touch Area of effect: any being Duration: 24 hours Effect: an Attack Roll, Dex check, or ST automatically succeeds Anyone benefitting from this spell is able to see the future before it happens: the knowledge remains in his unconscious until foreseen situation manifests. At that moment, he has a fleeting flash of inspiration regarding the scene that is in front of him as if it has already happened, such that he is able to anticipate what is about to happen next. The effect of the déjà-vu remains latent for 24 hours, during which the character can decide to use the power and at that point déjà-vu manifests and the spell ends. The effect available to the subject is chosen by the mage when he casts the spell from: Security: automatically make a Saving Throw that he would have failed. Far-sight: automatically make an Attack Roll or a Dexterity check to the best of his ability. The effect cannot be made permanent.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 113", "school": "Transmutation", "isCustom": false},
    "imm_deadly_oath": {"id": "imm_deadly_oath", "name": "Deadly Oath", "level": 6, "casterType": "immortal", "range": "Touch", "duration": "1 day per level", "effect": "Victim performs a task and dies", "area": "Living being with half the mage’s HD", "description": "When casting this spell, the mage must touch a living being that doesn’t have more than half his HD or Levels, who can oppose its effects with a successful Saving Throw vs. Death Ray. If however the ST fails, the subject loses control of its own body and the spellcaster gives it a simple and comprehensible order (deliver a message, kill a person, carry an item, guard a place, object, or person etc.) that must take a maximum of 1 day per mage level. The victim tries to perform the task without interacting with anyone, and if threatened reacts to defend himself to the best of his ability or flee (based on the situation). The mage must give him precise indications to perform his task (for example if he has to deliver something to someone he must be told where to go), or he can decide to leave him where he is: in this case, if he doesn’t have the knowledge needed to perform his task, the victim remains still and immobile in a state of agitation. If anyone finds him in this state, the victim asks to be led to the right place or person without doing anything else. Once he reaches his destination and fulfils his task, the victim contorts in great pain and expires. The victim survives for a maximum number of days equal to the mage’s level, or until he has performed his task (if this happens earlier). In this period of time the subject continues to need food, water, and rest, and tries to survive to complete the task, limiting his interaction with other beings to a minimum. To a close examination the person seems in a state of shock, with a fixed stare, heedless of what is going on around him and loath to respond to any question. If magically examined, the victim irradiates a necromantic aura. Only if someone casts a dispel magic or destroy evil (or similar more powerful spells) on the subject before the end of the deadly oath can the victim be saved from his destiny. In this case, the individual becomes himself and perfectly remembers everything that happened to him.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 135", "school": "Necromancy", "isCustom": false},
    "imm_deadly_weapon": {"id": "imm_deadly_weapon", "name": "Deadly Weapon", "level": 6, "casterType": "immortal", "range": "Touch", "duration": "2 turns", "effect": "A weapon kills or triples damage", "area": "A weapon", "description": "This terrible offensive spell only affects one type of weapon chosen by the mage. Based on the weapon type, the application of the spell takes the name of Slicing (slashing weapons), Piercing (piercing weapons), or Shattering (bludgeoning weapons). When, using a weapon enchanted with deadly weapon, if he obtains a natural “19” or “20” (without taking any modifier into account, but only counting the result shown on the die face), the victim must immediately make a Saving Throw vs. Death Ray. If the ST fails, the victim struck dies from the blow because of a profound series of wounds that appear on his body and from internal bleeding; If the ST succeeds, the victim however suffers triple the weapon’s normal damage (damage from any mastery is also tripled), as several gashes have opened up at the point of the injury. If the spell is cast on a magic weapon, the range in which the power takes effect increases by a point for each point of the bonus (for example, if it is a +3 sword, this power activates on a natural dice score of 16-20 on the d20, which is an additional three points– for the weapon’s magic bonus – to the normal range of 19-20). Undead, constructs, and oozes are immune to the effects of deadly weapon, as they are immune to bleeding because of their particular biology. This effect cannot be combined with permanency.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 136", "school": "Transmutation", "isCustom": false},
    "imm_death_recall": {"id": "imm_death_recall", "name": "Death Recall", "level": 3, "casterType": "immortal", "range": "", "duration": "", "effect": "", "description": "Granted by an Immortal in the Tome of the Magic of Mystara Vol. 2 (Divine Magic), Appendix \"Additional spells of each Immortal\". The provided books (Tome Vol. 1-2, Rules Cyclopedia) do not describe this spell; ask your DM or use your own source.", "source": "Tome of the Magic of Mystara Vol. 2, Appendix (no description)", "isCustom": false},
    "imm_deflecting_shield": {"id": "imm_deflecting_shield", "name": "Deflecting Shield", "level": 2, "casterType": "immortal", "range": "Touch", "duration": "6 turns", "effect": "Deflect normal and magic missiles and thrown weapons", "area": "A living creature", "description": "The subject on which the spellcaster cast this spell sees a transparent shield of energy appear in front of him, which he can position each round to guard one of his sides (front, back, left, and right). If the subject is attacked with thrown weapons, magic or mundane projectiles, or with magic effects that create projectiles of energy (like magic missile) while the shield is active on his side, it deflects any attack towards another target within a 30 feet semicircle; if there are no other victims, the bolt falls to the ground. This spell is only effective against thrown weapons and normal and magic bolts, but not against breath attacks or others that affect areas.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 58", "school": "Abjuration", "isCustom": false},
    "imm_delusion": {"id": "imm_delusion", "name": "Delusion", "level": 6, "casterType": "immortal", "range": "Touch", "duration": "24 hours", "effect": "An object emanates a false magic power, a creature gives false information to divinatory spells", "area": "An object or creature", "description": "This spell only has effect if cast on a non-magical object or creature (living or not). The spellcaster that cast delusion on an item selects any one magic power (generally similar to that of a spell or a magic item that is already known, it isn’t necessary that he has mastered the power) to associate to the item: for the spell’s entire duration (24 hours), the item emits a magical aura that can be detected detect magic or similar divinatory spells, and if closely examined or with a divinatory spell of 5th level or lower, it indeed seems to possess the magic powers that the spellcaster has attributed to it (divinatory spells of 6th level or higher instead aren’t fooled by the delusion). In reality such powers are usually illusory, and if any attempt to use the fictitious magic item is made, it naturally doesn’t work: the victim has the right to a Saving Throw vs. Mental Spells, and if the ST is successful, the victim understands that he has been tricked, otherwise he is convinced that the item functions perfectly (or, worse, thinks he hasn’t spoken the correct magic word). The DM can assign to such Saving Throws a 4-point maximum bonus or penalty according to how clear the delusion is. Example: a character tries to use a fictitious pair of boots of levitation, and cannot raise himself even a ½ inch, this deception is easy to detect (+3 bonus to the ST). If instead the same character finds a false potion that he identifies as a potion of healing, doesn’t have any right to a ST, because he hasn’t used the item. Some hours later, when he drinks the potion during a fight, it will be difficult to notice that it has no effect (–1 to the ST): if the Saving Throw fails, the character believes himself healed (recovering the Hit Points), but this is only a conviction of the character. If he instead drinks the potion at the end of the combat, his companions could notice that his injuries remain, putting him on his guard and giving him a bonus to the ST. If delusion is cast on a creature, it can avoid the effects if it wants to, by making a successful ST vs. Spells. If instead it accepts the spell or fails the ST, the spellcaster chooses one of the individual’s characteristics from those commonly read by divinatory spells (Alignment, Level, Hit Points, Race, Class, any presence of a magical aura or curse) and modify it to his liking. So for the spell’s duration any attempt to obtain a reading of that characteristic of the subject always gives false information chosen by the mage (even with trueseeing), unless if using a 7th level or higher spell. Multiple applications of delusion allows him to modify several characteristics simultaneously or to change the transmitted information. Example: The elf mage Elarianthas knows that to infiltrate a cave of shadow elves he must look like one of them. As such, after using an illusion to change appearance, casts delusion on himself three times to disguise the reading of his true race (shadow elf rather than wood elf), his level (5th rather than 15th), and his real hp (25 rather than 50). Delusion affects the mind and divinatory spells, and therefore if it is cast on an item it has no effect on the undead and constructs. A dispel magic spell successfully cast on the disguised item or creature disperses the effects of the delusion even on its “victim”.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 136", "school": "Illusion", "isCustom": false},
    "imm_demand": {"id": "imm_demand", "name": "Demand", "level": 7, "casterType": "immortal", "range": "Same plane", "duration": "Special", "effect": "Send a message with a command", "area": "A creature", "description": "This spell allows the mage to send a telepathic message containing 1 order to a creature that he has seen at least once and that is on the same plane. The mage must concentrate for 10 minutes reciting the formula of the ritual and to send his message, which however contains a command similar to the suggestion spell. The recipient can make a ST vs. Mental Spells at –4 to escape the suggestion’s effects, although he can listen to the message and then decide to follow the instructions or not. If however the ST fails, he is obliged to act according to the suggestion to the best of his ability. The sent message is always understood even by beings with an Intelligence of 1, as long as the instructions are easy enough to follow based on the subject’s mental and physical skills. If the circumstances to activate the suggestion aren’t met when the message arrives, the suggestion has no effect. If the message is a question, the creature quickly answers mentally and the mage receives a clear answer. If the target is in front of the mage when he casts the spell, he cannot oppose the suggestion (no ST).", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 155", "school": "Enchantment", "isCustom": false},
    "imm_demonshape": {"id": "imm_demonshape", "name": "Demonshape", "level": 7, "casterType": "immortal", "range": "0", "duration": "1 round per level", "effect": "The cleric is transformed into a screaming demon", "area": "Only the cleric", "description": "When the spellcaster casts this spell, his body suffers a mutation that transforms him entirely into a screaming demon, or a being with the head and a pair of raven wings, long stork legs and a pair of sinewy arms with sharp claws. The cleric keeps his own THAC0, ST, and mental characteristics, as well as his ability to cast divine spells, while his AC becomes −2 and he gains the Strength, Dexterity, and Constitution of a screaming demon (23 in all scores), which increases his physical resistance (hp) and combative ability (bonus to attack and damage). Like a screaming demon he can fly at a speed of 270(90) feet per round, gains infravision within 120 feet and can make attacks with his nature weapons in place of any type of other attack: 2 claws (1d4+4 hp each), 2 feet (1d8+4 hp each), and 1 bite (1d6+4 hp); the damage shown already includes the relevent Strength bonus. Moreover, he can enter and leave the Ethereal and Astral Planes once as as the spell lasts, and can raise once per round, simply by wanting to (he doesn’t need to concentrate) an 50% anti-magic barrier that completely shrouds him and that functions like the 5th level clerical spell magic resistance (only that it uses the percentage given above). As long as he remains in this form however, the cleric can be held by a protection from evil and suffers damage from holy water, although he cannot be magically turned. This effect cannot be made permanent.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 83", "isCustom": false},
    "imm_destroy_undead": {"id": "imm_destroy_undead", "name": "Destroy Undead", "level": 3, "casterType": "immortal", "range": "60 feet", "duration": "Instantaneous", "effect": "Damages undead; reverse heals undead", "area": "20-foot radius circle", "description": "This spell is only effective against undead: if cast against living beings it has no effect. The spell draws the negative energy from the area of effect, which the mage can centre on any point within 60 feet. All the undead within the area with 1 or 2 HD are destroyed; those with 3 or more HD suffer 3d6 points of damage (no ST). Creatures reduced to zero or less hp are considered destroyed, and their spirit is freed. Creatures like vampires, mummies, liches, and some ghosts, which can only be destroyed by certain methods, that succumb to this spell simply lose their physical body, but can regenerate normally based on their own special powers. The reverse spell, heal undead, instead instils negative energy into undead creatures within the area of effect, healing any wounds. The spell only affects undead, giving 3d6 hit points to each creature (without however exceeding the being’s initial hp).\nReversible.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 76", "school": "Necromancy", "isCustom": false},
    "imm_detect_shapechanger": {"id": "imm_detect_shapechanger", "name": "Detect Shapechanger", "level": 1, "casterType": "immortal", "range": "0", "duration": "Concentration", "effect": "Detect the presence of shapechangers", "area": "60 foot long, 20 foot wide cone", "description": "This spell allows the detection of creatures who can change (like lycanthropes, polymars, metamorphs, etc.) within the area of effect. The spell gives different information based on the number of rounds the mage spends concentrating on the same area, as follows: 1st round: presence or absence of shapechanger. 2nd round: number of shapechangers present. 3rd round: magnitude and precise location of each shapechanger within the area. If the shapechanger is outside the spellcaster’s field of vision, he knows in which direction it is. 4th round: race of each shapechanger. The magnitude of the aura depends on the shapechanger’s Hit Dice: HD Magnitude 1-2 Weak 3-5 Moderate 6-10 Strong 11+ Powerful The spellcaster can continue to move normally whilst maintaining concentration, and thus move the examined area each round, but loses concentration if he fights or casts other spells (he can only speak slowly). The spell cannot penetrate barriers of rock or stone thicker than 1 foot, barriers of wood thicker than 3 feet, or layers of metal or lead thicker than 1 inch.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 40", "school": "Divination", "isCustom": false},
    "imm_detect_totem": {"id": "imm_detect_totem", "name": "Detect Totem", "level": 1, "casterType": "immortal", "range": "0", "duration": "Permanent", "effect": "Determine the totem associated to an individual", "area": "Only the spellcaster", "description": "Thanks to this spell, the cleric is able to determine the totemic spirit linked with a subject. It is cast on all adolescent Atruaghins upon reaching the age of 15 and entering adulthood, and on new arrivals who wish to join the tribe. To cast this spell, the cleric must enter a state of deep trance that lasts for 1 to 4 hours. As soon as he enters the trance, he must focus on the person whose totem he wishes to determine and evoke the Immortals so that they reveal his deepest and true nature. At this point, the spellcaster no longer sees the person in his normal human form, but with the appearance of a wild animal (his totem animal). It is possible to hide the proper totem from the cleric in two ways: resist his spell (with a successful ST vs. Spells) or interrupt his trance. If the DM hasn’t assigned a specific totem to a character, he can sue this table: TABLE 2.5 –TOTEM TYPE d% Totem Type 01-13 Fish 14-20 Arachnid 21-25 Crustacean 26-35 Insect 36-40 Amphibian 41-55 Reptile 56-66 Bird 67-00 Mammal", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 52", "isCustom": false},
    "imm_detect_undead": {"id": "imm_detect_undead", "name": "Detect Undead", "level": 1, "casterType": "immortal", "range": "0", "duration": "Concentration", "effect": "Detect the presence of undead", "area": "60 foot long, 20 foot wide cone", "description": "This spell allows the detection of undead creatures within the area of effect. The spell gives different information based on the number of rounds the mage spends concentrating on the same area, as follows: 1st round: presence or absence of undead. 2nd round: number of undead present. 3rd round: magnitude of each undead and its location within the area. If the undead is outside the spellcaster’s field of vision, he knows in which direction it is. The magnitude of the aura depends on the undead’s Hit Dice: HD Magnitude 1-2 Weak 3-5 Moderate 6-10 Strong 11+ Powerful An undead creature’s aura lasts in a place even after the being has left or been destroyed. If the spell is used to examine an area in which an undead was present, the spell registers an intermittent aura, to indicate that the creature is no longer in the area, but without giving the magnitude. An undead creature’s aura remains detectable for a period of time, based on the creature’s magnitude: Magnitude Aura vanishes in: Weak 1d6 rounds Moderate 1d6 minutes Strong 1d6 hours Powerful 1d6 days The spellcaster can continue to move normally whilst maintaining concentration, and thus move the examined area each round, but loses concentration if he fights or casts other spells (he can only speak slowly). The spell cannot penetrate barriers of rock or stone thicker than 1 foot, barriers of wood thicker than 3 feet, or layers of metal or lead thicker than 1 inch.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 40", "school": "Divination", "isCustom": false},
    "imm_devastating_touch": {"id": "imm_devastating_touch", "name": "Devastating Touch", "level": 2, "casterType": "immortal", "range": "Touch", "duration": "1 round per level", "effect": "Touch causes 1d6 and –1 Strength", "area": "A living creature", "description": "With this spell, the spellcaster’s hand begins to glow with a livid blue light and is suffused by negative energy that damages living creatures. Each touch that follows (normal Attack Roll) causes 1d6 of negative energy damage and if he fails a ST vs. Death Ray the victim also loses 1 Strength point for 10 minutes (1 turn). The energy remains in the spellcaster’s hand for a number of rounds equal to his level or until the mage ends it early or it is magically dispelled, and while the spell is active, he can still cast other spells. Undead and constructs are immune to this spell.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 59", "school": "Necromancy", "isCustom": false},
    "imm_dig": {"id": "imm_dig", "name": "Dig", "level": 1, "casterType": "immortal", "range": "10 feet", "duration": "1 minute per level", "effect": "A spade digs 1 ft3 per round", "area": "A digging tool", "description": "When the spellcaster casts this spell on a digging tool (like a pick, spade shovel, etc.), which animates and begins to dig at that location 1 cubic feet of earth (not rock or stone however) al round for 1 minute per level. The excavated earth can be disposed of as the spellcaster likes, and it isn’t necessary to continue to concentrate to control the tool, although he must concentrate if he wants to change the direction of the digging or stop the tool early, bringing the spell to an end.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 41", "school": "Transmutation", "isCustom": false},
    "imm_dimension_tunnel": {"id": "imm_dimension_tunnel", "name": "Dimension Tunnel", "level": 5, "casterType": "immortal", "range": "10 feet", "duration": "Up to 1 round per level", "effect": "Create passage that connects two points up to 30 feet per spellcaster’s level apart", "area": "Special", "description": "This spell is a powerful version of dimension door. With it the spellcaster creates a magic portal that appears within 10 feet and which instantly transports anyone that passes through the place chosen by the mage, which must be within a maximum radius of 30 feet per mage level. Once created, the tunnel remains table for the time established by the spellcaster (to a maximum of 1 round per level), unless it is magically dispelled earlier. The portal appears as a shining door whose dimensions are large enough to all creatures of the mage’s size to pass through: this therefore means that larger creatures cannot pass through it. A similar door appears at the tunnel’s destination, through which it is possible to see the area of the tunnel’s origin and cross there. The movement through the tunnel is instantaneous and bidirectional, and the tunnel can be used by any creature of the right size (although, in a round, only a maximum of 10 creatures can pass through in each direction), except beings protected by an anti-magic barrier. The portal of arrival never appears in a space already occupied by a solid, but can appear in midair. If the chosen destination is an anti-magic area, the spell has no effect and the tunnel collapses.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 113", "school": "Conjuration", "isCustom": false},
    "imm_dimensional_refuge": {"id": "imm_dimensional_refuge", "name": "Dimensional Refuge", "level": 7, "casterType": "immortal", "range": "Touch", "duration": "Special", "effect": "Create a mini-dimension in which to hide; reverse create a dimensional prison", "area": "An object", "description": "While casting this spell, the mage must touch any object of small or tiny size (maximum 50 cn). At this point, a small door appears on the object, and if the secret word (which the mage immediately knows) is while touching the small door, the individual that does so is drawn into the object and transported to a completely closed alternative mini-dimension. Within this dimension there is a house-like building, with maximum dimensions equal to those of cube with 3 feet sides per 2 mage levels (arranged to his liking when he creates the refuge, on a maximum of 3 floors.). In the minidimension there is breathable air for 24 hours, plus another 24 hours for every 9 mages levels (rounded down) and the temperature remains a constant 20°C, the air is always fresh and clean unless affected magically (like with stinking cloud). The house is furnished with candles, normal weapons and shields appear on the walls, furniture (tables, beds, and seats), food and pure water sufficient for one person for a day per mage level. All the objects are absolutely ordinary and can be used normally, but cannot be taken out of the dwelling. There is no limit to the time spent in the dimension, as long as the mage (or his companions) is able to create air, food, and water with the appropriate spells to sustain those inside once those provided are exhausted. The dwelling has no doors or windows, and from the inside is indestructible. The only way to enter it is to know the command word, and have the mage’s permission if is already inside it. The only ways to leave it are through a wish, or by speaking the counter command word, which makes the subject, wherever it is (a gate is not enough). When the first individual to enter leaves, the spell ends, and all the creatures in the refuge appear close to the container. If the spell is cast again, the dwelling created is different to the previous one, and any item left behind in the first refuge is lost forever. When the spell is created, the catalyst rests where it is, and can never be taken into the house (it cannot enter itself!). It irradiates an intense magic aura, and if it is destroyed physically or through disjunction (dispel magic has no effect), the creatures inside are held forever in the mini dimension, unless a wish is used to free them. The reverse spell, dimensional prison, is cast on a nonmagical object, which however must be of at least medium size and commonly used. No symbol appears on it, although magical detections can reveal its enchanted nature. Any being of equal or smaller size of the object that touches its surface (including the mage) is irrevocably drawn inside it, and ends up in a dimension, which is totally devoid of matter, a simple spirit that wanders in a small prison universe. The object can hold up to 20 prisoners, which don’t age or need food or rest whilst inside it, but cannot do anything, except to send cries and try to speak with anyone staring at the object for more than a round (he hears it voice in his mind). All the prisoners are instantly freed if the object is physically destroyed, otherwise its effects vanish after 1 day per mage level, freeing the prisoners and rendering the object normal again. This effect cannot be combined with permanency.\nReversible.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 155", "school": "Conjuration", "isCustom": false},
    "imm_disguise": {"id": "imm_disguise", "name": "Disguise", "level": 5, "casterType": "immortal", "range": "Touch", "duration": "24 hours", "effect": "Modify the subject’s features", "area": "A creature", "description": "This spell allows the subject touched by the mage to disguise himself. He can change his height, weight, smell, sex, appearance, and race, taking that of any species known to him and to a maximum of one size smaller or larger than his own, and only with a height and weight that corresponds to that race. His Hit Points and physical and mental abilities don’t change, nor does he gain the special abilities and immunities of the new form: they remain the same, even if he assumes a totally different form, and fool all of the senses of the spectators. Example: a mage can transform himself into a dwarf or a goblin, and in the latter case smells like a goblin. If instead he chooses to become a centaur, he sprouts four hooved legs (although his movement speed remains the same). If he wants, he could also try to pass for a small dragon, but wouldn’t have any draconic abilities, even if he could move the air by beating his illusionary wings (although without producing any real effects). The spell doesn’t allow the subject to assume the exact features of another person. Indeed, it cannot happen even accidentally: if he imagines a face that corresponds to that of some other, the spell gives an approximately similar result to what he wanted, but not exactly the same (recognisable by someone who knows the original and stops him to closely examine him with 1-5 on d6). An individual under the effect of disguise is able to cast spells. The subject can remove his disguise at any time (which ends the spell), otherwise it lasts an entire day, and lasts even if the mage is asleep or unconscious; if he dies, however, he returns to his original form, as if it was magically dispelled. As long as the effect of the disguise lasts, the subject can change his appearance a maximum of once per hour.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 114", "school": "Illusion", "isCustom": false},
    "imm_disguise_self": {"id": "imm_disguise_self", "name": "Disguise Self", "level": 1, "casterType": "immortal", "range": "0", "duration": "1d6 turns + 1 turn per level", "effect": "Alter the spellcaster’s appearance", "area": "Only the spellcaster", "description": "The spellcaster can make himself (including clothes, weapons, and worn equipment) appear different. He can alter his height by up to 12 inches in either direction, change his weight by up to 40 lbs, but the assumed form must always be of the same type and sex (for example a human cannot grow a tail). The extent of the change is at his discretion and can add or remove small details (like a beard, scar, clothes, hair or eye colour) to appear different, although he remains recognisable to those who know him (1 on 1d6). The spell doesn’t confer any abilities, nor alter the individual’s senses and those of his equipment (a sword can be altered to make it resemble a dagger, but when it is used it remains a sword). The spell moreover doesn’t allow the spellcaster to assume the features of another specific individual. For the spell’s entire duration however, the spellcaster can always use his own abilities (and therefore cast spells) without any impediment. Creatures that physically interact with the individual (e.g. touch it and feel that its form doesn’t correspond to what he can see) can make a ST vs. Mental Spells to pierce the illusion, each time that the interaction is repeated.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 41", "school": "Illusion", "isCustom": false},
    "imm_disintegration": {"id": "imm_disintegration", "name": "Disintegration", "level": 6, "casterType": "immortal", "range": "60 feet", "duration": "Instantaneous", "effect": "Disintegrate a being or object", "area": "A being or object max 1,000 ft3.", "description": "This spell instantly reduces to dust a being or object within 60 feet, without leaving any trace. If the target is a living or animated creature, it must make a successful ST vs. Death Ray to avoid being disintegrated. If the objective is an item, it can only disintegrate a volume of matter of 1,000 cubic feet with a maximum area of 10×10 ft. (for large constructions, subtract a number of SP based on the percentage of the volume disintegrated). Normal objects are automatically vaporised, while magic items (artefacts excluded) can attempt a ST vs. Destruction (see Volume 3) to totally avoid the disintegration. If the spellcaster wants to, he can even concentrate the power of the disintegration on just one part of the target, reducing the area of effect. For a living being, it can just disintegrate part of its body, but in this case should make a further ST vs. Death Ray to avoid fainting from the shock. The disintegration of a body part reduced the Hit Points total by 10% for each leg, arm, or other limb struck (e.g. tail or wing); disintegrating the torso or head results in the victim’s death. The hp only return to maximum once the limb is regenerated or recreated. If instead it is an object, the effect could compromise the structure’s integrity, and still cause its destruction at the DM’s judgement.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 137", "school": "Transmutation", "isCustom": false},
    "imm_displacement": {"id": "imm_displacement", "name": "Displacement", "level": 4, "casterType": "immortal", "range": "Touch", "duration": "6 turns", "effect": "Distort the space around the target", "area": "One target vol. max 10 ft³ per level", "description": "This spell distorts and bends the light rays within a 6 feet diameter around the target touched by the mage, making it appear to be up to 3 feet from its real position. The target can be a fixed area, one creature, or a moveable object of a maximum volume of 10 ft³ per level, and the area of displacement moves with the creature (only affecting it) or with the object (affecting all those within 3 feet of it). This makes it rather difficult to hit targets in the affected area and protects the target from various forms of attack, especially from distance. All those that attack the target in melee suffer a –2 penalty to all Attack Rolls, while a target that is able to move also gains a +2 bonus to all Saving Throws against avoidable effects, as well as the chance of making a ST vs. Spells to also avoid the usually infallible magic missile and similar spells (e.g. fiery bolts of 4th level). Attacks made against the target with common ranged weapon automatically fail, while those made with magic weapons or projectiles have a 50% chance of missing it when the Attack Roll is successful. Obviously, displacement is ineffective against any blind adversary, who however has worse penalty to hit his adversaries, while a trueseeing annuls the effects of the displacement.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 93", "school": "Illusion", "isCustom": false},
    "imm_dominate_person": {"id": "imm_dominate_person", "name": "Dominate Person", "level": 5, "casterType": "immortal", "range": "60 feet", "duration": "1 day per level", "effect": "Mage controls the victim’s actions", "area": "A living humanoid creature", "description": "With this spell the mage can control the actions of any one living humanoid creature within 60 feet, except for undead, constructs, and oozes, by means of a telepathic bond with the subject’s mind. Once the domination is established, the only limit is that the mage and victim remain on the same plane of existence. If they share a common language the spellcaster can force the victim to follow his orders to the best of its intellective ability. If they don’t share a language, the mage can only impart basic commands like “Follow me”, “Come here”, “Attack him”, “Stay here”, and so on. Once the dominated creature is given an order, it continues to attempt to follow it to the exclusion of all other activities with the exception of those needed for daily survival (like eating and sleeping). If the mage wants to, he can change the given order at will, simply by concentrating for a round, and if the victim is on the same plane of existence he immediately follows the new instructions, otherwise it contains with its old task. Moreover, by concentrating on the dominated creature, the spellcaster can receive absolute sensory perceptions as they are interpreted by the subject’s mind, although there is no true telepathic link but only empathic. The mage cannot see through the eyes of the victim or hear through its ears, but can take account of what has happened based on the sensations (if for example he is cold, afraid, in pain, speaking with someone, or asleep). The victim can oppose the domination with a successful a ST vs. Mental Spells with a –2 penalty, but if the ST fails, he remains under the control of the spellcaster for the effect’s duration or until control is magically broken. Moreover, if the victim is forced to undertake actions against his true nature, he is opposed to this order and can annul the domination with a new ST vs. Spells with a +2 bonus. Evidently suicidal orders aren’t followed and free the creature from the spell’s bond. The creature always remembers all of the actions carried out under the mage’s influence and acts accordingly. Via this spell, each spellcaster can dominate a maximum of one creature per Intelligence or Charisma bonus (whichever is best). If he wants to dominate others, he must abandon his control over one of the ones he is currently controlling. Finally, the spellcaster must spend at least one turn per day concentrating on the dominated creature to maintain control, otherwise each day the victim receives a new ST vs. Spells with no penalty to free himself from the effect This effect cannot be made permanent.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 114", "school": "Enchantment", "isCustom": false},
    "imm_draconic_aura": {"id": "imm_draconic_aura", "name": "Draconic Aura", "level": 5, "casterType": "immortal", "range": "Touch", "duration": "1 round per level", "effect": "Bonus to ST, AC, Attacks, and magic resistance", "area": "A living being", "description": "This spell exists in three different forms, one for each of the three dragon lords and their followers, based on alignment. Only the priests of the Great One can choice which effect to evoke, the others are bound to only one. The spell only affects living beings, and reptilian and draconic creatures add a further effect: 2 additional hp for each of the creature’s Hit Dice. At the affect’s end, the remaining additional hp vanish, but if already below its hp maximumse suffers no further loss. Adamantine Aura (Diamond): The beneficiary’s skin assumes a diamond-like appearance (faceted, luminous, and reflecting, however it doesn’t become transparent), and he gains a +4 bonus to his natural AC, to all ST, and a 3 point damage reduction only towards physical attacks with weapons and natural attacks, not from magical effects; the use of any armour augments the damage reduction (if using the Armour Value rules). Opalescent Aura (Opal): The subject’s skin assumes an iridescent appearance similar to that of opal, and he gains a +2 bonus to Attack Rolls, damage inflicted with melee or natural weapons, AC, and all Saving Throws. Moreover, he gains a damage reduction of 2 points towards physical attacks with weapons and natural attacks, not from magical effects. Pearlescent Aura (Pearl): The subject’s skin becomes a milky pearl colour, and he gains a +4 bonus to Attack Rolls, damage inflicted with melee or natural weapons, and he gains a damage reduction of 2 points towards physical attacks with weapons and natural attacks, not from magical effects.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 75", "isCustom": false},
    "imm_dragon_scales": {"id": "imm_dragon_scales", "name": "Dragon Scales", "level": 3, "casterType": "immortal", "range": "Touch", "duration": "1 turn", "effect": "Skin is transformed into robust protective scales", "area": "One living creature", "description": "When casting this spell, the priest must touch a consenting creature: the spell instantly transforms the being’s skin into hard and resistant scales of a colour appropriate to the subject’s alignment. The scales give the subject a natural AC of 4, or a +2 bonus to the natural AC in the case that it is already equal to or better than 4. Moreover, each blow inflicted on the subject is mitigated by the scales that reduce the inflicted wounds by 1 point per attack, until the end of the spell’s duration. Finally, based on the scales’ colour, the subject gains an additional bonus to a certain type of Saving Throw:  AL Lawful: White Scales (+2 ST vs. cold)  AL Neutral: Blue Scales (+2 ST vs. lightning)  AL Chaotic: Red Scales (+2 ST vs. fire)", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 61", "isCustom": false},
    "imm_dragon_shield": {"id": "imm_dragon_shield", "name": "Dragon Shield", "level": 5, "casterType": "immortal", "range": "0", "duration": "3 turns", "effect": "Shield absorbs any dragon breath", "area": "Only the cleric", "description": "This spell creates in the hands of the cleric a medium sized shield incised with the symbol of Bemarris (a dragon transfixed by a sword). The shield gives the cleric a protection bonus of +1 per 4 caster levels (rounded down, max +5 at 20th) against any attack until the end of its duration, but its speciality is that it renders the priest immune to the breath od a specific draconic race, chosen by the cleric. The shield disappears at the end of the spell’s duration, if it removed from the cleric’s hands, or if magically dispelled. This effect cannot be made permanent.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 75", "isCustom": false},
    "imm_dream": {"id": "imm_dream", "name": "Dream", "level": 5, "casterType": "immortal", "range": "Infinite", "duration": "Special", "effect": "Send a dream to a sleeping creature; reverse send a nightmare to a sleeping creature", "area": "A creature", "description": "The spellcaster is able to send a message through his dreams to another living creature that is asleep and that the subject has seen at least once. It isn’t important where the dream’s addressee is if this is a known person, as the spell uses the Plane of Dreams or the Dimension of Nightmare to arrive at its addressee: the important thing is that he is sleeping (and cannot counter the dream in any way). When the mage concentrates, he enters a state of trance and appears in the dreams of the addressee, speaking with him until he decides to end the contact, which also ends the spell and makes the mage’s mind return to his body. During the dream the communication is bidirectional (both sender and addressee can interact) and the length of time isn’t important: the addressee always remembers what happened in the dream when he awakes. To the questions put to him by the mage, the addressee can respond directly (if friendly) or through visions and alterations of the dream that both are immersed in (if reticent or hostile), as when the recipient refuses to openly answer the spell draws from his subconscious the answers to the questions put by the spellcaster and shows them in a confusing or enigmatic way (for example if questioned about the testimony of an assassin that was seen to commit murder, he could show a vision of a tiger that rends his cubs to indicate a close relative). The messenger is also able to show the addressee images that he has personally seen, making these elements appear in the dream as part of their conversation (if for example if they are talking about a dragon that has attacked a village, the sender can create the vision of the attack or of the dragon in front of them). The messenger appears in addressee’s dream in exactly the form and with the items that he wore at the start of the dream. If it is a nightmare, the messenger cannot modify the visions, but can help the recipient to get out, and all the spells cast by the messenger during the dream are effectively removed from those memorised. If the addressee is awake at the moment of the contact attempt, the sender knows that the addressee isn’t yet asleep and can remain in the trance until that moment, or can suddenly awake and end the spell. If during the trance the messenger’s body is in any way injured, the trance is immediately interrupted and the spell ends with the awakening of the messenger in his body. The sender is totally unconscious of what is happening around his body whilst he remains in the trance, and is both mentally and physically defenceless (automatically fails any Saving Throw). The reverse spell, nightmare, sends a terrifying vision to the victim making it impossible to rest. The nature of the nightmare is up to the mage, but the victim is called to a ST vs. Mental Spells: if successful, the victim defeats his fear after an hour of disturbed sleep and can rest for the rest of the night (the hp recovered by the rest are however halved). If the ST fails, the nightmare not only lasts the entire time of the sleep, preventing him from resting (he recovers no hp and cannot memorise spells), but upon awakening the victim’s psyche is so shaken that it causes a temporary loss of 1 point of Intelligence and a –1 penalty to his Attack Rolls, Saving Throws, and any skill or characteristic check; this penalty is cumulative up to a maximum of –4. If his Intelligence score drops to zero, the victim goes insane (the madness renders a PC unmanageable) and can only be healed through more applications of mental cure, or with a wish. A prolonged period of nightmares also places great stress on the victim’s physique: in fact, for every week spent without rest, he loses 1 Constitution point. If because of this his Constitution score drops to zero, the victim enters into a coma and his mind is lost in the Dimension of Nightmare. It is only possible to recover it with a wish, or with dream or the Dreaming skill to reach the victim’s soul, and afterwards a heal spell cast on his body can revive him. Spells of mental protection prevent a person from falling victim to nightmare or dream, while a restorative sleep (2nd level divine spell) neutralises the effects of a dream or a nightmare for a day. For each day in which he rests, the victim normally recovers 1 point of Constitution and Intelligence.\nReversible.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 115", "school": "Illusion", "isCustom": false},
    "imm_dying_breath": {"id": "imm_dying_breath", "name": "Dying Breath", "level": 1, "casterType": "immortal", "range": "240 feet", "duration": "Special", "effect": "Inflict a minor curse", "area": "A creature", "description": "When the spellcaster casts this spell, it remains active until it is used, or the moment of the spellcaster’s death (reduced to 1 hp or less). With his last breath of life, he can evoke a curse (whether or not he has already acted in the round in which he dies) and cast it on anyone within 240 feet (usually his killer): the victim must make a ST vs. Spells to avoid all the effects, otherwise the spellcaster can impose a small deficit on the victim, like a –1 penalty to any one type of ST, or to Attack Rolls, or damage, or a skill check, or a 10 feet reduction to movement, and other similar penalties (it is up to the DM to judge, but he should remember that it shouldn’t be comparable to the effects of a 4th-level curse). The curse remains until it is removed with remove curse.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 41", "school": "Necromancy", "isCustom": false},
    "imm_eagle_eyes": {"id": "imm_eagle_eyes", "name": "Eagle Eyes", "level": 6, "casterType": "immortal", "range": "Touch", "duration": "From dawn to sunset", "effect": "Subject cannot miss targets with missile weapons", "area": "One creature", "description": "This spell can be cast on an individual only at sunrise. Once cast, it makes it so that the character, when using bows, slings, and bolas, can never miss his target (also functions against beings protected by distorting effects, but not against creatures hiding behind rigid cover); the effect lasts until sunset. Factors concerning the weapon’s range are only applied when they limit the weapon (e.g. a bow cannot fire arrows beyond a certain maximum distance), not the archer, so no Attack Roll is needed. If the weapon inflicts maximum damage (based on the archer’s mastery rank), the target has been struck with such precision that additional damage is inflicted: in game terms, roll the damage die (or dice) again and add it to the obtained value to the weapon’s bonus and any other magical bonus present). If the second damage roll also inflicted the maximum amount possible, add it to the total and repeat until a less than maximum result is rolled. For this reason, there is no theoretical limit to the damage that the archer can inflict when benefitting from eagle eyes. Projectiles that cause only 1 hp (like the darts of a blowgun), cause 4 hp, without other effects. This effect cannot be added to a magic item.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 79", "isCustom": false},
    "imm_earthmaw": {"id": "imm_earthmaw", "name": "Earthmaw", "level": 4, "casterType": "immortal", "range": "150 feet", "duration": "Instantaneous", "effect": "Fanged mouth of rock attacks a target", "area": "20-foot diameter circle", "description": "The spell creates a 20 feet wide mouth in the earth within range, which lunges at the chosen by jutting out of the ground for 10 feet like a snake of rock, and bites the target. The mouth can hit up to one Huge, two Large, four Medium, eight Small, sixteen Tiny, or thirtytwo Diminutive creatures, if they are concentrated within a 20 feet diameter circle. The maw automatically hits and causes 1d6 points of damage per spellcaster level (maximum 20d6 at 20th-level), halved with a successful ST vs. Spells. If the ST fails by 5 or more points, it means that the mouth has swallowed the target, burying him 10 feet underground. The victim should be returned to the surface quickly by digging or using an appropriate spell, before he begins to suffocate (he can hold his breath for a number of rounds equal to his Constitution score, after which he loses ⅓ of his hp each round and dies in the 4th round). Earthmaw can only be created in an area of earth or sand but not on a rock or stone surface (like inside a castle or a paved square), or in an area in which a tree is present. Any items in the affected area (like a tent or cart) are considered targets of the attack and end up swallowed by the earth.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 93", "school": "Conjuration", "isCustom": false},
    "imm_eclipse": {"id": "imm_eclipse", "name": "Eclipse", "level": 7, "casterType": "immortal", "range": "0", "duration": "12 turns", "effect": "Create a total eclipse in the area of effect, which gives a +3 bonus to Attacks, damage, ST, and AC to undead and followers of Nyx during the period of complete darkness", "area": "1 mile radius hemisphere per level", "description": "When the cleric casts this spell (only possible in the open during daylight hours) he begins a phenomenon analogous to a total eclipse of the sun: the eclipse involved a 1 mile radius area per cleric level, centered on the priest’s position when he cast the spell. The eclipse is generates a large sphere of interposing magic shadow at the right distance between the Sun and the affected planet (usually a few thousand miles), and this is the reason why the eclipse covers a smallish area, and the size of the penumbra is smaller than that of a natural eclipse. However, given its size, the spell can only be annulled with a wish. Eclipse lasts 2 hours (12 turns) in total, but the sun is only progressively obscured: complete darkness (that reduces the light level to that of twilight) occurs after half an hour, and the phenomena’s full effect lasts one hour (6 turns), after which another 30 minutes is needed to return to normality. Besides the obvious effects (principally that of terrifying the population), eclipse has additional magical effects: during the hour of complete darkness, the atmosphere is considered night, and so undead (including vampires) and all other creatures of shadow can leave cover with no danger. Moreover, during this time, all undead and clerics of Nyx within the area of effect gain a +3 bonus to all Attacks, damage, AC, and ST; undead, finally, cannot be turned. This spell cannot be made permanent on an item.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 83", "isCustom": false},
    "imm_ecstasy": {"id": "imm_ecstasy", "name": "Ecstasy", "level": 2, "casterType": "immortal", "range": "Touch", "duration": "1 turn", "effect": "Victim falls prey to a sensual desire", "area": "A living creature", "description": "This peculiar spell renders the target, who must always be a living being, victim to an extreme and irresistible sensual impulse that clouds the mind and affects the limbs. If the victim doesn’t make a successful ST vs. Mental Spells, his mind is totally obsessed by the desire and sends such impulses of adrenaline and testosterone to the body that it impedes any particular movement not aimed at satisfying the sexual ecstasy. In practice, the victim cannot fight or concentrate to cast spells, he can only speak with difficulty by keeping his concentration and containing his impulses (AC penalised by 3 points and movement rate halved) for the spell’s duration. The spell ends when the victim strips to physically satisfy his sensual desires coupling with someone else or practices autoerotism per 1d6 rounds, during which the subject is practically unarmed and benighted by the ecstasy.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 59", "school": "Enchantment", "isCustom": false},
    "imm_elemental_explosion": {"id": "imm_elemental_explosion", "name": "Elemental Explosion", "level": 1, "casterType": "immortal", "range": "120 feet", "duration": "Instantaneous", "effect": "An element deflagrates and causes 1d8 hp +1 hp per level (max +20, ST for half) to all within 10 feet", "area": "10 foot radius circle", "description": "When the spellcaster evokes elemental explosion, he must select a source present within range, based on the element he intends to use: for fire, a source of flame at least as big as a torch; for water, a mass of water of at least 2 pints; for earth, earth, stone, or rock of at least 3 cubic feet of volume; for air, a volume of air of at least 3 cubic feet. Casting the spell, the chosen element burns and automatically damages all the creatures and things present within 10 feet causing 1d8 points of damage plus one point for every mage level (max 1d8 + 20 hp at 20th). The spellcaster can choose to vary the intensity of the explosion from a minimum of 1d8+1 hit points to the maximum allowed by his level. The victims can halve the damage with a successful ST vs. Spells, but only if they can react. Sleeping creatures and items within the area of effect automatically suffer the damage. The explosion of fire releases tongues of fire and sparks, that of water small needles of congealed water, that of earth stone and rock shrapnel, and that of air a sonic wave. Elemental explosion doesn’t significantly damage its source, but is limited to cause scratches to stone, earth, and rock (on fire, water, and air there are instead no effects of note).", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 41", "school": "Conjuration", "isCustom": false},
    "imm_elemental_weapon": {"id": "imm_elemental_weapon", "name": "Elemental Weapon", "level": 3, "casterType": "immortal", "range": "Touch", "duration": "1 turn per level", "effect": "A weapon does double damage against a creature of fire or cold", "area": "A weapon", "description": "This spell can be cast on any melee, thrown, or missile weapon, selecting one of the two possible versions. Burning weapon: the weapon becomes warm to the touch, and any metallic parts (usually the blade or head) become reddish and smokes. When it is used against a monster of cold or water (for example white dragons, water elementals, or frost salamanders), the weapon’s magical bonus is doubled (for example, a sword +2 acts as it was a sword +4), and if the weapon isn’t magical, it temporarily becomes a +1 weapon. For missiles weapons, all the effects are applied to the fired projectiles, until the end of the duration. Icy weapon: the weapon becomes cold to the touch, and any metallic parts (usually the blade or head) become slick and whitish, as if it was made of ice. When it is used against a monster of (for example red dragons, fire elementals, or hellhounds the weapon’s magical bonus is doubled (for example, a sword +2 acts as it was a sword +4), and if the weapon isn’t magical, it temporarily becomes a +1 weapon. For missiles weapons, all the effects are applied to the fired projectiles, until the end of the duration. This effect cannot be combined with permanency.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 76", "school": "Transmutation", "isCustom": false},
    "imm_empathic_suffering": {"id": "imm_empathic_suffering", "name": "Empathic Suffering", "level": 5, "casterType": "immortal", "range": "", "duration": "", "effect": "", "description": "Granted by an Immortal in the Tome of the Magic of Mystara Vol. 2 (Divine Magic), Appendix \"Additional spells of each Immortal\". The provided books (Tome Vol. 1-2, Rules Cyclopedia) do not describe this spell; ask your DM or use your own source.", "source": "Tome of the Magic of Mystara Vol. 2, Appendix (no description)", "isCustom": false},
    "imm_enchant_item": {"id": "imm_enchant_item", "name": "Enchant Item", "level": 4, "casterType": "immortal", "range": "", "duration": "", "effect": "", "description": "Granted by an Immortal in the Tome of the Magic of Mystara Vol. 2 (Divine Magic), Appendix \"Additional spells of each Immortal\". The provided books (Tome Vol. 1-2, Rules Cyclopedia) do not describe this spell; ask your DM or use your own source.", "source": "Tome of the Magic of Mystara Vol. 2, Appendix (no description)", "isCustom": false},
    "imm_enchanted_ship": {"id": "imm_enchanted_ship", "name": "Enchanted Ship", "level": 7, "casterType": "immortal", "range": "", "duration": "", "effect": "", "description": "Granted by an Immortal in the Tome of the Magic of Mystara Vol. 2 (Divine Magic), Appendix \"Additional spells of each Immortal\". The provided books (Tome Vol. 1-2, Rules Cyclopedia) do not describe this spell; ask your DM or use your own source.", "source": "Tome of the Magic of Mystara Vol. 2, Appendix (no description)", "isCustom": false},
    "imm_enchanted_standard": {"id": "imm_enchanted_standard", "name": "Enchanted Standard", "level": 4, "casterType": "immortal", "range": "Touch", "duration": "1d6 hours", "effect": "Instil a magic power to a standard", "area": "A standard", "description": "This particular spell is mainly used in battle by cleric of Immortals of war. Touching a vessel that holds the very distinguishable image of a particular animal or symbol, the priest imbues it with such immense holy power that it becomes a divine receptable able to instil the protection and aid of the served Immortal to all those that can clearly see the symbol on the vessel and who wear an identical sign (e.g. a regiment that wears tabards or pins with the same identification sign, like a wolf’s head, cross, sun, etc.). The power remains within the standard for 1d6 hours, and only acts on the cleric’s allies who can clearly see the vessel, which once seen grant the subject, as long as he remains within 1,800 feet of the vessel, a particular ability chosen by the priest between the known spells of the first two levels (e.g. bless, sanctuary, protection from evil, etc.), or a +1 bonus to any Attacks and damage with a particular type of weapon, a +2 bonus to Morale or to a certain type of Saving Throw, or a special ability linked to the animal represented in the vessel, with limits imposed by the DM’s judgement. Examples of vessels and their associated powers are as follows: • Eagle: Courage or Observe (see general skill) • Camel: Resist heat (see general skill) or halve daily water requirements • Falcon: Observe or Surprise (see general skill) • Phoenix: protection from death (see divine aid, 1st) or Hard to kill (see general skill) • Thunderbolt: lightning touch (1d6 damage with bare hands) or resistance to lightning (2nd) • Hyena: the cry scares the enemy who flees in panic for 1d4 rounds if an ST vs. Paralysis fails. • Moon: night vision or individual silence (2nd) • Wolf: Scent or double speed • Snake: with a natural 20 on the Attack the enemy must make a ST vs. Poison or die from the blow • Sun: light once per hour or burning touch (1d6 damage with bare hands) • Fox: Listen or Stealth (see general skill)", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 80", "isCustom": false},
    "imm_endure_elements": {"id": "imm_endure_elements", "name": "Endure Elements", "level": 1, "casterType": "immortal", "range": "Touch", "duration": "1d6 hours", "effect": "Allow 1 creature to cope with the heat or cold", "area": "1 creature", "description": "When casting this spell, the spellcaster touches a creature that for the following 1d6 hours can cope with any conditions of cold or heat (from –20°C to +40°C) selected by the spellcaster. The subject’s body temperature remains constant and stable based on his physiology, without suffering from the external cold or heat. The spell doesn’t protect from damage derived from these two elements, or from environmental effects like smoke, lack of air and so on.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 42", "school": "Abjuration", "isCustom": false},
    "imm_enlarge": {"id": "imm_enlarge", "name": "Enlarge", "level": 3, "casterType": "immortal", "range": "Touch", "duration": "6 turns", "effect": "Target increases by 1 size; reverse reduces target by 1-3 sizes", "area": "1 creature or 1 object 36 ft.cu. × lvl.", "description": "Any creature on which this spell is cast increases by one size category (doubling its dimensions), but the victim can avoid the effects (if he wishes) with a ST vs. Spells. The subject gains a temporary +1 bonus to his Strength, but suffers a 1-point penalty to his Dexterity, while his weight doubles. Moreover, as the equipment he carries is also magnified, the blows inflicted by the creature with weapons are increased by one size (see the rules for the damage caused by larger and smaller weapons in the Mystaran Armoury). The subject can use magic items and cast spells (if he can) normally while remaining transformed, although he can have other types of impediments (like passing down a human-sized corridor). The creature’s encumbrance capacity is also increased: in line of the maximum encumbrances, values it can carry are doubled (but the DM determines, on a case-by-case basis, if this generalisation is sensible). The AC, HD, hit points, THAC0, Saving Throws, and other characteristics or abilities of the creature are unchanged. If enlarge is cast on a creature under the effects of a shrink spell, the effects of the two spells cancel each other out, and the victim instantly returns to his normal size. Enlarge can also be cast on an unguarded item that occupies a maximum volume of 36 cubic feet per spellcaster level, doubling its dimensions for the spell’s duration (the item is not allowed a ST to avoid it). If the touched object is worn by an individual, the spell acts instead on the entire individual (see above) who can avoid it with a successful Saving Throw. The reverse spell, shrink, reduces the touched creature by 1 to 3 size categories (minimum height of ½ foot with a weight of 4 lbs.) at the mage’s discretion, but the victim can avoid the effects (if he wants) with a successful ST vs. Spells. The shrunken subject can hide better (see the Observe general skill) and subjects of diminutive size can also pass through small holes. The individual gains a temporary bonus to his Dexterity, but suffers a penalty to his Strength in proportion to the assumed size (see Table III in the Introduction). As the equipment he carries is also reduced, the damage inflicted by the weapons are reduced in proportion to the new size assumed (see the rules for the damage caused by larger and smaller weapons in the Mystaran Armoury). Any spells or powers of the magic items of the shrunken creature instead function normally. If shrink is cast on a creature affected by an enlarge spell, the effects of the two spells cancel each other out, and the victim immediately returns to his normal size. Shrink can also be cast on an unguarded item that occupies a maximum volume of 36 cubic feet per spellcaster level, reducing its dimensions by 1 to 3 sizes at the mage’s discretion. If the touched object is worn or held by an individual, the spell acts instead on the entire individual (see above). Remember that smaller creatures strike more easily than larger ones and vice versa. For each difference in size, a smaller creature receives a cumulative +1 bonus to attacks, while larger creatures suffer a cumulative –1 penalty. Finally, if the creature is in a place too narrow for its size (either by being enlarged, or by returning to normal after being shrunk), it must make a ST vs. Death Ray: if it fails is crushed to death, otherwise is manages to escape the situation and survive, although it loses ¼ of its hp and could remain stuck (at the DM’s discretion).\nReversible.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 77", "school": "Transmutation", "isCustom": false},
    "imm_enlarge_animal": {"id": "imm_enlarge_animal", "name": "Enlarge Animal", "level": 3, "casterType": "immortal", "range": "120 feet", "duration": "12 turns", "effect": "Increase by 1 size the dimensions of up to 4 animals; reverse decrease by 1 size the dimensions of up to 4 animals", "area": "Up to 4 animals", "description": "This spell increases by one size the dimensions of up to 4 animals in range (the animals cannot avoid the effect). The growth increases the animal’s HD by 2, which augments its resistance (like hp and ST), combat ability (better THAC0), and maximum encumbrance; moreover the animal gains a –2 bonus to its damage with each attack, and its base movement improves by 20 feet for the spell’s duration. The growth doesn’t affect the animal’s other statistics (like AC, number of attacks, and intelligence), and it is only possible to cast this spell on normal or giant animals, and not on fantastic beasts. The reverse spell, shrink animals, reduces by one size the dimensions of up to 4 animals in range, although it is possible to avoid the effect with a successful ST vs. Spells. The reduction lowers the animal’s HD by 2 (if this takes them to 0 HD, then the animal is considered to have ½ HD, or 1d4 hp), which affects its (like hp and ST), combat ability (worse THAC0), and maximum encumbrance; moreover the animal suffers a –2 penalty to its damage with each attack, and its base movement lessens by 20 feet (minimum speed 5 ft per round) for the spell’s entire duration. The reduction doesn’t affect the animal’s other statistics (like AC, number of attacks, and intelligence) at all. It is only possible to use this spell on normal or giant animals, and not on fantastic beasts.\nReversible.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 122", "druidSpell": true, "isCustom": false},
    "imm_entropic_arrows": {"id": "imm_entropic_arrows", "name": "Entropic Arrows", "level": 5, "casterType": "immortal", "range": "150 feet", "duration": "Instantaneous", "effect": "Darts cause 2d6 hp + stun × 2d6 rounds", "area": "1 creature per 2 levels", "description": "This spell creates darts of entropic energy that leave the cleric’s hands and automatically hit up to 1 creature per 2 cleric levels within 150 feet. Each victim suffers 2d6 points of damage and must make a ST vs. Death Ray or be stunned because of the entropic energy that numbs the limbs. The stun lasts for 2d6 rounds and also pevents the victims from thinking. Entropic arrows also affect undead creatures.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 75", "isCustom": false},
    "imm_entropic_shield": {"id": "imm_entropic_shield", "name": "Entropic Shield", "level": 6, "casterType": "immortal", "range": "0", "duration": "1 hour (6 turns)", "effect": "Armour grants infravision and protects", "area": "Only the cleric", "description": "This spell creates around the priest’s body an aura of dark energy that completely swathes him hiding his features and adapting itself to his body. The shell gives the cleric a particularly sinister appearance, so that any creature with 3 HD or fewer are terrified of the priest, refusing to approach within 30 feet or attack him in any way. The aura, moreover, grants the cleric infravision within 60 feet and a +4 bonus to AC. The priest has a 90% chance to Hide in Shadows when he moves within an area of gloom or during the night, lacking an area of light that illuminates him. Finally, he receives a +3 bonus to Saving Throws to avoids the effects of positive energy or spells derived from clerics of Good or Lawful alignment. Entropic shield can be annulled by dispel magic or similar spell, and is impervious to any magic effect based on light, similarly protecting the cleric from their deleterious effects. It also protects the cleric from any effect of ultraviolet or solar rays in general (e.g. if the priest is a vampire, it allows him to endure daylight while protected by the shield). This spell cannot be made permanent on an item.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 80", "isCustom": false},
    "imm_entropic_sphere": {"id": "imm_entropic_sphere", "name": "Entropic Sphere", "level": 3, "casterType": "immortal", "range": "90 feet", "duration": "Instantaneous", "effect": "Cause 1d6 hp per 2 levels (ST for half)", "area": "A target", "description": "This spell creates a 1 foot diameter sphere of negative energy that the priest throws against a target within 90 feet. The sphere automatically hits the victim and causes 1d6 points of damage for every 2 cleric levels (max 10d6 hp at 20th level), halved with a successful ST vs. Death Ray. As entropic energy, the sphere damages both living beings and undead, and also causes a cellular decay in objects (animated or inanimate). Anything reduced to negative Hit Points (or Damage Points for objects) by the sphere, dies because of an accelerated withering of its tissues (for creatures) or breaks due to a sudden fragility (for objects). Creatures dead because of this spell are normally unresurectable.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 61", "isCustom": false},
    "imm_eternal_rest": {"id": "imm_eternal_rest", "name": "Eternal Rest", "level": 5, "casterType": "immortal", "range": "10 feet", "duration": "Permanent", "effect": "Prevents the resurrection, reanimation, and reincarnation of a corpse", "area": "A corpse", "description": "When this spell is cast on a corpse it makes impossible resurrection, reanimation as undead (either by an animate dead spell, or other cause, like for example when a creature is killed by a spectre), reincarnation and similar effects. Eternal rest is permanent and can be countered only with a wish. This spell has no effect if cast on a living creature or an undead.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 75", "isCustom": false},
    "imm_extended_elemental_protection": {"id": "imm_extended_elemental_protection", "name": "Extended Elemental Protection", "level": 6, "casterType": "immortal", "range": "0", "duration": "12 turns", "effect": "Sphere protects from element-based attacks", "area": "10-foot radius sphere", "description": "This spell is identical to the 5th level elemental protection, but in effect creates a 10 feet radius sphere centred on the mage (and that moves with him) that protects anyone inside it in the way described. If one of the creatures present within the circle of protection attacks an elemental of the element from which he is protected, all the creatures within the sphere can be attacked in melee by the elemental, although the damage is halved, as long as the creatures remain in the sphere.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 138", "school": "Abjuration", "isCustom": false},
    "imm_extended_range": {"id": "imm_extended_range", "name": "Extended Range", "level": 4, "casterType": "immortal", "range": "", "duration": "", "effect": "", "description": "Granted by an Immortal in the Tome of the Magic of Mystara Vol. 2 (Divine Magic), Appendix \"Additional spells of each Immortal\". The provided books (Tome Vol. 1-2, Rules Cyclopedia) do not describe this spell; ask your DM or use your own source.", "source": "Tome of the Magic of Mystara Vol. 2, Appendix (no description)", "isCustom": false},
    "imm_extension": {"id": "imm_extension", "name": "Extension", "level": 6, "casterType": "immortal", "range": "0", "duration": "Special", "effect": "Improve a 1st to 4th level spell’s duration, range, or area of effect", "area": "A spell", "description": "This spell must be cast before the spell that it is intended to alter. Its purpose is to increase by 50% the duration, range, or area of effect (only one of the three variables) of a 1st to 4th level spell, provided that the duration is neither instantaneous or permanent, the range isn’t zero (personal or touch, and the area of effect isn’t personal or a single creature. The spell in question must be cast the following round, otherwise the extension is wasted. This effect cannot be made permanent.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 138", "school": "Transmutation", "isCustom": false},
    "imm_eyebite": {"id": "imm_eyebite", "name": "Eyebite", "level": 6, "casterType": "immortal", "range": "30 feet", "duration": "1 round every 3 levels", "effect": "Look provokes coma, panic, or infirmity", "area": "1 living creature", "description": "Once he has cast this spell, for its duration (1 round per 3 mage levels) the spellcaster can choose to direct it against a different target each round. Simply by looking at the victim (there is no need for it to face the mage) and concentrating for that round, the spell acts like a curse based on the target’s HD (as shown in the table below), who can however avoid all the effects of the gaze with a successful ST vs. Spells. If there are more than one effect listed, they are all applied if the ST fails, in the order in which they are listed, with the next beginning as the preceding effect ends. TABLE 2.10: EYEBITE EFFECTS Hit Dice Effect on the victim 1-4 Coma, Panic, Infirmity 5-9 Panic, Infirmity 10+ Infirmity Coma: the victim falls into a catatonic coma for 1 turn per mage level. During this period of time it cannot be awakened in any way if the effect isn’t magically removed with dispel magic, remove curse, or similar. Panic: the victim falls prey to a panic that lasts for 1d4 rounds during which he remains curled up in a foetal position quivering so much that it prevents him doing anything else. After panicking the victim however remains afraid per 1 turn per mage level (–2 penalty to Attacks, ST, and skill and characteristic checks), and automatically falls prey to panic if during this period of time the mage re-enters his field of vision. Infirmity: a sudden pain and fever assaults the subject’s body. An infirm creature suffers a –2 penalty to Attacks, damage, ST, and skill and characteristic checks. The creature struck remains infirm for 1 turn per caster level. The effects of the infirmity can be negated by remove curse but not by remove disease or heal.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 138", "school": "Necromancy", "isCustom": false},
    "imm_eyes_of_the_beholder": {"id": "imm_eyes_of_the_beholder", "name": "Eyes of the Beholder", "level": 7, "casterType": "immortal", "range": "Special", "duration": "1 round per level", "effect": "Emit from the eyes one of the beholder’s powers", "area": "Special", "description": "For the spell’s duration, the spell is able to produce from the eyes by concentraing on one of the following magical effects characteristic of the beholder, which doesn’t prejudice his visual ability:  Flesh to stone within 120 feet;  Charm monsters within 120 feet;  Disintegrate within 60 feet;  Inflict serious wounds within 60 feet;  Slow within 240 feet (up to 4 beings);  Death within 240 feet (4d8 HD of being max 8 HD each, or a single being without limitation);  Sleep within 240 feet (2d6 beings of up to 4 HD each);  Telekinesis within 120 feet (up to 5,000 cn);  Terrorise within 240 feet;  Anti-magic ray: is a 60 feet long, 5 feet wide cone. All magic effects that enter its field of action are instantly annulled as long as they remain in the ray’s area of effect, except for the permanent bonuses of weapons, armour, and items of protection, which continue to function normally. At the same time however, as long as he is using the anti-magic ray, the priest cannot cast any spell, although he can use magic items that don’t produce effects on his person or in the ray’s area of effect. The ray has no power against an area of anti-magic (like another ray or an anti-magic barrier) or reflected magic: the two effects are simply ignored. Each round the cleric can orientate the ray, remaining fixed to a point or following a specific target in its movement, and can choose to deactivate the ray as a free action; to activate it he must concentrate for 1 round, doing nothing else. Each effect only affects visible targets and can be avoided with a ST vs. Spells with the exception of the anti-magic ray; death and sleep instead function as the spells of the same name. This spell cannot be made permanent on an item.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 84", "isCustom": false},
    "imm_fabricate": {"id": "imm_fabricate", "name": "Fabricate", "level": 5, "casterType": "immortal", "range": "", "duration": "", "effect": "", "description": "Granted by an Immortal in the Tome of the Magic of Mystara Vol. 2 (Divine Magic), Appendix \"Additional spells of each Immortal\". The provided books (Tome Vol. 1-2, Rules Cyclopedia) do not describe this spell; ask your DM or use your own source.", "source": "Tome of the Magic of Mystara Vol. 2, Appendix (no description)", "isCustom": false},
    "imm_false_vision": {"id": "imm_false_vision", "name": "False Vision", "level": 5, "casterType": "immortal", "range": "120 feet", "duration": "1 hour per level", "effect": "Fool divination spells with false images of a place", "area": "60-radius sphere", "description": "With this illusion, the spellcaster alters the results of the spells of scrying related to the area magically masked. In practice, at the moment of casting the mage decides which type of image he wants to make appear to any attempt of magical scrying of the selected area, and as long as the spell lasts, he can concentrate for a round to change the desired image. The image that appears to those that use divination spells seems real to all senses, but is always static. The spellcaster can therefore decide to create an empty candle-lit hall where there is a treasure room or a hall full of assembled warriors, or make it appear as a bedroom with a sleeping individual who snores whilst a nightingale’s song resonates, but cannot make any of the elements present in the area move.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 116", "school": "Illusion", "isCustom": false},
    "imm_fascination": {"id": "imm_fascination", "name": "Fascination", "level": 3, "casterType": "immortal", "range": "Touch", "duration": "1d6 hours + 1 hour every 3 levels", "effect": "Render the subject more fascinating", "area": "One intelligent living creature", "description": "This spell only affects one living creature with an Intelligence of at least 3. Fascination renders the subject more attractive and captivating, making it on one hand become physically more beautiful (the spell doesn’t change the features in a perceptible way, but corrects small aesthetic defects like wrinkles, scars, baldness and so on) and one the other more persuasive and charismatic in attitude. In game terms, the subject gains 1d4 points of Charisma + the priest’s Wisdom bonus (for example, if the cleric has 17 Wisdom, the subject gains a 1d4+2 bonus to Charisma). This spell cannot augment the subject’s Charisma beyond its racial maximum, unless the cleric casts it on himself: in this case there is no limit to the score it is possible to achieve. Two fascination spells aren’t cumulative.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 62", "isCustom": false},
    "imm_fate": {"id": "imm_fate", "name": "Fate", "level": 4, "casterType": "immortal", "range": "Touch", "duration": "Instantaneous", "effect": "Predict a character’s future", "area": "One creature", "description": "After having cast the spell, the cleric is able to predict in a certain measure the near future of a character (within the next 5 years). The prediction will only be madewith broad strokes: the place and the time in which the events take place aren’t noted and it isn’t possible to ask specific questions. H LEVEL The vision can be decided by the DM (who will have to create a cryptic or not too detailed prophecy), or determined randomly on the following table (roll a d10 three times and consult the result on each column): TABLE 2.6 – RANDOM VISION OUTCOME OF FATE d10 Subject d10 Action d10 Object 1 Battle 1 Wait 1 Victory 2 Foreigner 2 Aid 2 Ruin 3 Treasure 3 Fetch 3 Death 4 Friend 4 Hinder 4 Revenge 5 Enemy 5 Cause 5 Return 6 Beast 6 Avert 6 Fortune 7 Demon 7 Destroy 7 Enemies 8 Spellcaster 8 Lay a Trap 8 Friends 9 Travel 9 Betray 9 Beloved 10 Innocent 10 Protect 10 Honour For example, a 3-7-10 result would be read as: A treasure will destroy your honour. Unlikely results (like 6-5-9) should be discarded or slightly modified or expanded (in the above example: A beast causes the loss of your beloved). The DM could use the results obtained as a spur for an adventure or a series of adventures in which the character’s predicted destiny is completed. The fate shouldn’t however be immutable, but the character should have the opportunity to change it, or could die before the events take place. No character can simultaneously receive more than one vision of his future: only when the vision has happened, can he receive a new prediction thanks to this spell.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 67", "isCustom": false},
    "imm_feather_fall": {"id": "imm_feather_fall", "name": "Feather Fall", "level": 1, "casterType": "immortal", "range": "0", "duration": "1 round", "effect": "Slow a fall", "area": "Only the spellcaster", "description": "The spellcaster can evoke this power while falling to reduce the falling speed and avoid or reduce the damage. In practice, the spell is instantaneous and doesn’t require the usual round of concentration to be cast, but it is enough to speak an activation word that takes a second, which makes it useful when falling from heights greater than 15 feet (as in a second he can fall 15 feet). Feather fall slows the speed of the spellcaster so that he floats to the ground like a feather for a round. If in this period of time the spellcaster touches the earth, there is no risk of damage due to the fall, other than the fear of falling. If instead at the end of the round the mage has still not landed, it again falls based on the normal laws of gravity, but the height that is reached in that round is considered the starting height to calculate the falling damage. Example 1: a mage falls from a 30 foot high tower. In theory he wouldn’t have enough time to cast a spell to save himself as it only takes one and a half seconds to hit the ground (see the Table on Falling in the 7th-level spell control gravity). However, using feather fall that only needs a second, he can slow the fall for the rest of the round, and land without taking any damage. Example 2: a mage falls from a 1,200 feet tall cliff, and although he has a round to utter a spell before he reaches the ground, he doesn’t have any spell available that can save him except feather fall. So he glides for the distance that he would cover in 1 round (10 seconds), or 1,000 feet, but at the end of the round he again falls at full speed. However, reaching the ground he suffers damage for a fall from 200 feet (1,200 ft. less the 1,000 ft. absorbed by feather fall), which would be 10d6 points of damage, unless he uses another feather fall.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 43", "school": "Transmutation", "isCustom": false},
    "imm_feign_death": {"id": "imm_feign_death", "name": "Feign Death", "level": 2, "casterType": "immortal", "range": "", "duration": "", "effect": "", "description": "Granted by an Immortal in the Tome of the Magic of Mystara Vol. 2 (Divine Magic), Appendix \"Additional spells of each Immortal\". The provided books (Tome Vol. 1-2, Rules Cyclopedia) do not describe this spell; ask your DM or use your own source.", "source": "Tome of the Magic of Mystara Vol. 2, Appendix (no description)", "isCustom": false},
    "imm_fertility": {"id": "imm_fertility", "name": "Fertility", "level": 3, "casterType": "immortal", "range": "Touch", "duration": "Special", "effect": "Makes fertile 1 acre of land/a person or heals a plant; reverse renders sterile 1 acre of land terra/a person or kills a plant", "area": "1 acre of earth or a plant or living being", "description": "If the spell is cast on an acre of land after the harvest and before the next planting, making that specific area of ground fertile for an entire season, doubling the normal crop produced by that ground. If instead the spell is cast on a plant or plant creature, it cures it of any disease and allows it to recover 2d6+2 hit points. If finally it is used on a living being, it is healed of any disease affecting reproduction and becomes particularly fertile, such that at the first sexual coupling it automatically impregnates (for males) or become pregnant (for females). The reverse spell, sterility, prevents 1 acre of land from producing any type of crop for an entire season, and kills all the non-magical plants in the area (no ST). If it is cast on a single plant it withers away and dies (despite its size), while if it is a magic plant or plant creature, it causes 2d6+2 points of damage (if the magic plant doesn’t have hp, it dies on a result of 1-3 on d6). If finally it is cast on a living being, it becomes incapable of procreation in any way, and contracts a debilitating disease that will kill it within a year if it isn’t cured with remove curse, fertility, cure disease, or more powerful cure spell. Neither the spell fertility nor its reverse can be annulled by a dispel magic, but one can cancel the other and it can be countered by curse and its reverse.\nReversible.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 78", "school": "Transmutation", "isCustom": false},
    "imm_fiery_tentacle": {"id": "imm_fiery_tentacle", "name": "Fiery Tentacle", "level": 6, "casterType": "immortal", "range": "", "duration": "", "effect": "", "description": "Granted by an Immortal in the Tome of the Magic of Mystara Vol. 2 (Divine Magic), Appendix \"Additional spells of each Immortal\". The provided books (Tome Vol. 1-2, Rules Cyclopedia) do not describe this spell; ask your DM or use your own source.", "source": "Tome of the Magic of Mystara Vol. 2, Appendix (no description)", "isCustom": false},
    "imm_find_information": {"id": "imm_find_information", "name": "Find Information", "level": 1, "casterType": "immortal", "range": "120 feet", "duration": "6 turns", "effect": "Detects text with specific information", "area": "A written text", "description": "This spell detects the location of a written text on a subject chosen by the spellcaster (for example “the nation of Vestland”, “the hero Bemarris”, or “the trained horses”), but cannot find a scroll containing a specific spell. If the text is within 120 feet, the spellcaster automatically knows in which direction it is found, although the spell doesn’t reveal the exact distance. If instead the book is not within range, the spellcaster can continue to act normally without having to concentrate, and if the text enters his area of effect before the spell ends, he immediately knows in which direction it is. When there are more than one pertinent book within range, the spell identifies them all.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 43", "school": "Divination", "isCustom": false},
    "imm_fire_bow": {"id": "imm_fire_bow", "name": "Fire Bow", "level": 3, "casterType": "immortal", "range": "Touch", "duration": "1 round per level", "effect": "Wooden bow fires magical incendiary arrows", "area": "A wooden bow", "description": "Casting this spell on a bow, the cleric gives it the ability to fire magical incendiary arrows for the spell’s duration. When the archer draws the bow enchanted with this spell, a burning spectral arrow appears. If the Attack Roll succeeds, the arrow strikes the target and inflicts normal damage (the archer’s weapon mastery gives it normal attack bonus and amount of damage), +1d6 points of fire damage. Anytime the arrow hits something inflammable, there is a 50% chance that the material catching fire, in which case it suffers 1d6 points of damage ech round until it goes out. Fire Bow is also able to damage creatures that can only be hit with magic weapons (maximum +1). The arcane version of this spell is of 4th level and belongs to the school of Abjuration. The spell cannot be added to any magic item.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 62", "isCustom": false},
    "imm_fire_gate": {"id": "imm_fire_gate", "name": "Fire Gate", "level": 5, "casterType": "immortal", "range": "Same plane of existence", "duration": "1 hour per level", "effect": "Cleric is transported from one bonfire to another", "area": "Only the cleric", "description": "To cast this spell, the cleric must first light a special fire using sacred wood, powders, and herbs: the operation requires a hour, but gives life to a fire that burns for 1 hour per priest level. Once the fire has been lit in the prescribed manner, the cleric can cast the fire gate spell on himself, which allows the cleric to enter the middle of the flames without burning and to teleported into the middle of another fire that he knows (within the same plane). As such the tribes of the Atruaghin Clans always have lit fires in their camps in case a shaman wants to visit them. The spell doesn’t allow the cleric to return, or take others with him. However, as the priest is teleported with everything he carries, it is possible to take somebody through the fire if he holds the other person in his arms. The spell cannot be added to a magic item.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 76", "isCustom": false},
    "imm_fire_trap": {"id": "imm_fire_trap", "name": "Fire Trap", "level": 3, "casterType": "immortal", "range": "Touch", "duration": "Permanent", "effect": "Protect object with exploding rune", "area": "An closable object", "description": "This spell must be cast on a lockable item (a book, box, door, trunk, etc.), which from that moment acquires an invisible magic sigil of protection. The item on which fire trap is placed cannot have a second opening or other active spells of protection. The spellcaster selects a point on the item that becomes the centre of the effect, and when someone who isn’t the mage tries to open it, it causes a fiery explosion that extends for a radius of 5 feet starting from the centre. The flames inflict 3d6 damage + 1 point per spellcaster level (max 3d6+36 hp) to things and creatures within the explosion’s range (ST vs. Spells for half), but don’t damage the element protected by the trap. Fire trap if activated underwater inflicts half damage and creates a large cloud of steam. The spellcaster can use the item without triggering the trap, as can any other individual who knows the key word to open the item without activating the trap (the spellcaster must select a key word while evoking the trap). The trap is permanent until it is activated, after which it disappears. Fire trap can be magically dispelled with the normal chance, and it is so difficult to detect and disarm that a thief suffers a −30% penalty to these attempts.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 78", "school": "Abjuration", "isCustom": false},
    "imm_fist_of_rock": {"id": "imm_fist_of_rock", "name": "Fist of Rock", "level": 3, "casterType": "immortal", "range": "240 feet", "duration": "2 rounds", "effect": "Animates a fist that defends or attacks", "area": "300 ft3 of earth or rock", "description": "The spellcaster can manipulate a large quantity of rock or earth (requiring the presence of at least 300 ft3of earth or rock within 240 feet) to create an animated hand. Once the spell is uttered, from the surrounding ground emerges a huge fist made or rock and earth (12 feet long, 10 feet wide, and 3 feet thick), which remains for 2 rounds. The spellcaster can use it in two ways: offensively or defensively. If he chooses to use fist of rock in an offensive manner, the mage hurls it against a target that must be within 240 feet of him. If the target is a creature, the fist causes it 6d8 hp: with a ST vs. Spells can halve the damage, but if he doesn’t succeed, the victim must make a further Dexterity check to not be thrown 5d12 feet further away (suffering a further 1d6 hp for every 10 feet fallen, with a ST to reduce the damage). If the target instead is large item or a construction, it suffers 1d10 points of structural damage (ST vs. Destruction for half). Once used in this manner, the hand is dispelled. If fist of rock is used in a defensive manner, instead, it is immediately placed around the spellcaster, surrounding him like an impenetrable and unmoveable cupola, and it protects him from the damage directed at him in the next 2 rounds The fist can withstand up to 25 damage before vanishing, so it can be destroyed (materially or with a dispel magic) before the end of its duration. This effect cannot be combined with permanency", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 79", "school": "Conjuration", "isCustom": false},
    "imm_flame_of_justice": {"id": "imm_flame_of_justice", "name": "Flame of Justice", "level": 6, "casterType": "immortal", "range": "Touch", "duration": "10 round", "effect": "Discover lies and cause 2d6 hp to the liar", "area": "A creature", "description": "Casting this spell the mage must touch a creature (needing a normal Attack with a +2 bonus): if the attempt fails, the spell is wasted. If instead the spellcaster touches the target, it cannot negate the spell’s effects in any way and is engulfed by a reddish halo that reveals its position, as well as preventing it from using any magical means of instantaneous transport for the following 10 rounds. From this moment, the spellcaster can place a question to the victim per round, and if he answers in a truthful manner nothing happens. Otherwise, if he lies or refuses to answer but knows the truth, he suffers 2d6 points of fire damage, halved each time with a successful ST vs. Spells. The reddish halo is warm but doesn’t burn: it only flares up if the victim lies when addressing the spellcaster (and in this case only for a fraction of a second, enough however to cause pain and damage to the victim). Note that the truth perceived as such by the interrogated is considered sincere: if for example the victim has been informed of a falsehood, but believes the information he has acquired, his testimony (although objectively false) doesn’t cause the adverse reaction of the flames. Flames of justice affects any creature, living or not, and can only be negated by a dispel magic, an anti-magic barrier, or a mental barrier. Spells of fire resistance reduce the damage suffered, but cannot totally prevent it. Naturally the victim can try to escape normally from his questioners, and can act undisturbed for the spell’s duration, but the moment a question is asked by those that cast the enchantment, he is forced to give an answer (true or false). In this case, a silence spell can be used to resist the effects of the flames.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 139", "school": "Divination", "isCustom": false},
    "imm_flaming_liquid": {"id": "imm_flaming_liquid", "name": "Flaming Liquid", "level": 2, "casterType": "immortal", "range": "30 feet", "duration": "6 turns + 1 turn per level", "effect": "Creates a flaming liquid that burns water", "area": "1 inanimate object", "description": "This spell creates a source of liquid fire within 30 feet, which appears on an inanimate object and remains there until the end of the effect without damaging it. The flamesd appear as an area of scarlet water, bur doesn’t cosume air but water: in effect, in the absence of water the flames are immediately extinguished and the spell ends. This spell has been purposely created for aquatic spellcasters, and it is particularly used to facilitate underwater smithing, in order to create weapons, armour, and objects of various metals. The heat and size of the flames is comparable to that of a small forge, and they are usually thrown into their own furnace in which the material to be worked is then placed. Any object or creature that touch the flames suffers damage as if had been exposed to the flames of a furnace (3d6 per round of contact, which renders certain materials very malleable). Flamming liquid vanishes at the end of the spell’s duration or if it is magically dispelled earlier. It doesn’t produce smoke or bubbles, but heats the water within a 20 feet radius bringing it to a temperature of 40°C, and for every 3 feet further from the flames the temperature drops by 5°C.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 55", "isCustom": false},
    "imm_flaming_sphere": {"id": "imm_flaming_sphere", "name": "Flaming Sphere", "level": 2, "casterType": "immortal", "range": "240 feet", "duration": "1 round per level", "effect": "Burning sphere causes 2d6 hp and burns 5", "area": "5 ft. radius sphere", "description": "With this spell the mage creates a 10 foot diameter sphere of fire and whilst concentrating can direct it at a speed of 30 feet per round within a 240 foot radius. All the items and creatures touched by the sphere must make a ST (Magic Fire for items and Spells for creatures): if the ST fails, it suffers 2d6 damage and catches fire, continuing to suffer 1d6 damage each round until the flames are extinguished. If instead the ST succeeds, static items suffer 1d6 damage with no other consequences, while creatures avoid all the damage. If the mage stops concentrating, the sphere remains immobile at that point, and if it goes beyond the range limit the spell ends. The sphere cannot pass barriers of water over 3 foot thick.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 61", "school": "Evocation", "isCustom": false},
    "imm_flaming_web": {"id": "imm_flaming_web", "name": "Flaming Web", "level": 7, "casterType": "immortal", "range": "", "duration": "", "effect": "", "description": "Granted by an Immortal in the Tome of the Magic of Mystara Vol. 2 (Divine Magic), Appendix \"Additional spells of each Immortal\". The provided books (Tome Vol. 1-2, Rules Cyclopedia) do not describe this spell; ask your DM or use your own source.", "source": "Tome of the Magic of Mystara Vol. 2, Appendix (no description)", "isCustom": false},
    "imm_force_shapechange": {"id": "imm_force_shapechange", "name": "Force Shapechange", "level": 5, "casterType": "immortal", "range": "", "duration": "", "effect": "", "description": "Granted by an Immortal in the Tome of the Magic of Mystara Vol. 2 (Divine Magic), Appendix \"Additional spells of each Immortal\". The provided books (Tome Vol. 1-2, Rules Cyclopedia) do not describe this spell; ask your DM or use your own source.", "source": "Tome of the Magic of Mystara Vol. 2, Appendix (no description)", "isCustom": false},
    "imm_forcecage": {"id": "imm_forcecage", "name": "Forcecage", "level": 6, "casterType": "immortal", "range": "60 feet", "duration": "1 turn per level", "effect": "Create an indestructible and unmoveable cage", "area": "29 foot sided cube", "description": "This spell generates an unmoveable cubic prison made of bars of force that traps anyone that finds themselves inside it with no chance of escape. Only if the creatures inside the area of effect are smaller than the cage will they be imprisoned, otherwise the effect doesn’t take place. The forcecage also doesn’t appear if its perimeter is physically obstructed (excluding liquids): the area must be free for the spell to have effect. The bars of force that delimit the cage are ½ inch wide with a ½ inch gap between, and the cage extends to the neighbouring plane (usually the Ethereal if cast on the Prime), and thus prevents spells like ethereal form from being used to escape. If created on the ground, the cage has a compact and smooth roof from which the bars that end at the ground originate (it therefore has no floor of force). If created in air or water, it has both an aperture less roof and floor of force, joined by bars on the four sides. Any creature able to pass through a ½ inch space can escape, as can those using spells of dimensional transport like dimension door, or teleport, otherwise the bars are indestructible: only a disintegrate, wish, or an anti-magic ray can annul it earlier, no other attempt to dismiss the spell is effective. All spells and breath weapons can pass through the bars without problem, while melee weapons are stopped, like any other item more than ½ inch thick. If attacks are made against those imprisoned with missile weapons, there is always a 90% chance that each attack strikes one of the invisible bars and therefore the attack hits no one.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 139", "school": "Abjuration", "isCustom": false},
    "imm_forceful_hand": {"id": "imm_forceful_hand", "name": "Forceful Hand", "level": 6, "casterType": "immortal", "range": "0", "duration": "1 round per level", "effect": "Create a hand of force that obeys", "area": "6 feet per level", "description": "This spell creates a 10 feet diameter translucent hand of pure magical force, which can only be damaged by spells or magic weapons, has the same Hit Points and Saving Throws as the mage and an Armour Class equal to 0 if it is attacked. The hand moves with the mage and acts in an independent way based on the orders it receives (leaving the spellcaster free to do what he wants). It only and exclusively affects the creature designated as the target (ignoring other beings and they can pass by it as if it didn’t exist) and can be used in two ways (the mage must specify which task he wants the hand to perform for the spell’s duration the moment he casts it): Attack: the spellcaster designates a target at the moment of casting, and for the effect’s duration the hand throws itself violently against the target like a hammer. Every round the hand performs an attack (it is considered a magic weapon) that causes 2d8 points of damage if it hits, and requires an Attack with the mage’s THAC0 to establish if the hand strikes the victim. The hand continues to strike the victim as long as he remains within the Area of effect: if he leaves, the hand floats inert next to the spellcaster until the end of its duration without affecting the environment. If the target returns to approach the mage before the spell’s end, the hand attacks him again. If it dies before the end of the spell, the spellcaster can designate a new target that the hand attacks for the spell’s remaining duration. Defence: the spellcaster indicates a potential enemy, and the hand constantly places itself between this target and the mage anytime it tries to approach closer than thirty feet to the mage. It isn’t important from which side it arrives, the hand always acts more quickly than the assailant does and it will damage him before he can touch the mage, forcefully pushing him 6d4 feet away. The target must make a Dexterity check to avoid falling (and in this case suffers 1d6 damage for every 10 feet fallen), and can halve the distance of the push if it makes a successful Strength check with a –8 penalty. The hand in defence obstructs all melee attacks and any attempt by the target to pass it, but it doesn’t block magic or react to ranged attacks. The hand is able to stop up to 2,000 lb. of weight. Beings with greater weight that forcibly try to pass the hand are slowed and can only advance at 10 feet per round. The forceful hand disappears when its duration ends, or earlier if it is destroyed with magical attacks or with magic weapons, or finally if it is magically dispelled. The hand cannot pass through anti-magic barriers or fields (creatures protected by a similar barrier are therefore immune to its effects and ignore it, passing through it), nor can it pass beyond the area of effect. Forceful hand isn’t tricked by forms of disguise or transmutation, always recognises the target subject, but cannot prevent the illusionary form (like projected image) of the creature from passing it. The hand moreover is also able to affect an insubstantial subject or in gaseous form (evanescence), but not out of body projections (creeping shadow or astral body). There is no limit to the number of forceful hands that the mage can create simultaneously, but each must be bound to a different creature.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 140", "school": "Evocation", "isCustom": false},
    "imm_freezing_sphere": {"id": "imm_freezing_sphere", "name": "Freezing Sphere", "level": 6, "casterType": "immortal", "range": "360 feet", "duration": "Instantaneous or 1 round per level", "effect": "Sphere causes 1d6 damage per level or freezes", "area": "10-foot radius sphere", "description": "This spell creates a sphere of cold energy that flies from the mage’s finger to the selected point, where it bursts in a 10 feet radius explosion, inflicting 1d6 points of damage per level to each creature in the area, halved with s successful ST vs. Spells. Elemental creatures of water instead suffer 1d8 hp per level, while undead and constructs are immune to the effect, and creatures of cold automatically suffer half damage (and can be reduced to a quarter with a successful ST). If the freezing sphere bursts within a body of water or hits a liquid with a large percentage of water, it can freeze a maximum volume equal to a 20 feet radius sphere, which remains frozen for 1 round per level. The creatures that are trapped within the frozen area can try to free themselves with a Strength check with a −4 penalty, but only if they have at least half of their body (arms included) outside the frozen block.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 140", "school": "Evocation", "isCustom": false},
    "imm_friendship": {"id": "imm_friendship", "name": "Friendship", "level": 1, "casterType": "immortal", "range": "60 feet", "duration": "1d6 hours", "effect": "Increase the Charisma score", "area": "1 creature per level", "description": "This spell affects all intelligent beings within 60 feet of the spellcaster at the moment of casting. For each victim that fails its Saving Throw vs. Mental Spells the mage’s Charisma increases by 2d4 points while dealing with him (the spell’s duration is 1d6 hours); If instead the ST succeeds, the spellcaster just gains a +2 bonus to the Reactions of the victims. Those that are under the effect of friendship are always disposed to listen to the words of the spellcaster for the spell’s duration, although it doesn’t necessarily mean that they follow his advice. At the end of the spell the ascendency of the mage on the victims vanishes without those affected feeling any resentment for their part. This spell doesn’t affect creatures with an animal or lower intelligence, or modified by Charismabased special abilities. Its effects can only be broken by casting dispel magic on the spell’s victims: casting it on the spellcaster doesn’t affect friendship. This effect cannot be made permanent.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 44", "school": "Enchantment", "isCustom": false},
    "imm_gaseous_form": {"id": "imm_gaseous_form", "name": "Gaseous Form", "level": 3, "casterType": "immortal", "range": "Touch", "duration": "1 turn per level", "effect": "A creature assumes gaseous form", "area": "A creature", "description": "Thanks to this spell, the touched subject is transformed into a cloud of opaque gas along with all his equipment, keeping his visual and hearing abilities (affected by the surrounding environmental conditions, obviously). In this form, he is immune to all normal weapons (although a +1 weapon or better can injure him), critical hits, poison, paralysis, and polymorph. He cannot cast spells, attack, or use magic powers, but can fly at a speed of 120 feet per round and his AC becomes –2 (or he keeps his own AC if this is better). He can also enter a closed area if there are at least ½-inch cracks through which he can pass, ignoring the effects of winds of lesser intensity than 25 mph, but cannot enter water or pass through a barrier of water or ice. The subject cannot avoid being turned into gas, but can return to his normal form when he wishes, and this ends the spell’s effect; otherwise he remains in this form for the spell’s duration or until it is dispelled (or he is killed in some way). This effect cannot be combined with permanency.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 79", "school": "Transmutation", "isCustom": false},
    "imm_genealogy": {"id": "imm_genealogy", "name": "Genealogy", "level": 1, "casterType": "immortal", "range": "30 feet", "duration": "Instantaneous", "effect": "Determine the age and background of a creature, object, or place", "area": "One creature, item, or place", "description": "Casting this spell and concentrating for an instant on a being, object, or place that is within the radius of effect and his line of sight, the cleric is able to determine the real age (expressed in years since its creation or birth), proper name, that of its parents, or creator if an object or construction, or of the current owner if a place, and finally the city and region of origin (for objects and people), as well as at least one event of notable importance to it (that have involved at least one hundred people) for every 5 cleric levels. The spell doesn’t reveal alignment, the target’s magical capacity or powers, or particular secrets (like hidden passages or actions that aren’t public knowledge). Example: the priest of the king (C10th) examines a baron whohas just appeared at court with genealogy to discover that he is called Wulfric Magnusson of the house of Skolgrim, who is 40, his parents were Magnus Stallast and Inga Gefjun, who come from the city of Stallansford, in the region of Heldland and that the only thing of note in his life was a battle in which he defeated and destroyed a dangerous group of brigands that threatened his city about five years earlier. Normally no ST is allowed to avoid the spell’s effects, and the examined creature doesn’t notice anything. However, for beings who want to intentialy hide their true nature and history, it is possible to make a ST vs. Spells to not be unmasked. Magically camouflaged object, places, or buildings instead (like with polymorph any object, hallucinatory terrain, etc.) are immune to the spell, as are creatures protected by a barrier of anti-magic or that prevents mind reading or information gathering.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 53", "isCustom": false},
    "imm_geographic_map": {"id": "imm_geographic_map", "name": "Geographic Map", "level": 3, "casterType": "immortal", "range": "Touch", "duration": "Permanent", "effect": "Draws a dumb geographic map of the area", "area": "A smooth surface", "description": "When casting this spell, the mage must touch a relatively smooth and homogenous surface on which it is possible to write (a piece of paper, an already uncurled roll of parchment, a wax tablet, and a blackboard are all valid examples). On the surface signs and symbols begin to magically appear, which after 6 rounds have composed a large-scale geographic map of the surrounding area: the mapped surface is centred on the spellcaster’s position and has a radius of ½ mile per caster level. Any writing on the surface before the map was created is removed and irredeemably lost. The representation is faithful but not extremely detailed: it shows the profile of the coast, the rivers, and the principal roads, the morphologic elements of the territory like hills, mountains, forests, and swamps (without giving the height of the contours), and mark the position of cities, towns, fortifications, and other settlements. It doesn’t show small streams, paths, lairs of monsters or other creatures, political borders, interiors of buildings and caverns, or sites of historic interest (like a battlefield, unless it is a fortification or something similar). No name, inscription, or captions of any kind appear on the map (not even those of the principal cities or seas), which is therefore completely “dumb”. The scale of the map and the symbols that it uses are chosen by the mage at the moment of casting of the spell: typically, he opts for a scale that allows him to see the entire map on the available surface. Geographic map, once designed, is permanent and cannot be dispelled, with the traits of a normal object, but it can be physically destroyed or removed if the spell bleach or colour is cast on the same surface, or if it is used for the same spell or focused map to map a new area.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 79", "school": "Divination", "isCustom": false},
    "imm_ghost_sound": {"id": "imm_ghost_sound", "name": "Ghost Sound", "level": 1, "casterType": "immortal", "range": "90 feet", "duration": "1 round per level", "effect": "Creates illusionary sounds", "area": "N/A", "description": "This spell allows the creation a continuous sound that can rise or descend in tone, move towards and go away from the point in which it was created (within 90 feet of the spellcaster). The mage selects the type of sound as he casts the spell and cannot change it later. The volume of the sound that he can create depends on the spellcaster’s level: in general it is possible to create the noise produced by a person of medium for each spellcaster level, treat noises like the roar of a wild animal as equal to at least the sound produced by four people, while a medium size creature develops the same volume as a bunch of eight smaller creatures (like rats, squirrels, cats).", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 44", "school": "Illusion", "isCustom": false},
    "imm_ghostly_aura": {"id": "imm_ghostly_aura", "name": "Ghostly Aura", "level": 5, "casterType": "immortal", "range": "", "duration": "", "effect": "", "description": "Granted by an Immortal in the Tome of the Magic of Mystara Vol. 2 (Divine Magic), Appendix \"Additional spells of each Immortal\". The provided books (Tome Vol. 1-2, Rules Cyclopedia) do not describe this spell; ask your DM or use your own source.", "source": "Tome of the Magic of Mystara Vol. 2, Appendix (no description)", "isCustom": false},
    "imm_ghoul_touch": {"id": "imm_ghoul_touch", "name": "Ghoul Touch", "level": 1, "casterType": "immortal", "range": "Touch", "duration": "2d6 rounds", "effect": "Paralyse a living creature", "area": "1 living creature", "description": "When casting this spell, the spellcaster must touch a living being (the victim’s AC is calculated without his armour), and the victim can negate the effect with a ST vs. Paralysis. If the ST fails, the creature touched is immobilised for 2d6 rounds because of the negative energy that pervades its muscles, and its body begins to emit the stench of decaying flesh. This effect causes to all those that come closer than 10 feet and that fail the ST vs. Spells a strongish nausea, which translates into a –1 penalty to all Attack Rolls, skill and characteristic checks, as long as the individual remains within the area of the stench. Undead and constructs are completely immune to this spell.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 44", "school": "Necromancy", "isCustom": false},
    "imm_globe_of_invulnerability": {"id": "imm_globe_of_invulnerability", "name": "Globe of Invulnerability", "level": 6, "casterType": "immortal", "range": "0", "duration": "1 round per level", "effect": "Globe protects from 1st to 4th-level spells", "area": "10-foot radius sphere", "description": "This spell created around the spellcaster a 10 feet radius, immobile sphere that emits a weak light and that excludes the effects of any arcane or divine spell of 1st-4th level that is cast against anyone inside it. The excluded effects include the magical abilities of items, but not the magical powers of monsters or creatures unless they are derived from the fact that it is also a spellcaster (for example, it doesn’t block a vampire’s charm, but if that vampire is a mage and casts a fireball, this has no effect on those within the globe). Spells of 5th level or higher are not affected, and a simple dispel magic cast specifically on the globe is however able to dismiss the barrier, which otherwise lasts for 1 round per mage level. Any type of spell can be cast from inside to outside the globe, and anyone can leave and re-enter it without impediment. Note that the spells aren’t dispelled, but only suppressed if their area of effect overlaps that of the globe. For example, the creatures inside the globe could see a mage’s illusionary images created outside the sphere, but if they enter the globe, they vanish to reappear the moment the leave the spell’s area of effect.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 141", "school": "Abjuration", "isCustom": false},
    "imm_glyph_of_warding": {"id": "imm_glyph_of_warding", "name": "Glyph of Warding", "level": 4, "casterType": "immortal", "range": "Touch", "duration": "Permanent until activated", "effect": "Create a protective rune on an item", "area": "An object", "description": "This spell allows the spellcaster to draw a magic symbol (a rune) on an object to protect it. The objects on which the rune can appear are writings, drawers, doors, and any other object that can be opened or forced (so a jewellery box, trapdoor, or flask are possible targets). The object cannot have dimensions greater than a maximum of 10×10×10 feet, and no more than one glyph of warding can appear on the same object. It is never possible to draw a sigil of this type on a living being. When the spell is cast, the mage establishes a magic word or code; when someone tries to open, force, pick, or simply touch the object protected by the rune without speaking the magic word, the glyph of warding triggers, causing an intense detonation that can easily be heard within 240 feet. The destructive sound wave inflicts on all those within a radius of 15 feet from the object 4d6 point of damage + 1 hp per mage level (for example, if the spell was cast by a 12th level mage, the explosion inflicts 4d6+12 points of damage); the victims can make a ST vs. Spells for half damage. The explosion doesn’t damage the object on which the rune was drawn (as it was placed there to protect it) and ends the effect of the rune, which vanishes. Detect magic or trueseeing allow the easy detection of the rune. A thief searching for traps in the area of interest is able to find it normally and perhaps also realise the thing’s traits (he has a –20% penalty to his attempt), however he isn’t able to neutralise the sigil; a dispel magic spell is necessary to do that. If the protected object is safely opened at distance with telekinesis or knock, the sigil triggers with the related explosion (and detonation).", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 96", "school": "Abjuration", "isCustom": false},
    "imm_grim_reaper": {"id": "imm_grim_reaper", "name": "Grim Reaper", "level": 3, "casterType": "immortal", "range": "0", "duration": "1 round per level", "effect": "Victims believe that the cleric is Death and avoid him, if touched, faint", "area": "Only the cleric", "description": "Once he has cast this spell, the spellcaster assumes the semblance of Death incarnate: a skeleton wrapped in a shroud armed with a large scythe. The appearance is purely illusionary and doesn’t affect the cleric’s abilities or equipment in the slightest: simply each time that he attacks with his own weapon it looks like an attack with the scythe. Anyone observing the reaper is called to make a ST vs. Mental Spells: those that fail are assaulted by a atavistic terror that prevents them from attacking it in any way and that forces them to keep their distance from the reaper, such that if they stay within 30 feet of the cleric all their Attacks and ST are penalised by 1 point. Moreover, any victim struck by the reaper believes that he has been killed and falls in a comatose state for 1d6 rounds minus his Wisdom bonus (min. 1 round), after which the victim awakes and understands that he had been hallucinating; during his comatose state, the victim is defenceless. Those who make their ST are very disturbed by the cleric’s appearance and have a –1 penalty to all their attacks against him (Attack Roll and damage) and to their ST to avoid any effect produced by the priest.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 62", "isCustom": false},
    "imm_guardian_seal": {"id": "imm_guardian_seal", "name": "Guardian Seal", "level": 5, "casterType": "immortal", "range": "Touch", "duration": "Special", "effect": "Magic seal explodes if tampered with and causes 1d6 hp per level (max 20d6) in a (max) 40 feet radius", "area": "An object that can be opened", "description": "This spell can be cast on any inanimate object that can be opened (like a coffer, door, casket, etc.) whose volume is less than 3,000 ft³ and that doesn’t already have a glyph, rune, or seal on itself. To cast the spell the cleric draws a magic seal (visible or invisible, his choice) on the object: this operation requires 6 hours and uses alchemical components and precious metals for a total expense of 2,500 g.p., but once completed the seal ast forever or until triggered. The cleric is the only one who can open the object risk free, but if he wants, he can select a password that allows anyone to open the object without danger. If an unauthorised person attempts to open the object, the guardian seal activates with devastating effect (which however doesn’t damage the object): a shockwave of magic energy is violently thrust within a 40 feet radius around the object (the caster selects the amplitude of the wave when creating the seal), inflicting to the victims 1d6 points of damage per cleric level (maximum 20d6). The victim must make a ST vs. Spells: if successful, the damage is halved and he is stunned for 1d10 rounds (only living beings can be stunned); if the ST fails, the victim suffers full damage and enters a stated of suspended animation for 1 day per priest level. Creatures in suspended animation don’t need to eat or breathe, doesn’t age and is unaware, but are vulnerable to any threat (can be killed with a single blow); the victims can be returned to normality with dispel magic or heal. A thief searching for traps has a –50% penalty to his roll to find the seal, but not to neutralise it. The seal can only be removed by activating it or with dispel magic or disjunction; in this case however the failure chance is twice normal and never less than 10% (even if whoever casts the spell is of higher level than the seal’s creator).", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 76", "isCustom": false},
    "imm_gust_of_wind": {"id": "imm_gust_of_wind", "name": "Gust of Wind", "level": 2, "casterType": "immortal", "range": "0", "duration": "Instantaneous", "effect": "Gust of wind hampers movement and blinds", "area": "60 foot wide and long wave", "description": "This spell creates a very strong wind (37½ mph) that leaves the mage’s location in a direction chosen by him as a 60 feet wide and long wave that lifts dust or sand, pushes gas and leaves, and can uproot or turn over tents and items that aren’t well fixed down that find themselves in its path. The wind automatically extinguishes all candles, torches, and similar unprotected small flames, while protected flames have a 50% chance of being extinguished. Moreover, all the creatures that encounter it on its journey must make a ST vs. Paralysis to not be blinded for 1 round by the dust and detritus, and suffers repercussions based on their size: Small or smaller: it is pushed to the ground and rolls for 2d6x10 feet; if flying it is blown 3d6x10 feet away; in both cases losing 1 hp for every 10 feet fallen. Medium: it falls to the floor and rolls for 1d6x10 feet; if it was flying is forced 2d6x10 feet back; in both cases losing 1 hp for every 10 feet travelled. Large: it falls to the ground if it fails a Dexterity check and suffers 1d4 points of damage; if it was flying it is pushed 6d6 feet back and suffers 1 point of damage for every 10 feet travelled. Huge or bigger: the creature moves at half speed within the area of effect. Note that any being attempting to use a missile or throwing weapon within area of the gust of wind suffers a –6 penalty to its Attack Roll and the damage is automatically reduced to a third.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 61", "school": "Evocation", "isCustom": false},
    "imm_hallucinatory_nightmare": {"id": "imm_hallucinatory_nightmare", "name": "Hallucinatory Nightmare", "level": 7, "casterType": "immortal", "range": "90 feet", "duration": "1d6+1 hours", "effect": "An illusion provokes partially real wounds", "area": "30 foot sided cube", "description": "Via this spell, the mage creates a powerful version of phantasmal force by reaching into the dimension of nightmares and shadow to materialise the fears of the victims. When the spell is cast, all those in the area of effect see indistinct, floating apparitions form from shadow and emanate an aura of atavistic terror. There is always a spectral figure for each victim, and it just exclusively concentrates on its own target and is uninterested in the others, until the victim succumbs or flees the area of the nightmare, in which case its specific manifestation vanishes. The spectres take the semblance of what each victim fears the most, and only they see it in this way. Each shadow attacks its own target with the mage’s THAC0, and if successful causes 1d10 points of damage. If the victim dies because of this damage, after 1d10 turns it must make a ST vs. Mental Spells: if successful, it awakes with 1d10 less hp (minimum 1 hp) and knows it was the victim of an illusion; otherwise, it indeed suffers half of the hp caused by the nightmare when it awakes. If the hallucinatory nightmare is still active when the victim awakes, it understands that it is a simple illusion if it made its ST and becomes immune to the effects of that spell, otherwise it is convinced that the shadow can indeed harm it, and continues to apply the conditions listed above. The hallucinatory nightmare not only functions against any victims present in its area of effect when the spell is cast, but also against any creatures with a minimum Intelligence (at least 3 points, so animals and oozes are excluded) that enter its field until it ends. The moment a victim leaves the spell’s area of effect, it stops tormenting him, although it resumes if he re-enters the area. The nightmare can be magically dispelled with the normal chances, and also acts on blind creatures by stimulating the other senses (taste, hearing, and smell).", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 157", "school": "Illusion", "isCustom": false},
    "imm_hand_of_atzanteotl": {"id": "imm_hand_of_atzanteotl", "name": "Hand of Atzanteotl", "level": 3, "casterType": "immortal", "range": "Touch", "duration": "Special", "effect": "Causes 2d6+2 hp and coma", "area": "One creature", "description": "While uttering this spell, the cleric must touch the target, and this suffers 2d6+2 points of damage or 30% of its current hp (apply the most unfavourable condition). To touch the victim requires an attack with his holy symbol, but the victim’s AC ignores his armour, only bonuses from shield, Dexterity, magic, and weapon mastery apply. If the damage from this spell causes the victim’s death (taking him to below 0 Hit Points), in reality the victim doesn’t die, but remains a comatose state in which he cannot act or think (remain immobile, unaware of anything happening around him, with 0 Hit Points), until a curative spell returns him to life (with at least 1 Hit Point) or until his hp frop below –6, which causes his death. This spell is used to paralyse the sacrificial victims for use in the bloody rituals of Atzanteotl, who continue to suffer until the damage causes his martyrdom.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 62", "isCustom": false},
    "imm_hate": {"id": "imm_hate", "name": "Hate", "level": 3, "casterType": "immortal", "range": "120 feet", "duration": "1 round per cleric level", "effect": "A creature becomes crazy and violent", "area": "One living creature", "description": "The victim of this spell must make a ST vs. Mental Spells with a –2 penalty: if the ST fails, he is invaded by a fierce and irrational hate to all those that surround him, and begins to attack friend and foe alike in the most lethal way possible (also using spells and magic items, if possible). The victim of hate always attacks the creature closest to him (roll a dice if two or more targets are at the same distance) and continues to attack it until it is killed, and then moved to the next closest; if there are no monsters or characters around, the victim begins to smash objects and structures, screaming and cursing, until the spell’s end. When under the effects of hate a creature is disinterested in his own health, and never tries to cure himself or flee.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 63", "isCustom": false},
    "imm_heal": {"id": "imm_heal", "name": "Heal", "level": 8, "casterType": "immortal", "range": "Touch", "duration": "Permanent", "effect": "The cleric gives a creature 90% of its hp total; reverse takes the victim to 10% of his hp total", "area": "One creature", "description": "Thanks to this powerful curative spell, the individual on which the cleric places his hands instantly recovers a great part of his vigour and lost Hit Points, returning to 90% of his total hp. Moreover, it can also be used to cure one (and only one) of the following maladies (either magical or normal): a poisoning, a disease, a mental disturbance, blindness, deafness, paralysis, or stun. If an individual suffers from more than one malady, the spell must be cast more than once to heal him. If it is used on an individual that has been returned from the dead, it eliminates the need for two weeks rest, rendering him immediately ready for action. If it is used on a subject with reduced characteristic points, it immediately returns all temporarily lost points, but not those permanently lost characteristics. Finally, if used against an undead (requiring an Attack Roll without taking its armour into consideration), heal takes the creature to 10% of its total hp, unless the creature makes a successful ST vs. Death Ray, in which case it current hp are halved. The reverse spell, harm, causes the touched living creature blood loss and a sudden disintegration of tissues and internal organs, which takes the victim to 10% of its total hp, unless it makes a successful ST vs. Death Ray, in which case his current hp are halved. If used on an undead creature, wound acts as a heal, returning the undead to 90& of its hp total. To touch the victim requires an attck with the cleric’s holy symbol, but the victim’s AC is calculated without taking his armour into consideration, only bonuses derived from its shield, Dexterity, magic, and weapon mastery are taken into account.\nReversible.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 40", "isCustom": false},
    "imm_heatstroke": {"id": "imm_heatstroke", "name": "Heatstroke", "level": 4, "casterType": "immortal", "range": "120 feet", "duration": "Special", "effect": "Cause heat stroke in 1d4 victims", "area": "1d4 living beings", "description": "This spell causes an alteration in body temperature similar to sunstroke in 1d4 living being within 120 feet of the cleric. The victims must make a ST vs. Death Ray: if successful, the subjects are stunned for 1 round and suffer 2d6 points of damage. If instead the ST fails, the consequences depend on the margin of dice roll’s failure in respect to the result needed (all the effects are cumulative in order of seriousness): Margin Consequence 1-2 Sunstroke 3-4 Delirium 5-6 Sunburn 7+ Faint Critical Fatal Stroke Sunstroke: –1 to AC, Attacks, and Initiative by the fatigue and stunned per 1 round. Delirium: loss of 2 points of Intelligence and Wisdom and –2 to characteristic checks due to the delirium. Sunburn: sores and burns split the subject’s skin who loses 6d6 Hit Points. Faint: the character faints for 1d4 hours. Can recover earlier if given water in concert with a Heal check at –4. Fatal stroke: with a natural ST of 1 an apopletic stroke occurs that cause his death. If one of the two mental characteristics (Intelligence and Wisdom) is reduced to zero, the character becomes crazy, fleeing at maximum speed until he collapsed from exhaustion, and probably dies unable to help himself. A healing spell can recover the lost hit points and annul the penalty, while every hour in which he rests in the cool shade removes the sunstroke penalty and recovers 11 point in each characteristice and 1d4 hp of those lost due to the heat sroke.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 67", "isCustom": false},
    "imm_heroism": {"id": "imm_heroism", "name": "Heroism", "level": 7, "casterType": "immortal", "range": "240 feet", "duration": "1 turn per level", "effect": "Improve the HD/Lev of the affected creatures", "area": "1 creature per level", "description": "This potent spell only affects demihumans, humans, and humanoids that aren’t spellcasters (i.e. cannot cast arcane or divine spells). It allows up to 1 creature per mage level to gain additional levels and/or Hit Dice based on their normal level, provided that they are within 240 feet and visible when the mage casts the spell. Multiple applications of this spell on the same subjects have no effect (the benefits aren’t cumulative). For the spell’s duration (or until it is magically dispelled), the affected creatures gain Hit Dice (and the corresponding Hit Points), improving their THAC0 and level based abilities, as if they were one or two levels higher than their normal level (see table 2.11). Damage suffered by creatures affected by this spell are subtracted first from the magically gained Hit Points; a similar thing happens if the creatures are subjected to level drain. TABLE 2.11: EFFECTS OF HEROISM Creature Level Heroism Effect Normal Man Become 4th-level Fighter Level (HD) 1-3 Gain 3 levels or HD Level (HD) 4-7 Gain 2 levels or HD Level (HD) 8-10 Gain 1 level or HD Level (HD) 11+ No effect", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 158", "school": "Transmutation", "isCustom": false},
    "imm_hide_tracks": {"id": "imm_hide_tracks", "name": "Hide Tracks", "level": 1, "casterType": "immortal", "range": "", "duration": "", "effect": "", "description": "Granted by an Immortal in the Tome of the Magic of Mystara Vol. 2 (Divine Magic), Appendix \"Additional spells of each Immortal\". The provided books (Tome Vol. 1-2, Rules Cyclopedia) do not describe this spell; ask your DM or use your own source.", "source": "Tome of the Magic of Mystara Vol. 2, Appendix (no description)", "isCustom": false},
    "imm_hideous_laughter": {"id": "imm_hideous_laughter", "name": "Hideous Laughter", "level": 2, "casterType": "immortal", "range": "60 feet", "duration": "1 round per level", "effect": "Make a victim laugh until its sides ache", "area": "A creature", "description": "This strange spell is able to make the victim bend in two due to his laughter, rendering him totally unable to act or do anything until he collects himself. When the spellcaster casts this spell in the victim’s direction, he must make strange gestures and pull faces while reciting the formula, at the end of which the target must make a successful ST vs. Mental Spells with a –2 penalty: if it fails, he is suddenly struck by an attack of hysterical laughter that makes him literally fold in two, rendering him incapable of doing anything (impossible to move, attack, concentrate, or speak clearly). The effect lasts a maximum of one round per spellcaster level, but at the end of each round the victim can attempt a new ST to free himself from the spell’s effects; however, even if the ST succeeds, he needs another round to totally collect himself and get his breath back. This effect cannot be made permanent.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 61", "school": "Enchantment", "isCustom": false},
    "imm_hivemind": {"id": "imm_hivemind", "name": "Hivemind", "level": 7, "casterType": "immortal", "range": "", "duration": "", "effect": "", "description": "Granted by an Immortal in the Tome of the Magic of Mystara Vol. 2 (Divine Magic), Appendix \"Additional spells of each Immortal\". The provided books (Tome Vol. 1-2, Rules Cyclopedia) do not describe this spell; ask your DM or use your own source.", "source": "Tome of the Magic of Mystara Vol. 2, Appendix (no description)", "isCustom": false},
    "imm_hold_undead": {"id": "imm_hold_undead", "name": "Hold Undead", "level": 5, "casterType": "immortal", "range": "120 feet", "duration": "1 round per level", "effect": "Hold an undead or all those within a 30 feet diameter sphere", "area": "30-foot diameter sphere", "description": "This spell is able to hold undead in an apparently similar way to how hold monsters paralyses living creatures. In reality, the principal magic that forms the spell’s basis is completely different: it interferes with the field of negative energy (entropic) that feeds the undead; therefore, it only works on undead and has no effect on living creatures or constructs. The spell can be cast in a 30 feet diameter sphere or directly against a single undead. In the first case all (and only) the undead that are in the area can make a ST vs. Spells to avoid the effects; in the second case only the chosen victim must make the ST, but with a –4 penalty. The undead that fail the ST are paralysed for the given duration (if it was flying it falls to the earth, unless it is incorporeal, in which case it levitates in midair); undead with 2 HD or less aren’t allowed a ST (they are automatically paralysed). As long as they remain immobilised, the undead cannot use any of their powers and are in a catatonic state, incapable of perceiving anything that happens around them.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 118", "school": "Necromancy", "isCustom": false},
    "imm_holy_power": {"id": "imm_holy_power", "name": "Holy Power", "level": 6, "casterType": "immortal", "range": "0", "duration": "24 hours", "effect": "The cleric obtains 1 extra spell of 1st, 2nd, and 3rd level, and can be easily turn undead", "area": "Only the cleric", "description": "While this spell is in effect, it must be cast by the cleric at dusk, before sleeping, and the following morning, the cleric must dedicate himself to meditating for an hour more than usual. If all these conditions are met, the cleric is able to memorise three extra spells (in addition to the standard ones): one of 1st, one of 2nd, and one of 3rd level; the extra spells remain memorised for the remaining 24 hours or until cast. Moreover, for the whole day (24 hours), he has a +1 bonus to any dice rolls to control or turn undead, including those to determine the number of creatures turned, destroyed, or controlled. Note that two holy power spells aren’t in any way cumulative: since for the second to have effect, the effects of the first must be terminated.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 41", "isCustom": false},
    "imm_home_help": {"id": "imm_home_help", "name": "Home Help", "level": 1, "casterType": "immortal", "range": "10 feet", "duration": "Permanent", "effect": "Varies (see description)", "area": "Varies according to effect", "description": "This spell gathers together a series of magic cantrips conceived to aid domestic matters and make the person’s life more comfortable (indeed minor magic items are often made that reproduce these powers). Each time that he casts this spell, the spellcaster must select which of the following different effects it produces: Clean: this spell is normally used to instantly clean and tidy a room. Once cast on an area of 1,000 cubic feet, it removes the dust, sweeps floors and walls of dirt, removes cobwebs, and put in their right place all the furniture and furnishings, to leave the area perfectly tidy. Naturally, the area remains clean and tidy until someone untidies or soils it, and will surely fill up with dust and cobwebs if it is left to itself (the spell doesn’t permanently protect from these effects). If instead it is cast on a person, it instantly cleans the individual and his clothing of any type of dirt (excluding magic effects) and of skin parasites (non-magic) present; it can also be cast on a single item of clothing with the same effect. Cook: this spell allows the perfect preparation of a complete meal for 1 person per spellcaster level. There must be enough ingredients available within 30 feet to prepare the dishes, and the spellcaster must know the recipe that he wants to prepare, for the spell to have effect. If he doesn’t have the Domestic arts general skill, he must make an Intelligence check with a –4 penalty to perfectly prepare the food, otherwise he succeeds in only cooking enough for half the people (1 individual every 2 levels), whilst consuming all the ingredients. Cut: this spell permits the instant cutting of a specific item in the way that he wants and its application ends the moment in which the cut is executed. It can be used to cut cloth into a certain form, or to cut rope and leather, or to slice cold meat or vegetables, or on other materials that are normally cutable with a sharp knife. If cast on a living being, it only causes 1 point of damage via a small injury (no ST allowed). Dry: this spell dries 3 cubic feet of matter per spellcaster level within 10 feet. This spell has no other applications. Erase: this spell erases up to 100 words per spellcaster level without damaging the document on which they are written, but cannot be used to erase magical writing or runes. Iron: this spell affects a mass of 20 lb. (200 cn) of cloth or clothing, and immediately irons it and removes any wrinkles. Knot: this effect knots together any fibre within 10 feet that is already in contact with another, with permanent effect. It is usually used to tie string and rope, or to form braids in hair that remains intact for 4 months. Mend: this spell instantly and invisibly repairs a cut, as long as the two ends or parts of the cut item are present. It has no effect if cast on a living or animated creature. Purify: this spell only affects dirty or impure liquids, making them potable as long as no new external agent enters the container. It can purify up to two pints per level, which must be in one container within 10 feet. This effect can also remove any non-magical poison present in the liquid. Sterilise: the spell can be applied on a single item (either a bandage or a garment), on food, or on a wound to destroy any germs or bacteria present there, removing the chance of an infection. It is very useful for treating infected wounds, as well as to clean fruit and other food before eating it. It doesn’t remove any poisons present, only bacteria and microbes. The treated item remains sterile for 24 hours before being vulnerable to the possible presence of germs again. Wash: this simply spell instantly washes a volume of matter of 3 feet cube per spellcaster level, removing normal dirt. It has no effect on marks, writing, or runes (magical or not), if it cannot moisten the surface on which they had been placed; if it is in a scroll or similar, the writing can be erased (only if it isn’t magic). Untie: the spell instantly unties knotted fibres. It can be used to untie a knot, unravel a tangle or a hairdo. Write: Via this spell, the spellcaster can quickly write on a material (scroll, paper, papyrus, vellum, or even a stone slab). The spellcaster must simply think of the phrases he wishes written, and touch the surface on which he wants it done, and it immediately appears and becomes permanent (it cannot be magically dispelled except through the reverse of this spell). The spell can write messages of up to 500 words per level with each application. This spell however cannot create magic writing, only normal (also encoded).", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 45", "school": "Transmutation", "isCustom": false},
    "imm_honesty": {"id": "imm_honesty", "name": "Honesty", "level": 3, "casterType": "immortal", "range": "Touch", "duration": "Special (see below)", "effect": "Impose honesty on a living creature", "area": "One creature", "description": "Any creature that swears to do a certain action or proclaim a certain assertion as true after being placed under this spell, is cursed if he doesn’t keep his word or the assertion proves false. The DM is the only one who can judge if the action has been completed in an acceptable way or if the assertion is truthful. The followers of the cleric’s faith aren’t allowed a Saving Throw to counter this spell, while the infidels can make a ST vs. Spells with a –4 penalty to try to avoid the curse. The DM establishes the nature and duration of the curse; usually using the words of the oath for inspiration. For example, if a character said: “May Al-Kalim strike me with lightning if I don’t do this or that”, the cursed character could be struck by lightning during the next storm, or killed by a fighter of Al-Kalim during a fight in another adventure, or Al-Kalim could appear without warning and demolish the character with a spell. Make it so that the curse is proportionate to the severity of the crime, and make sure that the moment the curse’s effect have effect when the observers can know that is a judgement of the character’s infidelity to his oath.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 63", "isCustom": false},
    "imm_hunting_paint": {"id": "imm_hunting_paint", "name": "Hunting Paint", "level": 2, "casterType": "immortal", "range": "Touch", "duration": "24 hours", "effect": "Gives a +2 bonus to Attack Rolls, damage, Saving", "area": "An individual", "description": "Throws, or AC This spell can be cast on any type of pigment, dye, or other colouring substance, which are instantly transmuted into magical colours that can then be applied on the face of a character before a fight or hunt. The exact effects of the colours is determined by the cleric (see below), but must be declared at the moment of casting. Hunting colours can give the character a +2 bonus to Attack Rolls, damage, Saving Throws, or to Armour Class, and lasts for 24 hours, or until it is washed off. It isn’t possible to add the effects of this spell with those of an analogous spell (e.g. bless and warpaint). The application of the colour to the face requires 2 rounds and must be done by the cleric who cast the spell.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 56", "isCustom": false},
    "imm_hypothermia": {"id": "imm_hypothermia", "name": "Hypothermia", "level": 4, "casterType": "immortal", "range": "120 feet", "duration": "Special", "effect": "Cause hypothermia in 1d4 victims", "area": "1d4 living beings", "description": "This spell causes a sudden lowering of the body temperature in 1d4 living beings present within 120 feet of the cleric. The victims are called to make a ST vs. Death Ray: if successful, the subjects remain stunned per 1 round and suffer 1d6 points of damage. If instead the ST fails, the consequences depend on the margin of dice roll’s failure in respect to the result needed (all the effects are cumulative in order of seriousness): Margin Consequence 1-2 Frostbite 3-4 Delirium 5-6 Freezing 7+ Faint Critical Fatal hypothermia Frostbite: –1 to AC, Attacks, and Initiative for the stiffness and stunned per 1 round. Delirium: loss of 2 points of Intelligence and Wisdom and –2 to characteristic checks due to the delirium. Freezing: loss of 3 Dexterity points and 3d6 hp due to the freezing of a limb (roll 1d4: 1 left arm, 2 right arm, 3 left leg, 4 right leg) that becomes unusable (impossible to run if a leg). Faint: the character faints for 1d4 hours. Can recover earlier if warmed in concert with a Heal check at –4. Fatal hypothermia: with a natural ST of 1 crushing hypothermia occurs that causes his death. If one of the two mental characteristics (Intelligence and Wisdom) is reduced to zero, the character becomes crazy, fleeing at maximum speed until he collapsed from exhaustion, and probably dies unable to help himself. A healing spell can recover the lost hit points and annul the penalty, while every hour in which he rests in the warmth removes the frostbite penalty and recovers 11 point in each characteristice and 1d4 hp of those lost due to the hypothermia.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 68", "isCustom": false},
    "imm_ice_spear": {"id": "imm_ice_spear", "name": "Ice Spear", "level": 4, "casterType": "immortal", "range": "180 feet", "duration": "Instantaneous", "effect": "Ice spear that does 1d6 damage per level", "area": "Multiple targets", "description": "The spell creates a 10-foot long spear of ice above the mage who directs it (in a straight line) at a visible target from 20 to 180 feet away. The spear causes 1d6 points of damage per spellcaster level (halved with a ST vs. Spells) to the victims that it strikes along its path. Reaching the final target the spear explodes and the splinters cause the above damage reduced by 1 dice for each victim hit along the way to all the creatures within a 10 feet radius sphere (ST vs. Spell for half). Cold-based beings (like frost giants) and undead automatically suffer half damage, and can reduce it to a ¼ with a successful ST. Example: a 10th-level mage throws the spear at a red dragon and hits two orcs along the way. The orcs suffer 10d6 hp and when it impacts on the dragon the explosion causes 8d6 hp to everything within 10 feet (dragon included); all the victims can halve the damage with a successful ST vs. Spells.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 97", "school": "Evocation", "isCustom": false},
    "imm_icy_torment": {"id": "imm_icy_torment", "name": "Icy Torment", "level": 5, "casterType": "immortal", "range": "", "duration": "", "effect": "", "description": "Granted by an Immortal in the Tome of the Magic of Mystara Vol. 2 (Divine Magic), Appendix \"Additional spells of each Immortal\". The provided books (Tome Vol. 1-2, Rules Cyclopedia) do not describe this spell; ask your DM or use your own source.", "source": "Tome of the Magic of Mystara Vol. 2, Appendix (no description)", "isCustom": false},
    "imm_identify_species": {"id": "imm_identify_species", "name": "Identify Species", "level": 3, "casterType": "immortal", "range": "10 feet per level", "duration": "1 round per level", "effect": "Identify the species of 1 creature per level", "area": "A creature", "description": "With this spell, the spellcaster can determine the race and species of a specific creature within range. He can only analyse on creature per round until the end of the spell’s duration (whilst concentrating on the creature, he can do nothing else except move up to half speed), and if the creature fails a ST vs. Spells, the spellcaster knows with certainty its true race and species. The spell is effective against any type of magic disguise (like disguise) or transmutation (like polymorph), but is fooled by the natural shapechanging of polymars and aranea (as they invented the spell). The spell is useful for detecting shapechangers or magically transformed creatures, or identifying unknown monsters or victims of spells of mutation.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 80", "school": "Divination", "isCustom": false},
    "imm_impassable_defence": {"id": "imm_impassable_defence", "name": "Impassable Defence", "level": 4, "casterType": "immortal", "range": "0", "duration": "3 turns", "effect": "Magic circle in which the cleric gains a +3 bonus to AC and ST (or +5 if he concentrates)", "area": "10 feet diameter circle", "description": "When casting this spell, the cleric traces at his feet a 10 feet diameter magic circle. As long as he remains within that restricted area, the spellcaster constitutes an effective bastion capable of sustaining his enemies’ attacks: he in fact gains a +3 bonus to AC and all Saving Throws, and if he declares at the start of the round that he is concentrating on the circle (without doing any other action, or movement, for the entire round) the spell grants him a +5 bonus to AC and ST (instead of +3) until the beginning of the next round. If the cleric is in his homeland (and has drawn the circle on his native soil) he gains, as well as the above effects, 3 points of damage resistance against all attacks, as long as he remains within the circle (this means that each single attack against the spellcaster inflicts 3 Hit Points less, even annulling the effective damage). This spell can be magically dispelled by casting dispel magic on the magic circle (and not on the spellcaster), or by covering the circle with a layer of rock or stone at least 12 inches thick (attempts to hide the circle with a few inches of sand, a carpet, or anything similar is totally ineffective).", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 68", "isCustom": false},
    "imm_improved_invisibility": {"id": "imm_improved_invisibility", "name": "Improved Invisibility", "level": 4, "casterType": "immortal", "range": "Touch", "duration": "1d6 turns", "effect": "A creature becomes invisible", "area": "A creature", "description": "Thanks to this spell, the subject touched (to a maximum of Large size) immediately becomes invisible to all creatures. The individual becomes visible if he attacks someone, uses magic, or is hurt in some way, but as for long as the spell lasts, he can become invisible again by concentrating for a round (like casting a spell). At the end of the effect (or if it is magically dispelled), the subject becomes visible. Those under the effect of this spell can make themselves visible when they wish, and can be detected by see invisible, second sight, and trueseeing. This effect cannot be made permanent.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 98", "school": "Illusion", "isCustom": false},
    "imm_insatiable_hunger": {"id": "imm_insatiable_hunger", "name": "Insatiable Hunger", "level": 4, "casterType": "immortal", "range": "30 feet", "duration": "1 day (24 hours) per level", "effect": "Make a victim eternally hungry", "area": "One living creature", "description": "The victim of this terrible spell can longer gain sustenance from food while this curse lasts (1 day per cleric level); naturally it is possible to completely ignore the effects of insatiable hunger with a successful ST vs. Spells. However, if the ST fails, despite the amount of food engested daily, the victim will feel more and more hungry and desperate, and if the spell is annulled with a remove curse, he will waste away and die. Based on the period of time that he spends gripped by hunger pangs, the victim suffers various penalties: • 2nd day: after the first, the victim becomes distracted (–2 penalty to all skill checks); • 8th day: after the first week of hardship, the victim feels weakened, and from this moment each day alternatively loses 1 point of Strength and 1 point of Constitution. When one of these two characteristics drops to 3 the individual enters a coma, and at zero dies of starvation. If he is cured in time or is able to resist until the end of the spell (has more Strength and Constitution points than the spell’s duration), the victim recovers 1 point of Strength and Consitution each day he rests and is fed. It is also possible to annul the spell naturally, without needing a remove curse: if the victim finds the type of food that the cleric secretly whispered while casting the spell and eats it, the spell is broken. The food selected by the cleric (and kept secret) must be a natural food, common (like rice, lamb, honey, fish, etc.) or exotic (like the meat of a particular monster or animal, but not an alcemical compound), that the priest has tasted before. This spell cannot be added to any magic item.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 68", "isCustom": false},
    "imm_insect_swarm": {"id": "imm_insect_swarm", "name": "Insect Swarm", "level": 4, "casterType": "immortal", "range": "480 feet", "duration": "1 minute per level", "effect": "Create a 30’ radius insect swarm", "area": "30’ radius sphere of insects", "description": "When the druid casts this spell, it materialises a swarm of crawling, jumping, and flying insects that moves at his command at 60 feet per round, without he needing to concentrate. The insects limit visibility to 10 feet within the area they occupy (a 30 feet radius volume), casting spells within the swarm is impossible and any attack receives a –1 penalty to the Attack Roll because of the annoyance. Living creatures within the swarm moreover suffer 1 point of damage they remain there, regardless of their AC, because of the insects’ stings and bites. Creatures with 2 HD or less flee from the swarm as quickly as possible for 1 minute, and those that have 3-5 HD have the impulse to flee, although a successful ST vs. Mental Spells allows them to resist it. A wind of at least 25 mph or a destructive fire effect at least half as wide as the swarm sweeps the insects away ending the spell, which can be magically dispelled or dissipated by the druid’s before the end of its duration.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 123", "druidSpell": true, "isCustom": false},
    "imm_interdiction_of_the_tomb": {"id": "imm_interdiction_of_the_tomb", "name": "Interdiction of the Tomb", "level": 7, "casterType": "immortal", "range": "Touch", "duration": "Permanent", "effect": "Protect a tomb with a curse", "area": "Tomb with 30 feet sides", "description": "This spell allows the priest to protect a tomb with a curse that strikes anyone who violates it. An entire day is needed to cast this spell, during which the cleric must not be interrupted to not annul the ritual. The priest must walk through all the tomb’s rooms, tracing on walls, doors, ceilings, and floors the sigils that activate the curse. In the course of this operation the cleric defines the exact conditions that trigger the curse, which can go from the simple “any creature that enters this tomb” to the more complex “any mortal who disturbs the king’s remains, removes his treasure, or destroys his funeral outfit or sarcophageous”. The exact effect of the curse should correspond where possible to the wording (within the limits placed by the DM), and if vague or unclear passages exist, these will receive the least favourable interpretation for the transgressor. The curse’s effect is equal to that of the divine curse spell (reverse of divine blessing, 7th level clerical spell) and there is no chance of avoiding the effects once activated. Only a wish can remove the curse from a transgressor, or a remove curse uttered by a cleric of Orisis of at least 12th level, after which the transgressor has made amends for his sin. Interdiction of the tomb remains in effect on the tomb until it is removed with a wish, or the tomb is completely destroyed (but this places the curse on the author of the ruin). If the priest can take advantage of the aid of other clerics (who must be of at least 9th level, but don’t necessarily need to know how to cast this spell), it is possible to augment the area of effect’s sides by 10 feet for each assistant (so for example if there are 7 clerics involved, the volume has a side of 90 feet). The ritual requires the priest to leave in the tomb the holy symbols of the clerics involved, often buried in the walls or floor. In place of holy symbol it is also possible to leave a creature of the same race as the priest, which must be buried alive and becomes the spell’s focus. A combination of holy symbols and victims is also acceptable, as long as each priest involved leaves at least one of the two components. This spell cannot be added to a magic item.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 84", "isCustom": false},
    "imm_interposing_hands": {"id": "imm_interposing_hands", "name": "Interposing Hands", "level": 4, "casterType": "immortal", "range": "0", "duration": "1 round per level", "effect": "Hand prevents a being from approaching", "area": "3 foot radius per level", "description": "This spell creates a semi-transparent hand of pure force that is tasked by the mage to protect him against the attacks of a specified being in the area of effect. From that moment, the hand acts independently (the mage can therefore do something else) and it interposes itself between the spellcaster and the subject, preventing the latter from approaching the mage beyond a certain limit from any direction (the hand thus moves with the mage). The maximum distance of approach can be changed by the spellcaster once per round as long as the effect lasts, but obviously, it cannot be greater than the area of effect. The dimensions of the hand can vary from a minimum diameter of 5 feet to a maximum diameter of 25 feet (the size is chosen by the mage at the moment of casting). The hand doesn’t follow the subject out of the area, but each time he tries to enter and approach closer than the specified limit, the hand stops him. The hand only prevents physical contact between the subject and the spellcaster holding the former at distance, but doesn’t prevent the creature from attacking the mage with ranged weapons or spells. Moreover, it doesn’t damage the target creature, not even if it crashes into the hand at full speed (it is abruptly stopped but without damage). The interposing hand isn’t fooled by disguises or transmutation, always recognising the real subject, but cannot impede illusionary forms of the creature (like projected image) that pass beyond it. The hand moreover is also incapable of blocking a subject in gaseous or incorporeal form (evanescence), or its spirit projected from the body (creeping shadow or astral body). If the subject uses a spell of transport (like dimension door or teleport) to approach the mage, the hand immediately materialises in front of the creature and begins to push it away until, after a round, it is at the distance specified by the mage. The interposing hand is able to halt up to 1,800 lb. of weight. Beings of greater weight that forcibly pass through the hand are slowed, reducing their movement by half. It doesn’t however hamper any other creature that tries to pass through it: to all other beings, the hand is visible and transparent but doesn’t constitute an obstacle and can be passed through as if it was air. If the subject associated to the hand is killed before the spell has ended, the mage can select another subject within the area of effect to be protected from, and the hand protects him from the new creature for the remaining duration. The hand can be hit with normal weapons: it has AC 0 and the same Hit Points and ST as the mage, and if it is physically or magically destroyed this ends the spell. The spellcaster can also choose to dismiss the hand before the end of its duration, which ends the spell. The hand vanishes if it encounters an anti-magic field, and if the creature to which it is associated is surrounded by an anti-magic barrier, it isn’t able to obstruct him. There isn’t a limit to the number of interposing hands evocable simultaneously, but each must be bound to a different creature.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 98", "school": "Evocation", "isCustom": false},
    "imm_intuition": {"id": "imm_intuition", "name": "Intuition", "level": 1, "casterType": "immortal", "range": "120 feet", "duration": "1 turn", "effect": "Know intentions and emotions of a being", "area": "A living being", "description": "This spell allows the mage to know the precise and immediate intentions and emotions of a living creature within 120 feet, without it being able to oppose the spell (unless its mind is magically shielded against the reader of the thoughts). The mage can analyse the subject’s intentions for a round by concentrating for a full round: the spell doesn’t reveal the alignment or the precise thoughts of the target, only the current emotions and general intentions (or the predisposition to do a specific action within a short time).", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 46", "school": "Divination", "isCustom": false},
    "imm_invigorating_glyph": {"id": "imm_invigorating_glyph", "name": "Invigorating Glyph", "level": 1, "casterType": "immortal", "range": "Touch", "duration": "1d4 hours", "effect": "Regenerate 1 hp per turn", "area": "A wounded living creature", "description": "This spell can only be cast on a wounded living being (not at his maximum hp total) that the cleric must touch. The spell draws power from the divine spirit to accelerate the organism’s normal healing rate. From the moment the subject is touched a holy glyph appears on his hand that allows him to regenerate 1 Hit Point per turn until the spell ends or is dispelled. The spell allows the reconstruction of missing limbs or pulped organs (requiring at least 24 hours), but isn’y capable of returning the dead to life, and furthermore it doesn’t regenerate wounds caused by fire or acid.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 53", "isCustom": false},
    "imm_invisible_servant": {"id": "imm_invisible_servant", "name": "Invisible Servant", "level": 1, "casterType": "immortal", "range": "30 feet", "duration": "6 turns + 1 turn per level", "effect": "A creature of force completes simple actions", "area": "N/A", "description": "The servant evoked by this spell is a pure magical force without thought, normally used to recover items, open unlocked doors, tidy up and carry out easy tasks. Blindly obeying the spellcaster’s verbal orders, it can only do one thing at a time and, not being very strong, move only relatively light items (it can handle, lift, drag, or push up to 40 lb.). It has no definite form unless its creator gives it one (it however remains a type of spectral creature), it can respond to simple demands, report short messages (Intelligence 9), and it moves by floating and can pass through any crack at a speed of 30 feet per round. The servant cannot fight and is immune to Enchantment. It can be magically dispelled or destroyed by magic effects or enchanted weapons: to this end, the invisible servant has 6 hp and the Saving Throws of a 1stlevel mage.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 47", "school": "Conjuration", "isCustom": false},
    "imm_iron_constitution": {"id": "imm_iron_constitution", "name": "Iron Constitution", "level": 5, "casterType": "immortal", "range": "120 feet", "duration": "6 turns", "effect": "Gain Constitution 18; reverse gain Constitution 3", "area": "A creature", "description": "When this spell is cast on a living creature, its Constitution score immediately becomes 18 for the spell’s duration; it clearly doesn’t have any effect on a creature that already has a Constitution of 18 or higher. All the bonuses (Constitution checks, bonus hit points etc.) are immediately applied. Any injury suffered by the individual are first taken from the extra Hit Points gained with this spell, and then the subject’s real ones. Note that at the spell’s end, the subject must subtract from his hp those that he gained from this spell, only if his hp total is higher than his normal hp value. The reverse of this spell, weariness, reduces the victim’s Constitution to 3 (with all the consequential penalties), if he fails a Saving Throw vs. Spells; range and duration are the same as the normal spell. Neither effect can be combined with permanency.\nReversible.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 119", "school": "Transmutation", "isCustom": false},
    "imm_kiss_of_the_night": {"id": "imm_kiss_of_the_night", "name": "Kiss of the Night", "level": 4, "casterType": "immortal", "range": "Touch", "duration": "From sunset to dawn", "effect": "+10% to thief skills, +2 to AC and ST, +2 to a characteristic score and +2 to skill checks", "area": "One creature", "description": "This spell can be cast only between sunset and dawn (otherwise it is ineffective) and lasts for all the night (or to a maximum of 12 hours, if the night is longer), disappearing at sunrise. Even if the priest is underground and doesn’t know if outside it is day or night, the spell remains however bound to the phases of the day, and doesn’t work at all during daylight hours. Kiss of the night grants to the designated subject a large number of advantages: a +10% bonus to all thief skills, a +2 to all general skill checks, and a +2 bonus to ST and AC. Finally, he also benefits from a +2 bonus to a characteristic of his choice (e.g. Strength, Dexterity, etc.). This spell can be annulled by casting dispel magic on the subject: independently of the difference between levels, however, there is always at least a 10% failure chance.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 69", "isCustom": false},
    "imm_lethal_arrow_of_mealiden": {"id": "imm_lethal_arrow_of_mealiden", "name": "Lethal Arrow of Mealiden", "level": 4, "casterType": "immortal", "range": "Touch", "duration": "Special", "effect": "An arrow gains a +3 bonus to Attacks and damage and can kill the enemy with a single hit", "area": "An arrow", "description": "This spell is only effective on a normal or magic arrow: once enchanted, the arrow remains so until it is fired, or a maximum of 1 hour per cleric level. Firstly, the arrow gains a +3 magic bonus to attack and damage, cumulative with any pre-existing bonuses up to a maximum of +5 (e.g. a +1 arrow becomes +4, but a +3 arrow would only become +5, as this limit cannot be surpassed). When the arrow is fired (normal Attack, modified by the additional bonus from the spell), if it hits look up the result in the following list to determine the injury inflicted:  Natural Roll: between 2 & 15. The arrow has struck the target inflicting normal damage.  Natural Roll: between 16 & 19. The arrow has struck the target in a particularly vulnerable point: the damage inflicted is the maximum possible, and is always a critical (if using the critical hit rules).  Natural Roll: 20. The arrow has struck the target in a lethal way, piercing the heart or brain, or any other vital organ: the target dies from the blow if he fails a ST vs. Death Ray; in the case of a successful ST, the damage inflicted is double the maximum possible and is treated as a critical. Example: an archer armed with a +4 long bow (a weapon in which he is a Master) nocks a +2 arrow with this spell (which becomes a +5 arrow), and fires it at a dragon. The Attack Roll is a natural 16: the arrow inflicts 27 hit points (the maximum possible with 3d6+9) and rolls on the table of critical wounds.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 69", "isCustom": false},
    "imm_levitation": {"id": "imm_levitation", "name": "Levitation", "level": 2, "casterType": "immortal", "range": "Touch", "duration": "6 turns + 1 turn per level", "effect": "An individual or object is able to levitate vertically at a speed of 20 feet per round", "area": "A being or object of up to huge size", "description": "This spell allows the touched individual to magically levitate into the air, only moving along the vertical axis, at a speed of 20 feet per round. The spell doesn’t allow sideways movement, to do so requires pressure on a surface or a series of holds (like the branches of a tree or a ceiling), or is dragged by something or someone (he is susceptible to the push of any being that can move his total weight and winds of 25 mph or higher). If instead he is a place without gravity (for example in space), the individual can orientate himself as he wants and propel himself along his vertical axis, changing in practice direction as he likes. If cast on an unattended item, or on an item whose owner doesn’t oppose the spell (in which case the spell fails), it allows the object to move itself at 20 feet per round vertically (by touch) when a command word decided by the spellcaster is spoken. The spell can affect a creature or item of up to Huge (H) size, whose body weight (excluding equipment) is annulled. The creature or item can support a maximum weight equal to its own and continue to levitate (thus transporting other people or cargo), but if this is exceeded falls to the ground.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 62", "school": "Transmutation", "isCustom": false},
    "imm_lie": {"id": "imm_lie", "name": "Lie", "level": 1, "casterType": "immortal", "range": "0", "duration": "1 turn per level", "effect": "Can lie without being discovered", "area": "Only the spellcaster", "description": "This spell allows the spellcaster to lie, without the lie being discovered by listeners. Any use of the Detect deception general skill is rendered useless by this spell, while if examined with detect lies or ESP, the spellcaster can avoid discovery with a successful ST vs. Spells. Any divination spell of 3rd-level or higher is however able to penetrate this illusion.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 47", "school": "Illusion", "isCustom": false},
    "imm_lightning_reflexes": {"id": "imm_lightning_reflexes", "name": "Lightning Reflexes", "level": 3, "casterType": "immortal", "range": "0", "duration": "1 round per level", "effect": "Avoid surprise and win Initiative for 1 round", "area": "Only the spellcaster", "description": "This spell confers on the spellcaster an unusual quickness of response. In games terms, for the spell’s duration the spellcaster cannot be surprised, and can choose to automatically win the initiative for one round; in this case, however, the spell ends after this power is used, even if the duration hasn’t elapsed. This effect cannot be made permanent.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 81", "school": "Transmutation", "isCustom": false},
    "imm_lightning_strike": {"id": "imm_lightning_strike", "name": "Lightning Strike", "level": 5, "casterType": "immortal", "range": "0", "duration": "Instantaneous", "effect": "Lightning causes 1d6 hp per level in the area", "area": "3 foot per 2 levels radius sphere", "description": "With this spell, the mage’s body is charged with electromagnetic energy and discharges a potent series of lightning bolts on all those (friends and enemies) that are within 3 feet for every 2 spellcaster levels. Only the mage is immune to the discharge, but all the other victims struck by the discharge suffer 1d6 points of damage per level (max 20d6 hp at 20th level), although they can make a ST vs. Spells for half damage. The only variable that the mage can control is the extension of the radius of the lightning strike, which he can vary from a minimum of 3 feet to the maximum allowed by his level.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 119", "school": "Evocation", "isCustom": false},
    "imm_liquid_form": {"id": "imm_liquid_form", "name": "Liquid Form", "level": 3, "casterType": "immortal", "range": "Touch", "duration": "1 turn per level", "effect": "The subject assumes liquid form", "area": "A creature", "description": "This spell transforms forms the touched subject (together with all his equipment) into a 4-pint pool of water, which cannot be absorbed or divided in any way. The form has the subject’s hit points, AC, and ST, can see and hear clearly everything within 30 feet, and moves at 60 feet per round (double in water), climb any surface. As long as he remains in this form, the subject resembles a simple pool of water in every way. He doesn’t drown if immersed in water and can reach any depth desired, but cannot speak, attack, or use worn items. In this form, he can only be injured by magic weapons or spells, damaging himself without however losing body parts or suffering critical hits, and is immune to paralysis, critical hits, and polymorph. The touched subject cannot avoid the transformation, but can return to his normal form when he wants, and at that moment, the spell ends (if the duration hasn’t yet expired).", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 82", "school": "Transmutation", "isCustom": false},
    "imm_locate_creature": {"id": "imm_locate_creature", "name": "Locate Creature", "level": 4, "casterType": "immortal", "range": "0", "duration": "1 turn per level", "effect": "Find a known creature", "area": "300 foot radius + 20 feet per level", "description": "This spell allows the locating of a specific creature (like the smith Fergus) or belonging to a species known to the mage (like a unicorn), but not creatures of a generic type (“a humanoid” or “an animal”), if it is within the area of effect. The spellcaster must have seen the specific subject or a member of the desired species at least once before. If the subject is moving, the spellcaster also knows the direction in which he is moving and can therefore follow him as long as he remains within the spell’s area of effect. This spell isn’t able to locate subjects magically protected from divination spells and remains active for 1 turn per level, without him needing to concentrate to evoke the power. However, it only remains active in regards to the indicated subject, and he cannot thus change species or subject once he has cast the spell. Magically camouflaged creatures are registered by the spell as they belonging to their real species if the camouflage is only illusionary (e.g. disguise self); if instead the transformation is real (e.g. polymorph or polymorph self or the shapechanging ability) the subject sought can avoid discovery by making a ST vs. Spells (the only case in which it is allowed to avoid the detection) the moment that he first enters the spell’s area of effect (the ST result is valid for the spell’s entire duration).", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 98", "school": "Divination", "isCustom": false},
    "imm_locate_species": {"id": "imm_locate_species", "name": "Locate Species", "level": 1, "casterType": "immortal", "range": "0", "duration": "6 turns", "effect": "Detect a creature or plant", "area": "1 mile", "description": "When this spell is cast, the spellcaster can identify the direction in which the closest animals or plants of a specific species are within 1 mile of him when casting the spell. The choice of species is limited by the type of magic school that the spellcaster belongs to: forests (normal elves), seas (marine school), or underground (shadow elves). To successfully detect animals or plants of one of the other two settings, the spellcaster must learn the spell version of the appropriate magic school. The spell doesn’t allow the detection of fantastic creatures, monstrous plants, or intelligent beings, and the spellcaster must specifically nominate the type of animal or plant that he wants to find, and knows in which direction to go in to reach the nearest example up to the end of the spell; if there are no members of the sought for species within the area of effect, the spell doesn’t give any direction. The spell only allows the detection of one type of target: to detect a new species requires a new spell.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 47", "school": "Divination", "isCustom": false},
    "imm_locate_totem": {"id": "imm_locate_totem", "name": "Locate Totem", "level": 2, "casterType": "immortal", "range": "Limitless (same plane)", "duration": "1 hour (6 turns)", "effect": "Reveal an individual’s closest totem", "area": "An animal totem", "description": "This spell can be cast by the cleric only if he knows the totem spirit of the interested person Once cast, it reveals the distance and direction in which the closest example of an animal analogous to the individual’s totemic spirit, and until the spell’s end (after 1 hour), the spellcaster is in a position to say whether it is approaching or moving away. When the spell is cast, the cleric must touch, on the forehead, the individual of who’s totem he wants to locate, and must conetrate on the animal to find it.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 56", "isCustom": false},
    "imm_locate_water": {"id": "imm_locate_water", "name": "Locate Water", "level": 1, "casterType": "immortal", "range": "0", "duration": "2 turns", "effect": "Find the presence of water within 300 feet", "area": "300 feet radius", "description": "This spell allows the cleric to perceive the presence of water in any form within 300 feet, and vaguely guess the amount of water (precisely up to 20 pints, or simply “lots” for over 20 pints). The spell isn’t blocked by elements interfere that normally with divination magic and allows him to distinguish between fresh, salt, and the water present within living creatures.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 54", "isCustom": false},
    "imm_longsight": {"id": "imm_longsight", "name": "Longsight", "level": 1, "casterType": "immortal", "range": "Touch", "duration": "3 turns", "effect": "See clearly a 60 ft. diameter area within 1 mile", "area": "A creature", "description": "This spell allows its beneficiary to be able to see clearly for up to 1 mile as if it was only 10 feet. The subject must select a 60 feet diameter area and focus his attention on it, seeing it as if it was at the end of his nose; once chosen the area cannot be changed.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 48", "school": "Divination", "isCustom": false},
    "imm_longstride": {"id": "imm_longstride", "name": "Longstride", "level": 1, "casterType": "immortal", "range": "Touch", "duration": "1d4+4 hours", "effect": "Doubles a humanoid’s movement", "area": "A humanoid creature", "description": "The spell allows the being on which it was cast to move at double normal (walking) speed for 1d4+4 hours without tiring. Once the spell’s effect has elapsed however, the person on which it was used is forced to rest for the same number of hours; if he doesn’t, the subject temporarily loses 2-8 Constitution (recoverable with complete rest at the rate of 1 point per day, and only on condition that he has adequate rest). The spell only functions on humanoid beings.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 48", "school": "Transmutation", "isCustom": false},
    "imm_lord_of_the_storm": {"id": "imm_lord_of_the_storm", "name": "Lord of the Storm", "level": 7, "casterType": "immortal", "range": "0", "duration": "1 round per level", "effect": "The cleric augments his strength by controlling the power of the storm", "area": "Only the cleric", "description": "With this spell the cleric channels the power of the storm into his body, and so the spell can only be evoked in the open. From the moment he utters the prayer and for all its duration, the sky above him is concealed by dark clouds pierced by thunder and lightning, and in a radius of 1,800 feet ir raises a wind of modest strength (12 mph). The priest must continue to concentrate to canal the power of the storm for 6 rounds, during which he can do nothing else and is wrapped in a cocoon of static energy on which converge innumerable electrical discharges from the clouds. In this process his flesh becomes the colour of bronze and his hair becomes very blond, while his eyes are transformed into two spheres of light, pulsating with blue energy. While the cleric is wrapped in the energetic cocoon, he is immune to any type of spell, and those who attack him directly with a melee attack suffer 6d6 points of electric damage because of the cocoon of energy that protects him. If he is wounded during the evocation, the priest must make a Concentration check, else the ritual ends and the spell is wasted. After gathering for a minute, the power of the spell manifests and the cleric can act normally. From this moment and for an number of rounds equal to his level, the priest benefits from the following powers: • ability to fly at 360 feet per round (MF 5); • his natural Strength score becomes 20; • his body is totally immune to lightning and to electrical damage of any nature; • electric barrier: anyone who hits him with a melee attack is hit by an electrostatic charge that causes 4d6 points of damage (halved with a successful ST vs. Spells); • call lightning: once every six rounds he can summon a lightning bolt of 10 feet diameter from the within 100 feet, it automatically hits a target (two if they are adjacent) causing them damage equal to the amount of hp that the caster has at that precise moment (it is possible to make a ST vs. Dragon Breath for half damage). This spell cannot be made permanent.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 85", "isCustom": false},
    "imm_loving_idyll": {"id": "imm_loving_idyll", "name": "Loving Idyll", "level": 3, "casterType": "immortal", "range": "60 feet", "duration": "24 hours", "effect": "Cause two individuals to fall in love", "area": "Two living creatures", "description": "This spell touches the heart and mind of two living creatures within range to trigger in them a sudden and deep love towards each other (functions with creatures of different races or the same sex, but doesn’t affect plants). Both the victims can attempt a ST vs. Mental Spells to resist, but if one of the two already has a loving feeling or sexual desire towards it automatically fails its ST. Those that don’t resist the eefect are wrapped in a pastionate desire towards the other person, without being able to resist the impulse to show to all their love. Any enamoured individual supports every decision of the object of their desire and tries to stay close by and protect them to the best of their ability for per 24 hours, at the spell’s end the effect vanishes and the victim returns to himself (in full possession of his memories and mental faculties). This type of fascination can only be annulled by dispel magic or anti-enchantment.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 63", "isCustom": false},
    "imm_lower_defences": {"id": "imm_lower_defences", "name": "Lower Defences", "level": 5, "casterType": "immortal", "range": "", "duration": "", "effect": "", "description": "Granted by an Immortal in the Tome of the Magic of Mystara Vol. 2 (Divine Magic), Appendix \"Additional spells of each Immortal\". The provided books (Tome Vol. 1-2, Rules Cyclopedia) do not describe this spell; ask your DM or use your own source.", "source": "Tome of the Magic of Mystara Vol. 2, Appendix (no description)", "isCustom": false},
    "imm_lycanthropy": {"id": "imm_lycanthropy", "name": "Lycanthropy", "level": 4, "casterType": "immortal", "range": "Touch", "duration": "Permanent", "effect": "The victim contracts lycanthropy", "area": "One creature", "description": "The cleric casting the spell must injury the target with weapons, bites, claws, or punches or the spell is wasted. The wounded victim must make a Saving Throw vs. Spells with a penalty equal to the damage inflicted by the cleric or become a lycanthrope of the same type as the cleric or chosen by him (if he isn’t a lycanthrope). If the victim was already wounded by a lycanthrope in the previous 10 rounds, the cleric need only touch him solo toccarla (Attack ignores armour and shield) and his Saving Throw suffers a 4 point penalty. Any subject injured by a lycanthope’s bite has a percentage chance equal to the hp caused by the bite over the hp possessed by the subject of contracting lycanthropy (e.g.: a thief with 10 hp who loses 6 hp to the bite has a 60% chance of becoming a lycanthrope); the d% is made each time the victim is wounded, and the damage ic cumulative until cured. Moreover, the child of a lycanthrope parent has a 50% chance of inheriting the disease and every demihuman infected with lycanthropy dies with the first transformation. This spell cannot be dispelled with dispel magic, however lycanthropy can be removed in the conventional way appropriate to the campaign (usually cure disease or heal and remove curse cast by a high level cleric).", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 69", "isCustom": false},
    "imm_magic_container": {"id": "imm_magic_container", "name": "Magic Container", "level": 3, "casterType": "immortal", "range": "Touch", "duration": "12 hours + 1 hour per level", "effect": "Increase the internal capacity of a container; reverse causes objects to disappear from container", "area": "A container of 36 ft. cu. every 3 levels", "description": "This spell affects a pre-existing container like a bag, sack, or case, increasing its capacity. It in fact opens a miniscule fracture in the space inside the container, creating a mini dimension that can house a greater number of items. In practice, the container’s capacity is increased by 20 times, and the weight of the carried items becomes a twentieth of its real weight for the spell’s duration (so, a bag with a maximum encumbrance of 600 can carry up to 12,000 cn weighing a maximum of 600, or 6,000 weighs 300, etc.). The maximum volume of the container affected by this spell is of 36 cubic feet every 3 levels. If the spell is magically dispelled or the container is destroyed, the contents are hopelessly lost, and the same sort of thing happens to any items that aren’t removed from the container before the spell ends. The reverse spell, curse container, creates a mini dimension that, rather than contain, makes any item (including magic items) placed inside it disappear after 2d6 turns. If the item is removed earlier there is no problem, otherwise it disappears with no possibility of retrieval; no one knows exactly where the objects end up, but many believe that they are not destroyed, but simply transported to other places chosen randomly and very far from the container’s position. Neither magic container nor its reverse can be combined with a permanency spell.\nReversible.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 82", "school": "Conjuration", "isCustom": false},
    "imm_magic_double": {"id": "imm_magic_double", "name": "Magic Double", "level": 7, "casterType": "immortal", "range": "120 feet", "duration": "Permanent", "effect": "Create new duplicates of an object", "area": "An inanimate object", "description": "This potent spell allows the duplication of any normal item on which it is cast. The item to be reproduced cannot weigh more than 10 cn (1 pound) per mage level (to a maximum of 360 cn at 36th level, or 36 pounds), neither can its value exceed 1,000 g.p. per mage level, and the maximum number of duplicates is equal to half the mage’s level (for a maximum of 18 at 36th level, but the mage can also decide to create less). Each duplicates is created an hour after casting the spell, and it is necessary that the item isn’t handled until the all the desired duplicates have been created; if the item is touched earlier, the effect stops and the duplication ends. The duplicates are identical to the original, with the same properties and defects, although in the case of common items, each duplication is of proportionally lesser value to the original item’s true value. The mage must also sacrifice part of his energy to create the matter from nothing: as such, he loses a number of xp equal to double the value in gold pieces of each duplicate every time that he creates one (for example if he wants to create three duplicates of a crown worth 30,000 gold pieces, he must sacrifice 60,000 xp to obtain three crowns each worth 10,000 g.p.); the rule of xp loss is also applied to any use of an item enchanted with this power. If instead the spell is cast on a magic item without a bonus but with charges (like any staff or wand, or a ring of safety), it draws power from the item and divides it into two identical items with less power, without drawing on the mage’s energy. Each item has half the charges as the original (rounded down) and remains permanently separated from its double (to all effect they are two distinct magic items, whose maximum number of charges is equal to half those of the original). If finally it is cast on an item with a bonus (like a +3 sword or a +2 ring), the two items each get half of its bonus (rounded down), and each of them can be successively divided with the same procedure as long as they each have a +1 bonus (+1 items cannot be divided). The items remain in this form until they are reunited with a special command: when the primary item has been, the spell ends and the item cannot be divided again until a new magical double is cast on it. No magic item of any type or artefact can be duplicated with this spell, and the items created cannot be magically dispelled.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 159", "school": "Conjuration", "isCustom": false},
    "imm_magic_exchange": {"id": "imm_magic_exchange", "name": "Magic Exchange", "level": 4, "casterType": "immortal", "range": "", "duration": "", "effect": "", "description": "Granted by an Immortal in the Tome of the Magic of Mystara Vol. 2 (Divine Magic), Appendix \"Additional spells of each Immortal\". The provided books (Tome Vol. 1-2, Rules Cyclopedia) do not describe this spell; ask your DM or use your own source.", "source": "Tome of the Magic of Mystara Vol. 2, Appendix (no description)", "isCustom": false},
    "imm_magic_flame": {"id": "imm_magic_flame", "name": "Magic Flame", "level": 2, "casterType": "immortal", "range": "90 feet", "duration": "6 turns + 1 turn per level", "effect": "Creates a difficult to extinguish fire", "area": "A solid surface", "description": "This spell allows the spellcaster to create a small flame of reduced size (approximately 1-foot cube) within 90 feet, on any one solid surface: the flame burns without need of fuel for the indicated duration, unless the mage ends the spell earlier. The flame cannot be extinguished by the wind, however strong, but is immediately extinguished if it encounters water (unless it is small drops) or if it is smothered in another way (wet cloths, magically dispelled, etc.). Magic flame can ignite inflammable materials (50% chance) and if it is created on a creature, the victim benefits from a ST vs. Spells to oppose the effect. If the ST succeeds, the flame doesn’t manifest and the spell is broken, otherwise the flame engulfs the creature’s torso and inflict 1d6 points of damage per round; to extinguish it he can roll on the ground for a round, bathe it, or dispel it. If created on a weapon that isn’t of combustible material (such as any metallic weapon), it is surrounded by flames that don’t harm its wielder, and the fire increase the damage normally inflicted by the weapon based on the creature struck:  +1 point to generic creatures;  +2 points to creatures with feathers and plumage (for example a roc, hippogriff, or pegasus) or that don’t regenerate fire damage (e.g. troll);  +3 points to treant, undead, or cold-based creatures. This effect cannot be combined with permanency.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 63", "school": "Evocation", "isCustom": false},
    "imm_magic_muzzle": {"id": "imm_magic_muzzle", "name": "Magic Muzzle", "level": 4, "casterType": "immortal", "range": "60 feet", "duration": "6 turns + 1 turn per level", "effect": "Close the mouth of the victim with a muzzle", "area": "A creature", "description": "This spell can be cast on any creature with a mouth, which can resist the spell’s effect with a ST vs. Spells. If failed, it creates a magic muzzle that perfectly fits the creature’s face (of any size) and harnesses it, preventing it from being able to open it mouth, speak, bite, or use any type of attack via the mouth, although it permits breathing. The muzzle remains solidly fixed to the face for the spell’s duration, until it is magically dispelled, or the mage decides to make it vanish, ending the effect.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 99", "school": "Conjuration", "isCustom": false},
    "imm_magic_sanctum": {"id": "imm_magic_sanctum", "name": "Magic Sanctum", "level": 5, "casterType": "immortal", "range": "120 feet", "duration": "12 hour", "effect": "Impede divination within the protected area", "area": "10 foot per level radius sphere", "description": "This spell impedes any type of divinatory spell (like wizard eye or scry) of scrying within the protected area, or a sphere of 10 feet per spellcaster level. The area becomes unexplorable by any type of divinatory spell for the spell’s duration, and every attempt simply registers the presence of an unfathomable barrier that is impenetrable by magical techniques. Naturally, the spell doesn’t interfere with the natural sight or hearing of any creature that is near the protected area, but only those magical senses. This effect cannot be combined with permanency.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 120", "school": "Abjuration", "isCustom": false},
    "imm_magnetism": {"id": "imm_magnetism", "name": "Magnetism", "level": 4, "casterType": "immortal", "range": "Touch", "duration": "1 minute per level", "effect": "Attract or repel metal objects", "area": "One target max size Large", "description": "This spell gives the touched object a powerful magnetic field that is able to repel metal objects of equal or lower weight to that of the “magnet” or attract objects of a total weight equal to that of the “magnet”. For the spell’s duration a subject can chose to activate the power once per round, otherwise it remains asleep; as well as activating it, the subject can also perform other actions (fight, move, cast spells, etc.). If the magnetism is negative, any metallic object can advance no closer than 3 feet and weapons are deflected. However, if the subject possesses metallic items, they are thrown 10 feet away, so he cannot use metallic weapons. If the magnetism is positive, the subject attracts to itself 1 specific metallic item within 30 feet (or is attracted to the latter if its weight exceeds the limit) or all those within 10 feet of him, but in this case he cannot select metallic items to keep away from him. If the attracted item is worn or held by a creature, it can make a Strength check with a –4 penalty each round to keep the object. If the spell is associated to an item instead, the positive or negative magnetism is always active until the end of the spell or until it is magically dispelled, and the chosen type of magnetism cannot be changed.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 99", "school": "Transmutation", "isCustom": false},
    "imm_mantle_of_shadow": {"id": "imm_mantle_of_shadow", "name": "Mantle of Shadow", "level": 4, "casterType": "immortal", "range": "0", "duration": "3 turns", "effect": "Create an area of inpenetrable shadow that scares those that penetrate it", "area": "Sphere of up to 20 feet radius", "description": "With this spell the cleric creates an area of shadow of variable radius that surrounds and that he can manifest at his pleasure. Normally the power remains sleeping, but as long as the effect lasts (3 turns), the spellcaster can evoke a sphere of shadow centred on himself with variable radius from 5 to 20 feet (with 5 feet increments per round). Anyone inside the sphere is completely blinded as long as it remains (even infravision is useless), except for the cleric who can see normally; any ranged attack against the cleric wrapped by the mantlet of shadow suffers a –4 penalty. Moreover, anyone attempting to enter the sphere must make a ST vs. Mental Spells or be assaulted by horrible images and flee 30 feet away due to the fear that grips them for that round (this effect is useless against creatures that are immune to fear). The area of darkness can be annulled with a dispel magic, while a spell of continual light prevents the possibility of evoking the mantle in the area interected by the sphere of light.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 70", "isCustom": false},
    "imm_marine_fury": {"id": "imm_marine_fury", "name": "Marine Fury", "level": 7, "casterType": "immortal", "range": "240 feet", "duration": "1 turn", "effect": "Create a seaquake; reverse calms moving waves", "area": "Cube with 40 feet + 10 feet per level sides", "description": "This spell causes a seaquake that creates subacquatic currents of devastating force. The area affected by the seaquake is a a cube 40 feet + 10 feet per cleric level sides centered on any point within 240 feet of the priest. All buildings within the area of effect are violently shaken, with the result that the smallest or less resistant are completely destroyed, while it creates several breaches in the more imposing, without however causing them t o fall. Creatures present are thrown in a random direction at a speed of 60 feet per round, and suffer 6d10 points of damage (ST vs. Death Ray for half) because of the pressure and collisions each round they remain within the area. Ships directly above or within the affected area sffer due to the tremendous wves produced and lose 1d6 Hull Points (ST vs. Destruction for half) as long as they remain within the area of effect; to escape the seaquake, surface ships must manoeuvre and the crew is called to make a Seamanship check with a –4 penalty, which at least 50% of the sailors must make. Anyone underwater within the area of effect of the seaquake cannot complete any actions until they escape the currents, which happens if they are lucky enough to be thrown randomly out of the affected area. The seaquake stays in the area it was created for 1 turn, or until the caster decides to cancel it. The cleric doesn’t need to maintain concentration for it to remain active, but note that he is not immune to its effects (so if he doesn’t create far enough away could be involved). The reverse spell, flat calm, annuls any type of wave motion within the area of effect for the spell’s entire duration and annuls the effects of a marine fury, giving shelter to anyone within the volume affected by the adverse effects of seaquakes and strong submarine currents. This spell cannot be made permanent on an item.\nReversible.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 85", "isCustom": false},
    "imm_marine_vortex": {"id": "imm_marine_vortex", "name": "Marine Vortex", "level": 2, "casterType": "immortal", "range": "0", "duration": "Instantaneous", "effect": "Driving vortex, injures and stuns victims", "area": "60 feet long, 20 feet wide cone", "description": "This spell only functions if used underwater. From the cleric’s hands departs a conical shockwave that extends for 60 feet reaching a maximum width of 20 feet. All the creatures within this area must make a ST vs. Paralysis: if the ST succeeds, are pushed away by the vortex for its length and suffer 1d6 damage. If instead the ST fails, not only are they forced away and injured, but are also considerd stunned for 1d4 rounds. Creatures of Huge or Gargantuan size are immune to this spell because of their huge frame.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 56", "isCustom": false},
    "imm_mass_suggestion": {"id": "imm_mass_suggestion", "name": "Mass Suggestion", "level": 6, "casterType": "immortal", "range": "360 feet", "duration": "1 hour per level", "effect": "One or more victims are urged to perform an act", "area": "1 being/level within 30 ft. of each other", "description": "This spell functions in a similar way to suggestion, but can influence more creatures. When mass suggestion is cast, the spellcaster identifies a number of victims equal to his level, which must however be within range and cannot be more than 30 feet away from each other. The victims must make a successful ST vs. Mental Spells to totally avoid the effects, otherwise the spellcaster can affect the actions of the targets suggesting a certain action to them with a single phrase. The suggestion is the same for all of them and arrives telepathically to all contacted creatures, even those that have avoided the effects of the suggestion. The suggestion must be spoken in such a way that it makes the action seem achievable and must be given within an hour of casting the spell, otherwise the effect is wasted. If the suggestion seems forced or dangerous to the victim, the spell instantly vanishes. The suggestion cannot alter the perception of reality (like asking a person to throw himself into a ravine when in reality a ravine doesn’t exist), but can alter the mental state or predisposition of the victim to someone (for example ask a dragon not to attack before it has heard what the mage has to say, or ask a giant to stop fighting and ally with him to destroy a greater threat). The suggested action can be performed for a maximum of 1 hour per mage level, or until it is completed. The spellcaster can also specify certain conditions that activate the action as long as the spell is active (for example suggest to a knight to give his warhorse to the first person that passes); if the condition isn’t met within the spell’s duration, the suggestion is wasted.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 141", "school": "Enchantment", "isCustom": false},
    "imm_meld_into_stone": {"id": "imm_meld_into_stone", "name": "Meld Into Stone", "level": 3, "casterType": "immortal", "range": "0", "duration": "3 turns per level", "effect": "Meld into stone and recover 1d6 hp per hour", "area": "Only the cleric", "description": "This spell allows the cleric to meld into a single block of stone or rock that is big enough to house him; if these conditions aren’t met, the spell doesn’t function. Once fused with the stone, the cleric, although immobile, remains aware, can vaguely keep track of the passage of time, and can hear what happens within a radius of 30 feet. He cannot see out of the rock, cast spells, or use magic items. For each hour spent within the stone, the cleric recovers 1d6 Hit Points. He can exit the rock at any time, thus ending the spell. If the rock is damaged, the cleric isn’t hurt, unless the damage is such that it reduces the block’s volume so it can no longer house him: in this case he is violently expelled and suffers 6d6 points of damage (halved with a ST vs. Spells). The same thing happens if a magic effect forces the cleric to leave the stone against his will, like, for example, passwall, dispel magic, stone to flesh, and so on. Any magic effect that completely destroys the stone (e.g. disintegrate or dissolve) expels the cleric and kills him if he fails a ST vs. Death Ray; even if the ST succeeds, the cleric suffers 6d6 points of damage (not halved).", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 63", "isCustom": false},
    "imm_melding": {"id": "imm_melding", "name": "Melding", "level": 2, "casterType": "immortal", "range": "40 feet", "duration": "6 turns", "effect": "Allows a humanoid creature to hold others inside", "area": "A creature", "description": "This bizarre spell only affects consenting humanoid creatures: if the victim doesn’t want to be the object of the spell, it automatically fails. The subject on which it is cast becomes a sort of living vessel, is able to “meld” with a maximum of 7 other completely equipped humanoids (of the same size or smaller); it takes a full round to meld into the character, completely amalgamating with him. The fusion cannot be forced, and the amalgamated individuals can leave and re-enter (together or separately) the subject’s body when they wish (which takes a round, during which the subject must remain stationary) as long as the spell lasts. Neither the spell’s subject, or the amalgamated creatures inside attack or cast spells in this form, but all can speak (either telepathically between themselves, or outside, using the subject’s voice, and the subject can activate magic items. If the subject is attacked, the damage suffered doesn’t affect the amalgamated creature, but just the subject container. However, if he dies, the spell immediately ends, and all the characters within him are ejected out, but without suffering any physical damage. Such powers cannot be made permanent.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 64", "school": "Transmutation", "isCustom": false},
    "imm_melody_of_requiem": {"id": "imm_melody_of_requiem", "name": "Melody of Requiem", "level": 4, "casterType": "immortal", "range": "0", "duration": "1 round per level", "effect": "Provoke suicidal instincts in the victims", "area": "20 feet radius sphere", "description": "This spell affects anyone within the area of effect while he sings the song except the priest. The spell evokes such a potent funeral dirge that the victims are gripped by a sudden sense of desperation and discomfort that causes a –1 penality to Attack Rolls, damage, and to all Saving Throws (it is impossible to avoid this effect) as long as the effect lasts. Moreover, the victim must make a ST vs. Spells: if the ST is successful there are no other effects, but if the ST fails the victim begins to sream and lose hope, and can do nothing but hit himself with any weapon he is holding (the self-inflicted damage is real, but any weapon mastery in the weapon isn’t counted), even strangling himself with his own hands in has no weapon (non-lethal damage), doesn’t resist any attempts to injure him, or try to attack other people or to evoke magic effects. The melody functions against any living creature except constructs and oozes.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 70", "isCustom": false},
    "imm_memory": {"id": "imm_memory", "name": "Memory", "level": 5, "casterType": "immortal", "range": "Touch", "duration": "Special", "effect": "Recover a spell after casting it", "area": "A spellcaster", "description": "When the spellcaster casts this spell on himself or another spellcaster (arcane or divine), the subject can immediately recover (i.e. rememorize) any one spell of 1st to 5th level that he has cast with the previous 10 minutes (1 turn). This ability lasts until it is used for the first time (an action that then ends the spell). The spell is useless on subjects that cannot cast spells. This effect cannot be made permanent.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 120", "school": "Evocation", "isCustom": false},
    "imm_memory_seal": {"id": "imm_memory_seal", "name": "Memory Seal", "level": 2, "casterType": "immortal", "range": "Touch", "duration": "Permanent", "effect": "A being memorises information in a detailed manner; the victim forgets information", "area": "Creature with an Intelligence above 2", "description": "This spell allows the cleric to stamp into the memory of the person touched (who must have an Intelligence of above) a given piece of information (which he must know at the moment of casting) in a permanent and detailed manner, for example an elaborate map, the demonstration of a theorem, the sequence of notes that shape a melody, and so on. The information remains forever in the individual’s memory, and only the arcane spell amnesia and the reverse of this spell can remove or corrupt the information. There is no limit to the amount of knowledge that the cleric can “set” in a being’s mind with memory seal. The reverse spell, forgetfulness, causes the loss of specific information from the mind of the touched subject, who however can avoid the effect with a ST vs. Mental Spells. Touching the victim requires an attack with his holy symbol, but the victim’s AC ignores his armour, only taking his shield, Dexterity, magic, and weapon mastery into account. The information must be limited (e.g. the location of a place, the map of a locality, the identity of an individual, the subject of a conversation, or even a single spell), and can afterwards by recovered through experience (revisiting a place, restudying the forgotten spell, or listening to the report that has been forgotten). Finally, the cleric must know what type of information he wants to remove from the victim’s mind (it cannot be chosen randomly).\nReversible.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 57", "isCustom": false},
    "imm_memory_visions": {"id": "imm_memory_visions", "name": "Memory Visions", "level": 1, "casterType": "immortal", "range": "Touch", "duration": "Special", "effect": "Imprints memories of the past into an item", "area": "An item", "description": "Once cast, this spell allows the subject to transfer part of his memories into a touched item. Afterwards, if the item is touched by anyone the visions, inserted by the spellcaster, appear on it and are visible to anyone watching the item: once all the contained memories are shown, the spell’s effect ends and the item returns to normal (until that moment ,if examined with detect magic it emanates a weak divinatory aura). The mage can for every three levels insert up to one vision related to a real event that he has personally witnessed. Each vision lasts up to 3 minutes, and can be speeded up or slowed down without altering the truthfulness of the memory. Example: a mage wants to transmit the message that he was taken from his palace and brought to an unknown island that is three days away. The prepared visions show that the mage left his palace and embarked on a ship, then in the sky the sun and moon alternate three times (temporal jumps that don’t show what happened during the journey) until the ship is in sight of an island. A magic item given this power allows anyone to insert his own memories until it is. Only those that have the activation word can later remove some memories to insert new visions.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 48", "school": "Divination", "isCustom": false},
    "imm_mental_decay": {"id": "imm_mental_decay", "name": "Mental Decay", "level": 6, "casterType": "immortal", "range": "240 feet", "duration": "Permanent", "effect": "Reduces the mental abilities of a creature", "area": "A creature", "description": "This spell can be used against any intelligent creature, and causes to the victim a total regression of its intellectual and mnemonic ability (its Intelligence is reduced to 2 points), preventing it from recalling or memorising facts and concepts, and from thinking and acting correctly (thus inhibiting his languages and any type of non-instinctive behaviour). The victim can avoid all the spell’s effects with a successful ST vs. Mental Spells with a –4 penalty. The spell is permanent until removed with a mental cure or heal.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 142", "school": "Enchantment", "isCustom": false},
    "imm_mighty_blow": {"id": "imm_mighty_blow", "name": "Mighty Blow", "level": 5, "casterType": "immortal", "range": "Touch", "duration": "6 rounds", "effect": "The weapon crushes inert objects and augments the damage against animated or living creatures", "area": "A bludgeoning weapon", "description": "Evoking this spell the cleric must touch a bludgeoning weapon and imbues it with the power of smashing any thing for 6 rounds, allowing it to also injure creatures immune to normal weapons (as if it was a +2 weapon). If the target is a normal or magical inanimate object (excluding artefacts) of maximum volume 30 feet3, the first blows causes the loss of 50% of its Damage Points total if it fails a ST vs. Destruction; otherwise it only loses 25% of the total. If the target is a magic item and has no Damage Points and the ST fails, it is destroyed and reduced to fragments. If the target is a normal item without DP it is automatically smashing, no ST. If the target is a living or animated subject, with each hit you deliver add half your Strength score when calculating the damage. With this spell it is possible to destroy magic items whose bonus or power level is tge same as the weapon that hits it. It is however impossible to destroy items that have a +5 bonus, a power level of six, or are artefacts. This spell cannot be made permanent", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 75", "isCustom": false},
    "imm_mind_fog": {"id": "imm_mind_fog", "name": "Mind Fog", "level": 5, "casterType": "immortal", "range": "120 feet", "duration": "6 turns", "effect": "Create cloud of fog that weakens the mental resistance of those within it", "area": "20-foot radius cloud", "description": "This spell produces a light mist that doesn’t obstruct vision much but weakens the mental resistance of those that are inside it. The cloudbank forms within 120 feet of the mage and occupies a 20 feet radius sphere, remaining in the area for 6 turns. Those that venture inside it suffer a –4 penalty to all ST vs. Mental Spells and to all Wisdom and Intelligence checks as long as they remain within the cloud, and the penalty persists for another 1d6 rounds after they leave it. The cloud doesn’t obstruct sight or movement in a significant way and can normally be swept away in a minute by a moderate wind (16 mph) or in a round by a strong wind (25+ mph), as well as by a dispel magic.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 120", "school": "Enchantment", "isCustom": false},
    "imm_mind_shield": {"id": "imm_mind_shield", "name": "Mind Shield", "level": 2, "casterType": "immortal", "range": "Touch", "duration": "12 turns", "effect": "Prevents thoughts from being read", "area": "A creature", "description": "This spell can be cast on a creature with a simple touch, and prevents any type of detection of thoughts and intentions. It moreover alerts the subject when his mind is examined by a spell of this type, giving him the chance to communicate false information or thoughts (which requires concentration). Finally, the protection gives a +1 bonus to all ST vs. mind affecting effects.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 64", "school": "Abjuration", "isCustom": false},
    "imm_minor_luck": {"id": "imm_minor_luck", "name": "Minor Luck", "level": 3, "casterType": "immortal", "range": "120 feet", "duration": "6 turns", "effect": "+1 bonus to d20 rolls, +5% to percentile roles", "area": "One creature", "description": "The subject of this spell becomes lucky for its entire duration: he gains a +1 bonus to all d20 rolls (like Attack Rolls, Saving Throws, skill checks, etc.) and a +5% bonus to d% rolls (e.g. the rolls relating to thief skills). Note that the bonus is only applied to that activity that can be totally completed within the effect’s duration: a check to make weapons or the percentage chance to successfully enchant a magic item isn’t modified as these activities take over 6 turns to complete. The reverse spell, bad luck, renders the victim unlucky if he fails a ST vs. Spells: he suffers a –1 penalty to all d20 rolls and a –5% penalty to all d% rolls.\nReversible.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 64", "isCustom": false},
    "imm_miraculous_seeds": {"id": "imm_miraculous_seeds", "name": "Miraculous Seeds", "level": 7, "casterType": "immortal", "range": "Touch", "duration": "Special", "effect": "Imbue plant seeds with curative powers", "area": "1 seed per 12 levels", "description": "This spell is able to reproduce on some seeds previously prepared with the holy aura spell (one per seed) the curative powers of the mythical senzu plant. While casting the spell, the druid must hold the seeds in his hand (he can only enchant one seed per 12 levels with each spell, round down), which become magical things and keep their property for 1d4 hours. Anyone who eats one within this period of time is immediately brought to the maximum Hit Points possible for his class and race as if he had a Constitution of 18 based on the individual’s level (i.e. a 9th level fighter has 99 hp), even if this is more than his real hp. These additional hp remain for 1 hour (so if the individual is wounded and then cured within this period of time, he can return to this modified hp value), after which they slowly drop (1 per minute) until the character reaches his normal hp (if they have already been eliminated in some way, the individual doesn’t lose his own hp). Moreover, anyone who eats a miraculous seed is satiated and doesn’t need food or water for a week, and immediately feels rested (as after a night of sleep). The miraculous seeds finally permanently cure all those that eat them of diseases (normal or magic), blindness/deafness, but cannot return the dead to life, or revive those in a comatose state or temporal stasis. No one can eat more than one senzu seed within a twenty-four hour period: those that do must immediately make a ST vs. Spells, and if they fail die of a heart attack; if they succeed nothing serious happens, but the character is slowed down (as for the reverse of the haste spell) for the next 1d4 hours.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 131", "druidSpell": true, "isCustom": false},
    "imm_mirror_of_the_past": {"id": "imm_mirror_of_the_past", "name": "Mirror of the Past", "level": 7, "casterType": "immortal", "range": "Touch", "duration": "1 turn", "effect": "Show a scene from the past", "area": "A reflecting surface", "description": "When uttering this spell, the mage must touch a reflective surface (a pool of water, a mirror, a glass, etc.), then indicate a past event that he wants to see and the surface shows him exactly the desired event. The spell however has some limitations:  the event must have happened no more than 20 years per mage level ago or during his life (the better of the two options);  must be about a specific event (for example the death of King Lucinius or the Battle of Kurdal Pass);  the event must have happened on the world where the mage is. If even one of these conditions isn’t met, the spell has no effect. If instead they are all met, there is a 50% chance that mirror of the past shows the requested event, modified as follows (cumulative percentages):  +20% if the mage was involved in the event;  +15% if the event is well documented;  +10% if the event happened during the mage’s life;  +5% if the spellcaster has some information;  +5% if the mage’s Intelligence is at least 16;  +5% if the mage’s Wisdom is at least 16;  −10% for each failed attempt already made. If the spellcaster is able to correctly watch an event for the first time, he can recall the event in the future with no chance of error by using this spell. Mirror of the past shows the event from a good angle (distance of 3 to 12 feet from the main character or with an aerial view if it is a vast area), with the same conditions of visibility present at that moment (so if the scene happened at night it could be difficult to pick out details) and continues to show the same scene for the spell’s entire duration. It isn’t possible to interact with the scene in any way or cast spells through the mirror. If the surface is disturbed or destroyed while the vision is active, the spell ends. This effect cannot be combined with permanency.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 160", "school": "Divination", "isCustom": false},
    "imm_mislead": {"id": "imm_mislead", "name": "Mislead", "level": 6, "casterType": "immortal", "range": "60 feet", "duration": "1 round per level", "effect": "Make the mage invisible and create an illusionary double", "area": "Only spellcaster", "description": "This spell creates two effects simultaneously: it renders the spellcaster invisible and creates an identical holographic image within 60 feet of his position. The spellcaster can then act independently of the image, and if he wants he can concentrate to give it a command each round. The double appears real until it is physically wounded or is subjected to a dispel magic: in which case it disappears. The illusion is visual, audible, olfactory, and tactile: smells like the spellcaster, can be touched (only vanishing if it is wounded) and is able to speak with its own voice, based on what the illusionist suggests. It can also pretend to attack, although it attacks can unmask its true nature as it cannot successful injure someone. The image moves at the same speed as the spellcaster and once created can also leave the spell’s radius. The illusion vanishes at the end of the mislead’s effect or earlier if destroyed, as does the invisibility that the spellcaster enjoys thanks to the spell. This effect cannot be combined with permanency.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 142", "school": "Illusion", "isCustom": false},
    "imm_move_sand": {"id": "imm_move_sand", "name": "Move Sand", "level": 3, "casterType": "immortal", "range": "30 feet", "duration": "6 rounds + 1 round per level", "effect": "Move 5 cubic feet of sand per round", "area": "5 cubic feet of sand", "description": "This spell moves sand as is was water at the cleric’s command. He can move 5 cubic feet of sand each round, making it move horizontally or vertically over any solid surface. The spell can be used unearth or clean up a series of ruins, open blocked passages, retrieve buried object, or dig an emergency tunnel in sand. If the moved sand is directed against a creature, it halves its walking speed; if however the target is within a tight subterranean tunnel, he could also be buried alive if he doesn’t escape in time. At the end of the spell, the sand returns to be affected normally by gravity, and slides down any hole or slope in the terrain. If the moved sand is dampened and compressed before the spell’s end, it maintains its new form until it is dry again (usually a day).", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 64", "isCustom": false},
    "imm_natural_transformation": {"id": "imm_natural_transformation", "name": "Natural Transformation", "level": 9, "casterType": "immortal", "range": "120 feet", "duration": "Transform 5 lb per level of metal", "effect": "50 cn of metal objects", "description": "The spell can transform any metallic object into an equivalent object of stone or wood, at the druid’s choice. For each druid level, he can transform the equivalent of 50 cn (5 lb) of metal, but magical metallic objects can resist the effect with a successful ST vs. Destruction. Armour transformed into stone becomes useless and encumbering, while that transformed into wood can be used by the druid, but it isn’t possible to remove it without destroying it. Weapons transformed into stone or wood, based on the druid’s intent, can keep all their powers but change their molecular structure, or become useless pieces of rock or twisted that must be thrown away. The natural transformation is irreversible and can only be countered with a wish.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 131", "druidSpell": true, "isCustom": false},
    "imm_necromantic_frenzy": {"id": "imm_necromantic_frenzy", "name": "Necromantic Frenzy", "level": 7, "casterType": "immortal", "range": "0", "duration": "1 round per level", "effect": "Undead fight with greater effect", "area": "40-foot radius sphere", "description": "This spell only affects undead within 60 feet of the mage when the spell is cast. The spell is able to effect 1 HD of skeletons or zombies per mage level, or a single undead of any other species with maximum HD equal to double the mage’s level. Skeletons and zombies are automatically affected by the spell, while any other undead can make a ST vs. Spells to resist the spell. Those affected by the necromantic frenzy become dominated by the spellcaster, obey all his orders, and as long as they remain in the area of effect and the spell is active gain the mage’s natural THAC0 (if it is better than their own) and move and attack as if under the effects of the haste spell. The necromantic frenzy, however, causes the undead to rapidly decay: they suffer 1 point of damage per round and if they drop below zero incorporeal undead vanish, while those with physical bodies (like skeletons, zombies, ghouls, etc.) crumble away, giving rise to a toxic black dust that poisons living creatures within 10 feet (all the victims suffer 2d6 points of damage, but can make a ST vs. Poison for half damage). Creatures of great power (like vampires and mummies) aren’t eternally destroyed, bur regenerate in the characteristic ways of their nature.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 160", "school": "Necromancy", "isCustom": false},
    "imm_necromantic_fusion": {"id": "imm_necromantic_fusion", "name": "Necromantic Fusion", "level": 7, "casterType": "immortal", "range": "Touch", "duration": "1 turn per level", "effect": "Enter a dead body and possess it", "area": "An undead or corpse", "description": "The mage takes possession of a humanoid corpse or the body of an undead, dominating it. If he takes possession of a corpse, he can act exactly as if using the corpse possession spell, but can also cast his own spells from the possessed body. If he wants to dominate an undead, if it has an Intelligence of higher than 5 it is allowed a ST vs. Spells to resist the effect, but if the ST fails or the victim is an undead with little intelligence (the majority of zombies, skeletons, and ghouls) then the mage’s lifeforce enters the victim’s body and totally controls it. The mage keeps his Intelligence, Wisdom, and Charisma scores, and can use any physical or innate magical ability of the undead, except any spell memorised by the latter or by the mage. During the fusion, the mage’s body remains in a comatose state and can be injured normally. The mage can move as far from his body as he likes, provided he remains on the same plane: if this condition isn’t met, the spell ends instantly and the mage’s spirit returns to his body, and the same happens if the spell on the undead’s body is dispelled. Sharing the body with the undead’s spirit, the mage is placed under a constant pressure by the creature trying to regain control of its body. As such, each hour that passes after the start of the spell, the mage is forced to make an opposed Spiritual Strength test to maintain the. Each rolls 1d20 and add the sum of Intelligence, Wisdom, and Charisma to it: the highest result wins. When the mage fails the test, the spell is broken and his spirit returns to his body assaulted by terrifying and nefarious visions induced by the undead’s mind. In this he needs to make a ST vs. Mental Spells; if he fails, the individual is overcome by a homicidal rage for 1d6 turns, in constant search of victims to massacre and eat. If the ST was a natural, the mage is struck by a permanent form of feeblemind, until it is cured in an adequate manner.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 160", "school": "Necromancy", "isCustom": false},
    "imm_necromorph": {"id": "imm_necromorph", "name": "Necromorph", "level": 5, "casterType": "immortal", "range": "Touch", "duration": "1 turn per level", "effect": "A living individual resembles a zombie", "area": "A creature", "description": "This spell allows the living creature touched by the spellcaster to assume the appearance and characteristics of a zombie. For the duration’s, the subject stops breathing, doesn’t feel pain or emotions, becomes immune to paralysis, poison, and energy drain, but is still vulnerable to spells of charm and enchantment, and to fatigue (and thus to sleep). If he is exposed to a poison, the effect is only felt when the effect ends, while the effects of a poison taken before the transformation is temporarily held, and retakes its normal course at the spell’s end. The immunity to pain doesn’t give any protection against attacks, as the damage suffered remains such. Spells that have a specific effect on undead however (like destroy undead), do not have any effect on the subject, nor do attempts to turn him, revealing his real nature. The subject’s body assumes in all aspects the appearance of a body returned to life: skin and flesh discolour and sag exposing the bones beneath, but his clothing and items remain unchanged. However, because of this metamorphosis, although the subject’s joints and muscles lose flexibility, and he has the same handicaps as normal zombies, or a –4 penalty to Initiative Rolls, a base speed reduced to 90 (30) feet per round, and the impossibility to benefit from the effects of a haste spell, as well as the inability to make more than one attack per round. Finally, because of the transformation, the subject is forced to eat dead flesh to feed itself (assume other food do not satisfy its hunger), although he isn’t able to control himself perfectly until he has spent at least 24 hours in that form. Any creature that observes the subject of the necromorph believes that he really is a zombie, and even the undead believe that he is one of them and don’t attack him unless they receive a specific order to do so. If however the subject performs actions that don’t agree with his form, the observers could discover the deceit with a successful Wisdom check.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 121", "school": "Necromancy", "isCustom": false},
    "imm_neutralise_poison": {"id": "imm_neutralise_poison", "name": "Neutralise Poison", "level": 7, "casterType": "immortal", "range": "Touch", "duration": "Permanent", "effect": "Neutralise any poison present in a being, container, or item; reverse creates poison in a being or container", "area": "One being, item, or container", "description": "This spell renders innocuous any poison, stopping the harmful processes, either that within a being’s system, or contained in a container (like a bottle or reservoir), or spread over an item (e.g. a case or a blade). If uttered within 10 rounds of the poisoning, it can also return the victim to life (if it died from the poison), or eliminate all his physical damage (hp) derivied from the poison. The spell is effective against all the poisons present in the target at the moment it was cast, but doesn’t heal any wound produced by the poison (if is is not cast within 10 rounds of the poisoning), it simply prevents him incurring others. The reverse spell, create poison, can be cast against a being or container, but not on other objects, and poisons it instantly. The victim must immediately make a successful Saving Throw vs. Poison, otherwise he dies instantly. If the spell is directed against a container, its contents become poisoned, and doesn’t allow any Saving Throw to prevent the transformation, although if the container or contents have a magic nature (like potions); when someone takes the poisoned contents, he can make a normal Saving Throw to avoid the effects. The poisoning is considered an evil and sly act, and therefore not all Immortals are inclined to grant this spell.\nReversible.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 33", "isCustom": false},
    "imm_night_terrors": {"id": "imm_night_terrors", "name": "Night Terrors", "level": 4, "casterType": "immortal", "range": "½ mile", "duration": "Special", "effect": "A phobia negates the victim’s rest", "area": "A living being", "description": "This spell can only be cast after sunset and affects a living being that the mage must have seen at least once and that is within ½ mile (it isn’t possible to cast the spell more than once on the same person in a 24 hour period). The target remains the victim of a series of illusions based on what he fears the most or his phobias, which also amplifies reality making it impossible to rest. For example those that hate spiders will find them everywhere, those that fear wild animals will see them in every corner, those that fear the dark will see sinister movement in the shadows, those that fear thieves will hear footsteps behind them and so on. Night terrors are so harassing that it is impossible to get enough rest, thus preventing to the victim from recovering his strength (hp) and memorising his spells. Moreover, a prolonged period of insomnia also severely tests the victim’s physique and mind: in fact, for every week spent without rest, he temporarily loses 1 Constitution point and 1 Intelligence point (is no longer able to focus his attention and his physical resistance is suffers some). If because of this his Constitution score drops to zero, the victim dies from a heart attack. If instead it is his Intelligence that drops to zero, the victim literally driven mad and can only be cured with a heal or a wish. The victim can avoid any effect of the spell with a successful ST vs. Mental Spells. Moreover, for each day in which he remains under the spell, he is allowed a further ST to free himself of his night terrors. The spell ends when the victim dies, goes mad, or makes his ST, or if it is magically dispelled. For each day in which he is able to rest normally (for example through restorative sleep or sleep), the victim recovers 1 point of lost Constitution and Intelligence.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 100", "school": "Illusion", "isCustom": false},
    "imm_nightwatch": {"id": "imm_nightwatch", "name": "Nightwatch", "level": 2, "casterType": "immortal", "range": "Touch", "duration": "Special", "effect": "See in the dark as if it was day within 200 feet", "area": "A creature", "description": "The subject that benefits from this spell can see in darkness (normal and magic) as if it was day, but only in outdoor settings. The spell cannot be cast before two hours after the sun has set, and lasts from the moment of casting until dawn. As long as the spell is active, the subject can see clearly around himself outside as if in full daylight for a radius of 300 feet and act without any darkness derived penalties; beyond this radius, the normal lighting conditions apply.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 65", "school": "Transmutation", "isCustom": false},
    "imm_oblivion": {"id": "imm_oblivion", "name": "Oblivion", "level": 5, "casterType": "immortal", "range": "240 feet", "duration": "Instantaneous", "effect": "Destroy beings with 4 HD or less and wound those with 5+ HD", "area": "A living creature", "description": "This spell has different effects based on the victim’s toughness. It affects any living being (excluding undead and constructs) on which it is cast, and the effects are determined by the creature’s Hit Dice as follows:  4 HD or less: the creature is completely pulverised (excluding his equipment, which falls to the earth), leaving behind a cloud of smoke that dissipates shortly afterwards;  5-8 HD: the creature must make a ST vs. Spells to not be pulverised (see above); If the ST succeeds, it still suffers 6d6 points of damage;  9+ HD: the creature suffers 6d6 points of damage, which can be halved with a successful ST vs. Spells.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 121", "school": "Necromancy", "isCustom": false},
    "imm_offensive_impulse": {"id": "imm_offensive_impulse", "name": "Offensive Impulse", "level": 1, "casterType": "immortal", "range": "0", "duration": "Instantaneous", "effect": "Cleric gains +4 to Attacks and maximum damage", "area": "Only the cleric", "description": "With this prayer the cleric invokes on himself the spirit of battle to strike with a better certainty that his enemy will be mortally wounded. The effect is instantaneous, as while casting the spell the priest must deliver his blow, benefiting from a +4 bonus to Attack and if the attack hits it also inflicts maximum damage to the victim, or 10 damage if the maximum is lower. The only way the victim can avoid the damage is by dodging the blow or by parrying the cleric’s weapon before it hits (if he can parry).", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 54", "isCustom": false},
    "imm_pass_rock": {"id": "imm_pass_rock", "name": "Pass Rock", "level": 4, "casterType": "immortal", "range": "", "duration": "", "effect": "", "description": "Granted by an Immortal in the Tome of the Magic of Mystara Vol. 2 (Divine Magic), Appendix \"Additional spells of each Immortal\". The provided books (Tome Vol. 1-2, Rules Cyclopedia) do not describe this spell; ask your DM or use your own source.", "source": "Tome of the Magic of Mystara Vol. 2, Appendix (no description)", "isCustom": false},
    "imm_persistent_image": {"id": "imm_persistent_image", "name": "Persistent Image", "level": 5, "casterType": "immortal", "range": "240 feet", "duration": "1 turn per level", "effect": "Creates an autonomous illusion", "area": "Maximum volume of 8,000 ft3.", "description": "This spell is similar to phantasmal force but doesn’t require the mage to remain concentrating to control it. The illusion lasts for 1 turn per mage level and includes visual, audible, thermal, and olfactory effects and can be broken by anyone that penetrates or comes into contact with the area of effect and making a ST vs. Mental Spells (with a modifier from +5 to –5 given by the DM based on the illusion’s realism based on the surrounding environment). If it creates a creature or group of creatures (which must however remain within the spell’s area of effect), they behave by following the instructions that the mage gave when he cast the spell, and are even able to speak simple phrases that the spellcaster has taught. If the spellcaster concentrates and the illusion is in range, he can also move it as long as it remains within 240 feet of him. When it stops or the mage stops concentrating, that point becomes the new centre of the illusion’s area of effect. If instead the spellcaster creates an environmental or magical effect (like a storm or the explosion of a fireball), a ST vs. Mental Spells is allowed to recognise the illusion and ignore its effects. If the ST fails, the victim must behave exactly as if the effect was real, except if he leaves the spell’s area of effect when he notices the fiction. If with this effect a creature should die, it only remains unconscious for 1d4 rounds, and when he awakens is aware of the fiction.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 121", "school": "Illusion", "isCustom": false},
    "imm_phantasmal_killer": {"id": "imm_phantasmal_killer", "name": "Phantasmal Killer", "level": 3, "casterType": "immortal", "range": "120 feet", "duration": "Instantaneous", "effect": "Phantasm wounds the victim (3d6 hp + ST)", "area": "A creature", "description": "The spellcaster creates the illusionary image of the most frightful creature that the victim can imagine, giving form to the fears present in his subconscious and materialising it in monstrous form drawing on the energy of Nightmare. Only the victim of the hallucination can see it, while the spellcaster and others present see a dark and indistinct shape. The creature is cast against the target to kill it and at this point, the subject must make a ST vs. Mental Spells: If the ST succeeds, he suffers 3d6 points of damage because of the shock and the creature disappears. If the ST fails, as well as the damage caused by the illusion the victim believes he has been killed and instantly faints. He can be quickly revived with an energetic shaking that lasts an entire round, or awakens by himself after 1d6+1 rounds. The spell is ineffective against creatures with less than 3 Intelligence, undead, and constructs.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 84", "school": "Illusion", "isCustom": false},
    "imm_phantasmal_lover": {"id": "imm_phantasmal_lover", "name": "Phantasmal Lover", "level": 6, "casterType": "immortal", "range": "Touch", "duration": "2 turns", "effect": "Summon a being that heals through rapture", "area": "A living sentient creature", "description": "This spell can be cast on any one living being with an Intelligence higher than 3. The target sees materialise in front of him a source of light that asks the question: “Would you like me to satisfy your desires?” If the target doesn’t respond within two rounds or with a negative answer, the energy dissipates and the spell ends. If the individual accepts the proposal, the spell turns into a creature of incomparable beauty (according to the target’s tastes), who immediately beings to make love with the subject. Uninterrupted, the coupling lasts for 20 minutes during which the individual is totally enraptured with his phantasmal lover and defenceless: any attempt to injure him automatically succeeds, although it isn’t possible to make a coup de grace as the individual; continues to move during the sexual act. If, however, an attempt is made to strike the phantasmal lover, each attack simply passes through it and strikes its partner. At the culmination of the coupling, the beneficiary of the spell is cured of any physical handicap (blindness, deafness, and natural diseases) and recovers all lost hit points. If the phantasmal lover is dispelled before the end of the coupling, the subject doesn’t receive any benefit.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 142", "school": "Conjuration", "isCustom": false},
    "imm_plant_form": {"id": "imm_plant_form", "name": "Plant Form", "level": 5, "casterType": "immortal", "range": "0", "duration": "2 turns per level", "effect": "Transform the druid into a shrub or tree 11", "area": "Only the druid", "description": "When the druid casts this spell he transforms (with all his equipment) into a tree of his dimensions, or into a plant of his choice of one size smaller (he can choose the plant most appropriate to his location) once per round (or vice versa, return to his normal form) for the spell’s duration. The metamorphosis is so perfect that he can only be revealed by magic. Once in plant form, the druid keeps his mental faculties and his senses and so can see and hear all that happens around him, but cannot move, defend himself, cast spells, or use items, although magical effects already active on him before the change continue to function and he can converse with nearby plants. His Hit Points and Saving Throws don’t change; his AC is 7 if he becomes a shrub or plant, or 5 if he becomes a tree.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 126", "druidSpell": true, "isCustom": false},
    "imm_plant_growth": {"id": "imm_plant_growth", "name": "Plant Growth", "level": 4, "casterType": "immortal", "range": "", "duration": "", "effect": "", "description": "Granted by an Immortal in the Tome of the Magic of Mystara Vol. 2 (Divine Magic), Appendix \"Additional spells of each Immortal\". The provided books (Tome Vol. 1-2, Rules Cyclopedia) do not describe this spell; ask your DM or use your own source.\nReversible.", "source": "Tome of the Magic of Mystara Vol. 2, Appendix (no description)", "isCustom": false},
    "imm_poetic_inspiration": {"id": "imm_poetic_inspiration", "name": "Poetic Inspiration", "level": 2, "casterType": "immortal", "range": "60 feet", "duration": "6 turns", "effect": "+1 bonus to Attacks and damage for allies or –1 penalty to Attacks and damage for enemies", "area": "Beings within 400 ft2", "description": "With this spell the cleric encourages himself and his companions, receiting or improvising verses to instill martial ardour in his allies (+1 bonus to Attack Roll, damage, and Morale) or fear in his enemies (–1 penalty to Attack Roll, damage, and Morale) who must be within an area of 400 ft2 within 60 feet of the priest. This spell can also be used to influence the persuasive ability of the cleric and improve by one step any Reaction Rolls caused by the cleric thanks to his diplomatic or charismatic ability for the effect’s entire duration, taking the assumption that the priest can speak the language of those he’s speaking to (if the player gives a good roleplaying performance, it is possible to improve the Reaction Roll by two steps). This spell cannot be made permanent on a magic item.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 57", "isCustom": false},
    "imm_preserve": {"id": "imm_preserve", "name": "Preserve", "level": 7, "casterType": "immortal", "range": "", "duration": "", "effect": "", "description": "Granted by an Immortal in the Tome of the Magic of Mystara Vol. 2 (Divine Magic), Appendix \"Additional spells of each Immortal\". The provided books (Tome Vol. 1-2, Rules Cyclopedia) do not describe this spell; ask your DM or use your own source.", "source": "Tome of the Magic of Mystara Vol. 2, Appendix (no description)", "isCustom": false},
    "imm_primal_form": {"id": "imm_primal_form", "name": "Primal Form", "level": 4, "casterType": "immortal", "range": "Touch", "duration": "1 turn per level", "effect": "Being gains natural attacks (bite and claws) and increase in Str, Dex, and Con but loses Intelligence", "area": "A living creature", "description": "This spell transforms the target into a creature of bestial appearance, revealing its savage and sleeping primordial instincts. If he wants, the victim can oppose the spell with a successful ST vs. Spells, otherwise he suffers a mutation that augments his body hair, and makes his teeth and nails grow into fangs and claws with which he can make two natural attacks per round, causing 1d4 hp + Strength bonus with the claws; if both hit, it means that he has immobilised victim and can bite it (free attack), causing 1d6 hp + half Strength bonus. If he already has natural attacks, he adds 1d4 to the damage inflicted by the claws and bite. If he opts to attack with a weapon, he cannot use his natural attacks. Moreover, the subject gains 6 points that he can distribute, at his liking, between Strength, Dexterity, and Constitution (at least 1 additional point to each), while his Intelligence falls by 4 points (because of this he may have difficulty in speaking and focusing his attention); if the mage’s Intelligence drops below 9 points, he loses the ability to cast spells whilst he remains in primal form. The subject continues to think according to his own inclinations and keeps his alignment and memories, but becomes testier, rash, and more inclined to solve problems by physical force rather than with intelligence or cunning. Primal form persists until the effect ends or is dispelled.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 102", "school": "Transmutation", "isCustom": false},
    "imm_psychokinesis": {"id": "imm_psychokinesis", "name": "Psychokinesis", "level": 1, "casterType": "immortal", "range": "20 feet + 3 feet per level", "duration": "6 turns", "effect": "Can move unattended items", "area": "Unattended items in 3 ft2 (weight 6lb)", "description": "Pointing his finger at an unattended item, the mage can raise it and move it at his pleasure at a speed of 20 feet per round, as long as he concentrates and the item remains within range. The item cannot weigh more than 6 lb. (60 cn encumbrance) and must be free to move. Any bound, fixed, or held cannot be moved, and the mage cannot exercise control on objects he cannot see. If the spell is used on more than one target simultaneously, at the moment of casting they must be within a 3 feet square space and their combined weight cannot exceed 6 lb. The mage can also move a weapon and attack with it at distance with a –2 penalty to the Attack Roll, but cannot use any mastery. Psychokinesis remains active for 6 turns, and the spellcaster can use its effects by concentrating.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 50", "school": "Transmutation", "isCustom": false},
    "imm_purify_food_water": {"id": "imm_purify_food_water", "name": "Purify Food & Water", "level": 2, "casterType": "immortal", "range": "10 feet", "duration": "Permanent", "effect": "Purify food and water from impurities and mould", "area": "Volume of 1 cubic foot", "description": "This spell purifies food and water of any poison or makes it edible if it is rotten. The cleric can choose to purify water and food contained in a volume of 1 cubic foot, or a total of 60 pounds of food and water (e.g. 60 pints of water, or 60 pounds of food, or 30 pints of water and 30 pounds of food together). If it is cast on a mud pool, it immediately turns it into a pool of drinkable water (within the limits of allowed pints). It has no effect if cast on living beings, magic potions, or vials of poison.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 19", "isCustom": false},
    "imm_purifying_energy": {"id": "imm_purifying_energy", "name": "Purifying Energy", "level": 7, "casterType": "immortal", "range": "0", "duration": "Instantaneous", "effect": "Annul spells and turn undead", "area": "Sphere of 3 foot radius every 2 levels", "description": "Evoking this spell, the mage’s body gives off a strong charge of positive energy, which exrends to a radius of 3 feet per 2 levels around him. The lights acts as a powerful dispel magic spell, with a failure chance equal to only 3% (rather than 5%) per level of difference between the mage and the spellcasting adversary, annulling all the active spells in the area of effect (except anti-magic barrier, forcefield, and other spells normally impervious to dispel magic), but leaves any spells on the mage active. Moreover, undead, demons, and planar creatures that are in the energy’s area of effect are forced to make a ST vs. Spells: if they succeed they are force to leave the area, and cannot re-enter it for the following 24 hours. Those that fail are instead destroyed (undead) or returned to their home plane. This effect cannot be made permanent.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 162", "school": "Abjuration", "isCustom": false},
    "imm_purifying_flame": {"id": "imm_purifying_flame", "name": "Purifying Flame", "level": 5, "casterType": "immortal", "range": "6 feet per level", "duration": "Instantaneous", "effect": "Explosion of fire causes 1d6 hp per level, mage is immune, undead have –1 to ST", "area": "10-radius sphere", "description": "This spell is similar to fireball, with a notable difference: the explosion of fire doesn’t damage the spellcaster or his equipment, and so he can centre it on himself. Moreover, all undead creatures within the area of effect suffer a –1 penalty to their Saving Throws for half damage.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 122", "school": "Evocation", "isCustom": false},
    "imm_purity_of_spirit": {"id": "imm_purity_of_spirit", "name": "Purity of Spirit", "level": 4, "casterType": "immortal", "range": "Touch", "duration": "3 turns", "effect": "Aura protects subject from evil creatures", "area": "One creature", "description": "This spell only affects followers of the Immortal of the cleric who cast the spell or in exceptional cases individuals devoted mind and body to the cause of Good and considered allies (must have the alignment needed to be priests of the Immortal who gave them the power). The beneficiary is wrapped by an aura of pure white light that gives him a +3 bonus to all Saving Throws and rolls to Turn undead. Moreover, if the character protected by purity of spirit is hit in hand-to-hand by an evil creature (cursed, belongs to the Sphere of Entropy, or serves an Entropic Immortal), the latter is invested by a discharge of blinding energy that inflicts 3d6 points of damage (allowed ST vs. Spells for half damage).", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 70", "isCustom": false},
    "imm_push": {"id": "imm_push", "name": "Push", "level": 1, "casterType": "immortal", "range": "30 feet", "duration": "1 round per level", "effect": "Push an object or creature", "area": "One target max 400 lb. weight", "description": "As long as the spell lasts the mage can concentrate once per round and use air pressure to violently move any one target of up to 400 lb. (4,000 cn) present within 30 feet. If the target is an unattended item, it is thrown in the desired direction up to 6d6 feet + 3 feet per mage level (max +30). If the target is a held item (a weapon, a wand, etc.) or a creature, its wielder or the victim can oppose the effect with a successful ST vs. Spells. Any creature pushed away must also make a Dexterity check or fall to the ground, suffering 1d6 debilitating damage for every 20 feet travelled and if it loses more than 50% of its current hp is stunned for 1 round.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 50", "school": "Evocation", "isCustom": false},
    "imm_pyrokinesis": {"id": "imm_pyrokinesis", "name": "Pyrokinesis", "level": 2, "casterType": "immortal", "range": "10 feet per level", "duration": "Instantaneous", "effect": "Causes 1d6 hp per level (max 10d6) of fire damage", "area": "A creature or common object", "description": "The spellcaster selects any one target (creature or normal object) within range and it is suddenly struck by a huge rise in temperature that cause burns over its entire body equal to 1d6 points of damage per level (max 10d6 at 10th), halved with a successful ST vs. Spells for victims or ST vs. Fire for objects. If the target is reduced to zero hp or SP because of the spell, it catches fire (also causing 1d6 points of damage to anything he is holding or wearing) and ends up incinerated. The spell can be used everywhere, even in situations of extreme cold or underwater, as it affects the victim from within. Moreover, the spell can burn alive a living being without necessarily also incinerating his equipment his equipment. The spell is also effective against undead and constructs, but fire elementals and creatures composed of fire are immune to it.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 65", "school": "Evocation", "isCustom": false},
    "imm_rage": {"id": "imm_rage", "name": "Rage", "level": 2, "casterType": "immortal", "range": "Touch", "duration": "10 rounds", "effect": "Augment an individual’s fighting ability", "area": "One creature", "description": "The character touched by this spell becomes a berserker, a rampaging fighter of combat, and acquires an extra attack per round asnd an extra 1d8 Hit Points for 10 rounds (the acquired hp are subtracted from the character’s hp at the end of the 10 rounds, and this couild could cause his death if in the meantime he had been seriously injured), but his Intelligence and Wisdom scores are temporarily reduced by 2. When the spell ends, the character remains exhausted per 1 turn, with the following penalties: –1 to Attacks, damage, AC, and Strength and Dexterity checks. The character can be subjected to 2 or more spells in sequence: thus making, temporarily postponing the penalty by the use of another rage spell, but each use adds 1 turn to the period of exhaustion. This spell cannot be made permanent on a magic item.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 57", "isCustom": false},
    "imm_rainbow_path": {"id": "imm_rainbow_path", "name": "Rainbow Path", "level": 6, "casterType": "immortal", "range": "4 miles per level", "duration": "Special", "effect": "Create a rainbow that transports the creatures up to 4 miles per cleric level", "area": "Cleric and up to 6 creatures", "description": "This spell creates in front of the cleric a beautiful multicoloured rainbow that springs from the ground and is lost in the sky. The priest can go onto the rainbow together with a maximum of 6 other creatures, and thanks to it travel up to 4 miles per level (travelling 1 mile per round), in a direction chosen by him (it’s not important to name an exact place). The passengers of the rainbow disappear to the sight of those present that don’t go on it, and no one can see them while travelling through the air, as effectively they become immaterial. When the cleric wants to, he can descend from the rainbow and take with him all the passengers, ending the spell. If a passenger seeks to leave the rainbow against the priest’s will he must make a ST vs. Spells: if successful, he gets lost in the Astral Plane. The rainbow always deposits its passengers on the ground or on a stable surface (as long as some exists within the distance travelled), never within other solids or inside a construction. As long as he is within the rainbow, the cleric can choose to use one of the magical properties of its colours, activating one a round, to affect a single creature within rainbow. Based on the chosen colours, these are rhe granted powers: • Orange: cure serious wounds; • Blue: fly; • Yellow: haste; • Indigo: freedom of movement; • Red: elemental resistance; • Green: neutralise poison; • Violet: temporarily increase Wisdom by 1 point (up to racial maximum) for 24 hours. Once the power of a colour is activated, it disappears from the rainbow, reducing the coverable distance by 4 miles; when all the colours have been used, the rainbow vanishes and the effect ends, depositing the travellers anywhere it has been up to that moment. If the activation of one of the colours reduces the coverable distance to less than that remaining for the spell, the rainbow vanishes and the effect ends but the power doesn’t manifest.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 81", "isCustom": false},
    "imm_ray_of_enfeeblement": {"id": "imm_ray_of_enfeeblement", "name": "Ray of Enfeeblement", "level": 2, "casterType": "immortal", "range": "90 feet", "duration": "2 rounds per level", "effect": "Reduces Strength by 2d4 points for 2 rounds/level", "area": "A creature", "description": "Using this spell, the spellcaster can fire from his hand a 90 feet long line of negative energy that automatically hits the chosen target and all those along its, reducing their natural Strength score and weakening their combat ability. The victim must make a ST vs. Spells or lose 2d4 points of Strength for 2 rounds per spellcaster level, with the consequential loss of any Strength-derived bonus and application of penalties to Attack Rolls and damage, as well as to movement (if he is now carrying too much); If the ST succeeds, the subject loses 2 points of Strength for the period given above. The strength returns completely at the end of the spell. If the victim is reduced to 0 Strength, he collapses to the ground unable to move a muscle until he recovers at least one characteristic point. Moreover, if the victim wears a magic item that modifies his Strength, ray of enfeeblement has no effect as long as the creature continues to wear the item. It isn’t possible to make the effects of this spell permanent on a victim with permanency.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 65", "school": "Necromancy", "isCustom": false},
    "imm_reflection": {"id": "imm_reflection", "name": "Reflection", "level": 2, "casterType": "immortal", "range": "Touch", "duration": "2d6 turns", "effect": "Render immune and repulse attacks that affect the eyes or effects of magic blindness 59", "area": "A living creature", "description": "The subject on which the spellcaster casts this spell is considered protected against every form of attack that compromises his sight (like cause blindness) or that acts on him through his eyes (like a vampire’s charm, the petrifying gaze of a medusa, etc.), and repulse all delivered attacks of this type (the new victim is allowed a ST to negate the effect). For example, if a light spell or similar is directed against the individual to blind him, the effect is instantly reflected on its caster (who would be the only who that needed to make a ST to avoid the blindness); if instead darkness is cast on the area in which the individual is, the barrier doesn’t protect it.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 65", "school": "Abjuration", "isCustom": false},
    "imm_reinvigorating_soup": {"id": "imm_reinvigorating_soup", "name": "Reinvigorating Soup", "level": 2, "casterType": "immortal", "range": "Touch", "duration": "Special", "effect": "Satiate those that eat the soup and that gives 1d4+1 points of temporary Strength", "area": "1 portion of soup per 2 levels", "description": "This spell renders magic per 1 turn one portion of broth or soup prepared by the druid for every two druid levels. Anyone that eats the soup while it retains its magic suddenly becomes satiated as if he had had a day’s food, and moreover receives 1d4+1 additional points of Strength that last a hour. It isn’t possible to eat more than one reinvigorating soup per day.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 120", "druidSpell": true, "isCustom": false},
    "imm_remove_disease": {"id": "imm_remove_disease", "name": "Remove Disease", "level": 6, "casterType": "immortal", "range": "30 feet", "duration": "Permanent", "effect": "Cure a disease; reverse inflict a disease", "area": "One creature", "description": "This spell is able to instantly heal a being of a disease of any type (magic or normal), quickly annulling its effects and immediately restoring each debilitating physical and mental effect that affects any of the subject’s characteristics or abilities. Based on the level of the cleric it is possible to cure diseases of a certain category of dangerousness or power (see appendix for a description of the various disease categories):  Up to 7th level: Category A diseases  From 8th to 12th level: Category C diseases and infectious lycanthropy (if treated before the first transformation during the full moon)  13th level and higher: Category C diseases and lycanthropy (the lycanthrope must receive remove disease and remove curse by a cleric of higher level and must also drink an infusion of wolfsbane and make a ST vs. Poison to not die) The disease categories are defined next for clarity, showing the penalties commonly associated to each and the methods of cure (also some minor diseases, like a cold or influenza, if not cured can cause serious damage and even paralysis). Category A: Debilitating disease. The disease imposes a –1 penalty to one or two characteristics or skills, or to the Attack Rolls for each day in which it isn’t cured. After the incubation period the subject has to make a ST vs. Death Ray: if successful, his constitution has defeated the disease by itself, otherwise he continues to suffer and can attempt a new ST to self heal only once per week. Recourse to medical cures (Heal or Medicine check) grants the subject an additional ST per week with a +1 bonus. When a patient is healed (herbs, medicines, successful ST), the penality disappears at the rate of 1 point per day; if using a spell, the penalty disappears instantly. The loss of characteristic points is temporarily, but if the characteristic drops to zero, the victim’s immunity system isn’t able to counter it and can only be cured with a spell. Based on the affected characteristic, the subject has the following limitations: Strength, Dexterity, or Constitution: movement impossible. Intelligence or Wisdom: impossible reason or express themselves correctly, constant delirium. A disease can be transmitted to another person if he is exposed to the infection carrier in the correct manner (contact, ingested, inhaled, or injury), which depends on the disease. The next victims are called to make the same Saving Throw to avoid the contagion, and if they fail suffer the same effects. Category B: Mortal disease. A mortal disease always imposes a –1 penalty to all the ST of the character during its course, and gives a penality that varies from –1 to –3 to two or three elements from among characteristics and Attack Rolls for each day in which it isn’t cured. Moreover, the rate of natural healing of the victim’s wounds is slower, half normal (for humans or humanoid creatures it is usually equal to Constitution bonus each day in situations of stress, 1d3 + Constitution bonus in situations of rest). The disease causes the character’s death when one of his characteristic scores reaches zero, unless the disease is naturally cured with outside help (the character doesn’t benefit from a ST to heal by himself) or magically. Any natural cure attempt incurs a –2 penalty to the skill check (Heal or Medicine). Category C: Naturally incurable mortal diseases An incurable mortal disease is a non transmissible disease similar to those of category B, with one substantial difference: any attempt with natural remedies automatically fails. Only magic is able to cure the disease before it is too late. The reverse spell, inflict disease, infects the victim with a disease, unless he makes a successful Saving Throw vs. Spells. The disease cannot be magically dispelled once created, but can only be cured with cure spells or natural remedies (where possible). Before it develops completely and inflicts considerable penalities, the disease remains dormant for a certain period (called the incubation period) during which the subject manifests slight symptoms that to the trained eye announces the type of malady that is acting on the organism. If the disease is cured normally or magically within the incubation period, the subject takes no damage. The type of disease that can be created depends on the cleric’s level (see above, with the exception of lycanthropy). For a more detailed list of the diseases on Mystara see appendix 5 (which includes for each the category, the type of infection that causes the contagion, incubation period, damage inflicted, and the period of year and region in which it is possible encounter cases of epidemics).\nReversible.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 28", "isCustom": false},
    "imm_resistance": {"id": "imm_resistance", "name": "Resistance", "level": 1, "casterType": "immortal", "range": "Touch", "duration": "6 turns", "effect": "+1 bonus to all ST", "area": "A creature", "description": "This spell protects the subject from danger by granting him a +1 bonus to all his ST for 6 turns.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 50", "school": "Abjuration", "isCustom": false},
    "imm_returning_weapon": {"id": "imm_returning_weapon", "name": "Returning Weapon", "level": 1, "casterType": "immortal", "range": "Touch", "duration": "1 turn per level", "effect": "A weapon or 10 projectiles", "area": "A weapon", "description": "The mage can cast this spell by touching any one weapon (usually a throwing weapon, like javelin, spear, trident, dagger, throwing hammer, etc.) or 10 projectiles (arrows, bolts, sling stones and so on). For the spell’s entire duration if the weapon is thrown and misses the target, it automatically returns, at the end of the same round, to the character’s hand. The latter is able to catch the weapon without any difficulty, unless he was paralysed, petrified, stunned, or immobilised in some other way in the intervening time; in this case, the returning weapon falls at the character’s feet. If instead the attack hits, if the natural d20 result is an odd number the weapon hits and falls to the floor (but can be still used as a returning weapon for the remainder of the spell’s duration), if the result is an even number the weapon hits and returns to the character’s hands. A returning arrow or projectile doesn’t function in the same way: indeed once, it hits it breaks and no longer returns, and so the spell ends on a successful hit.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 50", "school": "Transmutation", "isCustom": false},
    "imm_rocks_to_spiders": {"id": "imm_rocks_to_spiders", "name": "Rocks to Spiders", "level": 4, "casterType": "immortal", "range": "120 feet", "duration": "6 turns", "effect": "Transform 2d4 stones into poisonous spiders; reverse transform 2d4 spiders into stones", "area": "2d4 stones or rocks", "description": "This spell transforms 2d4 stones of any form and size into as many small-sized poisonous black spiders, which obey the cleric’s orders (the order is given mentally without taking up one of the cleric’s actions) and transformed back into stone at the end of the spell, or if killed. The spiders have the following characteristics: Black Widow: AC 6; HD 3; # Atk 1 bite; Damage 1d6 + poison (ST or death in 1 turn); MV 60/20; ST F2. The reverse spell, spiders to rocks, can be used to counter the effects of rocks to spiders, returning the rocks to normality, or against real. In this case, the spell affects 2d4 spiders of small size or smaller, and each of them must make a successful ST vs. Spells or take the form of a rock for 6 turns. The transformed spiders keep their own hp and acquire AC 5, and if damaged and their hp are reduced to zero, die and return to their normal form. If the cleric wants to, he can direct the spell against a single spider of any size. If the ST vs. Paralysis fails, the spider becomes a stone (if of Small size or smaller) or a large rock (if of Medium size or larger) for the spell’s duration, with the above specific conditions.\nReversible.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 70", "isCustom": false},
    "imm_rod_of_the_wyrm": {"id": "imm_rod_of_the_wyrm", "name": "Rod of the Wyrm", "level": 6, "casterType": "immortal", "range": "", "duration": "", "effect": "", "description": "Granted by an Immortal in the Tome of the Magic of Mystara Vol. 2 (Divine Magic), Appendix \"Additional spells of each Immortal\". The provided books (Tome Vol. 1-2, Rules Cyclopedia) do not describe this spell; ask your DM or use your own source.", "source": "Tome of the Magic of Mystara Vol. 2, Appendix (no description)", "isCustom": false},
    "imm_rot": {"id": "imm_rot", "name": "Rot", "level": 2, "casterType": "immortal", "range": "240 feet", "duration": "Permanent", "effect": "Rot wood, leather, cloth, and food", "area": "An object or living being", "description": "This spell must be cast on a single item of perishable matter or a series of victuals within 240 feet. The target then begins to rot (only magic items are allowed a ST vs. Destruction), and becomes unusable (although the item is totally rotten, a sail or rope with rotted parts will tear with the first pressure). The spellcaster can affect an item or some consumables of a maximum encumbrance of 50 cn (½ pound) per level.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 66", "school": "Transmutation", "isCustom": false},
    "imm_sacred_breath": {"id": "imm_sacred_breath", "name": "Sacred Breath", "level": 4, "casterType": "immortal", "range": "Touch", "duration": "Special", "effect": "A dragon can make an extra breath attack, another creature can create a dragon breath", "area": "One creature", "description": "This spell has different effects depending on if it was cast on dragons or other beings. When it is cast on a dragon, it allows the creature an extra breath (with the normal properties, damage, and dimensions) in respect to the number of permited breaths, within the next three hours. If instead it is cast on another being, the spell allows the subject to produce conical breath of magical fire, cold, or acid (chosen by the cleric who cast it) 60 feet long and 20 feet wide, which causes to all those in its path an amount of damage equal to the subject’s hp; they are allowed a ST vs. Dragon Breath for half damage. The breath must be used within 3 hours of the casting of the spell, and the spell ends when it is used. The spell cannot be cast again on the same subject until he has used the effect of the first spell. This effect cannot be made permanent.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 71", "isCustom": false},
    "imm_sacrilegious_influence": {"id": "imm_sacrilegious_influence", "name": "Sacrilegious Influence", "level": 4, "casterType": "immortal", "range": "120 feet", "duration": "Instantaneous", "effect": "Damage Lawful or Good creatures", "area": "20 feet radius circle", "description": "The priest calls a on the sacrilegious power of his own Immortal to punish his enemies. It manifests as a cloud of icy and nauseating darkness, and influences all creatures of Good or Lawful alignment, while Evil creatures are completely immune. The victims that find themselves in the cloud suffer 1d6 points of damage per cleric level (max 15d6 at 15th level) and risk being stunned for a round. It is possible to avoid the stun totally and halve the damage with a successful ST vs. Death Ray. The spell inflicts half damage to creatures that are neither Good nor Lawful, aren’t stunned, and can reduce the damage to a quarter with a successful Saving Throw. Example: a cleric of Nyx casts sacrilegious influence on a group of enemies, a LG cleric, a CG mage, a CN thief, and a N elf. Cleric and mage suffer the full effects of the spell (being Good or Lawful), while the thief and elf (neither Good or Lawful) automatically take half damage without the risk of being stunned, and can reduce the damage to ¼ with a ST.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 71", "isCustom": false},
    "imm_sanctuary": {"id": "imm_sanctuary", "name": "Sanctuary", "level": 1, "casterType": "immortal", "range": "Touch", "duration": "6 rounds + 1 round per level", "effect": "The subject is protected from enemy attacks", "area": "One creature", "description": "Anyone who receives this spell is surrounded by a protective aura that obstructs enemy attacks. Anyone who attempts to hit the subject protected by the sanctuary must make a ST vs. Spells each round in which he attacks: if successful, he can perform all his attacks for that round normally, otherwise it is impossible for him to damage the individual for that round, and loses all the attacks he intended to bring against him. Those that don’t try wound or attack the subject are not in the least affected by the spell. Sanctuary however doesn’t protect from attacks of a magic nature (spells or magic effects of any type), only from directed physical attacks (like those made with weapons of any type). If the protected character directly attacks, these can automatically counterattack for that round without making any ST, but the next round the protection returns if the subject stops attacking. Until the spell is dispelled or its duration expires, sanctuary continues to protect the subject each round.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 20", "isCustom": false},
    "imm_sand_storm": {"id": "imm_sand_storm", "name": "Sand Storm", "level": 4, "casterType": "immortal", "range": "360 feet", "duration": "1 round per level", "effect": "Evoke a sand storm", "area": "40 feet radius sphere", "description": "This spell can only be cast outside and creates a very strong storm of sand and dust in the area of effect (40 feet radius sphere within 360 feet of the cleric). Once released, the storm is independent and remains fixed to the area is was created in, but by concentrating the priest can push the storm at a speed of 40 feet per round, al long as it remains within his range of effect; while concentrating to move the storm the cleric can only move at half walking speed, without fighting or casting other spells. The storm automatically extinguishes all unscreened fires it meets, and those within the storm cannot fight or fly and must proced at half walking speed. The strong winds and the poor visibility impose a –5 penalty to any Observe or Listen check (or –25% to Hear noise). Each round the victim is within the storm he must make a successful ST vs. Spells to not be blinded for 1d4 rounds by the dust (blind creatures or constructs are immune to this effect), and are called to make a Balance check with a –2 penalty (or Dexterity at –6) to avoid falling over (in which case it wastes a round getting back up).", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 71", "isCustom": false},
    "imm_scourge_of_evil": {"id": "imm_scourge_of_evil", "name": "Scourge of Evil", "level": 4, "casterType": "immortal", "range": "120 feet", "duration": "Instantaneous", "effect": "Damage Evil or non Good creatures", "area": "20 feet radius circle", "description": "The priest calls upon the holy power of his Immortal to punish his enemies. It manifests as a shining cloud of changing colours, and affects all creatures of Evil alignment, while Good creatures are completely immune. The victims that find themselves in the cloud suffer 1d6 points of damage per cleric level (max 15d6 at 15th level) and risk being stunned for a round. It is possible to avoid all the stun and halve the damage with a successful ST vs. Death Ray. The spell inflicts half damage to creatures of any other alignment, which are not stunned, and can reduce the damage to a quarter with a successful Saving Throw. Example: a cleric of Maat casts scourge of evil on a group of enemies, a NE cleric, a CE mage, a CN thief, and a N dwarf. The cleric and mage suffer the entire effects of the spell (being Evil), while the thief and the dwarf (non evil) halved automatically with no risk of stun, and can reduce the damage to a quarter with the ST.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 71", "isCustom": false},
    "imm_scry": {"id": "imm_scry", "name": "Scry", "level": 4, "casterType": "immortal", "range": "Same plane of existence", "duration": "Concentration", "effect": "Mage sees and hears thing that happen in a remote area", "area": "A known place/being/object", "description": "This spell allows the spellcaster to concentrate on a specific location, object, or individual and to see and hear things that happen at the chosen location or in the area in which the selected item or person is through an image that materialises on a reflective surface at his disposal, as long as he maintains his concentration (images and sounds are visible and audible by anyone who is near the reflective surface). The distance to the selected target is irrelevant, but must be a known object or place (which he must of seen at least once), or if it is unknown, the spellcaster must have something that allows him to visualise the target (for example clothing or hat of the sought person, or a map of the place, or a drawing of the target object or creature). Whether it is an unknown or familiar place or item, the spellcaster must make an Intelligence check, whose roll receives a modifier based on his knowledge of the target and the available focus (see the tables below). If the check succeeds, he is able to visualise the target, otherwise the spell fails he cannot retry to visualise that target for the next 24 hours. Table 2.5: Modifier to the ST vs. Scry Knowledge Modifier None (Focus)* +6 Second hand (heard about) +3 First hand (encountered once) +0 Familiar (known for a time) −3 Focus Modifier Drawing or map −2 Personal item −4 Body part −6 Note: the modifiers listed in the table are cumulative. If the mage attempts to visualise a being, the creature benefits from a ST vs. Spells to avoid being located, to which is applied a modifier based on the spellcaster’s knowledge of the target and any focus he has (see the table above). If the ST succeeds, the spell fails and the mage cannot retry to visualise that being for the next 24 hours. Example 1: the mage Lyrandar attempts to visualise the place where his companion Sabine is held prisoner. He has a personal amulet of Sabine, but has no idea where she is. He must therefore resort to scrying by focusing on Sabine, who must make a ST vs. Spells with a −7 penalty (−3 as it is familiar to Lyrandar, to which is added −4 as he has a personal item). If Sabine’s ST fails, Lyrandar would be able to visualise his target, otherwise the spell has no effect and Lyrandar must wait 24 hours before retrying. Note that it is in Sabine’s interest to be found, the ST against the scrying is still needed. Example 2: the mage Alamon attempts to visualise the place where the thief is who stole his treasure. He doesn’t know who it is, but has one of his tools that he left behind. He has two possibilities: the first is to visualise a specific object that was part of his treasure (for example his wand of cold), the second is to scry the actual thief. Alamon initially tries to visualise the wand, and must make an Intelligence check (16) with a −3 bonus on his dice roll, as he is familiar with the wand. In this case therefore, he will only fail in the attempt with a 20 on the d20 roll (as 20−3 = 17). If he unfortunately failed, he could try to identify the scoundrel, but would have a final modifier to his ST equal to +2 (+6 as Alamon has never seen him and −4 as he has a personal item). If the base value of the ST was 10, the thief comfortably manage to not be identified by rolling 8 or more with a d20. As long as he continues to concentrate, the spellcaster can moved the visualised area by up to 360° each round (provided it remains fixed on the target). If the target is an object or individual, the area of the scrying is fixed above him and moves with him; if instead the target is a place, the spellcaster must select a specific point inside it as the scrying’s fixed area. The spell allows any potential magical senses to function through it (for example infravision, detect magic, ESP, or trueseeing), and the mage can cast spells into the area he is scrying only if it is in range of the spell in respect to his real position. Moreover, any environmental condition in the affected area also affects the vision or hearing of the spellcaster (for example darkness or silence impede his vision and hearing as normal, and he certainly cannot see past a wall unless he has X-ray vision available). Note that the spellcaster can also be affected by any sight or hearing based spell or magical affect present in the scryed area (like a symbol, the gaze of a basilisk, or a song that fascinates those that listen to it, etc.). 10 feet of stone, a thin layer of gold or lead, or a protection spell cast on the place (come magic sanctum) is enough to block the effects of this spell. Moreover, any individual protected by a mental barrier or by a spell that prevents remote viewing is revealed by this spell (it is as if effectively he wasn’t there), although the spellcaster can deduce his presence based on the reactions around him. This effect cannot be combined with permanency.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 103", "school": "Divination", "isCustom": false},
    "imm_searing_light": {"id": "imm_searing_light", "name": "Searing Light", "level": 4, "casterType": "immortal", "range": "240 feet", "duration": "Instantaneous", "effect": "Solar ray causes 1d6 +1 hp per level", "area": "A creature", "description": "This spell creates a dazzling ray of light that projects from the sky onto the victim chosen by the spellcaster, chemist be within 240 feet and in an open area, from where it is possible to see the sky (it is impossible to use underground or within enclosed buildings). The ray seems to come from the sun, and automatically strike the target, causing it 1d6 + 1 point of damage per caster level (max 20d6 +20 hp). The victim is allowed a ST vs. Spells for half damage, with the exception of undead: they always suffer the entire damage, without being able to reduce it.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 104", "school": "Evocation", "isCustom": false},
    "imm_seaweed_to_snakes": {"id": "imm_seaweed_to_snakes", "name": "Seaweed to Snakes", "level": 4, "casterType": "immortal", "range": "120 feet", "duration": "6 turns", "effect": "Transform up to 16 sticks or seaweed into venomous snakes, or a branch or coral into a constrictor snake; reverse transforms 2d8 snakes into seaweed/coral", "area": "2d8 seaweed or sticks or coral", "description": "This spell transforms 2d8 pieces of unworked wood or seaweed of medium size or smaller into as many sea snakes, which can be venomous (50% chance) and that die in 1d4 rounds if they are pulled out of the water. The created snakes obey the cleric’s orders (the order is given telepathically as a free action) and transform back to seaweed or wood at the end of the spell, or if killed. The sea snakes have the following characteristics: Sea snakes: AC 6, HD 1, # Atk 1 bite, Damage 1d4 (if poisonous, ST or cause others 1d4 hp), MV Swim 90(30), ST F1. Alternatively, the cleric can direct the spell on a single non-magical branch or coral that must be of at least Large size, transforming it into a powerful snake that obeys all his orders (as above) and that has the ability to constrict anf immobalise its victim. When the cleric orders the snakes to attack, it attempts to coil itself around the victim. If the Attack Roll succeeds and the victim is of equal size or smaller than the snake, it has to make a ST vs. Spells to avoid being immobilised. The constriction doesn’t inflict any, but the victim held in this manner is considered paralysed and cannot do anything until the snake is killed or magically dispelled, or the spell ends (or the cleric orders the snake to free the victim). The snake is also able to constrict enchanted creatures and those immune to normal or silver weapons, as long as they aren’t incorporeal. The branch or coral remains in this form for the spell’s duration, or until killed; if wounded, it can be cured normally. When the snake dies, is magically dispelled, or when the spell ends, it disappears, changing again to its original form; if the snake was killed, the branch or coral is reduced to a thousand pieces. The statistics of the snakes are the following: Constrictor snake: AC 5; HD 3 (hp 20); # Atk. 1 constriction; Damage: hold; MV 90(30); ST F3. The reverse spell, snakes to seaweed, can be used to counter the effects of seaweed to snakes, returning the seaweed or coral to normality, or against real snakes. In this case, the spell affects 2d8 snakes of medium size or smaller, and each of them must make a successful ST vs. Spells or take the form of seaweed per 6 turns. The transformed snakes keep their hp and acquire AC 9, and if damaged and lose all their hp, die and return to their normal form. If the cleric wants to, he can direct the spell against a single snake of any size. If the ST vs. Paralysis fails, it becomes a large piece of coral (if of Medium size or smaller) or coral reef (if it is Large size or larger) with AC 5 for the spell’s duration.\nReversible.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 72", "isCustom": false},
    "imm_second_sight": {"id": "imm_second_sight", "name": "Second Sight", "level": 4, "casterType": "immortal", "range": "Touch", "duration": "24 hours", "effect": "See beings invisible to mortal eyes", "area": "A creature", "description": "This spell allows the touched subject to see all the creatures that belong to the faerie races within 60 feet (invisible or magically transformed) in their true form and to clearly see all invisible things and creatures within 60 feet.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 104", "school": "Divination", "isCustom": false},
    "imm_secure_shelter": {"id": "imm_secure_shelter", "name": "Secure Shelter", "level": 3, "casterType": "immortal", "range": "0", "duration": "2d8 hours", "effect": "Sphere that shelters from inclement weather", "area": "5-foot radius sphere", "description": "This spell creates a 5 feet radius spherical bubble centred on the spellcaster that shelters anyone inside from the inclemencies. The sphere is intangible but opaque, and remains fixed to the place the mage cast the spell. The sphere can contain up to 10 standing creatures of Medium size or 6 lying down, and anyone can enter and leave at their liking without destroying it. The shelter vanishes only at the end of its duration, if it is magically dispelled, or if the mage leaves the sphere. As long as it is active, the shelter protects those inside it from external elements (rain, snow, hail, wind, sand, dust, etc.), and can survive winds of up to strong intensity (up to 40 mph), but stronger storms sweep it completely away, destroying the sphere. The temperature within the refuge is a constant 25°C if the external temperature is between 40°C and −10°C. If it is higher or lower, the interior temperature is raised or lowered from the standard by an equal number of degrees (for example if it is 45°C outside, or 5°C above the maximum limit, the internal temperature becomes 30°C). The interior of the sphere is dark, but the spellcaster can illuminate it by varying the intensity from that of a candle to that of a torch, or make it dark again with a simple thought (he can make one variation per round without having to concentrate). The surface is only opaque from the outside, but from within it is possible to see outside without any problem. This means that even if the sphere doesn’t offer any real obstacle to any ranged weapon, however those outside cannot see those within, who therefore enjoy a minimal protection against missiles and thrown weapons from outside (+2 bonus AC against ranged attacks). This effect cannot be combined with permanency.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 84", "school": "Abjuration", "isCustom": false},
    "imm_see_invisibility": {"id": "imm_see_invisibility", "name": "See Invisibility", "level": 2, "casterType": "immortal", "range": "0", "duration": "6 turns", "effect": "Detect invisible creatures within 10 foot x level", "area": "10 foot radius per level", "description": "When casting this spell, the mage becomes capable of clearly seeing all invisible creatures and objects within a range of 10 feet for each of his own levels (for example, a 3rd-level mage can use this spell to see anything invisible within 30 feet), until the end of the spell’s duration. The spellcaster is the only one who can see the invisible creatures or objects, and if he aids others attack invisible beings, by indicating the direction and movements of the enemy (without doing anything else that round), the Attack Roll penalty for fighting invisible creatures is reduced to –3, rather than –6.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 66", "school": "Divination", "isCustom": false},
    "imm_shadow_aura": {"id": "imm_shadow_aura", "name": "Shadow Aura", "level": 2, "casterType": "immortal", "range": "Touch", "duration": "1 turn per level", "effect": "Bonus to cover and hiding", "area": "One creature", "description": "This spell surrounds the touched and consenting subject with a dark aura similar to a cloud of smoke that partially hides his features and constantly follows him. Because of this aura, the subject can only be recognised with great difficulty (–4 to Intelligence checks, only granted to someone who has seen him previously), gains a 50% chance to Hide in Shadow constantly (see the thief skill of the same name), and any projectile or thrown weapon has a 25% chance of missing the target e qualsiasi proietto o arma scagliata ha almeno il 25%. The effect vanishes only at the end of its duration or if it is magically dispelled.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 57", "isCustom": false},
    "imm_shadow_door": {"id": "imm_shadow_door", "name": "Shadow Door", "level": 2, "casterType": "immortal", "range": "0", "duration": "Instantaneous", "effect": "Cleric passes from one shadow to another", "area": "Only the cleric", "description": "Once he has cast this spell, the cleric can enter one area of shadow and leave by another area of shadow within a 100 feet radius (as well as higher or lower) in a similar way as dimension door (4th level arcane). If there isn’t a large enough area of shadow (circumference equal to his chest) in the area, the passage doesn’t activate.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 58", "isCustom": false},
    "imm_shadow_monster": {"id": "imm_shadow_monster", "name": "Shadow Monster", "level": 4, "casterType": "immortal", "range": "30 feet", "duration": "1 round per level", "effect": "Create illusionary monsters", "area": "20 foot sided cube", "description": "Uttering this spell the mage uses some Shadow energy to create quasi-real illusions of creatures he knows, which follow his orders for the spell’s duration. The spell can create a maximum number of Hit Dice of monsters equal to the mage’s level, and if the spellcaster chooses to create more than one being, all the shadows must be of the same species. The maximum volume of creatable creatures is a 20 feet sided cube, and in the case of more beings created simultaneously, their total volume cannot exceed the area of effect. This means that it isn’t possible to give form to monsters with one of its dimensions greater than 20 feet (e.g. an ancient dragon). As the illusions are quasi real, the creatures only have 20% of normal hit points (for example a bear with 6 HD would only have 20% of 6d8 hp), and all 1 HD creatures only have 1 hp. The monsters see in the dark as if it was light, have all the typical physical attacks of the emulated creature as well as its Armour Class (the THAC0 depends on each creature’s HD), but their attacks only cause half real damage, and they don’t have any of the weak points (for example holy water for undead, fire for trolls etc.) or the typical immunities or special qualities (regeneration for trolls and vampires) of some creatures. As such its special attacks (gazes, energy drain, breath, etc.) aren’t real and don’t produce their pre-established effects, but the victims that believe in the illusion consequently behave as if they aren’t aware of the deceit. Example: a 5th-level fighter that sees a shadow vampire and fails his ST, believes that it is a true vampire, and if he is touched by it behaves as if he had lost 2 levels, until the being is destroyed or he becomes aware that it is only an illusion. If he then doesn’t have a +2 weapon, he will have difficulty attacking the vampire, knowing of its immunity to normal weapons. If however he attacks it and understands that it can be damaged, he then has the right to another ST to break the illusion, like if he sees the reaction if the vampire is hit with holy water. Each victim that encounters the shadow monster can make a ST vs. Mental Spells: if successful, he sees the creature as a transparent vision that has a vaguely smoky form, otherwise he believes in the illusion until ii is destroyed or dispelled. Those that understand the fiction only suffer 20% of the real damage, aren’t at risk of any of the monster’s special attacks and know that they can damage it with any weapon.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 104", "school": "Illusion", "isCustom": false},
    "imm_shadow_trap": {"id": "imm_shadow_trap", "name": "Shadow Trap", "level": 1, "casterType": "immortal", "range": "90 feet", "duration": "1d6 turns", "effect": "Victim anchored to the shadow cannot move", "area": "One creaturs", "description": "This spell prevents the designated victim that fails his Saving Throw vs. Spells from moving outside the radius of its own shadow. The victim can speak and move his limbs, but must always remain in contact with the shadow at his feet that instead remains fixed, and because of this he suffers a –2 penalty to all melee Attack Rolls, Armour Class, and Saving Throws for evadible effects. If he tries to leave the surface of the shadow he is held as if held by invisible ropes. It is however possible to move magically with spells of instantaneous transport (e.g. teleport) but not flight. The effect vanishes only at the end of its duration or if it is magically dispelled, and it is effective against any creature with a shadow.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 54", "isCustom": false},
    "imm_shadow_twin": {"id": "imm_shadow_twin", "name": "Shadow Twin", "level": 7, "casterType": "immortal", "range": "Touch", "duration": "Permanent", "effect": "Create an illusionary duplicate of a creature", "area": "A statue", "description": "This spell creates a partially real, illusionary duplicate of any creature. The double is initially sculpted as a statue with the appearance and similar size of the creature to be imitated (the material from which it is made is unimportant), and a small part of the target creature’s body is inserted into it (nails, hairs, scales, pieces of skin, etc.). Afterwards the spell is cast on the statue through a ritual that lasts one hour and includes the use of a special powder created by the mage that costs 1,000 gold pieces, which he sprinkles on the simulacrum. The ritual invests the statue with the energy of shadow, animates it, and makes it more similar to the objective. The statue doesn’t have to be a work of art: instead, the mage needs a good knowledge of the person or creature to imitate, as long as the illusion is plausible. The less familiar the mage is with the model the less the penalty to the Intelligence check that those that interact with the double have to notice its true nature. The shadow twin has the appearance of the target creature and half of its Hit Dice or Levels, similar physical abilities, but none of its special abilities, and average mental abilities (Intelligence, Wisdom, and Charisma equal to 10, and can only speak the languages known by the mage). It can be wounded normally and use any magic item not limited to spellcasters. It isn’t possible for the mage to reproduce a being that has more HD or Levels than his own. The double remains under the mage’s control and never acts to really damage him. However, no telepathic bond exists between the two, so the control must be exercised with direct commands. Every creature that interacts with the double for more than a couple of minutes can notice the fictional creature with an Intelligence check, with a modifier based on the mage’s familiarity with the target creature as follows:  Intimate (the mage knows the creature and has been close to it for at least a year): +5.  Generic (the mage knows the creature through study and having personally seen it several times): +2.  Occasional (the mage knows the creature through third hand descriptions or has seen it once): −2. Although it can be unmasked, the shadow twin can continue to act normally until it is reduced to zero Hit Points or less: in this case, it falls to the ground and permanently breaks apart. To repair an injured but not destroyed shadow twin requires a particular ritual, which only the mage that created it can perform. This ritual must be prepared in a magic laboratory, lasts 1 turn per Hit Point to recover, and needs rare materials, with a cost equal to 20 gold pieces per hp. The shadow twin is in all effect a magically controlled construct, and can also be destroyed through spells that dispel the magic. As long as it isn’t destroyed, it can continue to live with no need of food, water, or rest (although it can pretend to eat and sleep), and isn’t subject to aging effects. However, it isn’t immortal, and is subject to a progressive wear and tear that limits its existence to a hundred years before its total decline.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 162", "school": "Illusion", "isCustom": false},
    "imm_shape_coral": {"id": "imm_shape_coral", "name": "Shape Coral", "level": 2, "casterType": "immortal", "range": "Touch", "duration": "Permanent", "effect": "Shape 10 cubic feet of coral at will", "area": "10 cubic feet of coral per level", "description": "With this power the spellcaster is able to mould any piece of already existing coral to a form adapted to his aims. He can, for example, create a coral weapon, a statue, a frieze, or a common object. Any type of artistic intervention must be accompanied by a relevant skill check: if the character doesn’t have it, the work is always rather rough and approximate, without any artistic value. It isn’t possible to create a coral form with moving parts. Shape coral also allows the complete repair of coral objects within the area of effect, or the repair of large, damaged coral constructions at the rate of 1 SP per 5 caster levels, or change the form of a coral wall to create an exit where none exists (the dimensions of the opening must always be within the maximum that can be shaped).", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 58", "isCustom": false},
    "imm_shatter": {"id": "imm_shatter", "name": "Shatter", "level": 5, "casterType": "immortal", "range": "", "duration": "", "effect": "", "description": "Granted by an Immortal in the Tome of the Magic of Mystara Vol. 2 (Divine Magic), Appendix \"Additional spells of each Immortal\". The provided books (Tome Vol. 1-2, Rules Cyclopedia) do not describe this spell; ask your DM or use your own source.", "source": "Tome of the Magic of Mystara Vol. 2, Appendix (no description)", "isCustom": false},
    "imm_shocking_grasp": {"id": "imm_shocking_grasp", "name": "Shocking Grasp", "level": 1, "casterType": "immortal", "range": "Touch", "duration": "Instantaneous", "effect": "Causes 1d6 hp per level (max 5d6)", "area": "A creature", "description": "Casting this spell, the mage must touch a victim in the same round (the victim’s AC is calculated without his armour) and if the attack succeeds, automatically inflicts 1d6 points of electric damage per spellcaster level (max 5d6 hp at 5th-level), not halved by any Saving Throw. The touch inflicts an additional 1d6 damage if the victim is wearing metal armour or has a metal body.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 51", "school": "Evocation", "isCustom": false},
    "imm_siege_fire": {"id": "imm_siege_fire", "name": "Siege Fire", "level": 5, "casterType": "immortal", "range": "360 feet", "duration": "12 hours", "effect": "+4 to Attack Rolls and BV of war machines", "area": "A siege engine every two levels", "description": "When casting this spell, the mage selects a war machine (placed within range) for every two experience levels he has attained (for example, a 21st level mage can involve up to 10); by siege engines we only mean artillery pieces such as ballista, catapults, trebuchets, and other similar machines (excluding siege towers, rams, and so on). All the machines involved magically hurl their missiles with unusual precision (+4 bonus to the Attack Roll); if using the rules for siege warfare, the BV bonus granted by each artillery piece is increased by 4 points. Each machine can only receive one application of this effect. The enchanted siege weapons don’t work by themselves, but must be manoeuvred and loaded by artillerymen; if there is enough ammunition, the spell is wasteful. Siege fire can be magically dispelled, but each dispel magic only affects one war machine at a time.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 123", "school": "Transmutation", "isCustom": false},
    "imm_silence": {"id": "imm_silence", "name": "Silence", "level": 2, "casterType": "immortal", "range": "180 feet", "duration": "12 turns", "effect": "Silence in a 30 feet diameter sphere", "area": "15 feet radius sphere", "description": "This spell annuls any sound within a 30 feet diameter sphere, centered within 180 feet of the spellcaster. For 12 turns, in the area struck by the aforesaid effects it isn’t possible to emit any sound (hear, speak, or cast spells), nor can sounds from an external source penetrate the area of silence (those inside it are therefore are deaf and mute as long as they remain inside it). If cast against a creature or an object held in the hand or worn by an individual, the victim can make a Saving Throw vs. Spells to resist the effect: if successful, the silence is fixed to the area where the victim was at that moment, vice versa the sphere of silence moves with the victim. This spell can be magically dispelled; otherwise it ends after 12 turns. A remove deafness spell is useless against this magic effect, as it distorts sound waves and doesn’t directly affect the hearing apparatus of an individual.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 23", "isCustom": false},
    "imm_silver_tongue": {"id": "imm_silver_tongue", "name": "Silver Tongue", "level": 1, "casterType": "immortal", "range": "Touch", "duration": "1d6 turns + 1 turn per level", "effect": "Gain 1d4 extra points to a skill check to obtain favours or persuade someone", "area": "A creature", "description": "The beneficiary of this spell is able to speak in an incisive and convincing manner for the spell’s duration, gaining a 1d4 bonus to the value of all his language based skills (like Persuasion, Storytelling, Bargaining and so on) when it is used in conversation. This bonus is only applied to persuade intelligent beings (not animals) or obtain their attention and/or favour (therefore, it can also be used with a simple Charisma check if the creature lacks the appropriate skill).", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 51", "school": "Enchantment", "isCustom": false},
    "imm_sixth_sense": {"id": "imm_sixth_sense", "name": "Sixth Sense", "level": 4, "casterType": "immortal", "range": "0", "duration": "24 hours", "effect": "Warns of attempts of magical scrying", "area": "10 foot radius", "description": "This spell allows the mage to instantly know of any attempts of magical scrying that happen within a 10 feet radius (although it doesn’t protect him from it). The spell’s area of effect moves with him and he is able to locate the precise position of the scrying sensor if it is within the area. Moreover, if the observer is on the same plane, the spellcaster can try to see him. Both roll 1d20 and add their level and Intelligence bonus: if the spellcaster obtains the higher value he is able to see for one round those observing him, and knows how far it is from his current position; if instead it is the observer who wins, he notices that he has been discovered.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 105", "school": "Divination", "isCustom": false},
    "imm_skin_of_amber": {"id": "imm_skin_of_amber", "name": "Skin of Amber", "level": 5, "casterType": "immortal", "range": "0", "duration": "12 turns", "effect": "Immunity to normal weapons and petrification", "area": "Only the cleric", "description": "The skin of the cleric assumes the colour (but not the consistency) of amber, while hair, nails, teeth, scales, and all other body parts other than skin also become amber, but with different tonality and brightness. As long as the spell lasts, the cleric becomes immune to normal and silver weapons, including projectiles and natural weapons, of any size and dimension; which means that a normal projectile cannot damage the cleric not even if fired from a magical missile weapon (e.g. a normal arrow fired from a +4 bow bounces off the cleric’s skin: to damage requires a magic arrow). The cleric is moreover immune to any form of petrification. Note that a magical weapon without a bonus is sufficient (e.g. a blessed weapon) to damage a character protected by skin of amber, and he is also vulnerable to falling damage. Finally, the natural attacks of particularly potent monsters are always considered magical: normally, any monster that can only be hit with magic weapons itself hits as a weapon with magic bonus related to its own (e.g. the natural attacks of a nightshade, which can only be wounded by +2 weapons or better, are considered +2 weapons).", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 76", "isCustom": false},
    "imm_slow_time": {"id": "imm_slow_time", "name": "Slow Time", "level": 3, "casterType": "immortal", "range": "120 feet", "duration": "1 day per level", "effect": "Victim loses the Initiative, is always surprised, and has a penalty to Attacks, ST, and number of attacks", "area": "1 being", "description": "This spell causes a loss of the sense of time in the selected victim if he fails a ST vs. Spells. The subject is incapable of correctly registering the passage of time and is constantly slow in respect to his timekeeping and other actions. In practice, the creature automatically always loses the Initiative, is constantly surprised (any ability to negate surprise is annulled), acquires a –1 penalty to all his Attacks against moving creatures and to his ST against avoidable effects, and if he has multiple attacks available he loses one, as long as the spell’s effects continue and aren’t dispelled. Finally, any action of the subject’s based on accurate timing fail (e.g. intercept a moving object, get on a moving cart, etc.).", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 64", "isCustom": false},
    "imm_snake_sigil": {"id": "imm_snake_sigil", "name": "Snake Sigil", "level": 3, "casterType": "immortal", "range": "Touch", "duration": "Special", "effect": "Protect writing with a sigil that immobilises anyone trying to read it", "area": "A written work", "description": "When the spellcaster casts snake sigil on a writing that must contain at least twenty words (like book page, scroll, or a series of runes etched on stone or another surface) a small symbol appears that mixes with the words. When this text is read and the reader comes to the symbol, it is activated and takes the form of a snake, which throws itself at the reader biting him (as long as the reader is within 10 feet of the writing). Simply looking at the text isn’t enough to activate the sigil: it needs to be deliberately read. The reader has the right to a ST vs. Spells to avoid the effects of the sigil: If the ST succeeds, the snake of energy dissipates without further effect, and the symbol disappears from the writing in a puff of smoke. Otherwise if the ST fails, the subject is engulfed in a force field that shines with an amber light and immobilises him until he is freed by the order of the sigil’s creator, the spell is dispelled, or after a period of time equal to 1 day per spellcaster level. Within the invisible force field the subject doesn’t age, nor does he need to eat, sleep, or breathe. He is kept in a state of suspended animation without being able to take account of what is happening around him or can in any way move. The victim can however be damaged by external forces, seeing as the forcefield doesn’t offer any protection against physical attacks, although it renders him immune to any type of mental attack. The sigil cannot be detected by a normal search without activating it, and spells like detect magic only reveals that the text shines with arcane magic. It remains on the writing until activated or magically dispelled.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 85", "school": "Conjuration", "isCustom": false},
    "imm_solar_ray": {"id": "imm_solar_ray", "name": "Solar Ray", "level": 2, "casterType": "immortal", "range": "10 feet per level", "duration": "1 round per level", "effect": "Creates sunbeams; reverse creates moonbeams", "area": "20 foot diameter cylinder", "description": "This spell makes a ray of sunlight appear that descends from the sky until it strikes the point chosen the spellcaster within range. The ray is a cylinder of 20 feet diameter that seems to come from the sky (or from the ceiling, if the spellcaster is in an enclosed place). Inside the illuminated area, it appears as if it was day, although those outside apply the normal environmental conditions (gloom, shadow, etc.). The spellcaster can moreover move the illuminated area each round by pointing his finger to the desired place, staying within the limit of the spell’s range. The creatures that don’t tolerate sunlight attempt to escape the area of effect, and if they make a successful ST vs. Wands it means they were able to move before being illuminated. Those that fail their ST must endure some penalty due to the sunlight until they are able to escape the illuminated area. In particular undead vulnerable to sunlight (like vampires, shadows, nightshades, etc.) suffering 2d6 points of damage for every round spent illuminated by the solar ray. The reverse spell, moonbeam, creates a ray of moonlight that descends to illuminate the fixed area. The ray is a cylinder of 20 feet diameter that seems to come from the sky (or from the ceiling, if the spellcaster is within an enclosed place). Inside the illuminated area it appears as if it was day, although those outside apply the normal environmental conditions (darkness, shadow, sun, etc.), and moonbeam doesn’t impede infravision. The spellcaster can moreover each round move the illuminated area by pointing his finger at another location, without leaving the range of the spell. All the lycanthropes within the moonbeam’s area of effect must make a successful ST vs. Spells or be forced to instantly assume their animal form, which they must remain in until they leave the area of effect.\nReversible.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 69", "school": "Evocation", "isCustom": false},
    "imm_speak_with_animals": {"id": "imm_speak_with_animals", "name": "Speak with Animals", "level": 2, "casterType": "immortal", "range": "30 feet", "duration": "6 turns", "effect": "You can converse with one type of animal", "area": "An animal species", "description": "When casting this spell, the cleric must also specify the type of animal that he wants to speak to (e.g. bats, wolves, bears, etc.), but not fantastic or intelligent animals (the animal must have an Intelligence of 1 or 2). For the spell’s duration, the cleric can speak to all the animals of the chosen within 30 feet: he is able to understand their cries, and they know his language, while any other listener simply hears the spellcaster express himself in animal cries. The creatures’ reactions are usually favourable (+2 bonus to reaction rolls), and the cleric can ask them a favour. The favour must be understandable to the animal and must be something it is capable of doing: it must be an order that it will do without protest, and the DM is the final arbiter of the animal’s behaviour.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 121", "druidSpell": true, "isCustom": false},
    "imm_spear_of_thorns": {"id": "imm_spear_of_thorns", "name": "Spear of Thorns", "level": 1, "casterType": "immortal", "range": "0", "duration": "2 rounds per level", "effect": "Creates a spear replete with thorns", "area": "N/A", "description": "With this spell the druid creates a spear made of thorns that can be used in melee or thrown. The spear lasts for 2 rounds per level before vanishing and can be used normally be the druid and any other creature he gave it to. The spear causes 1d8+1 damage + Strength bonus, and mastery with the spear can be used to augment its effect. If thrown at a target, it automatically hits and causes an additional 1d6 damage, before vanishing. The spear of thorns is however not considered a magic weapon and can be dispelled.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 119", "druidSpell": true, "isCustom": false},
    "imm_spell_acceleration": {"id": "imm_spell_acceleration", "name": "Spell Acceleration", "level": 6, "casterType": "immortal", "range": "", "duration": "", "effect": "", "description": "Granted by an Immortal in the Tome of the Magic of Mystara Vol. 2 (Divine Magic), Appendix \"Additional spells of each Immortal\". The provided books (Tome Vol. 1-2, Rules Cyclopedia) do not describe this spell; ask your DM or use your own source.", "source": "Tome of the Magic of Mystara Vol. 2, Appendix (no description)", "isCustom": false},
    "imm_spell_turning_barrier": {"id": "imm_spell_turning_barrier", "name": "Spell Turning Barrier", "level": 7, "casterType": "immortal", "range": "", "duration": "", "effect": "", "description": "Granted by an Immortal in the Tome of the Magic of Mystara Vol. 2 (Divine Magic), Appendix \"Additional spells of each Immortal\". The provided books (Tome Vol. 1-2, Rules Cyclopedia) do not describe this spell; ask your DM or use your own source.", "source": "Tome of the Magic of Mystara Vol. 2, Appendix (no description)", "isCustom": false},
    "imm_sphere_of_invisibility": {"id": "imm_sphere_of_invisibility", "name": "Sphere of Invisibility", "level": 3, "casterType": "immortal", "range": "0", "duration": "Special", "effect": "Beings within 10 feet of the mage become invisible", "area": "10 foot radius", "description": "This spell not only renders the caster invisible, but also all those that, at the moment it was spoken, are within a 10 feet radius of the mage. The area of invisibility afterwards moves with the spellcaster, and those that remain inside are hidden from all others (although they can see each other). Those (and only those) that move more than 10 feet away from the mage, or attack a target, become visible and cannot become invisible again even if they re-enter the area of effect. If the spellcaster attacks or casts a spell, the invisibility ends for everyone. For all its other effects, this spell is identical to the 2nd level invisibility spell.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 85", "school": "Illusion", "isCustom": false},
    "imm_sphere_of_security": {"id": "imm_sphere_of_security", "name": "Sphere of Security", "level": 7, "casterType": "immortal", "range": "0", "duration": "6 turns", "effect": "Barrier gives –2 to AC, +2 to ST and magic resistance of 50% plus three other defensive powers", "area": "10 feet radius sphere", "description": "This powerful spell protects the priest and all allies present within the area of effect, granting them a +2 bonus to AC and all Saving Throws, as well as a resistance to magic equal to 50%. Moreover, the cleric can select three defensive clerical spells of levels 1 to 5 that have effect for all of the sphere’s duration on him and on his allies present in the sphere of security. Any hostile creature doesn’t receive this protection, and the sphere moves with the priest. The cleric’s allies that leave the sphere no longer enjoy its benefits, but reacquire it once they return to the area of effect.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 85", "isCustom": false},
    "imm_spider_climb": {"id": "imm_spider_climb", "name": "Spider Climb", "level": 1, "casterType": "immortal", "range": "30 feet", "duration": "1 turn per level", "effect": "The creature can climb walls like a spider; reverse make a being slip", "area": "A creature", "description": "This spell allows all those that receive it to climb walls, climbing on vertical surfaces or walking on the ceiling exactly like a spider. The affected creature must have hands and feet well supported on the surface, without holding anything in the hands; if one of the limbs slips from the surface, the subject immediately falls. The individual moves at half normal speed and cannot carry objects or people that cause him to exceed his maximum encumbrance. A strong wind (25 mph) or a creature with at least 18 Strength can pull the subject from the surface.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 52", "school": "Transmutation", "isCustom": false},
    "imm_spidershape": {"id": "imm_spidershape", "name": "Spidershape", "level": 3, "casterType": "immortal", "range": "0", "duration": "1 turn per level", "effect": "Cleric becomes a spider or moveslike a spider", "area": "Only the cleric", "description": "When casting this spell, the cleric can select one of the three effects listed below. The spellcaster can return to his own frm when he wants, but this ends the spell. Spider Form: the cleric is transformed into small, innocuous black spider of about 1 inch in length (all his equipment melds into him and is unusable), and gains all the spider’s natural abilities, in particular the ability to climb vertical surfaces and the certainty to pass unnoticed in most situations. The cleric keeps his personality and mental faculties, AC, ST, THAC0, and Hit Points. In the new form he moves at a speed of 30(10) (even vertically or on webs), can only make one attack per round (inflicting 1 hp of non-lethal damagewith his bite due to a mild poison), and can spin about 36 in2 of web. The cleric cannot cast spells, or use any type of item in his new form. Giant Spider Form: the cleric is transformed into a black spider of Large size about 10 feet wide (all his equipment melds into him and is unusable), with his front legs fortified with razor-like claws. In his new form, the cleric keeps his own personality and statistics, moves at a speed of 120 (40) feet (even vertically), can make one attack per round with his bite (inflicting 2d6 points of damage + 1d8 hp from posion; the victim can make a ST vs. Poison to completely avoid the effects) and an aatack with each of his fron legs (each successful hit does 1d8 damage). The cleric can speak and cast spells in the new form but cannot use items. Spider Movement: the cleric isn’t transformed but is able to move at normal speed on webs without getting stuck, on smooth vertical walls with the same ease as a spider, with no chance of falling, unless he is violently pulled off (opposed Strength check).", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 64", "isCustom": false},
    "imm_spirit_armour": {"id": "imm_spirit_armour", "name": "Spirit Armour", "level": 4, "casterType": "immortal", "range": "0", "duration": "2 rounds per level", "effect": "Barrier offers AC 3 and +3 to ST vs. Spells", "area": "Only the spellcaster", "description": "Upon uttering this spell, the spellcaster’s body is engulfed by an emanation of his own lifeforce that assumes the form of a gleaming aura (white for Lawful, blue for Neutral, red for Chaotic). This magic barrier gives the spellcaster AC 3 and a +3 bonus to all ST vs. Spells. This armour isn’t encumbering and doesn’t interfere in any way with movement or the casting of spells. However, it cannot be hidden, as it always shines around the mage’s body. When the armour vanishes (at the spell’s end or if it is magically dispelled), the mage must make a ST vs. Spells: if he succeeds, there are no other effects, otherwise he loses the life energy he invested in creating the protective aura, or 1d6 hit points. These points can only be regained through magical healing.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 106", "school": "Abjuration", "isCustom": false},
    "imm_spiritual_bond": {"id": "imm_spiritual_bond", "name": "Spiritual Bond", "level": 4, "casterType": "immortal", "range": "Touch", "duration": "1 hour per level", "effect": "Cleric enters the body of a brother", "area": "A cleric of the same cult", "description": "This spell can be cast only on another priest that belongs to the same faith as the cleric and consents. Once touched, the second cleric becomes a host for the spirit of the priest who cast spiritual bond, who can repeatedly leave and enter his own body as long as the spell lasts. The cleric remains in himself until he wants to establish a contact with the host: in this case, he enters a trance, his body remains inert and his spirit is transfered to the host body, of whom he can exploit all five senses and with whom he can communicate telepatically. The cleric can repeatedly enter the host and return to his own body while the spell is active. There is no limit to te distance between the cleric and host as long as this link exists, as long as they are both on the same plane and not in an anti-magic zone. If he wants to moreover, the cleric can take possession of the host’s mind and control its body. However, if the host refuses to take part, he can make a ST vs. Spells, and if successful, the spell ends. If the ST fails or the host consents, the cleric is able to use the host’s body exploiting all its abilities and memories (so can also cast its spells), but cannot give knowledge or abilities to the host. While dominating the host body the cleric uses his Intelligence, Wisdom, and Charisma scores, while using the host’s Strength, Dexterity, and Consitution values. The cleric can release control of the host’s body when he wishes. Each time he is wounded while controlling the host’s body, the cleric must make a ST vs. Mental Spells: if the ST fails, the spell is broken and the emotive shock from the pain is also transmitted to the, which loses 1d6 hp. If the host body is reduced to below zero Hit Points, it dies and the cleric must make a ST vs. Death Ray or perish himself; if the ST succeeds, he is returned to his original body and stunned for a minute.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 77", "isCustom": false},
    "imm_squall_of_wind": {"id": "imm_squall_of_wind", "name": "Squall of Wind", "level": 4, "casterType": "immortal", "range": "120 feet", "duration": "Instantaneous", "effect": "Explosion of air that extinguishes fires, blinds for 1 round and causes 1d4 hp per level (ST for half)", "area": "10’ radius sphere", "description": "This spell creates an explosion of comprised air in a 10 feet radius area within 120 feet of the druid. The explosion can extinguish any open flame (candle, torch, campfire, etc.) present in the area of effect, and has a 50% chance of extinguishing protected flames. Moreover, the wind lifts dust, scraps, twigs, and leaves, blinding those in the area of effect for 1 round, and moreover causes 1d4 points of damage per druid level (max 20d4 hp at 20th level) to the creatures present because of the sudden pressure: a successful ST vs. Spells halves the damage and avoids being suddenly thrown to the ground. If used underwater, the spell has the same blinding effect, but automatically causes half damage (it isn’t however possible to reduce it further).", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 124", "druidSpell": true, "isCustom": false},
    "imm_steal_the_breath": {"id": "imm_steal_the_breath", "name": "Steal the Breath", "level": 3, "casterType": "immortal", "range": "120 feet", "duration": "4d4 rounds", "effect": "All the creatures within the area of effect faint", "area": "20 x 20 x 10 ft. volume", "description": "When the spellcaster casts this spell, he selects an area of 20×20×10 feet within 120 feet: all the beings within the area must make a successful ST vs. Spells or they cannot breathe and fall unconscious for 4d4 rounds, during which they cannot be revived; only a dispel magic spell can interrupt the spell before its duration ends. The spell obviously has no effect on creatures that don’t need to breathe to survive, like undead, elementals, oozes, and constructs.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 85", "school": "Necromancy", "isCustom": false},
    "imm_steelskin": {"id": "imm_steelskin", "name": "Steelskin", "level": 7, "casterType": "immortal", "range": "Touch", "duration": "1 turn per level", "effect": "AC 3 and subtract 6 points from each wound", "area": "A creature", "description": "Thanks to this potent spell, the skin of the touched subject becomes as thick as steel and assumes a silvery colour. The spell gives the subject AC 3 and protects him by subtracting 6 points of damage from each attack, except for acid and sonic attacks, which ignore the armour’s resistance. Example: a fighter attacks the mage protected by this spell, causing 16 hp with the first attack and 5 hp with the second. The mage, thanks to steelskin only suffers 10 hp of damage, as the first hit only does (16-6) = 10 hp and the second results in (5-6) = 0 hp suffered. The beneficial effects of this spell aren’t cumulative with other spells that modify a subject’s skin (the best affect is applied). The effect cannot be combined with permanency.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 163", "school": "Abjuration", "isCustom": false},
    "imm_sticks_to_flying_vipers": {"id": "imm_sticks_to_flying_vipers", "name": "Sticks to Flying Vipers", "level": 4, "casterType": "immortal", "range": "120 feet", "duration": "6 turns", "effect": "Transform up to 2d4 sticks into venomous flying vipers; reverse transform vipers into sticks", "area": "2d4 sticks or branches", "description": "This spell transforms 2d4 sticks or pieces of wood of Medium size or smaller into as many flying vipers, the created snakes obey the cleric’s orders (the order is given telepathically as a free action) and transform back to seaweed or wood at the end of the spell, or if killed. The flying vipers have the following characteristics: Flying viper: AC 6; HD 2; # Atk 1 bite or 1 spit (up to 10ft.); Damage 1d6 or 1d4 + poison (ST or cause another 2d4 hp); MV 60/20, Fly 300/100; ST F1. The reverse of the spell, vipers to sticks, functions like snakes to sticks, but also affects flying vipers.\nReversible.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 72", "isCustom": false},
    "imm_stone_hands": {"id": "imm_stone_hands", "name": "Stone Hands", "level": 2, "casterType": "immortal", "range": "Touch", "duration": "1d6 rounds + 1 round per level", "effect": "Arms become stone giving +4 to Strength and causing 1d6 damage", "area": "A creature", "description": "This spell transforms the hands and arms of the touched subject into solid stone and gives him a +4 bonus to his Strength (or takes it to 12, if the bonus gives a lower score). If he uses his own hand to attack, it causes 1d6 plus his Strength bonus in damage. For the spell’s duration, it is possible to use the hands normally, except that to the touch they are completely of stone. Finally, due to the poor flexibility of the fingers and arms there is always a 10% failure chance of casting any spell and it is also impossible to perform dexterous operations with the hands (for example picking pockets, conjuring tricks, or playing instruments).", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 68", "school": "Transmutation", "isCustom": false},
    "imm_stone_shape": {"id": "imm_stone_shape", "name": "Stone Shape", "level": 4, "casterType": "immortal", "range": "", "duration": "", "effect": "", "description": "Granted by an Immortal in the Tome of the Magic of Mystara Vol. 2 (Divine Magic), Appendix \"Additional spells of each Immortal\". The provided books (Tome Vol. 1-2, Rules Cyclopedia) do not describe this spell; ask your DM or use your own source.", "source": "Tome of the Magic of Mystara Vol. 2, Appendix (no description)", "isCustom": false},
    "imm_succour": {"id": "imm_succour", "name": "Succour", "level": 7, "casterType": "immortal", "range": "Touch", "duration": "Special", "effect": "Transport a creature to a fixed point or the mage next to whoever has the focus", "area": "An object", "description": "With this spell the mage gives to an item previously prepared with a special ritual (which costs 1,000 g.p.) one of the two following abilities: automatically transport the subject to the place where the object is when the item is broken or the command word chosen by the mage is spoken (provided they are both on the same plane); automatically transport whoever broke the item or spoke the command word to a prefixed spot chosen by the mage (provided they are both on the same plane). The individual or the mage is transported with all his equipment worn when the succour activated, and at that point the spell ends. If one of the subjects is dead, it will be his corpse that is transported next to the item, while if the item or mage is in an anti-magic area when the effect is activated, or in a place protected against magical transport, the spell has no effect and is wasted. A dispel magic has the normal chance to annul the succour cast on the item.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 163", "school": "Conjuration", "isCustom": false},
    "imm_suggestion": {"id": "imm_suggestion", "name": "Suggestion", "level": 3, "casterType": "immortal", "range": "30 feet", "duration": "Special", "effect": "Victim is urged to follow an action", "area": "1 living being", "description": "With this spell, the spellcaster identifies a victim, who must make a successful ST vs. Mental Spells if he wants to totally avoid all the effects. If however the ST fails, the spellcaster can influence the victim’s actions suggesting to him with a single phrase a certain action. To have effect, the suggestion must be sent to the victim by the mage within an hour of the spell’s casting. The suggestion must be spoken in a way to make it seem a reasonable action and the victim must be able to understand the language in which it was given. If the suggestion seems forced or dangerous to the victim, the charm instantly vanishes. Suggestion cannot alter the perception of reality (asking a person to throw himself into a gorge spread out before him where in reality the gorge doesn’t exist for example is an impossible attempt), but can alter the victim’s mental state or predisposition to someone (for example asking a dragon to not attack before it has heard what the spellcaster has to say or asking a giant to stop fighting and to ally himself with them to destroy a much worse threat). The suggested action can take up to a maximum of 1 hour per mage level, or until it is completed. The spellcaster can also specify certain conditions that activate an action as long as the spell is active (for example suggest to a knight to give his warhorse to the first person that passes); if the condition isn’t met within the spell’s duration, the suggestion is wasted.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 85", "school": "Enchantment", "isCustom": false},
    "imm_summon_air_elemental": {"id": "imm_summon_air_elemental", "name": "Summon Air Elemental", "level": 5, "casterType": "immortal", "range": "240 feet", "duration": "Concentration", "effect": "Summon a 16 HD elemental", "area": "An elemental", "description": "This spell allows the spellcaster to summon an elemental from its native plane. As long as the spellcaster concentrates, the elemental performs each task it is given to the best of its power (like carry items or people, attack, defend the spellcaster, watch a place or person, etc.). The elemental’s statistics are based on the type of elemental, but all summoned elementals are 16 feet tall and take the form of legless humanoids, with a torso, head, and arms made of its own element. Each elemental inflicts an additional 1d8 damage to creatures that it fights in its habitat (air, earth, fire, or water): Air Elemental: AC –2; HD 16; MV fly 360(120); # Atk. 1 punch; Damage 3d8; ST F16; AL N; Immunity to normal weapons, make beings with 2 HD or less automatically fall (ST vs. Spell avoids); Receives double damage from earth elementals (ST vs. Death Ray for normal damage) and minimum damage from water elementals; cannot pass through a barrier of earth thicker than 1 foot. Earth Elemental: AC –2; HD 16; MV 60(20) or tunnel 90(30); # Atk. 1 punch; Damage 3d8; ST F16; AL N; Immunity to normal weapons; Receives double damage from fire elementals (ST vs. Death Ray for normal damage) and minimum damage from air elementals, cannot pass through a barrier of fire thicker than 6 feet. Fire Elemental: AC –2; HD 16; MV 120(40); # Atk. 1 punch; Damage 3d8; ST F16; AL N; Immunity to normal weapons, inflicts +1d8 points of damage to creatures of cold or water; Receives double damage from water elementals (ST vs. Death Ray for normal damage) and minimum damage from earth elementals, cannot pass through a barrier of water thicker than 6 feet. Water Elemental: AC –2; HD 16; MV 60(20) or swim 180(60); # Atk. 1 punch; Damage 3d8; ST F16; AL N; Immunity to normal weapons, inflicts +1d8 points of damage to creatures of fire; Receives double damage from air elementals (ST vs. Death Ray for normal damage) and minimum damage from fire elementals; cannot pass through a barrier of air thicker than 6 feet. To keep control of the elemental, the spellcaster cannot fight, cast spells, or use magic items, but can walk at half normal speed and speak; if for any reason the concentration is interrupted (for example if he is injured), the domination of the elemental is lost and cannot be re-established with this spell. Uncontrolled elementals try to kill those that summoned them and attack anyone that places themselves between them and their target and its target. As long as the elemental remains under the summoner’s control, the latter can return it to its home plane with simple concentration; if instead, it is uncontrolled, it can be returned to its own plane with a dispel magic, destroy evil, exile, or banish spell. It should be noted that defeating magically created or summoned creatures doesn’t grant the xp related to them until whoever summoned them has also been defeated.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 124", "school": "Conjuration", "isCustom": false},
    "imm_summon_fire_elemental": {"id": "imm_summon_fire_elemental", "name": "Summon Fire Elemental", "level": 5, "casterType": "immortal", "range": "", "duration": "", "effect": "", "description": "Granted by an Immortal in the Tome of the Magic of Mystara Vol. 2 (Divine Magic), Appendix \"Additional spells of each Immortal\". The provided books (Tome Vol. 1-2, Rules Cyclopedia) do not describe this spell; ask your DM or use your own source.", "source": "Tome of the Magic of Mystara Vol. 2, Appendix (no description)", "isCustom": false},
    "imm_summon_horned_skull": {"id": "imm_summon_horned_skull", "name": "Summon Horned Skull", "level": 5, "casterType": "immortal", "range": "240 feet", "duration": "6 turns", "effect": "Summon a horned skull", "area": "N/A", "description": "This spell allows the cleric to summon a horned skull, a minor demon sacred to the Immortal Alphaks. It has the appearance of a floating skull about 20 inches wide, with two curved, pointy horns; the hollow eye sockets shine with an evil reddish light, and from time to time the monster emits a guttural and sinister scream, or suddenly closes its jaw with a dry and threatening noise. Horned Skull: AC –2; HD 10; hp 70; MV 120(40) fly; # Atk. 1 bite/1 horn or 1 breath; Damage 1d8/2d6 or 10d6; ST F10; AL C; considered a minor demon (an enchanted and planar monster); Special abilities: immune to fire, poison, gas, and mental spell; only damaged by at least +11 magic weapons; can breathe, once per turn, a vortex of fire 30 feet long × 5 feet diameter: creatures in the area suffer 10d6 points of fire damage, but can make a ST vs. Dragon Breath for half. The horned skull can only be summoned if a source of fire is present within within 240 feet, from which the skull emerges. It blindly obeys to the best of its ability any orders given it by its summoner, with which it is in telepathic contact, and disappears after 6 turns, or if killed, dispelled (with dispel magic), or banished (with dispel evil, banish, and similar spells). Defeating magically created or summoned creatures grants no xp unless their evoker is also defeated.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 77", "isCustom": false},
    "imm_summon_lycanthrope": {"id": "imm_summon_lycanthrope", "name": "Summon Lycanthrope", "level": 4, "casterType": "immortal", "range": "30 feet", "duration": "3 turns", "effect": "Summon upto 2 HD × level of lycanthopes; reverse drive away upto 2 HD × level of lycanthopes", "area": "Up to 2 HD x level of lycanthrope", "description": "This spell allows the spellcaster to summon upto 2 HD per level of any type of lycanthope he knows, as well as mixed types (e.g. a 12th level cleric can summon 24 HD of lycanthropes, equal to 4 werewolves of 4 HD each, 1 wearbear of 6 HD, and a 2 HD wererat). The creatures appear at any point within range and obey the cleric’s orders, which can send them anywhere to do his bidding. They appear in animal form and cannot return to human form for any reason (if placed under a spell that attempts to force this transformation they are paralysed for a round and then continue). The lycanthropes remain in telepathic contact with the priest until the spell’s end, and return to their place of origin if killed or the effect is dispelled or terminated. Anytime a lycanthrope is killed, the cleric must make a ST vs. Mental Spells to not be stunned for 1 round because of the psychic backlash. The reverse spell, repel lycanthropes, forces a total of Hit Dice of lycanthropes equal to double the cleric’s level within the area of effect to flee scared from the area if they fail a ST vs. Mental Spells. Those that resist still have a –1 penalty to all their rolls against the priest for 24 hours.\nReversible.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 72", "isCustom": false},
    "imm_summon_refuge": {"id": "imm_summon_refuge", "name": "Summon Refuge", "level": 4, "casterType": "immortal", "range": "120 feet", "duration": "1 hour per level", "effect": "Create a stone or wooden dwelling", "area": "Habitation of max surface of 60 sq.ft. × lvl", "description": "This spell creates from nothing a cottage of wood and stone in which it is possible to rest. The building can only be created in an empty flat space, and its effective dimensions as well as it form are decided by the mage to his liking, as long as the house has just one floor. The habitation is 10 feet high, has one door, two or more windows and a fireplace, and can be subdivided into a maximum of five rooms separated by wooden walls with doorless openings. The door and all the windows are protected by a wizard lock spell worked by its creator, while the fireplace is protected by a grate from any intrusion. The house has 8-inch thick walls and roof, a number of Structural Points equal to the mage’s level, and its resistance is similar to stone in regards to its Armour Class and Saving Throws against any type of attack. It can resist winds of up to 60 mph without being destroyed, but the temperature within it is similar to the temperature outside (so if it is too cold it must be heated using the fireplace). The spellcaster can choose to create within its interior a series of objects from the following: bed (with pillow and sheets), table for 4 people, chair, and desk with 2 drawers. The total number of objects cannot exceed half the mage’s level (Example: a 10th level mage can create 2 beds, a table, and two chairs), which vanish if taken out of the refuge. The cottage and the created objects disappear at the end of the effect, or if it is affected by a successful dispel magic. Any object within the refuge at the moment of its disappearance falls to the floor in the area previous occupied by the building. This effect cannot be made permanent.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 106", "school": "Conjuration", "isCustom": false},
    "imm_summon_shadows": {"id": "imm_summon_shadows", "name": "Summon Shadows", "level": 3, "casterType": "immortal", "range": "240 feet", "duration": "1 turn per level", "effect": "Summon 1 shadow per 2 levels that obey him", "area": "1 spectral shadow every 2 levels", "description": "This spell permits the summoning of one spectral shadow for every two cleric levels. The shadows faithfully obey their summoner’s telepathic commands, within the limits of the ability: spectral shadows, being incorporeal, cannot interact with the physical world, move objects or open doors, but can pass through walls and explore, communicating telepathically what it discovers with simple thoughts. The shadows cannot travel further than 240 feet from the spellcaster, otherwise they vanish and the spell ends. Spectral Shadow: AC 7; HD 2+2*; MV 90(30) fly; Atk.1 touch; Damage: 1d4 + special; ST F2; AL N; Int 4; THAC0 17; Special abilities: incorporeal; darkvision; surprises 1-5 on 1d6; each touch drains the subject of 1 point of Strength (recovered after 8 hours); only damaged by magic weapons; immune to mental spells; extraplanar creature vulnerable to light (exposed to sunlight it loses 1 hp/round, if target of light ST to not dissolve). Summon shadows doesn’t function in an area illuminated by sunlight, neither can it be used more than once to simultaneously summon a greater number of shadows than he can control based on his level (fixed at 1 per 2 cleric levels).", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 65", "isCustom": false},
    "imm_summon_skinner": {"id": "imm_summon_skinner", "name": "Summon Skinner", "level": 5, "casterType": "immortal", "range": "30 feet", "duration": "1d4 hours", "effect": "Summon a skinner that serves the spellcaster", "area": "A mirror", "description": "With this spell, the spellcaster summons a creature of the outer planes called Skinner, which serves him to the best of its ability. The skinner is a 6 feet tall, intelligent being of solid shadow, with long silver blades as claws and two silver-plated marble like eyes. It has the natural instincts of a hunter, and loves to skin its prey, particularly lycanthropes, which it considers its mortal enemies. The cleric must cast the spell on a mirror within 30 feet, which opens a portal to the outer plane where the skinner lives and calls one. Through the mirror, the skinner obeys the summoner’s orders for 1d4 hours, using it physical and magical abilities to the best of its ability; if the summoner is a lycanthrope, the skinner attacks him immediately, until one of the two are kill, after which it returns to its own plane through the mirror. If at the end of the spell the Skinner isn’t near a mirror, it cannot return to its own world, and this makes it so angry that it seeks out its summoner to kill him, and then seeks another to send it home. Skinner: AC –1; HD 12; hp. 80; MV 150(50); # Atk. 2 claws or chains; Damage 1d6+2/1d6+2 or special; ST F12; AL N; considered a planar monster; Special abilities: surprise 1-3 on d6 (doesn’t make noise and is impossible to hear it approach); detect lycanthropes within 40 feet; can summon 3 times per day silver chains that imprison the victim’s hands and feet (ST vs. Spells negates); Mirror portal: able to enter any mirror and emerge from another within 10 miles; regenerates 1 hp/round if it remains within a mirror.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 77", "isCustom": false},
    "imm_summon_totem": {"id": "imm_summon_totem", "name": "Summon Totem", "level": 3, "casterType": "immortal", "range": "1 mile per level", "duration": "Special", "effect": "Summon an animal totem", "area": "An individual’s animal totem", "description": "This spell allows the cleric to mentally summom an individual’s animal totem. To cast the spell, the clericmust know the totem of that person and touch his forehead. Doing this, if the animal is within the spell’s radius (decided by the DM based on the surrounding environment), it will immediately feel the insuppressible need to seek out the cleric: the impulse lasts for 1 hour per caster level and the animal moves at maximum speed for this period of time. When the animal reaches the cleric, the latter can order it to perform a service for him that binds it to him for one day per level. The order must be understandable to a creature with animal intelligence (so nothing too complex), but can have any grade of risk (it can even require the animal to sacrifice itself). For example, he could command a squirrel to nibble a rope or go and take a small item; he could even order it to attack an animal from a squirrel would normally flee, but cannot order it to open a locked chest (as the animal cannot do it).", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 65", "isCustom": false},
    "imm_summon_water_elemental": {"id": "imm_summon_water_elemental", "name": "Summon Water Elemental", "level": 5, "casterType": "immortal", "range": "", "duration": "", "effect": "", "description": "Granted by an Immortal in the Tome of the Magic of Mystara Vol. 2 (Divine Magic), Appendix \"Additional spells of each Immortal\". The provided books (Tome Vol. 1-2, Rules Cyclopedia) do not describe this spell; ask your DM or use your own source.", "source": "Tome of the Magic of Mystara Vol. 2, Appendix (no description)", "isCustom": false},
    "imm_summon_whirlwind": {"id": "imm_summon_whirlwind", "name": "Summon Whirlwind", "level": 3, "casterType": "immortal", "range": "120 feet", "duration": "1 turn per level", "effect": "Sea currents blind for 1d3 rounds and do 8d6 hp", "area": "20 feet diameter sphere", "description": "Once he has evoked the power, the spellcaster can concentrate for one round each turn (until the end of its duration) and create a whirlwind (of water if under the sea or of air if on the surface) at his ground level that invests a 20 feet diameter area within 120 feet of the spellcaster (taking care not to enter the area). Within the area of effect, all creatures present are invested by the pebbles and stones present on the ground, each suffering 8d6 points of damage (halved with a successful ST vs. Dragon Breath) and are blinded for 1d3 rounds.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 65", "isCustom": false},
    "imm_summoning": {"id": "imm_summoning", "name": "Summoning", "level": 6, "casterType": "immortal", "range": "", "duration": "", "effect": "", "description": "Granted by an Immortal in the Tome of the Magic of Mystara Vol. 2 (Divine Magic), Appendix \"Additional spells of each Immortal\". The provided books (Tome Vol. 1-2, Rules Cyclopedia) do not describe this spell; ask your DM or use your own source.\nReversible.", "source": "Tome of the Magic of Mystara Vol. 2, Appendix (no description)", "isCustom": false},
    "imm_sun_stone": {"id": "imm_sun_stone", "name": "Sun Stone", "level": 7, "casterType": "immortal", "range": "Touch", "duration": "Special", "effect": "A stone accumulates solar energy and discharges it", "area": "A stone from 4 lb (40 cn)", "description": "This spell renders a stone of at least 4 lb a magic receptable of the solar energy: the stone is charged with 1d6 points for each hour in which it is exposed to the sun, up to a maximum of 1d6 points per cleric level. Once the maximum limit is reached it shines with sunlight and lights a 5 feet radius area per cleric level, which is also heated and kept at a constant temperature of 25°C, until the power is discharged, ending the spell. Anyone who takes it in hand and invokes the name of the cleric’s Immortal that created it can direct the power of the sun towards a single point within the area lit and discharge on it all the accumulated energy. The victim can make a ST vs. Dragon Breath for half damage, and if he dies because of this he evaporates; the same thing happens to objects (which must make a ST vs. Fire).", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 86", "isCustom": false},
    "imm_sunbeam": {"id": "imm_sunbeam", "name": "Sunbeam", "level": 2, "casterType": "immortal", "range": "Touch", "duration": "Permanent", "effect": "A beam of light that comes from the torso", "area": "An item or creature", "description": "This spell must be cast on an object or creature, which can avoid the effect with a successful ST vs. Spells. Once he touches the target whilst speaking the spell, it begins to emit from the eyes a beam of light 60 feet long and 12 inches wide per 10 feet (to a maximum thus of 60 feet long and 6 feet wide) that clearly illuminates the indicated area as if it was a beam of sunlight. Sunbeam is visible at great distance, but the person that emits it (if a creature was chosen as the target) can interrupt it and later relight it at his discretion, until it it magically dispelled (counting as a permanency). The beam can illuminate an area of darkness, but not of continual darkness. The ray can be interrupted by simply placing a shield in front of the area from which it shines. If the beam is directed against the eyes of a creature that normally doesn’t support sunlight (this free action can be attempred only once per round), it must make a ST vs. Spells to avoid it; if the ST fails, it means that its eyes have been dazzled and it suffers the normal penalty as if it was fighting in daylight. Sunbeam doesn’t however have the intensity to damage undead and other creatures vulnarble to sunlight.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 58", "isCustom": false},
    "imm_sure_strike": {"id": "imm_sure_strike", "name": "Sure Strike", "level": 2, "casterType": "immortal", "range": "Touch", "duration": "1 turn", "effect": "A bolt or thrown weapon strikes without fail", "area": "A throwing weapon or bolt", "description": "When the spellcaster casts this spell, he touches a projectile or throwable weapon (like a spear or javelin), and if it is used within 1 turn, it automatically hits the first creature it was launched at (without the need of an Attack Roll), as long as the victim is within its maximum range and visible to the attacker; once it strikes the target, the spell ends. This spell allows the weapon to also hit creatures that are normally immune to normal missiles (like a displacer beast or an individual protected by protection from normal missiles). This effect cannot be combined with permanency.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 68", "school": "Transmutation", "isCustom": false},
    "imm_sustenance": {"id": "imm_sustenance", "name": "Sustenance", "level": 3, "casterType": "immortal", "range": "Touch", "duration": "Permanent", "effect": "A being does not need to eat for 24 hours", "area": "A living creature", "description": "This spell gives the subject all the liquids, salts, sugars, and proteins that he needs daily. In practice, after having it cast, the subject doesn’t need to consume food or water for 24 hours, as if he had eaten to full meals, although in reality he hasn’t ingested any food.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 86", "school": "Transmutation", "isCustom": false},
    "imm_swap_spells": {"id": "imm_swap_spells", "name": "Swap Spells", "level": 2, "casterType": "immortal", "range": "240 feet", "duration": "Special", "effect": "Exploit an arcane spell in place of divine one", "area": "An arcane spellcaster", "description": "This spell only affects arcane spellcasters and allows the priest to establish a mental contact with the victim and access the memorised spells. The cleric must concentrate on the victim whilst making the exchange: each round he can take one spell from the mage’s mind and make it his own, sacrificing one of his onw spells of equal spell level, (naturally he cannot take spells of a higher level of those he has learnt). Any effect of the new spell is based on the cleric’s level to determine the variables. The spell ends once his concentration is interrupted, or if the victim notices the priest’s intrusion. Each round in which the contact continues the mage can make a Wisdom check and if it succeeds he understands that someone is in his mind and can close the contact with a. The stolen spells can be used by the cleric within the next 4 hours, otherwise they vanish from his mind as if they had been used. If the priest is hit by an effective attempt to dispel the magic whilst possing stolen spells, they are lost. Example: a 7th level cleric (max spell level: 4th) casts this spell to strike a mage of equal level and steal a fireball (3rd), renouncing a cure serious wounds (3rd). If the affected victim makes a successful Wisdom test he notices the intrusion and can attempt a ST vs. Spells to stop the effect; if failed he can try again the next round before the theft.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 58", "isCustom": false},
    "imm_swim": {"id": "imm_swim", "name": "Swim", "level": 2, "casterType": "immortal", "range": "120 feet", "duration": "4 hours", "effect": "Subject swims at triple normal speed; reverse victim sinks underwater at 60 ft./rnd", "area": "A creature", "description": "This spell allows the subject on which it was cast to swim at triple his normal speed by moving his arms and legs (or fins), or at 360/120 ft. per round with just concentration. Note however, that although the spell allows the subject to swim on both the surface and underwater, it doesn’t give him the ability to breathe underwater. His maximum carrying capacity is equal to triple his bodily weight: up to double is considered a light load and his speed is unaffected, over that limit each 20% increase in encumbrance reduces the maximum speed by 10%. If the encumbrance exceeds triple his weight the subject sinks and on the seabed can only walk or crawl at 3 feet per round. The reverse form of this spell, drown, causes the victim to sink at a speed of 60 feet per round in the liquid in which it was swimming, unless he is able to grab onto some support. He is allowed a Saving Throw vs. Spells to avoid the effect, otherwise the victim remains unable to float for the spell’s duration (stranding themselves on the seabed). The marine creature victims of drown are simply pushed towards the seabed, and cannot rise by themselves for the spell’s duration, but are still able to breathe and move about on the seabed. Creatures in flight aren’t affected by this spell (air isn’t considered a liquid, not even on the elemental planes). This magic replaces the fly spell underwater and can be used to create subaquatic craft that move magically.\nReversible.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 69", "school": "Transmutation", "isCustom": false},
    "imm_symbol_of_discord": {"id": "imm_symbol_of_discord", "name": "Symbol of Discord", "level": 5, "casterType": "immortal", "range": "Touch", "duration": "Special", "effect": "Victim attacks his own allies or those present", "area": "60 foot radius", "description": "When casting this spell, the spellcaster materialises a magic symbol on a surface or suspended in midair within 3 feet of his position. The symbol lasts until it is annulled with dispel magic or similar spells, and remains fixed to the area it was created. If it was created on a living being or moving object, when the surface moves, the rune remains suspended in midair. The symbol cannot be made invisible, although it can be covered or hidden with using objects in the area. Anyone that reads, passes through, or touches the symbol activates its effects, which affect every creature (living or not) within 60 feet of the symbol when it activated: only spellcasters (arcane and divine) can avoid the effects with a successful ST vs. Mental Spells. Those that fall under the effects of the symbol of discord is invaded by a blind fury and considers every other creature his enemy (including his allies). As long as the spell is active, the victims attack each round in the most lethal manner possible, using missile weapons, spells of direct damage, and magic items, and make their attacks against the closest creature or creatures and that they can damage in the most effective manner, with no regard to his own safety (a mage could cast a fireball centred on himself to damage a large number of creatures). The spell’s victims gain a +2 bonus to damage inflicted with melee weapons because of the spiritual fervour that pervades them, but suffer a –2 penalty to their ST vs. Mental Spells because of the psychic disorder caused by the madness. If the victim has no available viable target, he turns his wrath onto the objects, breaking and setting fire to things, and screaming like a possessed person. When the effects of the symbol of discord have ended (or are dispelled), the victim regains his sanity, but is exhausted for a number of rounds equal to those he remained under the spell’s effect. The penalties of an exhausted creature are the following: those that attack it receive a +2 bonus to their Attack Roll, the subject’s AC is calculated without his shield and his movement is halved. This altered state affects the victims for 1 round per spellcaster level that created the symbol, and can only be magically removed earlier with the cleric spells heal or mental cure or by spells with similar effects and of no lower than 5th level (like break enchantment). A heal as well as eliminating the effects of the discord also avoids the distress described above.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 125", "school": "Enchantment", "isCustom": false},
    "imm_symbol_of_fainting": {"id": "imm_symbol_of_fainting", "name": "Symbol of Fainting", "level": 1, "casterType": "immortal", "range": "", "duration": "", "effect": "", "description": "Granted by an Immortal in the Tome of the Magic of Mystara Vol. 2 (Divine Magic), Appendix \"Additional spells of each Immortal\". The provided books (Tome Vol. 1-2, Rules Cyclopedia) do not describe this spell; ask your DM or use your own source.", "source": "Tome of the Magic of Mystara Vol. 2, Appendix (no description)", "isCustom": false},
    "imm_symbol_of_pain": {"id": "imm_symbol_of_pain", "name": "Symbol of Pain", "level": 6, "casterType": "immortal", "range": "Touch", "duration": "Special", "effect": "Victims suffer –4 to Attack Rolls and skill checks", "area": "60 foot radius", "description": "When casting this spell, the spellcaster materialises a magical symbol on a surface or suspended in the air within 3 feet of his position. The symbol lasts until it is annulled with dispel magic or similar spells, and remains fixed in the area it was created. If it is created on a living being or a moving object, when the surface moves, the rune remains suspended in midair. The symbol cannot be made invisible, although it can be covered or hidden using objects present in the area. Anyone that reads, passes through, or touches the symbol activates its effects, which affects any creature (except constructs) that are within 60 feet of the symbol when it activates: only spellcasters (arcane and divine) can avoid the effects with a successful ST vs. Death Ray. Those that fall under the symbol of pain’s effect suffer an unexpected physical wasting and are pervaded by a constant shooting pain that prevents them from acting and thinking clearly. Because of this pain the victim suffers a –4 penalty to all Attack Rolls, characteristic and skill checks, and have a 30% chance of spell failure because of the pain for 1 hour per level of the mage who created the symbol. This state can be only be magically removed earlier with the cleric spells heal or destroy evil or with spells with similar effects of 6th level or higher. The penalty derived from this spell is cumulative with other applications of the same spell, only with the effects of different spells, although the duration of the pain is added together with more than one application. For example, if a victim of the symbol activates another symbol of pain it doesn’t suffer –8 to its rolls, but its state could last for a number of additional hours equal to that of the second effect. If he is however cursed, any penalty caused by the curse would be added to that derived from the symbol.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 146", "school": "Necromancy", "isCustom": false},
    "imm_symbol_of_sleep": {"id": "imm_symbol_of_sleep", "name": "Symbol of Sleep", "level": 7, "casterType": "immortal", "range": "Touch", "duration": "Special", "effect": "Victims are put to sleep", "area": "60 foot radius", "description": "When casting this spell, the mages materialises a magic symbol on a surface or suspended in the air within 3 feet of his position. The symbol lasts until it is dismissed with dispel magic or similar spells, and remains fixed to the area it was created in. If it is created on a living being or a moving object, when the surface moves, the rune remains suspended in midair. The symbol cannot be made invisible, although it can be covered or hidden by items in the area. Anyone reading, passing, or touching the symbol activates the effects, which affect any living creature within 60 feet of the symbol when it activates: only spellcasters (arcane and divine) can avoid the effects with a successful a ST vs. Mental Spells. Those that fall under the effect of the symbol of sleep instantly fall asleep, fall to the ground, and sleep for 8+1d10 hours. The victim can only be awakened via a dispel magic (with the normal chance of success) or by similar magical means that annul the enchantment.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 164", "school": "Enchantment", "isCustom": false},
    "imm_symbol_of_stun": {"id": "imm_symbol_of_stun", "name": "Symbol of Stun", "level": 2, "casterType": "immortal", "range": "Touch", "duration": "Special", "effect": "Stun for 1d6 rounds living beings within 30 feet", "area": "30 foot radius", "description": "When casting this spell, the spellcaster materialises a magic symbol on a surface or suspended in the air within 3 feet of his position. The symbol lasts until it is activated for the first time, although it can be annulled earlier with dispel magic or similar spells, and remains fixed to the area in which it was created. If it is created on a living being or a moving object, when the surface is moved, the rune remains suspended in midair. The symbol cannot be made invisible, although it can be covered or hidden using items within the area. Anyone reading, passing through, or touching the symbol activates the effects, which affects any living creature within 30 feet of the symbol when it activates. The victims are struck by a magic wave that stuns the mind unless they make a ST vs. Mental Spells. If the ST succeeds, the victim simply loses his own action for that round (or for the following if he has already acted), otherwise, he is stunned for 1d6 rounds, unable to attack, cast spells, or activate magic items, moves at half speed, and has a –4 penalty to AC, ST, and any skill check.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 69", "school": "Enchantment", "isCustom": false},
    "imm_technomancy": {"id": "imm_technomancy", "name": "Technomancy", "level": 4, "casterType": "immortal", "range": "30 feet", "duration": "6 turns", "effect": "Cleric understands the function of a device and can control it", "area": "A mechanical device", "description": "This spell allows the cleric to fully understand the function of a single mechanical device or other technological apparatus on which it is cast (with the only exceptional of extremely complex magical devices, like the multifunctional gear of the gnomes). As long as it is within 30 feet of him, moreover, the spellcaster can magically control and operate the device, simply be concentrating (while concentrating he can do nothing else except move at half walking speed); to do so however it is necessary that the controlled object isn’t broken and has all that it needs to function (e.g. a steam device won’t function if it lacks fuel to heat the water). This spell allows the cleric, for example, to temporarily deactivate a mechanical trap (or even to activate it), load a siege engine or simple crossbow and fire it by mere concentration (it is naturally necessary that ammunition is present and the weapon’s rate of fire cannot be increased; the Attack Rolls is made as if the cleric was physically using that weapon), manoeuvre a hoist, or pick a complicated lock. The object of interest doesn’t get a Saving Throw to avoid the effects of this spell, except when the cleric tries to control a weapon with mechanical parts (like a crossbow) that is in the hands of another character: the latter can make a ST vs. Spells each round to prevent the weapon from working. This spell cannot be made permanent on a magic item.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 73", "isCustom": false},
    "imm_telepathic_recall": {"id": "imm_telepathic_recall", "name": "Telepathic Recall", "level": 6, "casterType": "immortal", "range": "Same plane of existence", "duration": "1 day every 2 levels", "effect": "Send a message to several subjects", "area": "1 person per Intelligence point", "description": "This spell allows the mage to send a telepathic message to one or more specified individuals, briefly informing the recipient of his position and situation. The spell must be prepared for beforehand with an hour-long ritual, but from that moment one magic word is enough to instantly send a powerful mental impulse that reaches its addressees, as long as they are on the same plane as the mage and aren’t protected against telepathy. The maximum number of addressees is equal to the mage’s Intelligence score, and must all be individually named or be part of a very precise group. If within the group there are individuals that the mage doesn’t want to affect, the call just reaches those that the mage has individually selected, on a case-by-case basis. The sent message, moreover, cannot have more than 100 words. Example: the mage Naren is imprisoned in a fortress and casts a message of help (“I have been imprisoned by the evil Vagnar who will kill me tomorrow”), indicating as the telepathic recall’s addressees the knights of Lord Timenko and his adventuring group, the Company of the Chalice. The creatures that receive the message instinctively know who sent it, and as long as the effects of the call last obtain a clear indication about the sender’s feelings, vaguely know his location (for example know that he is imprisoned in a fortress that sits at the base of the Broken Mountain), and instinctively which direction to travel to reach him.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 146", "school": "Divination", "isCustom": false},
    "imm_telepathy": {"id": "imm_telepathy", "name": "Telepathy", "level": 5, "casterType": "immortal", "range": "Special", "duration": "1 turn per level", "effect": "Mage communicates with the thoughts of another creature", "area": "A thinking being", "description": "This spell can be used in two ways by the spellcaster: aimed at a specific person, or at an area (this is decided whilst casting the spell). In the first case, the spellcaster decides which person he knows and has already seen at least once he want to telepathically contact (he must be on the same plane when he casts the spell). When the contact begins, the recipient instinctively knows that someone is attempting to contact him telepathically, but if he doesn’t want to establish the contact, he need only make a successful ST vs. Mental Spells and the spell fails. If instead contact is established, for the spell’s entire duration the spellcaster can speak telepathically with the person he is connected to simply by concentrating (he can naturally also not concentrate and act normally, without losing this ability, which lasts for 1 turn per level). The communication always happens as long as the two are on the same plane, regardless of the distance, or as long as one of the two isn’t shielding his mind with a 5th-level or higher spell. Thanks to telepathy the spellcaster can perceive the true thoughts and intentions of his recipient, and see any images that emerge from his mind, dreams included. The second use of telepathy allows the spellcaster to establish a mental contact with any living creature within 90 feet, whose mind isn’t magically protected. The spellcaster must concentrate for a round on an individual, who can avoid the mental contact with a successful ST vs. Mental Spells. Once established, the contact lasts as long as the spellcaster continues to concentrate and he can read all the creature’s thoughts, even those hidden, as well as to make telepathic demands. As long as the spell lasts, the spellcaster can change target once per round, by concentrating, but can only address himself to one speaker per round. In both cases, the two speakers understand their thoughts even if speaking different languages, and if actively engaged in telepathic conversation they cannot do anything but move at normal speed. If the contact chooses not to actively respond to the telepathic questions he can act normally, but the will equally find the answer in his mind in an independent way.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 126", "school": "Divination", "isCustom": false},
    "imm_temporal_barrier": {"id": "imm_temporal_barrier", "name": "Temporal Barrier", "level": 7, "casterType": "immortal", "range": "0", "duration": "1 turn", "effect": "Barrier retards part of the damage suffered and protected from the effects of temporal alteration", "area": "Only the cleric", "description": "This potent spell creates around the cleric a barrier that distorts the flow of time. The barrier intercepts any type of damage causing attack directed against the priest and deflects part of the damage into the future, allowing the subject to prepare himself for it. If an attack produces physical damage of any type, half of the damage affects the cleric immediately, and the other half only after the barrier ends. Note that at the end of the spell, all the retarded damage affects the cleric simultaneously, so he must carefully prepare himself by using curative spells and defences available to him to not receive massive damage that could kill him. Any type of cure is always applied immediately before the damage suffered, and only when the recovered Hit Points are above the priest’s maximum, the excess hp are used to annul the delayed damage. If the attack produces an effect but no damage (e.g. hold person, dimensional trap, maze, curse, etc.), the effect is stopped until the end of the barrier as if the ST (if applicable) to avoid or partly reduce the effect was successful. This obviously gives the cleric the chance to use a spell to protect him before the effect takes place (e.g. casting a type of protection to improve his defence against a specific effect). Finally, the barrier completely annuls any spell that alters the cleric’s age or that cause a temporal dislocation.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 86", "isCustom": false},
    "imm_temporal_stasis": {"id": "imm_temporal_stasis", "name": "Temporal Stasis", "level": 7, "casterType": "immortal", "range": "Touch", "duration": "Permanent", "effect": "Creature enters a coma, doesn’t age or die; reverse free from coma or magic stasis", "area": "A creature", "description": "Casting this spell, the spellcaster touches the target creature (normal Attack Roll) and if the attempt succeeds, it falls into a state of suspended animation (no ST allowed). In this state, his vital functions cease, but his body doesn’t age, and no force or effect can injure the victim in any manner (it is virtually immune to any spell or attack, with the exception of a well-worded wish). Time stops running for the victim and his condition remains held until the spell’s reverse form is cast on him or a wish is used to reanimate him. The reverse spell, reanimate, returns to life with its maximum Hit Points any creature in a coma or similar state of life stasis.\nReversible.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 180", "school": "Transmutation", "isCustom": false},
    "imm_temporary_skill": {"id": "imm_temporary_skill", "name": "Temporary Skill", "level": 2, "casterType": "immortal", "range": "Touch", "duration": "6 turns + 1 turn per level", "effect": "The individual acquires a general skill", "area": "A creature", "description": "The spellcaster selects which general skill he wants to confer to the touched creature while uttering the spell, and for its entire duration (or until it is magically dispelled) the beneficiary can use that specific skill as if he possessed it. It is only possible to attribute skills based on the following characteristics: Strength, Constitution, Dexterity, and Charisma. Alternatively, the character can choose to strengthen a skill that he already has (of any type) and gain a +2 bonus to all checks with that skill for the spell’s duration. With the points system, the spell grants 2 ranks in an unpossessed skill or 3 ranks in an already known.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 70", "school": "Transmutation", "isCustom": false},
    "imm_thaumaturgical_circle": {"id": "imm_thaumaturgical_circle", "name": "Thaumaturgical Circle", "level": 3, "casterType": "immortal", "range": "60 feet", "duration": "1 turn per level", "effect": "Area in which curative magic is more effective", "area": "10 feet diameter circle", "description": "When the cleric casts this spell, he makes a circle of scintillating magical energy of 10 feet diameter appear within range that stays at the point where it was created for the indicated duration or until dispelled. If the thaumaturgical circle is cast in an area that is too small to contain it (e.g. in a 5×10 feet room) the spell fails. All cure spells cast within the circle cure an additional 10% hit points (or +1 Hit Point for each dice, accoding to which is the most advantageous. Similarly, all inflict spells cause 10% or 1 hp per dice less, when cast on creatures within the circle. Example: A cleric of Chardastes who is within a thaumaturgical circle casts a cure serious wounds on himself thus recovering 40% of lost Hit Points, or 2d6+4 hp, according to which is the most advantageous to him (remember that cure serious wounds normally cures 30% of wounds or 2d6+2). If later the same cleric is attacked with an inflict light wounds spell he suffers nothing (as the damage, equal to 10% of his hp, is totally compensated by the thaumaturgical circle).", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 65", "isCustom": false},
    "imm_thief_skills": {"id": "imm_thief_skills", "name": "Thief Skills", "level": 3, "casterType": "immortal", "range": "", "duration": "", "effect": "", "description": "Granted by an Immortal in the Tome of the Magic of Mystara Vol. 2 (Divine Magic), Appendix \"Additional spells of each Immortal\". The provided books (Tome Vol. 1-2, Rules Cyclopedia) do not describe this spell; ask your DM or use your own source.\nReversible.", "source": "Tome of the Magic of Mystara Vol. 2, Appendix (no description)", "isCustom": false},
    "imm_thunder_bow": {"id": "imm_thunder_bow", "name": "Thunder Bow", "level": 4, "casterType": "immortal", "range": "30 feet", "duration": "1 turn", "effect": "The bow’s arrow becomes forked lightning that inflicts +1d10 hp and causes stun", "area": "A bow", "description": "This spell instils into the bow on which it is cast the power of thunder and lightning. For the spell’s duration, each arrow fired by that bow is transformed into a lightning bolt, and if it hits the target (normal Attack) exploding with a clash of thunder (breaking the projectile), causing to the victim normal damage based on his mastery with a bow, +1d10 points of damage from electricity; the victim must moreover make a successful ST vs. Paralysis to avoid the stun for 2 rounds caused by the thunder and lightning. The transformed projectile is considered a magic item with a +1 bonus for every 5 cleric levels to determine the type of monster that it can wound (without adding the bonus to Attacks or damage); if it uses a magic arrow with a higher bonus, it uses that bonus.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 73", "isCustom": false},
    "imm_thunder_drum": {"id": "imm_thunder_drum", "name": "Thunder Drum", "level": 4, "casterType": "immortal", "range": "Touch", "duration": "Special", "effect": "Cause a frightening cacophony within 120 feet", "area": "A drum", "description": "This spell confers to the percussion instrument on which it was cast (usually a drum) the ability to trigger a discordant cacophony when it is played by the cleric; all those (friends and enemies) that are within 10 feet of the cleric aren’t however affected by the drum’s power. Beyond these 10 feet, the drum’s effects are frightful, and can be felt up to 120 feet from the item. All creatures of lower level or HD than the cleric are instantly paniced and forced to flee in terror, per 2d6 rounds. Creatures of equal level (or HD) as the priest can make a Saving Throw vs. Mental Spells to avoid the panic, while the creatures of higher level to that of the cleric (or with better HD) can make the ST with a +2 bonus. Independent of HD, all the creatures that hear drum roll (except those within 10 feet of the cleric) lose a number of hit points equal to the priest’s level (halved with ST vs. Spells). The ability to evoke the cacophonic sound remain in the drum until thecleric uses it for the first time (max 24 hours), or until the spell is dispelled, then the effect vanishes.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 73", "isCustom": false},
    "imm_time_trap": {"id": "imm_time_trap", "name": "Time Trap", "level": 2, "casterType": "immortal", "range": "90 feet", "duration": "Special", "effect": "Victim continues to repeat an action until it makes a successful ST or the conditions change", "area": "A being", "description": "This powerful spell affects one creature and traps it in a vicious circle that obliges it to constantly repeat the same action until it successfully opposes the spell. In practice, the moment that the priest cast’s the spell is considered the victim’s last action: if the creature makes a successful ST vs. Spells it can continue to act normally and the effect is annulled. If instead the ST fails, the subject is force to repeat exactly what he has just done, with the same outcome, until the conditions to repeat the action cease. After 1 minute the victim is allowed a ST to free himself from the time trap each round, and with the first successful ST the spell’s effect vanishes, so from that moment it becomes possible to not repeat the action (the victim for that round completes the same action but notices the absurdity and thus the effect isinterrupted). Example 1: a cleric casts this spell on an enemy who has just missed his mage companion. The victim fails his ST and in the next round attacks the mage again with the same dice result, automatically missing. The scene is repeated until the enemy makes a successful ST or the mage cannot be reached by the victim (because he vanishes or goes too far away). Example 2: a cleric casts the trap against a magethat has just cast shield on himself. The mage failed his ST and in the next round is forced to repeat the action. This is possible if he has other applications of the same spell memorised (which is clearly wasted, as the effects of shield aren’t cumulative), otherwise the mage loses the next round (casting a spell he knows he hasn’t memorised) but afterwards will behave as he believes best, being freed of the effect.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 58", "isCustom": false},
    "imm_timeshift": {"id": "imm_timeshift", "name": "Timeshift", "level": 6, "casterType": "immortal", "range": "30 feet", "duration": "1 hour per level", "effect": "Victim vanishes and reappears at the spell’s end", "area": "1 being or object of max size Huge", "description": "This powerful spell manipulates the flow of time trapping the victim (a being or object of up to Huge size) in a temporal bubble and projects it into the future. If the subject fails his ST vs. Spells with a –4 penalty (and any object not worn or held automatically fails it), he disappears instantly, to reappear at exactly the same point at the end of the spell. During this period of time, the target cannot be contacted or detected in anyway, as he is within another dimension (that of the flow of time), and when he reappears for the victim it is as if nothing happened, as he has no perception of the time passing (because to him not even a second passes from the time the spell had effect until he reappears). If the target has cast spells that depend on his presence, they are considered “dead” or “destroyed” for the duration of the shift to understand if their effects can be considered vanished. If instead the victim is under some type of magic or deleterious effect, the time spent “out of phase” doesn’t count against the effect’s duration (as already said, for him not even a second passes). If at the moment of its return its space is occupied by another solid, he materialises in the closest free space ending up on the ground.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 81", "isCustom": false},
    "imm_tongues": {"id": "imm_tongues", "name": "Tongues", "level": 3, "casterType": "immortal", "range": "Touch", "duration": "1 turn per level", "effect": "Allows the understanding of spoken language", "area": "A creature", "description": "This spell gives the creature touches the ability to understand and speak the language of any intelligent creature (including dialects and racial tongues). The subject can speak and understand only one language at a time, and can select which tongue he prefers to understand (if hearing different ones simultaneously), changing once per round as long as the spell lasts. The range is limited by the subject’s hearing and the speaker’s voice, and he cannot understand the languages of animals or non-intelligent creatures, or the meaning of writing in an unknown tongue.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 86", "school": "Divination", "isCustom": false},
    "imm_totemic_bond": {"id": "imm_totemic_bond", "name": "Totemic Bond", "level": 3, "casterType": "immortal", "range": "60 feet", "duration": "Permanent", "effect": "Bind a character to his animal totem", "area": "An animal and an individual", "description": "This spell allows the cleric to join an individual to his animal totem. Once the spell has been cast, the animal follows the individual to which it is bound and obeys his verbal order to the best of its physical and intellective ability. An individual can only bond one animal totem to himself at a time; if he casts the spell on another animal, the first is freed from the bond. When the spell is cast, both the animal and the target character must be within 60 feet of the cleric but neither of the two benefit from a ST to avoid the effect.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 66", "isCustom": false},
    "imm_transfer_spell": {"id": "imm_transfer_spell", "name": "Transfer Spell", "level": 6, "casterType": "immortal", "range": "", "duration": "", "effect": "", "description": "Granted by an Immortal in the Tome of the Magic of Mystara Vol. 2 (Divine Magic), Appendix \"Additional spells of each Immortal\". The provided books (Tome Vol. 1-2, Rules Cyclopedia) do not describe this spell; ask your DM or use your own source.", "source": "Tome of the Magic of Mystara Vol. 2, Appendix (no description)", "isCustom": false},
    "imm_transmute_liquids": {"id": "imm_transmute_liquids", "name": "Transmute Liquids", "level": 3, "casterType": "immortal", "range": "Touch", "duration": "Permanent", "effect": "Transmute a liquid into another type of liquid", "area": "1 pint of liquid per level", "description": "While casting this spell the mage must touch the liquid that he chose to transform, and at the end of the formula it is permanently transmuted into the selected type of non-magical liquid (e.g. beer into water or wine into alcohol). If the volume of liquid is higher than that transmutable, the effect is diluted. If it is cast on a magic liquid like a potion, the only possible transmutation is into a liquid with a spell of the same spell level and that has been mastered by the author of the transmutation (for example a mage can transform a potion of fly into a potion of speed as long as he has the haste spell). If the spellcaster doesn’t attune a transformation to the same spell level (e.g. he doesn’t understand the spell level of a potion and tries to associate it with a higher or lower level spell), the spell has no effect and the liquid keeps its original properties. Moreover, there is a 10% chance per level of the effective magic that the potion completely resists the transmutation.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 86", "school": "Transmutation", "isCustom": false},
    "imm_transmute_solids": {"id": "imm_transmute_solids", "name": "Transmute Solids", "level": 6, "casterType": "immortal", "range": "Touch", "duration": "1 turn per level", "effect": "An object can assume several forms", "area": "An object of 10 cn per level", "description": "This spell can be cast on a normal or magic item, and the amount of matter effectible is equal to 10 cn of encumbrance (1 pound) per spellcaster level. Once it functions on an item, anyone that holds it can, with simple concentration, transforms it into another single item (not composed of different parts or mechanical) of any material, as long as this item does weigh or cost more than the original item (for example, a sword that weighs 60 cn and costs 10 g.p. can be transformed into a noble’s cloak, an ebony staff, or a sturdy chair, and so on, as long as the weight and value of the new item don’t exceed those of the original item). For magical items with bonuses, the new item keeps the same bonus, while if it is an item with powers or charges, the power can be used normally by anyone who knows the activation word. The item can be transformed once per round as long as the spell lasts, and if the transmutation is magically dispelled, it returns to its original form.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 147", "school": "Transmutation", "isCustom": false},
    "imm_transport_via_plants": {"id": "imm_transport_via_plants", "name": "Transport Via Plants", "level": 6, "casterType": "immortal", "range": "Infinite (within the same plane)", "duration": "Instantaneous", "effect": "Teleport within the same plant through plants", "area": "Only the druid", "description": "This spell can be cast a maximum of once per day. The druid must be next to a plant (of any size) and must indicate a place in general or a specific plant at any distance. Uttering the spell the druid magically enters the nearest plant and emerges from the specified one at his destination (if none has been specified, it should be determined randomly). There is no limit to the distance between the two plants, but both must be alive and on the same plane; if one of the two plants is dead, the spell doesn’t work. The druid appears in the specified place without error, and can take two living beings with him.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 129", "druidSpell": true, "isCustom": false},
    "imm_transport_via_rock": {"id": "imm_transport_via_rock", "name": "Transport Via Rock", "level": 7, "casterType": "immortal", "range": "Infinite", "duration": "Instantaneous", "effect": "Teleport at long range", "area": "Spellcaster + 2 beings", "description": "This spell can be used a maximum of once per day. The mage must be near a rocky formation of any size (excluding the walls of a cavern) and must select a generic destination or a specific rocky formation that is somewhere and that he already knows. After casting the spell, the mage magically penetrates into the rock and exits from the destination rock (which is randomly determined if it hasn’t been specified). This is no limit to the range, but both rocks must be on the same Plane, and the mage can take two creatures with him, as long as they consent.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 164", "school": "Conjuration", "isCustom": false},
    "imm_trusting_wait": {"id": "imm_trusting_wait", "name": "Trusting Wait", "level": 5, "casterType": "immortal", "range": "0", "duration": "Min. 1 hour, max. 1 day per 2 levels", "effect": "After a period of waiting, the cleric gains a score of 18 (or more) in one of his six characteristics", "area": "Only the cleric", "description": "When casting this perculiar spell the cleric selectsany one of his six characteristics (Strength, Intelligence, Wisdom, Dexterity, Constitution, or Charisma) and then trustingly waits for the spell to take effect. During this waiting period, the cleric gains a +2 bonus to all Saving Throws vs. fear, confusion, and desperation because of his great strength of mind, but no others. The cleric can lengthen the waiting period as he likes, from a minimum of 1 hour to a maximum of 1 day per 2 levels, but once fixed the wait remains as it is and the effect cannot be magically dispelled (although the cleric emits an aura of abjuration). At the end of the wait, the priest gains a score of 18 in the characteristic chosen at the moment of casting (if the characteristic already has a score of 18+, it only adds 1 point), and this effect lasts for exactally has long as the waiting period (only then can the effect be dispelled). The spell cannot be cast more than once on the same subject: multiple applications have no effect.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 78", "isCustom": false},
    "imm_truth_of_blood": {"id": "imm_truth_of_blood", "name": "Truth of Blood", "level": 3, "casterType": "immortal", "range": "Touch", "duration": "Concentration", "effect": "Obtain information based on a trace of blood", "area": "Trace of blood", "description": "While uttering this spell the mage must touch the traces of blood no older than one hour per spellcaster level. As long as he concentrates, the mage can obtain information about the creature that lost the blood, and can change traces (if there are more than one blood trace) and gain similar information for all the creatures that have left traces of their blood behind. Based on the number of rounds he concentrates, the mage gains the following information: 1st round: race and type of creature. 2nd round: number of Hit Dice, weight, size, and age of the creature. 3rd round: direction and approximate distance in which the creature can be found at that moment. If the being is deceased, the spellcaster is aware of its death and the direction in which it lies.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 87", "school": "Divination", "isCustom": false},
    "imm_unbearable_pain": {"id": "imm_unbearable_pain", "name": "Unbearable Pain", "level": 3, "casterType": "immortal", "range": "", "duration": "", "effect": "", "description": "Granted by an Immortal in the Tome of the Magic of Mystara Vol. 2 (Divine Magic), Appendix \"Additional spells of each Immortal\". The provided books (Tome Vol. 1-2, Rules Cyclopedia) do not describe this spell; ask your DM or use your own source.", "source": "Tome of the Magic of Mystara Vol. 2, Appendix (no description)", "isCustom": false},
    "imm_unclean_touch": {"id": "imm_unclean_touch", "name": "Unclean Touch", "level": 5, "casterType": "immortal", "range": "0", "duration": "1 round per level", "effect": "The cleric injures and infects the touched creature", "area": "Only the cleric", "description": "When the cleric casts this spell, one of his hands becomes horribly swollen and invaded by plague like that of a leper; the cleric cannot effectively use a weapon or shield with that limb, although it can still manage small items (like a potion) or cast spells. Any creature touched by the cleric with the infected hand (normal Attack Rolls) loses 10% of its current Hit Points, or 1d6+1 hp (according to which is the most disadvantageous to the victim), and must make a ST vs. Spells to avoid contracting a horrible, devastating magical disease. Unclean touch remains active in the priest’s hand for 1 round per level, so the cleric is able to infect more victims during this period of; if he wants to, tuttavia, he can end the spell early. The exact type of disease is determined by the cleric when he casts the spell: if he doesn’t specify one, the contagion would be mummy rot (for details on this and other affections see the inflict disease spell).", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 78", "isCustom": false},
    "imm_unconscious_command": {"id": "imm_unconscious_command", "name": "Unconscious Command", "level": 5, "casterType": "immortal", "range": "Touch", "duration": "Special", "effect": "Victim is unconsciously programmed to perform an action", "area": "A living creature", "description": "This spell is only effective against living creatures: undead and constructs are thus immune. While evoking this power, the spellcaster must touch the designated victim, who can make a ST vs. Mental Spells to totally ignore the effect and the mage’s words. If however the ST fails, the spellcaster puts the victim into a trance that lasts 2 rounds, and acts on his subconscious planting in his mind a relatively task (the DM must judge the complexity) which he follows when the occasion presents itself. The spellcaster must specify well the type of event that triggers the required action, and when this is met, the victim automatically finds himself doing what the mage demanded. Once he leaves the trance, the victim remembers nothing about what happened in the previous 2 rounds nor the implanted order, and continues to act as if nothing (so if he was attacking the mage he continues to do so). Example: the witch Rowena casts this spell of the son of the king while the two fight in her private rooms. The young prince falls victim to the sorcery, and is stopped with weapon in hand, while the woman whispers his order: “Tomorrow you will present yourself before your father with your weapon at your side, and when he greets you, you will attack and kill him.” The trance then vanishes, the prince continues to attack the witch calling reinforcements, but she escapes laughing before being caught. If the programmed action goes against the victim’s morality, after having undertaken it the victim can make a new ST vs. Mental Spells with a −2 penalty each round after the first in which he continues to perform that action to rebel against the manipulation: If the ST succeeds, the spell’s effect vanishes. While undertaking the subconscious order, the victim cannot communicate his true intentions, but continues to watch his actions like a defenceless spectator until he performs the imparted command. At that point the effect is deemed concluded, and he can interact with the outside as he wishes, having recovered control of his body and mind and remembers well what has happened up to that moment (except the trance period in which he received the command). The spell remains active until the conditions to follow the order are met, or until the victim is hit by a dispel magic spell or enters an area that annuls the spell.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 128", "school": "Enchantment", "isCustom": false},
    "imm_undead_plague": {"id": "imm_undead_plague", "name": "Undead Plague", "level": 6, "casterType": "immortal", "range": "1 mile", "duration": "Permanent", "effect": "Animate corpses as skeletons", "area": "100 ft2 per level", "description": "This is a potent version of animate dead. The cleric selects an area within 1 mile, and with the spell affects the corpses present in the area of effect, or a surface of 100 ft2 per level. The magic permanently animates the corpses as skeletons all in the cleric’s service: they are impervious to dispel magic and follow any orders until they are destroyed or the same chooses priest to break the bond, reducing them to dust. The number of skeletons created depends on the terrain type:  Cemetary or battlefield: 1 skeleton per 5 ft2.  Rural or wild area: 1 skeleton per 100 ft2.  Desert or urban area: 1 skeleton per 1,000 ft2. If there are corpses of creatures with more Hit Dice than those of a simple humanoid (for example the carcass of a dragon or of a group of centaurs) within the area it is possible to animate them, but each HD of the creatures in question counts as one skeleton, to know how many of these creatures can be transformed into skeletal versions. The humanoid skeletons all have 1 HD, Armour Class 7, can attack with a claw (1d6 points of damage) or a weapon (supplied by the priest, if not possessed by the corpses) and receive half damage from piercing weapons, as well as enjoying the normal defences of undead. Skeletons of different animals have the same physical attacks that they had in life, a number of Hit Dice equal to what they had in life, the same Saving Throws and an AC better by 1 point than the original, but non of the special forms of attack or defence that they had in life (e.g. a dragon thus cannot breath). All the skeletons thus animated are turned as if they had 2 more Hit Dice than they actually have.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 82", "isCustom": false},
    "imm_universal_tongue": {"id": "imm_universal_tongue", "name": "Universal Tongue", "level": 5, "casterType": "immortal", "range": "0", "duration": "1 turn per level", "effect": "Mage speaks with any living being within 30 foot", "area": "30 foot radius", "description": "This spell allows the spellcaster to speak with any living creature (including animals and monsters but excluding plants), he is able to understand it and make it understand him in its turn, as long as it remains within 30 feet of the spellcaster. The spell also allows him to interject with more than one creature at the same time.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 128", "school": "Divination", "isCustom": false},
    "imm_unmissable_shot": {"id": "imm_unmissable_shot", "name": "Unmissable Shot", "level": 1, "casterType": "immortal", "range": "Touch", "duration": "1 hour", "effect": "The dart strikes ignoring the target’s cover", "area": "A small sized arrow or bolt", "description": "This spell can be cast on an arrow, bolt, stone, or any other common projectile (normal or magic) of small size or smaller usable by a missile weapon. The projectile remains enchanted for up to an hour, but once used (whether it hits or misses the target) the magic ends. Before firing the projectile, the firer must select any one target within sight, either an inanimate object or living creature, and then fire the bolt. According to whether it was used against a living creature or inanimate object, unmissible shot has different effects. Intermittent: If fired against a creature, unmissible shot heads straight towards the target, completely ignoring any type of cover that are between the firer and target, dematerialising to avoid the obstacles that are in its path and rematerialises once it has passed them, until it strikes the target. Make a normal Attack Roll, but ignore any cover penalties due to the environment around the target (if for example it is hidden behind a wall, bush, or individual) or any shield. Example: an archer using unmissible shot sees an enemy sheltering behind the merlon of a tower, and fires his arrow at him (normal Attack Roll; if the roll succeeds, the arrow dematerialises before touching the merlon and reappears on the other side to penetrate the enemy’s body, while if it failed it doesn’t completely re-emerge from the wall and remains stuck. Searching: If directed against an object, the projectile automatically strikes the desired point, and this can prove very useful (it can indeed press a button, set off certain traps, pierce a bag, or cut a rope); if directed against a living being or object it always misses the target. In both cases, the range of the missile weapon that uses unmissible shot determines the maximum range that the projectile can reach, while the damage inflicted depends on the attacker’s mastery with that type of weapon (the spell doesn’t influence the damage caused).", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 53", "school": "Transmutation", "isCustom": false},
    "imm_veil": {"id": "imm_veil", "name": "Veil", "level": 7, "casterType": "immortal", "range": "240 feet", "duration": "1 turn per level", "effect": "Group of creatures assume an illusionary form", "area": "1 being x lvl within 30 feet of each other", "description": "This spell instantly changes the appearance of the interested subjects and maintain it for the effect’s duration, or until it is magically dispelled. The spellcaster can influence a maximum of one subject per level, including himself, as long as they are no more than 30 feet from each other and are within a 240 feet radius. Each can be given a different appearance, which can be up to one size larger or smaller than their real size: those affected acquire an appearance decided by the mage (aspect, tattoos and smell), but return to their true form once dead. This spell cannot replicate the exact features of an individual, only the typical characteristics of a race, ethnicity, or class: two subjects will never be identical in any case. Non-consenting subjects can negate the effect with a successful ST vs. Spells. Moreover, anyone interacting with the subjects protected by veil can see the illusion with a successful a ST vs. Mental Spells with a –2 penalty, but only if there is something wrong about the character (because of his behaviour or the unexplainable presence of that type of being in a certain place).", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 164", "school": "Illusion", "isCustom": false},
    "imm_vengeance": {"id": "imm_vengeance", "name": "Vengeance", "level": 6, "casterType": "immortal", "range": "Infinite", "duration": "Permanent", "effect": "Torment the victim’s rest", "area": "A guilty being", "description": "The cleric can cast this spell only on beings that have already caused an offence, an unforgivable wrong, or that are known to be guilty of crimes of extreme severity against the cult or according to the precepts of the priest. The spellcaster can cast vengeance on only one creature at a time (in other terms, two active vengeance spells cannot be simultaneously cast by the same character). To cast vengeance the cleric must possess an item or a fetish belonging to the victim and that has touched his body (for example a lock of hair, a drop of blood, a coin that the victim has held in his hand, or a fragment of clothing): the casting of the spell requires a whole hour, at the end of which the object becomes enchanted and the priest loses 500 xp per level or Hit Dice possessed by the victim (the life energy that is sacrificed to enchant the fetish with its curse). At this point the target of the vengeance is subject to something similar to a terrible curse: his sleep is tormented by nightmares and recurring images in which he continually sees the guilt he committed (and that has caused the priest’s hatred). Upon awakening, the victim doesn’t recover any Hit Points due to rest and natural regeneration, but suffers 2d6+2 damage or 30% of his actual hp (this wound can be cured by common magical means). The victim moreover must make a ST vs. Spells: if he fails it means that he is so disturbed at that point that he is no longer able to memorise his spells (if a spellcaster) and suffer a 1 point penalty to all his Attacks, ST, and damage until he is able to sleep properly. When the victim and spellcaster are less than 360 feet from each other, both are intensely aware of the presence of their own nemesis, and are able to identify it without error if it is in their field of vision, even if camouflaged, invisibile or subject to a polymorph spell. In combat, the priest gains a +3 bonus to his Attack Rolls when attacking the victim and the latter suffers a –3 penalty to his ST against the cleric’s spells. The spell has a permanent duration, and it can only end in the following ways: 1. victim dies by the spellcaster’s hand or vice versa; 2. the enchanted fetished is destroyed or the spell placed on it is dispelled with a dispel magic; 3. a wish is used to dispel the vengeance; The effects of the vengeance are suppresed (but not dispelled) if the victim is on a different plane to that of the enchanted fetish. This spell cannot be made permanent on an item.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 82", "isCustom": false},
    "imm_victory": {"id": "imm_victory", "name": "Victory", "level": 7, "casterType": "immortal", "range": "0", "duration": "24 hours", "effect": "Augment the morale and combat ability of a group of people tanks to divine intervention", "area": "200 people per level with ½ mile", "description": "This legendary spell can be cast only by a cleric that can meet the extraordinary prerequisites: he must have reached 20th level, and must have a Wisdom or Charisma score of at least 18. When the spell is cast, the cleric is invested with an extraordinary power, and emits in a quasi palpable manner authority and security for the next 24 hours. Dispel magic cast on the cleric has no effect on this spell, since a wish is needed to dispel it. If the cleric personally participates in a battle while he is empowered by this spell, his allied troops draw great benefits and they fight with great fervour, fury, and firmness. In game terms, the effect influences up to 200 people per level within ½ mile from the cleric (including himself), which gain the bonuses of the spells divine aid, bless and spell of striking for the duration of the clash (max 24 hours). If instead the War Machine system is used for mass combat, it gains the following bonus: 1. a +25 bonus is applied to the Combat Results roll 2. if the army is defeated, and on the Combat Results Table the difference between the scores is 101 or more, use the column “91-100” instead, thus limiting the loss. CHAPTER 3. NEW FOR RUNIC MAGIC (taken from Gazetteer 7: The Northern Reaches) “The runes are there, for any fool to read,” Onund proclaimed. “But only he who has Hung on the Tree, as did Father Odin, one who has gazed on the Abyss and suffered its emptiness, may know their true meanings or tap the Power that lies within. “It is said that the runes were given to Man by the Immortal Odin All-Father. The legends suggest that the Immortal ‘died’ – hung on the Great Ash Tree of the World, Yggdrasil. Through the experience of death and gazing on the incomprehensible void, Odin gained some insight into the magical significance and the power of the runes, and he gave it to his mortal children. “However, anyone who wants to receive the All-FKather’s knowledge must make incredible sacrifices, like those made at the end of time. Because knowledge of the runes is always accompanied by ritual suicides and great deprivations…” In the everyday Northlands life, the runes are simply a special form of written language used by Northlands clerics, particularly used to write on wood, stone, and other hard surfaces. However, there is another type of particular runes, sacred to Odin known as the “runes of power”, which have special magical meaning. With the help of some cleric spells, the more skilled priests can enhance the power and significance of the runes to obtain miracles. The commonest use of these runes is in seeking divine inspiration and guidance. The interpret runes spell allows the cleric to learn the Immortal’s will or see the future. A second use of the runes is for inscriptions on standing stones. Standing stones are slabs of rock inscribed with a mixture of practical advice and mystical insights, about famous men or enlightened individuals, the trials they have faced, and the wisdom they learnt from their deeds. The skalds (Nordic bards) inscribe the stones erected along the roads to commemorate important events and relate the good and bad acts of man. The inscriptions have been left for those that come after, so that they may learn from the experiences of those eye witnesses inspired by the Immortals. These runic inscriptions can only be read by those with the Read Runes skill, or with the read language spell, which translates therunes into a known language. With regard to the runes of power, read magic doesn’t permit these symbols to be understood, but analyise, know rune, or contact outer planes can reveal their effects. These stones and the runes inscribed there are sacred to the Immortals of the Northmen’s pantheon. Defacing or removing them is a great sacrilage, and the followers of Odin never hesitate to avenge a similar affront to the runic stones. The third way the runes are used is to enchant weapons, jewels, clothing, graves, and items with ritual value. The priest must use the inscribe runes spell to fix a RMS OF DIVINE MAGIC specific rune of power on an item, thus creating magic items that only clerics can use; the magical properties of an item of this type are in fact only activated by the bless rune spell. To correctly add a rune of power to an item, the cleric must have learnt that specific rune by means of the know rune spell and must have undergone the dangerous nine night ritual associated with this spell. RUNIC SPELLS The following clerical spells are known at the appropriate level by all the clerics that possess the Read Runes general skill and serve the Immortals that belong to the group of the Aesir and Ásynjur (see the Codex Immortalis: Book Two for further information on the list of these Immortals, which belong to the cult called Asatru or Odinism), and to only Frey and Freyja of the Vanir group (by virtue of their particular tight bond with Odin as his advisers on war and “godchildren”) in addition to those given by the Immortals. Obviously, a cleric who worships one of the Immortals of this group under another name but doesn’ follow the doctrine of Asatru doesn’t have access to the runic spells. Note: bless rune has been moved to 1st level (it was originally a 2nd level spell), while the interpret runes is the Nordic version of oracle (3rd level).", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 86", "isCustom": false},
    "imm_vigilant_guardian": {"id": "imm_vigilant_guardian", "name": "Vigilant Guardian", "level": 3, "casterType": "immortal", "range": "Touch", "duration": "1 day per level", "effect": "Casting this spell the wage must touch a subject that he wishes to watch, who must accept the effect or the spell fails.", "area": "A creature", "description": "From that moment the subject is considered the “protected” and for all the effect’s duration the mage will always be aware if something dangerous is happening to his protected, receiving in real time a mental vision of the situation that threatens the subject (which is any situation that can cause physical damage to the subject). The distance between protected and guardian isn’t important, and the spell functions even if they are on two different planes of existence. The effect is blocked if either the protected or guardian is in an anti-magic field or an area shield from divinatory spells. The effect can be magically dispelled with the normal chance if dispel magic is cast against the protected.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 87", "school": "Divination", "isCustom": false},
    "imm_wail_of_the_banshee": {"id": "imm_wail_of_the_banshee", "name": "Wail of the Banshee", "level": 7, "casterType": "immortal", "range": "0", "duration": "Instantaneous", "effect": "Scare and cause the death or injury of 1 creature per 4 levels", "area": "60-foot radius sphere", "description": "When casting this spell, the mage emits a sad sound that is heard by all the creatures (friends and enemies) present within 60 feet, which are considered scared (–1 to Attacks and skill checks against the mage) for 1 hour. Moreover, the spellcaster can select one being per 4 levels (rounded down) on which he concentrates the deadly energy of the wail. The designated victims must make a ST vs. Death Ray or die from the blow (as if it had been hit with finger of death); even if the ST succeeds, it suffers 1 point of damage per mage level. Alternatively, the mage can select a single living creature as the target, which however has a –4 penalty to the ST. Anyone within an area of magical silence is immune to the effects of this spell, as are undead and constructs.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 165", "school": "Necromancy", "isCustom": false},
    "imm_walking_dead": {"id": "imm_walking_dead", "name": "Walking Dead", "level": 1, "casterType": "immortal", "range": "10 feet", "duration": "Permanent", "effect": "Animates a corpse that walks", "area": "A corpse of a maximum of large size", "description": "The spellcaster instils the semblance of life into a corpse, which, animated by negative energy, obeys his vocal commands. The creature doesn’t speak or react to external stimuli outside of the necromancer’s orders; it has AC 10 and the ability to attack (1 HD), carry weights (20lb per hp possessed), perform simple actions, and move at 30 feet per round. Based on his level, the mage can animate beings of different size: Mage lvl. Max size hp Damage 1st-3rd Small 1d6 1 4th-6th Medium 1d8 1d4 7th+ Large 1d8+2 1d6 The mage can control up to a maximum of one corpse every 2 levels, and can animate a whole being or a part (hand, leg, head, etc.), that become inert if the body is cut to pieces or the effect is dispelled.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 70", "school": "Necromancy", "isCustom": false},
    "imm_wall_of_ice": {"id": "imm_wall_of_ice", "name": "Wall of Ice", "level": 4, "casterType": "immortal", "range": "120 feet", "duration": "6 turns", "effect": "Create a wall of ice of 1,200 ft2", "area": "Wall of 1,200 ft2, 12” thick", "description": "The wall created by da this spell is a thin, 12 inch thick, vertical wall of magical ice, with the form and dimensions chosen by the mage, up to a maximum of 1,200 square feet (for example 10×120, 20×60, 30×40 etc.). The wall must rest on a stable surface for all its length and cannot be created in a place already occupied by another solid (including living beings). The wall of ice is opaque and block normal vision, has AC 7 and 5 Structural Points (see Volume 3). Beings with 4 or less HD/levels cannot physically damage it in any way, but could use spells to destroy it. Beings with 5+ HD/levels can open a way by smashing it (Strength check with a –18 penalty) or striking it with weapons until it is dealt at least 1 SP (considered as Crystal, see Vol. 3 p.38). If a creature that isn’t immune to cold approaches closer than 3 feet from the wall he suffers 1d6 hp per round because of the magical cold, and this also happens when he passes through it after creating a breach. The wall can also be magically dispelled, otherwise it remains in existence for 6 turns, at the end of which it melts, leaving behind a small pool of water.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 107", "school": "Evocation", "isCustom": false},
    "imm_wall_of_water": {"id": "imm_wall_of_water", "name": "Wall of Water", "level": 4, "casterType": "immortal", "range": "60 feet", "duration": "3 turns", "effect": "Create a wall of water of 1,200 ft2", "area": "Opaque wall of water of 1,200 ft2", "description": "This spell creates an 12 inch thick, opaque barrier of gurgling water of 1,200 ft2 (the dimensions and form are at the mage’s discretion), which blocks vision and prevents creature with 4 or fewer HD/levels from passing through it because of the extreme water pressure. Creature with 5+ HD/levels can pass through it, but suffer 4d6 points of damage (no save), and creatures of fire suffer 5d6 damage. The wall cannot be created in a space that already contains a solid object, although it is possible to create it underwater (even not on the seabed), and can be magically dispelled, otherwise it lasts for 3 turns after being created).", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 108", "school": "Evocation", "isCustom": false},
    "imm_war_cry": {"id": "imm_war_cry", "name": "War Cry", "level": 4, "casterType": "immortal", "range": "0", "duration": "1 round per level", "effect": "Cleric gains the same THAC0 or number attacks of a fighter", "area": "Only the cleric", "description": "When the cleric casts war cry, he becomes an optimal combatant, gaining either the base THAC0 or the number of attacks of a fighter of equal level (his choice) for the spell’s duration. This spell cannot be made permanent, not even thanks to an item.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 73", "isCustom": false},
    "imm_war_paint": {"id": "imm_war_paint", "name": "War Paint", "level": 3, "casterType": "immortal", "range": "Touch", "duration": "1 day", "effect": "+4 bonus to Attacks, damage, ST, or AC", "area": "One creature", "description": "This spell is exactly like hunting colours, with the only difference that the effects are more powerful. The facial colours can confer to the individual that wears them a +4 bonus to Attack Rolls, damage, Saving Throws, or even Armour Class, as chosen by the cleric. These effects cannot be combined with other similar magical auras (like bless and hunting paint), otherwise the spell doesn’t function. This spell cannot be made permanent.", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 66", "isCustom": false},
    "imm_warding_sigil": {"id": "imm_warding_sigil", "name": "Warding Sigil", "level": 1, "casterType": "immortal", "range": "1 mile per level", "duration": "Special", "effect": "Alerts the spellcaster if an event occurs", "area": "20 foot radius sphere", "description": "Casting this spell the mage touches an item no bigger than 3 feet cube, which acquires a small magic glyph (detectable only if carefully examined or if using spells that reveal magic). The spellcaster then specifies the event that activates the sigil (simple or complex at his choice), and from that moment the sigil remains active until the planned event happens within 20 feet of the item (or until it is magically dispelled). When the event occurs, the sigil transmits a magic signal to the mind of the mage who set it up, and then disappears. This signal can however only be perceived by the spellcaster if he is within 1 mile per level of the point where he set up the warding sigil. Usually this effect is used to warn the mage of the proximity of a specific enemy to a particular place or creature, or to alert himself to danger. This effect cannot be combined with permanency.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 54", "school": "Abjuration", "isCustom": false},
    "imm_water_to_ice": {"id": "imm_water_to_ice", "name": "Water to Ice", "level": 4, "casterType": "immortal", "range": "", "duration": "", "effect": "", "description": "Granted by an Immortal in the Tome of the Magic of Mystara Vol. 2 (Divine Magic), Appendix \"Additional spells of each Immortal\". The provided books (Tome Vol. 1-2, Rules Cyclopedia) do not describe this spell; ask your DM or use your own source.\nReversible.", "source": "Tome of the Magic of Mystara Vol. 2, Appendix (no description)", "isCustom": false},
    "imm_weaken_undead": {"id": "imm_weaken_undead", "name": "Weaken Undead", "level": 2, "casterType": "immortal", "range": "", "duration": "", "effect": "", "description": "Granted by an Immortal in the Tome of the Magic of Mystara Vol. 2 (Divine Magic), Appendix \"Additional spells of each Immortal\". The provided books (Tome Vol. 1-2, Rules Cyclopedia) do not describe this spell; ask your DM or use your own source.\nReversible.", "source": "Tome of the Magic of Mystara Vol. 2, Appendix (no description)", "isCustom": false},
    "imm_weather_prediction": {"id": "imm_weather_prediction", "name": "Weather Prediction", "level": 1, "casterType": "immortal", "range": "0", "duration": "Instantaneous", "effect": "Druid knows the exact weather conditions", "area": "1 mile diameter per level", "description": "This spell allows the druid to know the exact weather conditions of the next 12 hours, within a 1 mile per druid level diameter area (e.g. a 10th level druid can know the weather conditions within a 10 mile diameter area). The effect cannot change the weather in any way, but only know of it beforehand. Note: subterranean druids replace this spell with dig (1st level arcane spell).", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 119", "druidSpell": true, "isCustom": false},
    "imm_weresnakeform": {"id": "imm_weresnakeform", "name": "Weresnakeform", "level": 5, "casterType": "immortal", "range": "Touch", "duration": "Permanent", "effect": "The individual becomes a serpentman", "area": "One creature", "description": "This potent spell is able to change any living being into a creature able to assume the form of a giant snake, a true weresnake. The individual touched can try to oppose the transformation with a ST vs. Spells with a –2 penalty, but if failed the effect is irreversible and he is considered cursed: his alignment becomes Chaotic (if it isn’t already) and his spirit is prey to evil impulses. The being can transform at his pleasure, without being affected by the phases of the moon, but is forced to obey the orders of the cleric who transformed him and generally the word of clerics of Bachraeus. As a lycanthrope, he has two forms: his normal, and that of a giant snake. When in snake form, he becomes immune to normal weapons, has magic resistance 10%, and has a bite attack that causes 1d6 hp, plus another 2d6 for the injected venom (a ST vs. Poison halves the damage). The victim has a percentage chance equal to the hp caused by the bite over his total hp of contracting lycanthopy (e.g.: a fighter with 10 hp that loses 6 to the bite has a 60% chance), transforming into in a weresnake enslaved to its progenitor (as if under the effects of a permanent charm) until the latter is killed. While in snake form, the lycanthrope can constrict a victim rather than biting him (requiring a normal Attack), and if the attack is successful, the victim suffers 10d6 points of damage per round and remains imprisoned until he wins an opposed Strength check. The statistics of the victim while in weresnake form are modified as follows: AC 0, Strength +2, Dexterity +2, Wisdom –2, Charisma –2, +2 HD more than its original form (THAC0 is based on the new HD).", "source": "Tome of the Magic of Mystara Vol. 2 (Divine Magic), p. 78", "isCustom": false},
    "imm_whirlwind": {"id": "imm_whirlwind", "name": "Whirlwind", "level": 4, "casterType": "immortal", "range": "120 feet", "duration": "", "effect": "A whirlwind 70-foot tall, 10 foot wide at", "description": "the bottom and 20 foot wide at the top Duration: concentration Effect: create a miniature whirlwind The spell creates a 75 feet high whirlwind, with a 10 feet diameter at the base and a 20 feet diameter at the top (it isn’t possible to create the whirlwind in an area of lesser size), and inside it the winds spin at a speed of 60 mph. The whirlwind moves at a speed of 60 feet per round following the mage’s commands as long as the latter keeps his concentration, and cannot move more than 120 feet away from him. Any item or being that weighs less than 200 lb. (2,000 cn) that finds itself in the whirlwind’s path is always thrown 3d4 × 10 feet away in a random direction (roll 1d8: 1=N, 2=NE, 3=E, 4=SE, 5=S, 6=SW, 7=W, 8=NW), if it isn’t solidly fixed to a stable support (or well held by its owner for objects). Any creature battered by the wind, as well as losing 1d6 hp for every 10 feet travelled, must also make a ST vs. Paralysis or be stunned for 2d4 rounds. All creatures of large or huge size or that weighs over 200 lb. that are overrun by the whirlwind suffer 2d6 points of damage, and must make a ST vs. Paralysis or be swept 1d6 × 10 feet away, suffering another 1d6 damage for every 10 feet travelled, and (if still alive) is stunned for 1d4 rounds. Flying creatures that find themselves in the area of the whirlwind must make a ST vs. Death Ray: if successful, they are thrown in a random direction on the same axis for 1d6 × 20 feet of distance, suffering 1d6 hp for every 20 feet travelled and stunned for 1d4 rounds. If the ST fails, the victim is projected for 2d6 × 20 feet in a random direction (1-2 on d4 remains on the same horizontal axis, 3-4 instead moved on the vertical axis), losing 1d6 hp for every 20 feet travelled and stunned for 2d4 rounds; if it hits the ground, it suffers the standard damage for the fall (1d6 for every 10 feet fallen, up to a maximum of 20d6). A creature within the whirlwind can only try to leave it with difficulty: it is absolutely impossible to attack with ranged weapons, concentrate (and therefore cast spells or use most magic items), and any action requires a Strength check with a 3 point penalty. If a character, for example, tries to extract a potion and drink it, he must make a Strength check with a –3 penalty to prevent the flask flying from his hand, and maybe smashing on the ground. Creatures of gargantuan size are slowed (as the reverse of haste) and lose 1d6 hp as long as they remain in the area of the whirlwind.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 108", "school": "Conjuration", "isCustom": false},
    "imm_windwhip": {"id": "imm_windwhip", "name": "Windwhip", "level": 5, "casterType": "immortal", "range": "0", "duration": "1 round per level", "effect": "Invisible whip causes 3d6 hp + deafness", "area": "20 foot radius", "description": "This spell uses the force of the wind to create an invisible and howling whip that extends from the mage’s finger and it can be used by him to strike any creature within 20 feet. The whip causes 3d6 points of slashing damage to creatures and objects and emits a sharp crack that stuns for 1 hour if the victim doesn’t make a successful ST vs. Spells. The whip cannot be blocked as it is made of compressed air, neither can the spellcaster be disarmed as the energy comes directly from his finger. To injure the enemy requires an Attack Roll modified by the mages Dexterity bonus, but as the victim cannot see the weapon the mage receives a +3 bonus to his Attack Roll. The whip is considered a +3 magic weapon in order to know which creatures it is able to damage. The effect lasts 1 round per level, but can be magically dispelled earlier or can vanish if the mage faints or dies. The spellcaster can also cast other spells or use his hands to perform other actions, but when he uses the wind whip he cannot evoke other spells and must have at least one hand free. Telepathy cannot be blocked by any insulating material, and mental protection doesn’t make the victim immune but gives him a bonus to his ST.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 129", "school": "Evocation", "isCustom": false},
    "imm_zone_of_truth": {"id": "imm_zone_of_truth", "name": "Zone of Truth", "level": 2, "casterType": "immortal", "range": "90 feet", "duration": "1 minute per level", "effect": "Forced to only tell the truth; reverse forced to always lie", "area": "20 foot radius", "description": "This spell acts on a fixed circular area with a 20 feet radius, affects the minds of all the creatures present there while the spell is in effect. Both those beings already in the area when the spell is cast and those that enter it afterwards (and each time that they set a foot inside) must make a ST vs. Mental Spells before making any statement: If the ST succeeds, they ignore the spell’s effects, otherwise from the first failure they are obliged to always tell the truth as long as they remain in the area. The subjects are able to decide what to say and how to say it, but each statement must be true or perceived as such based on the subject’s information (for example if the individual has acquired false information but doesn’t suspect anything, he will think it is true and report it as such). As questions, exclamations, and suppositions don’t constitute assertions, these are not affected. The reverse spell, zone of deceit, forces all those within the area of effect to only speak false statements. As usual the subjects can avoid all the effects with a successful a ST vs. Mental Spells, but this must be repeated each time that re-enter the area or make an assertion. The victims can decide what to say and how to say it, but each assertion must be a lie based on the subject’s information. As questions, exclamations, and suppositions don’t constitute assertions, these are not affected. The DM must examine each spoken phrase to decide if it is a true or false statement or an exception. For example the phrase “I can only lie” for those under the spell’s effect is true, so it cannot be spoken.\nReversible.", "source": "Tome of the Magic of Mystara Vol. 1 (Arcane Magic), p. 71", "school": "Enchantment", "isCustom": false}
};

